# ---- Telegram ---------------------------------------------------------------
# Each client supplies their own Telegram app API credentials. The desktop
# stores them with Windows DPAPI (CurrentUser) under LOCALAPPDATA; they are not
# embedded in the package, written into source/config JSON, or sent to EdgeQuant.
# EDGEQUANT_API_ID / EDGEQUANT_API_HASH remain supported as a local fallback.
_TELEGRAM_CREDENTIALS_SOURCE = "missing"
_TELEGRAM_CREDENTIALS_ERROR = ""
_TELEGRAM_CREDENTIALS_FILENAME = "telegram_api_credentials.dpapi"


def normalize_telegram_api_credentials(api_id, api_hash) -> tuple[int, str]:
    """Validate/normalize credentials copied from https://my.telegram.org/apps."""
    raw_id = str(api_id or "").strip()
    raw_hash = str(api_hash or "").strip()
    if not raw_id or not raw_id.isdigit():
        raise ValueError("API ID must be a positive number.")
    numeric_id = int(raw_id)
    if numeric_id <= 0:
        raise ValueError("API ID must be a positive number.")
    if len(raw_hash) != 32 or not re.fullmatch(r"[0-9a-fA-F]{32}", raw_hash):
        raise ValueError("API hash must be the 32-character value from my.telegram.org/apps.")
    return numeric_id, raw_hash.lower()


def _telegram_credentials_path() -> Path:
    """Per-Windows-user location; never save credentials beside the distributable."""
    if os.name != "nt":
        raise RuntimeError("Secure Telegram API-key storage is available in the Windows desktop app.")
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
    if not base:
        base = str(Path.home() / "AppData" / "Local")
    return Path(base) / "EdgeQuant" / _TELEGRAM_CREDENTIALS_FILENAME


def _dpapi_crypt(data: bytes, *, protect: bool) -> bytes:
    """Use native Windows DPAPI for encryption tied to the current Windows user."""
    if os.name != "nt":
        raise RuntimeError("Windows DPAPI is required for secure credential storage.")
    import ctypes
    from ctypes import wintypes

    class DATA_BLOB(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD),
                    ("pbData", ctypes.POINTER(ctypes.c_ubyte))]

    payload = bytes(data)
    in_buffer = ctypes.create_string_buffer(payload, max(1, len(payload)))
    in_blob = DATA_BLOB(len(payload), ctypes.cast(
        in_buffer, ctypes.POINTER(ctypes.c_ubyte)))
    out_blob = DATA_BLOB()
    crypt32 = ctypes.WinDLL("crypt32.dll", use_last_error=True)
    kernel32 = ctypes.WinDLL("kernel32.dll", use_last_error=True)
    if protect:
        fn = crypt32.CryptProtectData
        fn.argtypes = [ctypes.POINTER(DATA_BLOB), wintypes.LPCWSTR,
                       ctypes.POINTER(DATA_BLOB), ctypes.c_void_p,
                       ctypes.c_void_p, wintypes.DWORD,
                       ctypes.POINTER(DATA_BLOB)]
    else:
        fn = crypt32.CryptUnprotectData
        fn.argtypes = [ctypes.POINTER(DATA_BLOB), ctypes.c_void_p,
                       ctypes.POINTER(DATA_BLOB), ctypes.c_void_p,
                       ctypes.c_void_p, wintypes.DWORD,
                       ctypes.POINTER(DATA_BLOB)]
    fn.restype = wintypes.BOOL
    if protect:
        ok = fn(ctypes.byref(in_blob), "EdgeQuant Telegram API credentials",
                None, None, None, 0x1, ctypes.byref(out_blob))
    else:
        ok = fn(ctypes.byref(in_blob), None, None, None, None, 0x1,
                ctypes.byref(out_blob))
    if not ok:
        error = ctypes.get_last_error()
        raise OSError(error, "Windows could not protect/unprotect the Telegram API credentials.")
    try:
        return ctypes.string_at(out_blob.pbData, out_blob.cbData)
    finally:
        local_free = kernel32.LocalFree
        local_free.argtypes = [ctypes.c_void_p]
        local_free.restype = ctypes.c_void_p
        local_free(ctypes.cast(out_blob.pbData, ctypes.c_void_p))


def _load_telegram_credentials() -> tuple[int, str, str, str]:
    """Prefer this Windows user's DPAPI store; fall back to local environment vars."""
    global _TELEGRAM_CREDENTIALS_ERROR
    load_error = ""
    if os.name == "nt":
        try:
            store = _telegram_credentials_path()
            if store.is_file():
                try:
                    item = json.loads(_dpapi_crypt(store.read_bytes(), protect=False).decode("utf-8"))
                    if not isinstance(item, dict) or item.get("version") != 1:
                        raise ValueError("unsupported encrypted credential format")
                    api_id, api_hash = normalize_telegram_api_credentials(
                        item.get("api_id"), item.get("api_hash"))
                    _TELEGRAM_CREDENTIALS_ERROR = ""
                    return api_id, api_hash, "windows_dpapi", ""
                except Exception:
                    load_error = "Saved API credentials could not be opened on this Windows account; enter them again."
        except Exception:
            load_error = "Secure API-key storage is unavailable; enter credentials again on this Windows PC."
    env_id = os.environ.get("EDGEQUANT_API_ID", "")
    env_hash = os.environ.get("EDGEQUANT_API_HASH", "")
    if str(env_id or "").strip() or str(env_hash or "").strip():
        try:
            api_id, api_hash = normalize_telegram_api_credentials(env_id, env_hash)
            _TELEGRAM_CREDENTIALS_ERROR = load_error
            return api_id, api_hash, "environment", load_error
        except ValueError:
            if not load_error:
                load_error = "Windows environment API credentials are missing or invalid."
    _TELEGRAM_CREDENTIALS_ERROR = load_error
    return 0, "", "missing", load_error


def telegram_credentials_source() -> str:
    """Return only the source label, never credential contents."""
    return str(_TELEGRAM_CREDENTIALS_SOURCE or "missing")


def telegram_credentials_load_error() -> str:
    """Return a safe, non-secret explanation for a failed local credential load."""
    return str(_TELEGRAM_CREDENTIALS_ERROR or "")


def save_telegram_credentials(api_id, api_hash) -> Path:
    """Validate and encrypt a client's own API pair with current-user Windows DPAPI."""
    global API_ID, API_HASH, _TELEGRAM_CREDENTIALS_SOURCE, _TELEGRAM_CREDENTIALS_ERROR
    numeric_id, normalized_hash = normalize_telegram_api_credentials(api_id, api_hash)
    path = _telegram_credentials_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps({"version": 1, "api_id": numeric_id,
                          "api_hash": normalized_hash}, separators=(",", ":")).encode("utf-8")
    protected = _dpapi_crypt(payload, protect=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    try:
        temporary.write_bytes(protected)
        os.replace(temporary, path)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except Exception:
            pass
    API_ID, API_HASH = numeric_id, normalized_hash
    _TELEGRAM_CREDENTIALS_SOURCE = "windows_dpapi"
    _TELEGRAM_CREDENTIALS_ERROR = ""
    return path


API_ID, API_HASH, _TELEGRAM_CREDENTIALS_SOURCE, _TELEGRAM_CREDENTIALS_ERROR = _load_telegram_credentials()
