def telegram_credentials_ready() -> bool:
    """True only for a positive API ID and a correctly shaped Telegram API hash."""
    try:
        normalize_telegram_api_credentials(API_ID, API_HASH)
        return True
    except (TypeError, ValueError):
        return False

