BANNER = r"""
 _____ ____   ____ _____ ____   ___  _   _   _    _  _____ _  _
| ____|  _ \ / ___| ____/ ___| / _ \| | | | / \  | |/ / _ \| || |
|  _| | | | | |  _|  _|| |  _ | | | | | | |/ _ \ | ' / | | | || |_
| |___| |_| | |_| | |__| |_| || |_| | |_| / ___ \| . \ |_| |__   _|
|_____|____/ \____|_____\____| \___/ \___/_/   \_\_|\_\___/  |_|

          {name}          |          v{v}
          Telegram  ->  MetaTrader 5   execution engine
          Smart Trading, Better Decisions
"""

LEVEL_TAG = {"info": "INFO ", "ok": "OK   ", "warn": "WARN ", "err": "ERROR", "note": "NOTE ",
             "sig": "SIGNAL", "ord": "ORDER", "mng": "MANAGE", "live": " LIVE "}


def log(msg: str = "", level: str = "info") -> None:
    print(f"[{datetime.now().strftime('%H:%M:%S')}] {LEVEL_TAG.get(level, 'INFO ')} {msg}", flush=True)


def rule(char: str = "-", width: int = 76) -> None:
    print(char * width, flush=True)


def journal(entry: dict, durable: bool = False) -> bool:
    try:
        with open(HERE / JOURNAL, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(entry, ensure_ascii=False) + "\n")
            if durable:
                fh.flush()
                os.fsync(fh.fileno())
        return True
    except Exception as exc:
        log(f"processing journal write failed: {type(exc).__name__}", "err")
        return False


def _monitor_clean_text(value, limit=220) -> str:
    return " ".join(str(value or "").split())[:max(0, int(limit))]


def channel_monitor_snapshot(path=None) -> dict:
    """Safe, compact per-channel health snapshot for the local read-only UI."""
    file = Path(path) if path is not None else HERE / CHANNEL_MONITOR_FILE
    try:
        data = json.loads(file.read_text(encoding="utf-8"))
        rows = data.get("channels", {}) if isinstance(data, dict) else {}
        if not isinstance(rows, dict):
            rows = {}
        clean = []
        keys = ("chat_id", "name", "category", "enabled", "connected", "cursor",
                "last_event", "last_seen_ts", "last_seen_message_id",
                "last_decision_ts", "last_decision_message_id", "last_outcome",
                "last_reason", "last_history_check_ts", "last_history_status",
                "last_history_reason", "retry_pending", "retry_message_id",
                "retry_attempts", "retry_last_ts", "retry_after_ts",
                "backlog_pending", "updated_ts")
        for key, row in rows.items():
            if not isinstance(row, dict):
                continue
            item = {k: row.get(k) for k in keys if k in row}
            try:
                item["chat_id"] = int(item.get("chat_id") or key)
            except (TypeError, ValueError):
                continue
            for k in ("name", "category", "last_event", "last_outcome", "last_reason",
                      "last_history_status", "last_history_reason"):
                if k in item:
                    item[k] = _monitor_clean_text(item[k], 160)
            for k in ("enabled", "connected", "retry_pending", "backlog_pending"):
                if k in item:
                    item[k] = bool(item[k])
            for k in ("cursor", "last_seen_message_id", "last_decision_message_id",
                      "retry_message_id", "retry_attempts"):
                try:
                    item[k] = max(0, int(item.get(k) or 0))
                except (TypeError, ValueError):
                    item[k] = 0
            for k in ("last_seen_ts", "last_decision_ts", "last_history_check_ts",
                      "retry_last_ts", "retry_after_ts", "updated_ts"):
                try:
                    value = float(item.get(k) or 0)
                    item[k] = value if math.isfinite(value) and value > 0 else None
                except (TypeError, ValueError):
                    item[k] = None
            clean.append(item)
        clean.sort(key=lambda x: (x.get("name") or "").casefold())
        updated = float(data.get("updated_ts") or 0) if isinstance(data, dict) else 0.0
        return {"updated_ts": updated if math.isfinite(updated) and updated > 0 else None,
                "channels": clean[:100]}
    except Exception:
        return {"updated_ts": None, "channels": []}


def channel_monitor_update(chat_id, name="", category="", *, event="", outcome=None,
                           reason="", message_id=0, message_ts=0, cursor=None,
                           enabled=None, connected=None, history_status=None,
                           history_reason="", retry_pending=None, retry_message_id=0,
                           retry_attempts=None, retry_last_ts=None, retry_after_ts=None,
                           backlog_pending=None, path=None, write_status=True) -> dict:
    """Persist channel health; this is observability only and never sends orders."""
    try:
        cid = int(chat_id)
        if not cid:
            return {}
    except (TypeError, ValueError):
        return {}
    file = Path(path) if path is not None else HERE / CHANNEL_MONITOR_FILE
    now = time.time()
    key = str(cid)
    with _CHANNEL_MONITOR_LOCK:
        try:
            data = json.loads(file.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                data = {}
        except Exception:
            data = {}
        rows = data.get("channels")
        if not isinstance(rows, dict):
            rows = {}
        row = rows.get(key) if isinstance(rows.get(key), dict) else {}
        row.update({"chat_id": cid,
                    "name": _monitor_clean_text(name or row.get("name") or "", 120),
                    "category": _monitor_clean_text(category or row.get("category") or "", 24).upper(),
                    "updated_ts": now})
        if event:
            row["last_event"] = _monitor_clean_text(event, 48)
        if message_id:
            try:
                mid = int(message_id)
                if mid > 0:
                    if event in ("received", "ignored_own_post", "ignored_non_text", "debug_only"):
                        row["last_seen_message_id"] = mid
                        row["last_seen_ts"] = float(message_ts or now)
                    if outcome is not None:
                        row["last_decision_message_id"] = mid
            except (TypeError, ValueError):
                pass
        if outcome is not None:
            row["last_outcome"] = _monitor_clean_text(outcome, 48)
            row["last_reason"] = _monitor_clean_text(reason, 220)
            row["last_decision_ts"] = now
        if cursor is not None:
            try:
                row["cursor"] = max(0, int(cursor))
            except (TypeError, ValueError):
                pass
        if enabled is not None:
            row["enabled"] = bool(enabled)
        if connected is not None:
            row["connected"] = bool(connected)
        if history_status is not None:
            row["last_history_status"] = _monitor_clean_text(history_status, 48)
            row["last_history_check_ts"] = now
            row["last_history_reason"] = _monitor_clean_text(history_reason, 220)
        if retry_pending is not None:
            row["retry_pending"] = bool(retry_pending)
            row["retry_message_id"] = max(0, int(retry_message_id or 0)) if retry_pending else 0
        if retry_attempts is not None:
            try:
                row["retry_attempts"] = max(0, min(10, int(retry_attempts or 0)))
            except (TypeError, ValueError):
                pass
        for key, value in (("retry_last_ts", retry_last_ts), ("retry_after_ts", retry_after_ts)):
            if value is not None:
                try:
                    stamp = float(value or 0)
                    row[key] = stamp if math.isfinite(stamp) and stamp > 0 else None
                except (TypeError, ValueError):
                    row[key] = None
        if backlog_pending is not None:
            row["backlog_pending"] = bool(backlog_pending)
        rows[key] = row
        # Bound the file to configured channels; stale rows sort out after the current set.
        if len(rows) > 100:
            rows = dict(sorted(rows.items(), key=lambda kv: float((kv[1] or {}).get("updated_ts") or 0),
                               reverse=True)[:100])
        data = {"updated_ts": now, "channels": rows}
        try:
            file.parent.mkdir(parents=True, exist_ok=True)
            tmp = file.with_name(file.name + ".new")
            tmp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
            tmp.replace(file)
        except Exception as exc:
            log(f"channel monitor could not be saved: {type(exc).__name__}", "warn")
    if write_status and path is None:
        try:
            tg_status_write()
        except Exception:
            pass
    return dict(row)


def channel_monitor_seed(sources: dict, cursors: dict | None = None,
                         connected: bool = False, path=None) -> None:
    """Seed current selected channels while retaining their last message details."""
    cursors = cursors or {}
    for raw_id, source in (sources or {}).items():
        try:
            cid = int(raw_id)
            entity, title, category = source
        except Exception:
            continue
        try:
            enabled = bool(channel_is_on(title, category, cid))
        except Exception:
            enabled = True
        channel_monitor_update(cid, title, category, event="listener_started",
                               cursor=cursors.get(str(cid), 0), enabled=enabled,
                               connected=connected, history_status="waiting",
                               path=path, write_status=False)
    if path is None:
        try:
            tg_status_write()
        except Exception:
            pass


def signal_audit(event: str, *, source="", chat_id=0, message_id=0, category="",
                 message_ts=0, action="", confidence="", symbol="", direction="",
                 outcome=None, reason="", broker="", tickets=None, needs_review=False,
                 message_text=None, path=None, monitor=True) -> dict:
    """Append a private-text-free processing event for local audit and review.

    The raw Telegram post is never copied into this audit log; only its SHA-256
    fingerprint is kept. Exact unknown posts remain in the existing owner-local
    unknown-signals/review files for deliberate manual inspection.
    """
    now = time.time()
    record = {"ts": now, "event": _monitor_clean_text(event, 48),
              "source": _monitor_clean_text(source, 120), "category": _monitor_clean_text(category, 24).upper(),
              "outcome": _monitor_clean_text(outcome, 48) if outcome is not None else "",
              "reason": _monitor_clean_text(reason, 220),
              "action": _monitor_clean_text(action, 40),
              "confidence": _monitor_clean_text(confidence, 24),
              "symbol": _monitor_clean_text(symbol, 32).upper(),
              "direction": _monitor_clean_text(direction, 8).upper(),
              "broker": _monitor_clean_text(broker, 80),
              "needs_review": bool(needs_review)}
    try:
        record["chat_id"] = int(chat_id or 0)
    except (TypeError, ValueError):
        record["chat_id"] = 0
    try:
        record["message_id"] = int(message_id or 0)
    except (TypeError, ValueError):
        record["message_id"] = 0
    try:
        ts = float(message_ts or 0)
        record["message_ts"] = ts if math.isfinite(ts) and ts > 0 else None
    except (TypeError, ValueError):
        record["message_ts"] = None
    clean_tickets = []
    for value in list(tickets or [])[:20]:
        try:
            ticket = int(value)
            if ticket:
                clean_tickets.append(ticket)
        except (TypeError, ValueError):
            continue
    record["tickets"] = clean_tickets
    if message_text is not None:
        try:
            record["message_hash"] = hashlib.sha256(
                str(message_text).encode("utf-8", errors="replace")).hexdigest()[:24]
        except Exception:
            record["message_hash"] = ""
    file = Path(path) if path is not None else HERE / SIGNAL_AUDIT_FILE
    try:
        with _SIGNAL_AUDIT_LOCK:
            file.parent.mkdir(parents=True, exist_ok=True)
            if file.exists() and file.stat().st_size > 5 * 1024 * 1024:
                backup = file.with_name(file.name + ".1")
                try:
                    backup.unlink(missing_ok=True)
                    file.replace(backup)
                except OSError:
                    pass
            with file.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")
    except Exception as exc:
        log(f"signal audit could not be written: {type(exc).__name__}", "warn")
    if monitor and path is None and record["chat_id"] and outcome is not None:
        channel_monitor_update(record["chat_id"], record["source"], record["category"],
                               event=record["event"], outcome=record["outcome"],
                               reason=record["reason"], message_id=record["message_id"],
                               message_ts=record["message_ts"] or 0, write_status=False)
    return record


def signal_review_add(*, source="", chat_id=0, message_id=0, category="",
                      message_ts=0, reason="", text="", path=None,
                      kind="unknown_signal") -> bool:
    """Store exact Telegram text for human review; this queue never replays it."""
    file = Path(path) if path is not None else HERE / SIGNAL_REVIEW_FILE
    raw = str(text or "")
    text_hash = hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()[:24]
    try:
        cid, mid = int(chat_id or 0), int(message_id or 0)
    except (TypeError, ValueError):
        cid, mid = 0, 0
    try:
        stamp = float(message_ts or 0)
        stamp = stamp if math.isfinite(stamp) and stamp > 0 else None
    except (TypeError, ValueError):
        stamp = None
    source_text = _monitor_clean_text(source, 120)
    source_key = source_text.casefold()
    record = {"ts": time.time(), "source": source_text,
              "chat_id": cid, "message_id": mid,
              "category": _monitor_clean_text(category, 24).upper(),
              "message_ts": stamp, "reason": _monitor_clean_text(reason, 220),
              "kind": _monitor_clean_text(kind, 40) or "unknown_signal",
              "message_hash": text_hash, "text": raw, "status": "needs_review"}
    key = f"{cid}:{mid}:{source_key}:{text_hash}"
    try:
        with _SIGNAL_REVIEW_LOCK:
            if file.exists():
                try:
                    with file.open("r", encoding="utf-8", errors="replace") as fh:
                        for line in deque(fh, maxlen=5000):
                            try:
                                old = json.loads(line)
                                oldkey = (f"{int(old.get('chat_id') or 0)}:"
                                          f"{int(old.get('message_id') or 0)}:"
                                          f"{_monitor_clean_text(old.get('source'), 120).casefold()}:"
                                          f"{str(old.get('message_hash') or '')}")
                                if oldkey == key:
                                    return False
                            except Exception:
                                continue
                except OSError:
                    pass
            file.parent.mkdir(parents=True, exist_ok=True)
            with file.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n")
        return True
    except Exception as exc:
        log(f"signal review queue could not be written: {type(exc).__name__}", "warn")
        return False


def signal_audit_latest(chat_id, message_id, path=None) -> dict:
    """Return the newest audit entry for a message, without reading raw text."""
    try:
        cid, mid = int(chat_id or 0), int(message_id or 0)
    except (TypeError, ValueError):
        return {}
    file = Path(path) if path is not None else HERE / SIGNAL_AUDIT_FILE
    try:
        with _SIGNAL_AUDIT_LOCK:
            with file.open("r", encoding="utf-8", errors="replace") as fh:
                lines = list(deque(fh, maxlen=5000))
        first_match = {}
        for line in reversed(lines):
            try:
                item = json.loads(line)
                if not isinstance(item, dict):
                    continue
                if (int(item.get("chat_id") or 0) == cid and
                        int(item.get("message_id") or 0) == mid):
                    if not first_match:
                        first_match = item
                    if str(item.get("outcome") or "").strip():
                        return item
            except Exception:
                continue
        return first_match
    except OSError:
        pass
    return {}


def signal_signature(sig, category="") -> str:
    """Stable duplicate fingerprint for a parsed signal; never contains raw text."""
    def _number(value):
        try:
            number = float(value)
            return number if math.isfinite(number) else None
        except (TypeError, ValueError):
            return None
    payload = {
        "action": _monitor_clean_text(getattr(sig, "action", ""), 32),
        "symbol": _monitor_clean_text(getattr(sig, "symbol", ""), 32).upper(),
        "direction": _monitor_clean_text(getattr(sig, "direction", ""), 8).upper(),
        "entries": [_number(x) for x in (getattr(sig, "entries", None) or [])],
        "sl": _number(getattr(sig, "sl", None)),
        "tps": [_number(x) for x in (getattr(sig, "tps", None) or [])],
        "tp": _number(getattr(sig, "tp", None)),
        "category": _monitor_clean_text(category, 24).upper(),
    }
    packed = json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return hashlib.sha256(packed.encode("utf-8")).hexdigest()[:24]


def signal_deferred_load(path=None) -> list:
    """Load the local weekend queue; records include exact text for safe re-parse."""
    file = Path(path) if path is not None else HERE / SIGNAL_DEFERRED_FILE
    try:
        with _SIGNAL_DEFERRED_LOCK:
            data = json.loads(file.read_text(encoding="utf-8"))
        rows = data.get("signals", []) if isinstance(data, dict) else []
        return [row for row in rows if isinstance(row, dict)][-2000:]
    except Exception:
        return []


def _signal_deferred_store(rows: list, path=None) -> bool:
    file = Path(path) if path is not None else HERE / SIGNAL_DEFERRED_FILE
    active = [r for r in rows if str(r.get("status") or "") in
              ("pending", "pending_market_open", "processing")]
    history = [r for r in rows if str(r.get("status") or "") not in
               ("pending", "pending_market_open", "processing")]
    room = max(0, 2000 - len(active))
    rows = active + (history[-room:] if room else [])
    try:
        file.parent.mkdir(parents=True, exist_ok=True)
        tmp = file.with_name(file.name + ".new")
        payload = json.dumps({"updated_ts": time.time(), "signals": rows},
                             ensure_ascii=False, indent=2)
        with tmp.open("w", encoding="utf-8") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        tmp.replace(file)
        return True
    except Exception as exc:
        log(f"deferred signal queue could not be saved: {type(exc).__name__}", "warn")
        return False


def signal_deferred_add(*, source="", chat_id=0, message_id=0, category="",
                        message_ts=0, text="", reason="", signature="",
                        expires_ts=0, next_check_ts=0, queue_policy="", path=None) -> dict:
    """Persist a weekend-blocked signal for later revalidation, never blind replay."""
    file = Path(path) if path is not None else HERE / SIGNAL_DEFERRED_FILE
    raw = str(text or "")
    try:
        cid, mid = int(chat_id or 0), int(message_id or 0)
    except (TypeError, ValueError):
        cid, mid = 0, 0
    source_text = _monitor_clean_text(source, 120)
    raw_hash = hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()[:24]
    stable = f"{cid}:{mid}:{source_text.casefold()}:{raw_hash}"
    deferred_id = hashlib.sha256(stable.encode("utf-8")).hexdigest()[:24]
    try:
        stamp = float(message_ts or 0)
        stamp = stamp if math.isfinite(stamp) and stamp > 0 else None
    except (TypeError, ValueError):
        stamp = None
    now = time.time()
    try:
        expiry = float(expires_ts or 0)
        expiry = expiry if math.isfinite(expiry) and expiry > 0 else None
    except (TypeError, ValueError):
        expiry = None
    policy = _monitor_clean_text(queue_policy, 48)
    if policy != WEEKEND_LIMIT_QUEUE_POLICY:
        policy = ""
    record = {"id": deferred_id, "created_ts": now, "updated_ts": now,
              "source": source_text, "chat_id": cid, "message_id": mid,
              "category": _monitor_clean_text(category, 24).upper(),
              "message_ts": stamp, "expires_ts": expiry,
              "queue_policy": policy,
              "next_check_ts": float(next_check_ts or 0) or now,
              "signature": _monitor_clean_text(signature, 32),
              "message_hash": raw_hash, "text": raw,
              "status": "pending_market_open",
              "reason": _monitor_clean_text(reason, 220), "attempts": 0}
    try:
        with _SIGNAL_DEFERRED_LOCK:
            try:
                data = json.loads(file.read_text(encoding="utf-8"))
                rows = data.get("signals", []) if isinstance(data, dict) else []
            except Exception:
                rows = []
            rows = [r for r in rows if isinstance(r, dict)]
            for idx, old in enumerate(rows):
                if str(old.get("id") or "") == deferred_id:
                    record["created_ts"] = old.get("created_ts") or now
                    record["attempts"] = max(0, int(old.get("attempts") or 0))
                    if not record.get("queue_policy"):
                        old_policy = _monitor_clean_text(old.get("queue_policy"), 48)
                        record["queue_policy"] = (old_policy if
                            old_policy == WEEKEND_LIMIT_QUEUE_POLICY else "")
                    if not record.get("expires_ts"):
                        try:
                            old_expiry = float(old.get("expires_ts") or 0)
                            record["expires_ts"] = (old_expiry if
                                math.isfinite(old_expiry) and old_expiry > 0 else None)
                        except (TypeError, ValueError):
                            record["expires_ts"] = None
                    rows[idx] = record
                    break
            else:
                rows.append(record)
            if not _signal_deferred_store(rows, file):
                return {}
        return dict(record)
    except Exception as exc:
        log(f"deferred signal queue failed: {type(exc).__name__}", "warn")
        return {}


def signal_deferred_update(deferred_id, *, status=None, reason=None, outcome=None,
                           next_check_ts=None, attempts=None, path=None) -> dict:
    file = Path(path) if path is not None else HERE / SIGNAL_DEFERRED_FILE
    try:
        with _SIGNAL_DEFERRED_LOCK:
            try:
                data = json.loads(file.read_text(encoding="utf-8"))
                rows = data.get("signals", []) if isinstance(data, dict) else []
            except Exception:
                return {}
            for row in rows:
                if not isinstance(row, dict) or str(row.get("id") or "") != str(deferred_id):
                    continue
                if status is not None:
                    row["status"] = _monitor_clean_text(status, 40)
                if reason is not None:
                    row["reason"] = _monitor_clean_text(reason, 220)
                if outcome is not None:
                    row["outcome"] = _monitor_clean_text(outcome, 48)
                if next_check_ts is not None:
                    try:
                        value = float(next_check_ts or 0)
                        row["next_check_ts"] = value if math.isfinite(value) and value > 0 else None
                    except (TypeError, ValueError):
                        row["next_check_ts"] = None
                if attempts is not None:
                    try:
                        row["attempts"] = max(0, min(100, int(attempts)))
                    except (TypeError, ValueError):
                        pass
                row["updated_ts"] = time.time()
                if not _signal_deferred_store(rows, file):
                    return {}
                return dict(row)
    except Exception as exc:
        log(f"deferred signal queue update failed: {type(exc).__name__}", "warn")
    return {}


def signal_deferred_duplicate(signature=None, exclude_id="", path=None,
                               chat_id=None, message_id=None) -> dict:
    """Find only the same Telegram event; equal parsed content is not a duplicate."""
    try:
        cid, mid = int(chat_id or 0), int(message_id or 0)
    except (TypeError, ValueError):
        return {}
    if not cid or mid <= 0:
        return {}
    for row in signal_deferred_load(path):
        try:
            row_cid, row_mid = int(row.get("chat_id") or 0), int(row.get("message_id") or 0)
        except (TypeError, ValueError):
            continue
        if (str(row.get("status") or "") in ("pending_market_open", "processing")
                and row_cid == cid and row_mid == mid
                and str(row.get("id") or "") != str(exclude_id or "")):
            return row
    return {}


def signal_deferred_pending(path=None) -> list:
    rows = signal_deferred_load(path)
    return sorted((r for r in rows if str(r.get("status") or "") == "pending_market_open"),
                  key=lambda r: float(r.get("created_ts") or 0))


def signal_deferred_get(deferred_id, path=None) -> dict:
    if not str(deferred_id or ""):
        return {}
    return next((dict(row) for row in signal_deferred_load(path)
                 if str(row.get("id") or "") == str(deferred_id)), {})


def signal_deferred_uses_weekend_limit_policy(row, category="") -> bool:
    if not isinstance(row, dict):
        return False
    cat = str(category or row.get("category") or "").strip().upper()
    row_cat = str(row.get("category") or "").strip().upper()
    policy = _monitor_clean_text(row.get("queue_policy"), 48)
    return (cat == "LIMIT" and row_cat == "LIMIT" and
            policy == WEEKEND_LIMIT_QUEUE_POLICY)


def signal_deferred_age_limit_min(category="", row=None) -> float:
    """Freshness cap for a durable deferred item (72h only for weekend LIMIT)."""
    if signal_deferred_uses_weekend_limit_policy(row, category):
        return max(0.0, float(WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS)) * 60.0
    try:
        value = float(signal_age_limit_min(category) or CATCHUP_BOOTSTRAP_MINUTES)
        return max(0.0, value)
    except (TypeError, ValueError):
        return 0.0


def signal_deferred_expiry_ts(row, category="") -> float:
    """Never extend a stored expiry beyond its original message-age limit."""
    if not isinstance(row, dict):
        return 0.0
    try:
        stamp = float(row.get("message_ts") or 0)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(stamp) or stamp <= 0:
        return 0.0
    max_age = signal_deferred_age_limit_min(category or row.get("category"), row)
    if max_age <= 0:
        return 0.0
    calculated = stamp + max_age * 60.0
    try:
        stored = float(row.get("expires_ts") or 0)
        if math.isfinite(stored) and stored > 0:
            calculated = min(calculated, stored)
    except (TypeError, ValueError):
        pass
    return calculated


def signal_deferred_is_expired(row, category="", *, now=None) -> bool:
    deadline = signal_deferred_expiry_ts(row, category)
    try:
        current = float(now if now is not None else time.time())
    except (TypeError, ValueError):
        current = time.time()
    return deadline <= 0 or current >= deadline


def channel_alert_once(source: str, tag: str, text: str, cooldown_s: float = 900.0) -> bool:
    """Rate-limited operational alert; never includes raw private signal text."""
    key = (channel_key(source), _monitor_clean_text(tag, 40))
    now = time.time()
    with _CHANNEL_ALERT_LOCK:
        if now - float(_CHANNEL_ALERT_TIMES.get(key, 0) or 0) < max(60.0, cooldown_s):
            return False
        _CHANNEL_ALERT_TIMES[key] = now
    notify("\n".join([tg_title(EV_ICON.get("warn", "⚠️"), "SIGNAL NEEDS ATTENTION",
                              _monitor_clean_text(source, 100)),
                      _monitor_clean_text(text, 220), tg_foot()]))
    return True


# =========================================================================== #
#  v1.9.2  -  WHAT IS THE TELEGRAM CONNECTION DOING RIGHT NOW?
#  The app used to light its TELEGRAM chip from one startup log line only, so
#  a bot started in another window (or a login that was still waiting for the
#  phone code) showed a red "not connected" even when everything was fine.
#  The engine now keeps this box + a small status file, and the app reads it.
# =========================================================================== #
TG_STATE = {"online": False, "who": "", "reason": "", "phase": "idle", "ts": 0.0}


def tg_set_state(online=None, who=None, reason=None, phase=None) -> None:
    """Remember what the Telegram connection is doing (thread safe enough)."""
    if online is not None:
        TG_STATE["online"] = bool(online)
    if who is not None:
        TG_STATE["who"] = str(who or "")
    if reason is not None:
        TG_STATE["reason"] = str(reason or "")
    if phase is not None:
        TG_STATE["phase"] = str(phase or "")
    TG_STATE["ts"] = time.time()


def tg_online_now() -> tuple:
    """(is the Telegram client connected, who) - the live truth, not a log line."""
    try:
        cl = _notify_client
    except Exception:
        cl = None
    if cl is None:
        # no client in THIS process: report what the login/status box knows
        return bool(TG_STATE.get("online")), str(TG_STATE.get("who") or "")
    try:
        on = bool(cl.is_connected())
    except Exception:
        on = False
    if on and not TG_STATE.get("online"):
        tg_set_state(online=True, phase="online")
    return on, str(TG_STATE.get("who") or "")


def tg_session_exists() -> bool:
    """Is there a saved Telegram login in this folder?"""
    try:
        sp = session_path()
        return Path(str(sp) + ".session").exists()
    except Exception:
        return False


def tg_reason_short(text: str = "", limit: int = 70) -> str:
    got = str(text or TG_STATE.get("reason") or "").strip().replace("\n", " ")
    return got[:limit]


def tg_status_snapshot() -> dict:
    """Everything the app + other windows may want to know."""
    on, who = tg_online_now()
    mt5_bits = {}
    try:
        if HAVE_MT5 and mt5_ready():
            acc = mt5.account_info()
            if acc:
                mt5_bits = {"login": int(acc.login), "balance": float(acc.balance),
                            "currency": str(acc.currency or "USD"),
                            "server": str(acc.server or "")}
    except Exception:
        mt5_bits = {}
    return {"pid": os.getpid(), "ts": time.time(), "version": VERSION,
            "bot": BOT_NAME, "telegram": bool(on), "who": who,
            "reason": str(TG_STATE.get("reason") or ""),
            "phase": str(TG_STATE.get("phase") or ""),
            "mode": ("DRY-RUN" if DRY_RUN else "LIVE"),
            "session": tg_session_exists(), "mt5": mt5_bits,
            "channel_monitor": channel_monitor_snapshot()}


def tg_status_write(quiet: bool = True) -> None:
    """Save the snapshot where any window can read it (never raises)."""
    try:
        data = tg_status_snapshot()
        tmp = HERE / (STATUS_FILE + ".new")
        tmp.write_text(json.dumps(data, indent=2), encoding="utf-8")
        tmp.replace(HERE / STATUS_FILE)
    except Exception as exc:
        if not quiet:
            log(f"      status file could not be written: {exc}", "warn")


def tg_status_read() -> dict:
    """Read the snapshot of whichever window runs the engine ({} when none)."""
    try:
        data = json.loads((HERE / STATUS_FILE).read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return {}
        age = time.time() - float(data.get("ts") or 0)
        data["age_s"] = age
        data["fresh"] = age <= float(TG_STATUS_FRESH_S)
        return data
    except Exception:
        return {}


def tg_status_text() -> str:
    """One line for /status and the settings tab."""
    on, who = tg_online_now()
    if on:
        return f"telegram: CONNECTED   {who}   (session file: {SESSION_NAME}.session)"
    why = tg_reason_short()
    tail = f"   -   {why}" if why else ("   (/login from Telegram or LOGIN in the app)" if not tg_session_exists() else "")
    return f"telegram: NOT connected{tail}"


def tg_login_advice() -> str:
    """Exactly what the user has to do when the login is not there yet."""
    if tg_session_exists():
        return ("the saved login is there but Telegram did not answer - check the "
                "internet and press START again (or /login)")
    return ("no Telegram login file in this folder yet - one login is needed: open "
            "EDGEQUANT-START.bat once (a console window opens, type your phone number "
            "+ the code Telegram sends), or press LOGIN in the app")


def telegram_transient_connection_error(exc) -> bool:
    """True only for transport/server outages that can recover without a new login."""
    if exc is None or session_death_kind(exc):
        return False
    try:
        if isinstance(exc, (TimeoutError, ConnectionError, OSError)):
            return True
        name = type(exc).__name__.lower()
        text = f"{name} {exc}".lower()
    except Exception:
        return False
    return any(token in text for token in (
        "timeout", "timed out", "connectionerror", "connection reset",
        "connection refused", "connection lost", "cannot connect",
        "could not connect", "network is unreachable", "network unreachable",
        "temporary failure", "temporarily unavailable", "socket", "servererror",
        "rpc_call_fail", "disconnected"))


async def tg_login_with_timeout(client, timeout: float = None, _sleep_fn=None) -> bool:
    """Start Telegram, retrying temporary connection failures for saved sessions.

    A missing/revoked login still requires the user to authenticate again. A
    waiting phone-code prompt is never mistaken for a network outage. With an
    authorized saved session, transient transport failures retry indefinitely
    using capped backoff until Telegram returns or STOP is requested.
    """
    t = float(timeout if timeout is not None else TG_LOGIN_TIMEOUT_S or 120)
    timeout_s = max(15.0, t)
    sleeper = _sleep_fn or asyncio.sleep
    attempt = 0
    last_exc = None
    tg_set_state(online=False, phase="connecting", reason="")
    if not tg_session_exists():
        tg_set_state(reason="the login needs your phone number + code (no session file yet)")
    while not stop_requested():
        try:
            globals()["_LAST_LOGIN_EXC"] = None
            started = await asyncio.wait_for(safe_start(client), timeout=timeout_s)
            if started:
                tg_set_state(online=True, phase="online", reason="")
                return True
            last_exc = globals().get("_LAST_LOGIN_EXC")
        except asyncio.TimeoutError as exc:
            last_exc = exc
            try:
                still_connected = bool(client.is_connected())
            except Exception:
                still_connected = False
            # A connected client timing out is commonly a phone/code prompt.
            # Do not loop or hide that required user action.
            if still_connected:
                why = ("Telegram login is waiting for user input after "
                       f"{timeout_s:.0f}s - " + tg_login_advice())
                tg_set_state(online=False, phase="login_required", reason=why)
                log("Telegram : " + why, "err")
                tg_status_write()
                return False
        except Exception as exc:
            last_exc = exc

        if session_death_kind(last_exc):
            break
        if (not tg_session_exists() or
                not telegram_transient_connection_error(last_exc)):
            break

        attempt += 1
        wait = min(120, 5 * attempt)
        why = (f"temporary Telegram connection failure ({type(last_exc).__name__}); "
               f"retrying in {wait}s, attempt {attempt}")
        tg_set_state(online=False, phase="reconnecting", reason=why)
        tg_status_write()
        log("Telegram : " + why, "warn")
        try:
            await client.disconnect()
        except Exception:
            pass
        # Use short sleeps so the desktop STOP button remains responsive.
        for _ in range(wait):
            if stop_requested():
                break
            await sleeper(1.0)

    if stop_requested():
        tg_set_state(online=False, phase="stopped", reason="stopped by user")
        tg_status_write()
        return False
    if session_death_kind(last_exc):
        globals()["_LAST_LOGIN_EXC"] = last_exc
        why = f"{type(last_exc).__name__}: {last_exc}"
        tg_set_state(online=False, phase="login_required", reason=why)
        tg_status_write()
        return False
    why = (f"{type(last_exc).__name__}: {last_exc}" if last_exc else tg_login_advice())
    tg_set_state(online=False, phase="error", reason=why)
    tg_status_write()
    return False


# ---- v1.9.2  a login the APP can do (no console, no hidden prompt) ---------
_login_client = None


async def tg_login_reset_client() -> bool:
    """Disconnect an unfinished login client before replacing its API keys."""
    global _login_client
    client = _login_client
    _login_client = None
    if client is not None:
        try:
            if client.is_connected():
                await client.disconnect()
        except Exception:
            pass
    return True


async def tg_login_dead_reset(exc: Exception, where: str = "app login") -> str:
    """v1.9.7: a dead auth key during any login step must be discarded.

    Telethon may report AUTH_KEY_UNREGISTERED at GetPasswordRequest, after the
    code step has already worked. Disconnect and park that key, then tell the UI
    to SEND CODE again; do not keep reusing the invalid authorization/session.
    """
    global _login_client
    kind = session_death_kind(exc)
    if not kind:
        return ""
    client = _login_client
    _login_client = None
    if client is not None:
        try:
            await client.disconnect()
        except Exception:
            pass
    moved = ""
    if kind != "deactivated":
        try:
            moved = quarantine_session()
        except Exception:
            moved = ""
    session_dead_write(kind, where, str(exc))
    if kind == "deactivated":
        return (f"{type(exc).__name__}: {exc}\n"
                ">> Telegram says this account is deactivated; a new code will not fix it.\n"
                ">> Check the account with Telegram support before trying again.")
    parked = (f"old login file parked as {moved}" if moved else
              "the old login file could not be moved (another window may still have it open)")
    return (f"{type(exc).__name__}: {exc}\n"
            f">> Telegram ended the saved authorization; {parked}.\n"
            ">> Close other EdgeQuant windows and request a FRESH code.\n"
            ">> In this app press SEND CODE again; in a console rerun\n"
            ">> EDGEQUANT-LOGIN.bat. Do not reuse the failed code.")


async def tg_login_send_code(phone: str) -> dict:
    """Step 1 of the app login: ask Telegram for the code."""
    global _login_client
    phone = str(phone or "").strip()
    if not phone:
        return {"ok": False, "error": "type your phone number first (example +94771234567)"}
    if not telegram_credentials_ready():
        return {"ok": False, "error":
                "Telegram API ID/API hash are missing or invalid. Open API SETUP / "
                "Telegram API සකසන්න first; the code has not been requested yet."}
    try:
        # v1.9.5: if the last login was killed, start this one on a clean file -
        # reusing a dead key is what makes "log in again" fail again.
        if session_dead_read(7 * 86400.0):
            moved = quarantine_session()
            try:
                await _login_client.disconnect()
            except Exception:
                pass
            _login_client = None
            if moved:
                log(f"login: the dead login file was parked as {moved}", "info")
        if _login_client is None:
            _login_client = TelegramClient(str(session_path()), int(API_ID), API_HASH)
        await _login_client.connect()
        await _login_client.send_code_request(phone)
        tg_set_state(phase="code", who="", reason="waiting for the code Telegram sent")
        return {"ok": True, "phone": phone}
    except Exception as exc:
        dead = await tg_login_dead_reset(exc, "SEND CODE")
        if dead:
            return {"ok": False, "error": dead}
        why = explain_login_error(exc)
        tg_set_state(online=False, phase="error", reason=why)
        return {"ok": False, "error": why}


async def tg_login_enter_code(phone: str, code: str) -> dict:
    """Step 2: the code that arrived in Telegram."""
    global _login_client
    code = str(code or "").strip()
    if _login_client is None:
        return {"ok": False, "error": "press SEND CODE first"}
    if not code:
        return {"ok": False, "error": "type the code Telegram sent"}
    try:
        await _login_client.sign_in(phone=phone, code=code)
    except Exception as exc:
        name = type(exc).__name__
        if "SessionPasswordNeeded" in name or "password" in str(exc).lower():
            tg_set_state(phase="2fa", reason="two step password needed")
            return {"ok": True, "need_password": True}
        dead = await tg_login_dead_reset(exc, "USE THE CODE")
        if dead:
            return {"ok": False, "error": dead}
        why = explain_login_error(exc)
        tg_set_state(online=False, phase="error", reason=why)
        return {"ok": False, "error": why}
    return await tg_login_finish()


async def tg_login_enter_password(pw: str) -> dict:
    """Step 3 (only when two step verification is on)."""
    global _login_client
    if _login_client is None:
        return {"ok": False, "error": "press SEND CODE first"}
    try:
        await _login_client.sign_in(password=str(pw or ""))
    except Exception as exc:
        dead = await tg_login_dead_reset(exc, "2FA FINISH")
        if dead:
            return {"ok": False, "error": dead}
        why = explain_login_error(exc)
        tg_set_state(online=False, phase="error", reason=why)
        return {"ok": False, "error": why}
    return await tg_login_finish()


async def tg_login_finish() -> dict:
    """The login worked - save it, say who, clean up."""
    global _login_client
    try:
        me = await _login_client.get_me()
        first = str(getattr(me, "first_name", "") or "").strip()
        last = str(getattr(me, "last_name", "") or "").strip()
        display_name = " ".join(part for part in (first, last) if part).strip()
        username = str(getattr(me, "username", "") or "").strip().lstrip("@")
        display_name = display_name or username or "Telegram user"
        who = f"{display_name} (@{username})" if username else display_name
        tg_set_state(online=True, who=who, phase="online", reason="")
        try:
            await _login_client.disconnect()
        except Exception:
            pass
        _login_client = None
        session_dead_clear()          # v1.9.5: the login is healthy again
        log(f"Telegram : login saved - {who}", "ok")
        log("           choose your signal sources in CHANNELS, then press START "
            "(or run EDGEQUANT-START.bat)", "info")
        log("           (if the bot is already running and waiting for a login it "
            "picks this up by itself within 20 s)", "info")
        tg_status_write()
        return {"ok": True, "who": who, "name": display_name,
                "username": username}
    except Exception as exc:
        dead = await tg_login_dead_reset(exc, "login finish")
        if dead:
            return {"ok": False, "error": dead}
        return {"ok": False, "error": explain_login_error(exc)}


# =========================================================================== #
#  PART 3b - SAFE LOGIN / SINGLETON GUARD
# =========================================================================== #
LOCK_FILE = "edgequant.lock"
ERROR_LOG = "edgequant_error.log"
_lock_handle = None


def session_path() -> Path:
    """Reuse an older login file if the new one does not exist yet (no re-login)."""
    if (HERE / (SESSION_NAME + ".session")).exists():
        return HERE / SESSION_NAME
    for other in SESSION_FALLBACKS:
        if (HERE / (other + ".session")).exists():
            return HERE / other
    return HERE / SESSION_NAME


def telegram_dialog_kind(dialog) -> tuple:
    """Return (visible type, can be used as a signal source) for one Telegram chat."""
    entity = getattr(dialog, "entity", None)
    entity_type = type(entity).__name__.lower() if entity is not None else ""
    is_group = bool(getattr(dialog, "is_group", False) or
                    getattr(entity, "megagroup", False) or
                    getattr(entity, "gigagroup", False) or entity_type == "chat")
    if is_group:
        return "GROUP", True
    is_channel = bool(getattr(dialog, "is_channel", False) or entity_type == "channel")
    if is_channel:
        return "CHANNEL", True
    is_user = bool(getattr(dialog, "is_user", False) or entity_type == "user")
    if is_user:
        return ("BOT" if bool(getattr(entity, "bot", False)) else "PRIVATE"), False
    return "OTHER", False


async def telegram_scan_dialogs() -> list:
    """Use a short authorized session for chat metadata; never inspect message text/history."""
    if not HAVE_TELETHON or TelegramClient is None:
        raise RuntimeError("Telethon is not installed; run BUILD-EXE.bat or install requirements.txt")
    client = None
    try:
        client = TelegramClient(str(session_path()), int(API_ID), API_HASH)
        await client.connect()
        if not await client.is_user_authorized():
            raise RuntimeError("Telegram is not logged in in this folder. Press LOGIN first, then scan again.")
        rows, seen = [], set()
        async for dialog in client.iter_dialogs(limit=None):
            entity = getattr(dialog, "entity", None)
            try:
                # Mark peers by Telegram type (user/group/channel IDs can overlap).
                from telethon.utils import get_peer_id
                chat_id = int(get_peer_id(entity))
            except Exception:
                try:
                    chat_id = int(getattr(entity, "id"))
                except Exception:
                    continue
            if chat_id in seen:
                continue
            seen.add(chat_id)
            name = (getattr(dialog, "name", None) or
                    getattr(entity, "title", None) or
                    getattr(entity, "first_name", None) or
                    getattr(entity, "username", None) or f"Chat {chat_id}")
            kind, can_add = telegram_dialog_kind(dialog)
            rows.append({"id": chat_id, "name": str(name), "kind": kind,
                         "can_add": bool(can_add)})
        session_dead_clear()
        return rows
    except Exception as exc:
        kind = session_death_kind(exc)
        if kind:
            if client is not None:
                try:
                    await client.disconnect()
                except Exception:
                    pass
            if kind != "deactivated":
                try:
                    quarantine_session()
                except Exception:
                    pass
            session_dead_write(kind, "CHANNEL SCAN", str(exc))
            raise RuntimeError("Telegram login ended while scanning. "
                               "Press LOGIN, finish a fresh login, then scan again.") from exc
        raise
    finally:
        if client is not None:
            try:
                if client.is_connected():
                    await client.disconnect()
            except Exception:
                pass



def telegram_studio_username_valid(value: str) -> bool:
    """Telegram public usernames: 5-32 chars, letter first, letter/digit last."""
    return bool(re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{3,30}[A-Za-z0-9]",
                             str(value or "").strip().lstrip("@")))


def telegram_studio_username_suggestion(title: str) -> str:
    """Build a valid editable username suggestion from a group/channel title.

    Telegram still decides whether the username is available; this only avoids
    the common blank/invalid field shown in the setup screenshot.
    """
    slug = re.sub(r"[^A-Za-z0-9_]+", "_", str(title or "").strip()).strip("_")
    if not slug:
        slug = "edgequant_group"
    if not re.match(r"^[A-Za-z]", slug):
        slug = "eq_" + slug
    slug = slug[:32].rstrip("_")
    if len(slug) < 5:
        slug = (slug + "_group")[:32].rstrip("_")
    if not telegram_studio_username_valid(slug):
        slug = "edgequant_group"
    return slug.lower()


async def _telegram_studio_client(client=None):
    """Use the current bot client, or open one authorized short session."""
    if client is not None:
        try:
            if not client.is_connected():
                raise RuntimeError("Telegram client is disconnected; wait for CONNECTED and retry.")
        except AttributeError:
            pass
        return client, False
    if not HAVE_TELETHON or TelegramClient is None:
        raise RuntimeError("Telethon is unavailable; install requirements.txt or run BUILD-EXE.bat")
    if not telegram_credentials_ready():
        raise RuntimeError("Telegram API credentials are not configured. Set EDGEQUANT_API_ID and EDGEQUANT_API_HASH on this PC; do not paste them into chat.")
    client = TelegramClient(str(session_path()), int(API_ID), API_HASH)
    try:
        await client.connect()
        if not await client.is_user_authorized():
            raise RuntimeError("Telegram is not logged in in this folder. Press LOGIN first.")
        return client, True
    except Exception:
        try:
            if client.is_connected():
                await client.disconnect()
        except Exception:
            pass
        raise


async def _telegram_studio_close(client, owned: bool) -> None:
    if owned and client is not None:
        try:
            if client.is_connected():
                await client.disconnect()
        except Exception:
            pass


async def _telegram_studio_find_chat(client, chat_id):
    """Resolve a saved Telegram peer ID safely, preferring its exact marked ID.

    Telegram user, basic-chat and channel ID number ranges can overlap. The old
    alias-only lookup could therefore resolve a saved channel to an unrelated
    basic group with the same raw number. Studio stores marked IDs from
    get_peer_id(); match those exactly first, and only accept a legacy/raw-ID
    alias when it identifies one unambiguous dialog.
    """
    try:
        target_value = int(str(chat_id).strip())
    except Exception:
        target_value = None
    try:
        target_forms = id_forms(chat_id)
    except Exception:
        target_forms = {str(chat_id)}
    try:
        from telethon.utils import get_peer_id
    except Exception:
        get_peer_id = None
    aliases = {}
    async for dialog in client.iter_dialogs(limit=None):
        entity = getattr(dialog, "entity", None)
        if entity is None:
            continue
        peer_id = None
        if get_peer_id:
            try:
                peer_id = int(get_peer_id(entity))
            except Exception:
                pass
        if peer_id is None:
            try:
                peer_id = int(getattr(dialog, "id"))
            except Exception:
                try:
                    peer_id = int(getattr(entity, "id"))
                except Exception:
                    continue
        if target_value is not None and peer_id == target_value:
            return entity
        forms = id_forms(peer_id)
        for alias in target_forms & forms:
            aliases.setdefault(alias, {})[peer_id] = entity
    matches = {}
    for peers in aliases.values():
        matches.update(peers)
    if len(matches) == 1:
        return next(iter(matches.values()))
    if len(matches) > 1:
        raise RuntimeError(
            "The saved Telegram destination ID matches more than one chat type. "
            "Refresh the destination list and select the channel again; nothing was sent.")
    raise RuntimeError("That group/channel is not in this account's dialogs. Refresh the list and try again.")


async def telegram_studio_create_chat(title, kind="GROUP", visibility="PRIVATE",
                                      username="", about="", client=None) -> dict:
    """Create a Telegram supergroup or broadcast channel, then return a share link."""
    title = re.sub(r"\s+", " ", str(title or "")).strip()
    kind = str(kind or "GROUP").strip().upper()
    visibility = str(visibility or "PRIVATE").strip().upper()
    username = str(username or "").strip().lstrip("@")
    about = str(about or "").strip()[:255]
    if not title or len(title) > 128:
        raise ValueError("Enter a group/channel name (1-128 characters).")
    if kind not in ("GROUP", "CHANNEL"):
        raise ValueError("Choose GROUP or CHANNEL.")
    if visibility not in ("PRIVATE", "PUBLIC"):
        raise ValueError("Choose PRIVATE or PUBLIC.")
    if visibility == "PUBLIC" and not telegram_studio_username_valid(username):
        raise ValueError("PUBLIC needs a valid username: 5-32 letters/numbers/underscore, starts with a letter.")
    if visibility == "PRIVATE":
        username = ""

    client, owned = await _telegram_studio_client(client)
    try:
        from telethon.tl.functions.channels import CreateChannelRequest, UpdateUsernameRequest
        result = await client(CreateChannelRequest(
            title=title, about=about,
            broadcast=(kind == "CHANNEL"), megagroup=(kind == "GROUP")))
        chats = list(getattr(result, "chats", []) or [])
        if not chats:
            raise RuntimeError("Telegram created the chat but did not return its details. Refresh the dialog list.")
        chat = chats[0]
        try:
            from telethon.utils import get_peer_id
            marked_id = int(get_peer_id(chat))
        except Exception:
            marked_id = int(getattr(chat, "id"))
        actual_visibility, link, warning = "PRIVATE", "", ""
        if visibility == "PUBLIC":
            try:
                changed = await client(UpdateUsernameRequest(channel=chat, username=username))
                if changed:
                    actual_visibility = "PUBLIC"
                    link = f"https://t.me/{username}"
                else:
                    warning = "Telegram did not accept the username; the new chat remains PRIVATE."
            except Exception as exc:
                warning = ("Telegram did not set the public username; the new chat remains PRIVATE: "
                           f"{type(exc).__name__}: {exc}")
        if not link:
            try:
                from telethon.tl.functions.messages import ExportChatInviteRequest
                invite = await client(ExportChatInviteRequest(peer=chat))
                link = str(getattr(invite, "link", "") or "")
            except Exception as exc:
                warning = (warning + "  " if warning else "") + f"Private link could not be exported: {exc}"
        return {"id": marked_id, "raw_id": int(getattr(chat, "id", 0)),
                "name": str(getattr(chat, "title", title) or title),
                "kind": kind, "visibility": actual_visibility,
                "username": username if actual_visibility == "PUBLIC" else "",
                "link": link, "access": "OWNED", "owned": True, "admin": True,
                "can_post": True, "warning": warning}
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_list_chats(client=None) -> list:
    """List this account's joined groups/channels for Studio destinations."""
    client, owned = await _telegram_studio_client(client)
    try:
        try:
            from telethon.utils import get_peer_id
        except Exception:
            get_peer_id = None
        rows, seen = [], set()
        async for dialog in client.iter_dialogs(limit=None):
            entity = getattr(dialog, "entity", None)
            kind, can_add = telegram_dialog_kind(dialog)
            if kind not in ("GROUP", "CHANNEL"):
                continue
            try:
                chat_id = int(get_peer_id(entity)) if get_peer_id else int(getattr(entity, "id"))
            except Exception:
                try:
                    chat_id = int(getattr(entity, "id"))
                except Exception:
                    continue
            if chat_id in seen:
                continue
            seen.add(chat_id)
            creator = bool(getattr(entity, "creator", False))
            admin_rights = getattr(entity, "admin_rights", None)
            admin = admin_rights is not None
            access = "OWNED" if creator else ("ADMIN" if admin else "JOINED")
            broadcast = bool(getattr(entity, "broadcast", False))
            if broadcast:
                can_post = creator or bool(getattr(admin_rights, "post_messages", False))
            else:
                banned = getattr(entity, "banned_rights", None)
                can_post = not bool(getattr(banned, "send_messages", False))
            rows.append({"id": chat_id,
                         "name": str(getattr(dialog, "name", None) or
                                      getattr(entity, "title", None) or f"Chat {chat_id}"),
                         "kind": kind,
                         "username": str(getattr(entity, "username", "") or ""),
                         "access": access, "owned": creator, "admin": admin,
                         "can_post": bool(can_post)})
        rows.sort(key=lambda r: (r["name"].casefold(), r["id"]))
        return rows
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_contacts(client=None) -> list:
    """Return selectable Telegram contacts (no phone numbers exposed to the UI)."""
    client, owned = await _telegram_studio_client(client)
    try:
        from telethon.tl.functions.contacts import GetContactsRequest
        result = await client(GetContactsRequest(hash=0))
        rows, seen = [], set()
        for user in getattr(result, "users", []) or []:
            if getattr(user, "deleted", False) or getattr(user, "bot", False):
                continue
            try:
                uid = int(user.id)
            except Exception:
                continue
            if uid in seen:
                continue
            seen.add(uid)
            name = " ".join(x for x in (getattr(user, "first_name", ""),
                                         getattr(user, "last_name", "")) if x).strip()
            username = str(getattr(user, "username", "") or "")
            rows.append({"id": uid, "name": name or ("@" + username if username else f"User {uid}"),
                         "username": username,
                         "mutual": bool(getattr(user, "mutual_contact", False))})
        rows.sort(key=lambda r: (r["name"].casefold(), r["id"]))
        return rows
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_invite_members(chat_id, user_ids, client=None) -> dict:
    """Invite up to ten explicitly-selected contacts to an owned group/channel."""
    try:
        ids = list(dict.fromkeys(int(x) for x in (user_ids or [])))
    except Exception as exc:
        raise ValueError("Selected contact ID is invalid.") from exc
    if not ids:
        raise ValueError("Select at least one contact.")
    if len(ids) > 10:
        raise ValueError("Select no more than 10 contacts per invite operation.")
    client, owned = await _telegram_studio_client(client)
    try:
        from telethon.tl.functions.contacts import GetContactsRequest
        from telethon.tl.functions.channels import InviteToChannelRequest
        result = await client(GetContactsRequest(hash=0))
        contacts = {int(u.id): u for u in (getattr(result, "users", []) or [])
                    if not getattr(u, "deleted", False) and not getattr(u, "bot", False)}
        missing = [uid for uid in ids if uid not in contacts]
        if missing:
            raise ValueError("Direct adding is limited to contacts. Use the invite link for non-contacts.")
        chat = await _telegram_studio_find_chat(client, chat_id)
        added, failed = [], []
        for index, uid in enumerate(ids):
            try:
                await client(InviteToChannelRequest(channel=chat, users=[contacts[uid]]))
                added.append(uid)
                if index < len(ids) - 1:
                    await asyncio.sleep(1.0)
            except Exception as exc:
                wait = float(flood_wait_seconds(exc) or 0.0)
                failed.append({"id": uid, "error": f"{type(exc).__name__}: {exc}"})
                if wait > 0:
                    for pending_id in ids[index + 1:]:
                        failed.append({"id": pending_id,
                                       "error": f"Not attempted: Telegram rate limit; wait about {int(wait)}s."})
                    break
        return {"added": added, "failed": failed}
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_export_link(chat_id, client=None) -> str:
    """Return a public URL or create a private invite link for a selected dialog."""
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        username = str(getattr(chat, "username", "") or "").strip()
        if username:
            return f"https://t.me/{username}"
        from telethon.tl.functions.messages import ExportChatInviteRequest
        result = await client(ExportChatInviteRequest(peer=chat))
        link = str(getattr(result, "link", "") or "")
        if not link:
            raise RuntimeError("Telegram did not return an invite link.")
        return link
    finally:
        await _telegram_studio_close(client, owned)


def _telegram_studio_is_basic_group(chat) -> bool:
    """True only for Telegram's basic Chat peer; not channels/supergroups."""
    return type(chat).__name__.lower() in {"chat", "inputpeerchat"} and not bool(
        getattr(chat, "megagroup", False) or getattr(chat, "broadcast", False))


async def _telegram_studio_require_target_send_as(client, chat):
    """Preflight destination identity; basic groups use the explicitly selected signed-in account."""
    # Telegram basic groups have no channel-style Send As list. Owner explicitly
    # chose the connected personal account for basic-group posts. Do not call
    # channels.getSendAs on these peers; channels/supergroups still require the
    # target identity to be authorized and never fall back after a failure.
    if _telegram_studio_is_basic_group(chat):
        return None
    title = str(getattr(chat, "title", "") or getattr(chat, "username", "") or
                getattr(chat, "id", "destination"))
    try:
        from telethon.tl.functions.channels import GetSendAsRequest
        from telethon.utils import get_peer_id
    except Exception as exc:
        raise RuntimeError(
            "Telegram Send As permission check is unavailable. Install the packaged "
            "Telethon version >=1.41 and restart; nothing was sent.") from exc
    try:
        result = await client(GetSendAsRequest(peer=chat))
        options = list(getattr(result, "peers", []) or [])
        target_id = int(get_peer_id(chat))
        allowed = False
        premium_required = False
        for option in options:
            peer = getattr(option, "peer", option)
            try:
                if int(get_peer_id(peer)) == target_id:
                    allowed = True
                    premium_required = bool(getattr(option, "premium_required", False))
                    break
            except Exception:
                continue
    except Exception as exc:
        raise RuntimeError(
            f"Could not verify Telegram Send As permission for {title}; no message was sent. "
            f"Telegram check error: {type(exc).__name__}: {exc}") from exc
    if not allowed:
        raise RuntimeError(
            f"Telegram does not allow this account to send as {title}. Open that destination in Telegram "
            "and check its Send As identity list. The destination itself must be available there; if it is "
            "missing, the owner/admin must grant the required posting/anonymous-admin rights. "
            "Nothing was sent; EdgeQuant will not fall back to your personal account.")
    if premium_required:
        raise RuntimeError(
            f"Telegram lists {title} as a Send As identity but marks it Premium-only for this account. "
            "Nothing was sent; no personal-account fallback was attempted.")
    return chat


async def _telegram_studio_dispatch_as(client, chat, sender, *args, **kwargs):
    """Send basic groups as the explicitly chosen account; channel peers as exact target."""
    if _telegram_studio_is_basic_group(chat):
        # For a basic private group, the account itself is the sender; there is
        # no group Send As identity and no channel-identity fallback involved.
        return await sender(chat, *args, **kwargs)
    try:
        return await sender(chat, *args, send_as=chat, **kwargs)
    except Exception as exc:
        detail = str(exc)
        if (type(exc).__name__ == "SendAsPeerInvalidError" or
                "can't send messages as the specified peer" in detail.lower()):
            title = str(getattr(chat, "title", "") or getattr(chat, "username", "") or
                        getattr(chat, "id", "destination"))
            raise RuntimeError(
                f"Telegram rejected sending as {title}. The target identity is not authorized for this "
                "destination. Check the Telegram Send As selector and grant the required owner/admin/"
                "anonymous-posting rights. No message was sent and EdgeQuant did not fall back to your "
                f"personal account. Telegram detail: {type(exc).__name__}: {detail}") from exc
        raise


async def telegram_studio_send_signal(chat_id, caption, logo_path, client=None):
    """Send a signal as its destination identity; Telegram permission errors fail closed."""
    caption = str(caption or "").strip()
    if not caption:
        raise ValueError("Signal message is empty.")
    if len(caption) > 1000:
        raise ValueError("Keep the signal caption under 1000 characters for the logo photo.")
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        await _telegram_studio_require_target_send_as(client, chat)
        logo = Path(logo_path) if logo_path else None
        if logo is not None and logo.is_file():
            sent = await _telegram_studio_dispatch_as(
                client, chat, client.send_file, str(logo), caption=caption, force_document=False)
        else:
            sent = await _telegram_studio_dispatch_as(
                client, chat, client.send_message, caption, parse_mode=None, link_preview=False)
        if isinstance(sent, (list, tuple)):
            sent = sent[0] if sent else None
        return int(getattr(sent, "id", 0) or 0)
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_send_message(chat_id, text, client=None):
    """Send as the explicitly selected destination identity; never fall back to the user."""
    text = str(text or "").strip()
    if not text:
        raise ValueError("Message text is empty.")
    try:
        units = len(text.encode("utf-16-le")) // 2
    except UnicodeError as exc:
        raise ValueError("Message contains invalid Unicode text.") from exc
    if units > 4096:
        raise ValueError("Telegram posts must be no more than 4096 UTF-16 characters.")
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        await _telegram_studio_require_target_send_as(client, chat)
        sent = await _telegram_studio_dispatch_as(
            client, chat, client.send_message, text, parse_mode=None, link_preview=False)
        if isinstance(sent, (list, tuple)):
            sent = sent[0] if sent else None
        return int(getattr(sent, "id", 0) or 0)
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_send_file(chat_id, file_path, caption="", client=None):
    """Send a local file as the destination identity; permission failures are not retried."""
    path = Path(str(file_path or "")).expanduser()
    if not path.is_file():
        raise ValueError("Choose an existing file to attach.")
    caption = str(caption or "").strip()
    try:
        units = len(caption.encode("utf-16-le")) // 2
    except UnicodeError as exc:
        raise ValueError("Caption contains invalid Unicode text.") from exc
    if units > 1024:
        raise ValueError("Telegram file captions must be no more than 1024 UTF-16 characters.")
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        await _telegram_studio_require_target_send_as(client, chat)
        sent = await _telegram_studio_dispatch_as(
            client, chat, client.send_file, str(path), caption=caption,
            force_document=False, parse_mode=None)
        if isinstance(sent, (list, tuple)):
            sent = sent[0] if sent else None
        message_id = int(getattr(sent, "id", 0) or 0)
        if not message_id:
            raise RuntimeError("Telegram returned no message ID for the uploaded file.")
        return message_id
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_send_poll(chat_id, question, options, multiple=False,
                                    anonymous=True, client=None):
    """Send a poll as its destination identity; permission failures are not retried."""
    question = str(question or "").strip()
    answers = [str(item or "").strip() for item in (options or [])]
    answers = [item for item in answers if item]
    if not question:
        raise ValueError("Enter a poll question.")
    if len(question.encode("utf-16-le")) // 2 > 300:
        raise ValueError("Telegram poll questions must be no more than 300 characters.")
    if not 2 <= len(answers) <= 10:
        raise ValueError("A Telegram poll needs 2 to 10 non-empty answer options.")
    if any(len(item.encode("utf-16-le")) // 2 > 100 for item in answers):
        raise ValueError("Each Telegram poll option must be no more than 100 characters.")
    if len({item.casefold() for item in answers}) != len(answers):
        raise ValueError("Poll answer options must be unique.")
    client, owned = await _telegram_studio_client(client)
    try:
        try:
            from telethon.tl.types import InputMediaPoll, Poll, PollAnswer, TextWithEntities
        except Exception as exc:
            raise RuntimeError(
                "Telethon poll support is unavailable in this installation; rebuild/install Telethon.") from exc
        chat = await _telegram_studio_find_chat(client, chat_id)
        await _telegram_studio_require_target_send_as(client, chat)
        poll_kwargs = {
            "id": (secrets.randbits(63) or 1),
            "question": TextWithEntities(text=question, entities=[]),
            "answers": [PollAnswer(text=TextWithEntities(text=item, entities=[]),
                                   option=bytes([index + 1]))
                        for index, item in enumerate(answers)],
            "closed": False, "public_voters": not bool(anonymous),
            "multiple_choice": bool(multiple), "quiz": False}
        # Telethon 1.45+ follows the current TL Poll constructor, which requires
        # hash=0 for a newly-created poll. Older supported Telethon releases do
        # not expose this field, so inspect the generated constructor instead of
        # unconditionally passing it and breaking the 1.41+ compatibility range.
        try:
            if "hash" in inspect.signature(Poll).parameters:
                poll_kwargs["hash"] = 0
        except (TypeError, ValueError):
            pass
        poll = Poll(**poll_kwargs)
        # Use Telethon's high-level send_message(media) path so it resolves the
        # destination and extracts the returned Message ID consistently across
        # Telethon versions. No retry: an exception may represent an uncertain send.
        sent = await _telegram_studio_dispatch_as(
            client, chat, client.send_message, file=InputMediaPoll(poll=poll),
            parse_mode=None, link_preview=False)
        if isinstance(sent, (list, tuple)):
            sent = sent[0] if sent else None
        message_id = int(getattr(sent, "id", 0) or 0)
        if not message_id:
            raise RuntimeError("Telegram returned no message ID for the poll.")
        return message_id
    finally:
        await _telegram_studio_close(client, owned)

async def telegram_studio_edit_signal(chat_id, message_id, caption, client=None):
    """Edit one previously published Studio message/caption."""
    caption = str(caption or "").strip()
    if not caption:
        raise ValueError("Signal message is empty.")
    if len(caption) > 1024:
        raise ValueError("Keep an edited Telegram message under 1024 characters.")
    try:
        mid = int(message_id)
    except Exception as exc:
        raise ValueError("Telegram message ID is invalid.") from exc
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        await client.edit_message(chat, mid, caption)
        return mid
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_delete_signal(chat_id, message_id, client=None):
    """Delete a Studio post only when Telegram permissions allow it."""
    try:
        mid = int(message_id)
    except Exception as exc:
        raise ValueError("Telegram message ID is invalid.") from exc
    client, owned = await _telegram_studio_client(client)
    try:
        chat = await _telegram_studio_find_chat(client, chat_id)
        result = await client.delete_messages(chat, [mid])
        return bool(result)
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_pending_join_requests(chat_id, client=None) -> list:
    """Read pending join requests for a group/channel where this account is admin."""
    client, owned = await _telegram_studio_client(client)
    try:
        from telethon.tl.functions.channels import GetParticipantsRequest
        from telethon.tl.types import ChannelParticipantsRequests
        chat = await _telegram_studio_find_chat(client, chat_id)
        result = await client(GetParticipantsRequest(
            channel=chat, filter=ChannelParticipantsRequests(), offset=0, limit=100, hash=0))
        users = {int(getattr(u, "id", 0)): u for u in (getattr(result, "users", []) or [])}
        rows = []
        for participant in (getattr(result, "participants", []) or []):
            user_id = int(getattr(participant, "user_id", 0) or 0)
            user = users.get(user_id)
            if not user_id or user is None:
                continue
            name = " ".join(x for x in (getattr(user, "first_name", ""),
                                         getattr(user, "last_name", "")) if x).strip()
            username = str(getattr(user, "username", "") or "")
            rows.append({"id": user_id, "name": name or ("@" + username if username else f"User {user_id}"),
                         "username": username})
        return rows
    finally:
        await _telegram_studio_close(client, owned)


async def telegram_studio_decide_join_requests(chat_id, user_ids, approved: bool,
                                                client=None) -> dict:
    """Approve/reject explicitly selected join requests (Telegram admin permission required)."""
    try:
        ids = list(dict.fromkeys(int(x) for x in (user_ids or [])))
    except Exception as exc:
        raise ValueError("Selected requester ID is invalid.") from exc
    if not ids:
        raise ValueError("Select at least one pending request.")
    if len(ids) > 100:
        raise ValueError("Select at most 100 requests per operation.")
    client, owned = await _telegram_studio_client(client)
    try:
        from telethon.tl.functions.messages import HideChatJoinRequestRequest
        chat = await _telegram_studio_find_chat(client, chat_id)
        done, failed = [], []
        for user_id in ids:
            try:
                user = await client.get_input_entity(user_id)
                await client(HideChatJoinRequestRequest(
                    peer=chat, user_id=user, approved=bool(approved)))
                done.append(user_id)
            except Exception as exc:
                failed.append({"id": user_id, "error": f"{type(exc).__name__}: {exc}"})
        return {"done": done, "failed": failed, "approved": bool(approved)}
    finally:
        await _telegram_studio_close(client, owned)

def acquire_singleton():
    """Make sure only ONE EdgeQuant Sentinel runs at a time (Telegram session must not
    be opened twice - that is what causes 'database is locked')."""
    global _lock_handle
    path = HERE / LOCK_FILE
    try:
        fh = open(path, "a+", encoding="utf-8")
        if fh.tell() == 0:
            fh.write("0")
            fh.flush()
        fh.seek(0)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        try:
            fh.close()
        except Exception:
            pass
        return None
    _lock_handle = fh
    return fh


def release_singleton() -> None:
    global _lock_handle
    if _lock_handle is None:
        return
    try:
        _lock_handle.seek(0)
        if os.name == "nt":
            import msvcrt
            msvcrt.locking(_lock_handle.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(_lock_handle.fileno(), fcntl.LOCK_UN)
    except Exception:
        pass
    try:
        _lock_handle.close()
    except Exception:
        pass
    _lock_handle = None


def explain_login_error(exc: Exception) -> str:
    """Telegram login problems -> a message in plain language."""
    name = type(exc).__name__
    msg = str(exc)
    low = msg.lower()

    if "database is locked" in low or "operationalerror" in low:
        return (f"{name}: {msg}\n"
                f"        >> {BOT_NAME} or the session file is ALREADY OPEN somewhere.\n"
                f"           * close every {BOT_NAME} window (START / DEBUG / LIST)\n"
                "           * Task Manager (Ctrl+Shift+Esc) -> find python.exe -> End task\n"
                "           * start it again - only ONE window at a time\n"
                "           * close the OLD bot.py too, and any other Telegram Python\n"
                "             window (they all open the same session file)\n"
                "           * still locked? Task Manager -> end EVERY python.exe")
    if "authkeyduplicated" in name.lower():
        return (f"{name}: {msg}\n"
                "        >> The session was used from two different computers / IPs.\n"
                f"           Delete this file and log in again:\n"
                f"           {HERE / (SESSION_NAME + '.session')}")
    _dead_kind = session_death_kind(exc)
    if _dead_kind:
        if _dead_kind == "deactivated":
            return (f"{name}: {msg}\n"
                    "        >> Telegram says this account is deactivated. A new code\n"
                    "           will not fix it; check the account with Telegram support.")
        return (f"{name}: {msg}\n"
                "        >> Telegram rejected the saved authorization key; it cannot be reused.\n"
                "        >> In the app the dead session is parked. Press SEND CODE again\n"
                "           for a fresh code, then enter that new code (and 2FA if asked).\n"
                "        >> Close other EdgeQuant windows first; use one login window only.")
    if "apiidinvalid" in name.lower() or "api_id" in low:
        return (f"{name}: {msg}\n"
                "        >> Check the local EDGEQUANT_API_ID / EDGEQUANT_API_HASH\n"
                "           environment settings and compare them with\n"
                "           https://my.telegram.org -> API development tools")
    if "sessionpasswordneeded" in name.lower():
        return (f"{name}: {msg}\n"
                "        >> Your Telegram has 2-step verification (password). Run this file\n"
                "           in a cmd window (not by double-click) so you can type the password:\n"
                "           python edgequant_auto.py")
    if "phonenumberinvalid" in name.lower() or "phonecodeinvalid" in name.lower() \
            or "phonecodeexpired" in name.lower():
        return (f"{name}: {msg}\n"
                "        >> The phone number / code was not what Telegram expected.\n"
                f"           Delete {SESSION_NAME}.session and try again (country code first).")
    if "floodwait" in name.lower():
        return f"{name}: {msg}\n        >> Telegram asked us to wait. Try again in a few minutes."
    return (f"{name}: {msg}\n"
            "        >> Full technical detail was saved to:  " + ERROR_LOG)


async def safe_start(client):
    """client.start() with a friendly message instead of a traceback."""
    global _LAST_LOGIN_EXC
    try:
        await client.start()
        return True
    except Exception as exc:
        _LAST_LOGIN_EXC = exc
        log(explain_login_error(exc), "err")
        rule("=")
        return False

# =========================================================================== #
#  v1.9.5  -  "The key is not registered in the system"
#             Telegram ended the login.  THIS MUST NEVER STOP THE BOT.
# =========================================================================== #
SESSION_DEAD_FILE = "edgequant_session_dead.json"
SESSION_RETRY_S = 20.0           # how often we look for a new login
STOP_REQUESTED = False           # the STOP button sets this (even while waiting)
_LAST_LOGIN_EXC = None           # what the last login attempt threw


class SessionDeadError(RuntimeError):
    """v1.9.5: the Telegram login is dead - only a NEW login can fix it."""


def stop_requested() -> bool:
    return bool(STOP_REQUESTED)


def request_stop() -> None:
    """The STOP button (and the wait-for-login loop) use this."""
    global STOP_REQUESTED
    STOP_REQUESTED = True


def clear_stop() -> None:
    global STOP_REQUESTED
    STOP_REQUESTED = False


def session_death_kind(exc) -> str:
    """'' = an ordinary error.  Else the login is gone for good.

    Telegram answers 401 AUTH_KEY_UNREGISTERED -> "The key is not registered in
    the system (caused by GetDialogsRequest)".  No reconnect can fix that - only
    a new login can.  Treating it like a network hiccup hid the real problem (and
    treating it as fatal killed the bot), so it gets its own path.
    """
    try:
        name = type(exc).__name__.lower()
        low = f"{name} {exc}".lower()
    except Exception:
        return ""
    if "sessiondead" in name:
        return "unregistered"
    if "authkeyunregistered" in name or "key is not registered" in low:
        return "unregistered"
    if "authkeyduplicated" in name or "key is already registered" in low:
        return "duplicated"
    if "authkeyinvalid" in name or "authkeypermempty" in name or \
            "auth key invalid" in low:
        return "invalid"
    if "sessionrevoked" in name or ("session" in low and "revoked" in low):
        return "revoked"
    if "userdeactivated" in name or "user is deactivated" in low or \
            "user_deactivated" in low:
        return "deactivated"
    return ""


def session_dead_text(kind: str = "") -> str:
    """What happened + exactly what to do (plain words)."""
    why = {
        "unregistered": "Telegram ended this login (the saved key is no longer valid)",
        "duplicated": ("the same login file was used from two places at once "
                       "(two windows / two computers)"),
        "invalid": "the saved key was rejected by Telegram",
        "revoked": "this login was logged out (Telegram -> Devices -> Terminate)",
        "deactivated": "the Telegram account itself is deactivated",
    }.get(kind or "", "Telegram ended this login")
    return (
        f"TELEGRAM SESSION IS DEAD  -  {why}\n"
        "   >> DO THIS:   run  EDGEQUANT-LOGIN.bat   (or press the LOGIN button in the app)\n"
        "                  -> your phone number -> the code that arrives INSIDE Telegram\n"
        "   >> The bot KEEPS RUNNING while you do it and picks the new login up by\n"
        "      itself - you do NOT have to start it again and it does not lose anything.\n"
        "   >> How this happens:   two EdgeQuant windows open at once,  EDGEQUANT-LOGIN\n"
        "      run while the bot was running,  or Telegram -> Settings -> Devices ->\n"
        "      Terminate all sessions.   Keep ONE window at a time.\n"
        "   >> SINHALA: Telegram eken me login eka cancel karala.  Aluthin LOGIN karanna -\n"
        "      bot eka duwan-nawa, oya login kalama eka-th-anma wada patan gan-nawa."
    )


def session_dead_write(kind: str, where: str = "", msg: str = "") -> None:
    """Put the flag where the desktop app and the next run can see it."""
    try:
        (HERE / SESSION_DEAD_FILE).write_text(
            json.dumps({"ts": time.time(), "kind": kind or "unknown",
                        "where": where, "message": (msg or "")[:400],
                        "advice": session_dead_text(kind)}), encoding="utf-8")
    except Exception:
        pass
    try:
        tg_set_state(online=False, phase="session_dead",
                     reason="the Telegram login is dead - press LOGIN "
                            "(EDGEQUANT-LOGIN.bat)")
        tg_status_write()
    except Exception:
        pass


def session_dead_read(max_age_s: float = 0.0) -> dict:
    """{} = no dead login.  max_age_s > 0 = ignore an old flag."""
    try:
        data = json.loads((HERE / SESSION_DEAD_FILE).read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    if max_age_s and (time.time() - float(data.get("ts") or 0)) > max_age_s:
        return {}
    return data


def session_dead_clear() -> None:
    try:
        (HERE / SESSION_DEAD_FILE).unlink()
    except Exception:
        pass


def quarantine_session() -> str:
    """Park every possible session stem so a dead legacy fallback is not reused."""
    moved = []
    stems = [SESSION_NAME] + [x for x in SESSION_FALLBACKS if x != SESSION_NAME]
    suffixes = (".session", ".session-journal", ".session-wal", ".session-shm")
    stamp = int(time.time())
    for stem in stems:
        for suffix in suffixes:
            p = HERE / (stem + suffix)
            if p.exists():
                try:
                    tgt = p.with_name(p.name + f".dead-{stamp}")
                    p.replace(tgt)
                    moved.append(tgt.name)
                except Exception:
                    pass
    return ", ".join(moved)


async def wait_for_new_login(kind: str = "", where: str = "") -> "object":
    """Stay alive until a NEW login exists, then hand back a fresh client.

    None = the user pressed STOP (or Ctrl+C) while we were waiting.
    """
    moved = quarantine_session()
    session_dead_write(kind, where)
    rule("=")
    log("Telegram : the session ended (only a new login can fix it)", "err")
    for line in session_dead_text(kind).splitlines():
        log(line, "warn")
    if moved:
        log(f"Telegram : the dead login file was parked as {moved}", "info")
    log(f"Telegram : the bot is STILL RUNNING - looking for a new login every "
        f"{SESSION_RETRY_S:.0f} s (press STOP to give up)", "info")
    rule("=")
    tries = 0
    while not stop_requested():
        try:
            await asyncio.sleep(SESSION_RETRY_S)
        except asyncio.CancelledError:
            return None
        if stop_requested():
            break
        tries += 1
        cl = None
        try:
            cl = TelegramClient(str(session_path()), int(API_ID), API_HASH)
            await cl.connect()
            me = await cl.get_me()
            if me:
                session_dead_clear()
                who = (f"{getattr(me, 'first_name', '')} "
                       f"(@{getattr(me, 'username', '-')})").strip()
                log(f"Telegram : NEW LOGIN FOUND - {who} - back to work", "ok")
                return cl
            try:
                await cl.disconnect()
            except Exception:
                pass
        except Exception as exc:
            try:
                if cl is not None:
                    await cl.disconnect()
            except Exception:
                pass
            if tries in (1, 3) or tries % 15 == 0:
                log(f"Telegram : still logged out ({type(exc).__name__}) - waiting.  "
                    f"Run EDGEQUANT-LOGIN.bat and type the code Telegram sends you.",
                    "warn")
        if tries % 30 == 0:
            log(f"the bot is alive and waiting for your login "
                f"({tries * SESSION_RETRY_S / 60:.0f} min so far)", "info")
    log("Telegram : stop was pressed while waiting for a login", "warn")
    return None


# =========================================================================== #
#  PART 4 - PRICE HELPERS
# =========================================================================== #
RECENT_ENTRIES: list = []      # (source, symbol, direction, price, ts)
                               #   what THIS channel already took (this session,
                               #   so the filter also works in TEST RUN)


def same_symbol(a, b) -> bool:
    """XAUUSD == XAUUSD.ic == XAUUSD.a   (broker suffixes do not matter)."""
    ca = re.sub(r"[^A-Z0-9]", "", str(a or "").upper())
    cb = re.sub(r"[^A-Z0-9]", "", str(b or "").upper())
    if not ca or not cb:
        return False
    if ca == cb:
        return True
    return (len(ca) >= 3 and len(cb) >= 3
            and (ca.startswith(cb) or cb.startswith(ca)))


def taken_entries(src="", symbol="", direction="", window=None) -> dict:
    """Deprecated compatibility shim: content never marks a new post as taken."""
    return {}


def dedup_entries(entries, src="", symbol="", direction="", window=None) -> tuple:
    """Legacy compatibility shim: never suppress a distinct Telegram post by content.

    Exactly-once handling is keyed only by chat ID + Telegram message ID in
    ``signal_message_is_new`` and the persisted catch-up cursor/journal.
    """
    return list(entries or []), []


def pip_size_of(symbol: str) -> float:
    """GOLD/XAUUSD = 0.1 (100 pips = $10) | US30 = 1.0 | JPY = 0.01 | FX = 0.0001"""
    s = (symbol or "").upper()
    for key, val in (SYMBOL_PIPS or {}).items():          # your own table first
        if key.upper() in s:
            return float(val)
    if s.startswith("XAU"):
        return 0.1
    if s.startswith("XAG"):
        return 0.01
    if s.startswith(("US30", "US100", "US500", "NAS", "GER", "DAX", "UK100", "JP225")):
        return 1.0
    if "JPY" in s:
        return 0.01
    if s.startswith(("BTC", "ETH")):
        return 1.0
    return 0.0001


def rnd(value: float, digits: int) -> float:
    return round(float(value), int(digits))


class Broker:
    """The bits of MT5 symbol_info we need (so the plan can be tested without MT5)."""

    def __init__(self, symbol="XAUUSD", digits=2, point=0.01, stops_level=0.0,
                 freeze_level=0.0, volume_min=0.01, volume_step=0.01,
                 volume_max=100.0, tick_value=1.0, tick_size=0.01, spread=0.0):
        self.symbol = symbol
        self.digits = int(digits)
        self.point = float(point)
        self.stops_level = float(stops_level)
        self.freeze_level = float(freeze_level)
        self.volume_min = float(volume_min)
        self.volume_step = float(volume_step)
        self.volume_max = float(volume_max)
        self.tick_value = float(tick_value)
        self.tick_size = float(tick_size)
        self.spread = float(spread)

    @property
    def min_dist(self) -> float:
        """broker demand: how far a pending price / SL / TP must be from the market"""
        return max(self.stops_level, self.freeze_level) * self.point + 2 * self.point


def normalize_lot(br: Broker, lot: float) -> float:
    step = br.volume_step or 0.01
    lot = math.floor(max(lot, br.volume_min) / step) * step
    lot = min(lot, br.volume_max)
    return rnd(lot, 2)


def shift_earlier(price: float, market: float, pips: float, pip: float, digits: int,
                  always: bool = False, direction: str = "") -> tuple:
    """Apply the owner-confirmed directional offset to a signal entry.

    BUY entries move down; SELL entries move up. ``market`` is retained for
    backwards-compatible callers without a direction. The caller validates the
    unchanged signal SL against the shifted entry before building orders.
    """
    if pips <= 0 or price <= 0:
        return rnd(price, digits), ""
    step = pips * pip
    side = str(direction or "").upper()
    if side == "BUY":
        new, label = price - step, "down"
    elif side == "SELL":
        new, label = price + step, "up"
    else:
        # Compatibility for callers without a direction: move toward market.
        if market <= 0:
            return rnd(price, digits), "direction unavailable; not shifted"
        new = price - step if price > market else price + step
        label = "down" if new < price else "up"
    return rnd(new, digits), f"shifted {label} {pips:g} pips for {side or 'the signal'}"


def shift_target_toward_entry(target: float, direction: str, entry: float,
                              pips: float, pip: float, digits: int) -> tuple:
    """Move the selected signal TP inward by the configured pip offset."""
    try:
        target, entry = float(target), float(entry)
        step = max(0.0, float(pips)) * float(pip)
    except (TypeError, ValueError):
        return 0.0, "invalid target/entry/offset"
    side = str(direction or "").upper()
    if target <= 0 or entry <= 0 or step <= 0:
        return rnd(target, digits), ""
    if side == "BUY":
        adjusted = target - step
    elif side == "SELL":
        adjusted = target + step
    else:
        return rnd(target, digits), "unknown direction; TP not shifted"
    return rnd(adjusted, digits), f"TP moved {step:g} price units toward entry ({pips:g} pips)"


def layer_plan(price: float, quick: float, tp_signal: float, tp_label: str,
               n_layers, direction: str, digits: int,
               quick_pips_setting: float = None) -> list:
    """[(tp, tag, label)] - the TP of EVERY layer at ONE entry price.

    layer 1        = the configurable quick TP (LAYER1_TP_PIPS, Dashboard control)
    layer n        = the selected signal TP (TP3 by default)
    the ones between = spread evenly between the two
    n_layers = 1   = a single order that uses the channel TP
    """
    try:
        n = int(n_layers)
    except Exception:
        n = int(FIXED_LAYERS_PER_ENTRY)
    n = max(1, min(8, n))
    try:
        quick_label_pips = float(quick_pips_setting if quick_pips_setting is not None
                                 else LAYER1_TP_PIPS)
    except Exception:
        quick_label_pips = float(LAYER1_TP_PIPS)
    if n == 1:
        tp = tp_signal if tp_signal else quick
        return [(tp, (tp_label.lower() if tp_label else "same"), "the channel TP")]
    if not tp_signal:
        tp_signal = quick
    out = []
    # The user-mandated two-layer strategy always keeps the signal TP on L2.
    # Runner mode is reserved for three-or-more layers; it cannot replace L2's TP.
    runner_last = bool(RUNNER_MODE) and n >= 3
    for i in range(n):
        if i == 0:
            out.append((quick, f"quick{quick_label_pips:g}", f"quick +{quick_label_pips:g} pips"))
            continue
        if (i == n - 1 and runner_last):
            # v1.8.0 RUNNER: the last layer gets no fixed TP - the SL follows
            # the price (see runner_one) so a big trend day is not cut short.
            out.append((0.0, "runner", f"runner - no TP, SL follows (+{RUNNER_START_PIPS:g} pips)"))
            continue
        if i == n - 1 or abs(tp_signal - quick) < 1e-9:
            out.append((tp_signal, (tp_label.lower() if tp_label else "tp"),
                        (tp_label or "channel TP")))
            continue
        frac = i / float(n - 1)
        d_q = (quick - price) if direction == "BUY" else (price - quick)
        d_s = (tp_signal - price) if direction == "BUY" else (price - tp_signal)
        d = d_q + (d_s - d_q) * frac
        tp = rnd(price + d if direction == "BUY" else price - d, digits)
        out.append((tp, f"mid{i}", f"layer {i + 1}"))
    return out


def pending_type_for(direction: str, price: float, ask: float, bid: float, br: Broker) -> str:
    """Which pending order type triggers when the market reaches `price`?

    BUY : below the market -> BUY LIMIT      above the market -> BUY STOP
    SELL: above the market -> SELL LIMIT     below the market -> SELL STOP
    """
    if PENDING_TYPE in ("LIMIT", "STOP"):
        base = PENDING_TYPE
    else:
        if direction == "BUY":
            base = "LIMIT" if price < ask else "STOP"
        else:
            base = "LIMIT" if price > bid else "STOP"
    return f"{direction}_{base}"


# =========================================================================== #
#  PART 5 - ORDER PLAN   (pure function -> fully testable, see --selftest)
# =========================================================================== #
def build_plan(sig, category: str, br: Broker, ask: float, bid: float, balance: float = 0.0,
               quick_tp_pips: float = None) -> list:
    """Turn one parsed signal into the exact list of orders to send.

    Each order: {"kind", "type", "price", "sl", "tp", "tag", "lot"}
    """
    plan: list = []
    direction = (sig.direction or "").upper()
    if direction not in ("BUY", "SELL"):
        return plan

    symbol = sig.symbol or ""
    pip = pip_size_of(symbol)
    market = ask if direction == "BUY" else bid
    if market <= 0:
        market = 0.0

    entries = [float(x) for x in (sig.entries or [])]
    sl_signal = float(sig.sl) if sig.sl else 0.0
    tps = [float(x) for x in (sig.tps or [])]
    # ---- layer 2 takes the channel TP: TP3 when there are 3 or more, else the
    #      last one it wrote (TP2 for two, TP1 for one) ----------------------
    if tps:
        tp_idx = min(int(LAYER2_TP_MAX_INDEX), len(tps) - 1)
        tp_signal = tps[tp_idx]
        tp_label = f"TP{tp_idx + 1}"
    else:
        tp_signal = 0.0
        tp_label = ""
    entry_marked = bool(getattr(sig, "entry_marked", False))

    # ---------------------------------------------------------------- mode ---
    if category == "LIMIT":
        pending = True                        # LIMIT channel -> always pending orders
    elif category == "MARKET":
        # MARKET-category sources must never turn explicit entries/ranges into
        # pending or limit orders. Use the current broker quote immediately.
        pending = False
        if entries:
            log("      MARKET channel: entry levels are informational; executing at the current market price", "info")
    elif not entries:
        pending = False                       # no entry price -> market order
    elif entry_marked or (len(entries) >= 2 and MARKET_CHANNEL_RANGE_IS_PENDING):
        # a real entry price / range ("ENTER IN 4185" / "ENTRY:" / "@ 4185" / "BUY 4155-4160")
        pending = (MARKET_CHANNEL_WITH_PRICE == "PENDING")
    else:
        # one bare price in a MARKET channel = the price it is trading at right now
        #   "MARKET"  (default) : fill immediately at the live price - there is no
        #                         entry level, so nothing can be moved 10 pips earlier
        #   "PENDING"           : treat that one price as an entry -> a pending order
        #                         10 pips earlier (like the channels that give a range)
        pending = (str(MARKET_CHANNEL_SINGLE_PRICE).strip().upper() == "PENDING")
        if not pending:
            log(f"      one price ({entries[0]:g}) in a MARKET channel -> an instant fill "
                f"at the live price (an entry level to move {SHIFT_PIPS:g} pips earlier "
                f"only exists when the channel gives a range or an ENTRY line)", "info")

    # ------------------------------------------------------------- lot size --
    _cfg = channel_cfg()                       # v1.8.0 - per channel settings
    # Fixed strategy: two orders at each entry, never altered by legacy UI,
    # state-file, or per-channel layer overrides.
    _layers = 2
    try:
        _legacy_layers = int(_cfg.get("layers") or _layers)
        if _legacy_layers != _layers:
            log(f"      legacy layers={_legacy_layers} for '{_CUR_CHANNEL[0]}' ignored; "
                f"the strategy is fixed at 2 (quick +{LAYER1_TP_PIPS:g} pips + signal TP).", "warn")
    except Exception:
        pass
    levels = entries[:MAX_LEVELS] if pending else []
    per_price = _layers if levels else 0
    n_orders = max(1, (len(levels) * per_price) if levels else 1)
    auto_sl = bool(AUTO_SL_WHEN_MISSING and AUTO_SL_PIPS > 0)

    # a signal with no SL: refused only when nothing can be put in its place
    if REQUIRE_SL and not sl_signal and not auto_sl:
        log("      this signal has no SL and REQUIRE_SL = True -> nothing is placed", "warn")
        return plan
    if not sl_signal:
        if auto_sl:
            log(f"      no SL in the message -> auto SL {AUTO_SL_PIPS:g} pips from each entry",
                "warn")
        else:
            log("      no SL in the message -> trading WITHOUT a stop loss", "warn")

    _fixed_lot = float(_cfg.get("lot") or FIXED_LOT)
    _risk_pct = float(_cfg.get("risk") or RISK_PERCENT)
    if (USE_FIXED_LOT and not _cfg.get("lot")) or not balance:
        lot = _fixed_lot
    else:
        ref = levels[0] if levels else market
        dist = abs(ref - sl_signal) if sl_signal else 0.0
        if dist > 0 and br.tick_size > 0 and br.tick_value > 0:
            lot = (balance * _risk_pct / 100.0 / n_orders) / ((dist / br.tick_size) * br.tick_value)
        else:
            lot = br.volume_min
    lot = normalize_lot(br, lot)
    if _cfg:
        log(f"      channel settings for '{_CUR_CHANNEL[0]}': layers {_layers}"
            + (f" | lot {_cfg.get('lot')}" if _cfg.get("lot") else "")
            + (f" | risk {_cfg.get('risk')}%" if _cfg.get("risk") else "")
            + (f" | expiry {_cfg.get('expiry') or _cfg.get('expiry_h')} h"
               if (_cfg.get("expiry") or _cfg.get("expiry_h")) else ""), "info")

    quick_pips = float(LAYER1_TP_PIPS)
    if quick_tp_pips is not None:
        try:
            _requested_quick = float(quick_tp_pips)
            if not math.isfinite(_requested_quick) or not (1.0 <= _requested_quick <= 100000.0):
                raise ValueError("Provider Layer 1 quick TP must be between 1 and 100000 pips")
            quick_pips = _requested_quick
        except (TypeError, ValueError) as exc:
            log(f"      invalid Provider Layer 1 quick TP override: {exc}", "warn")
            return plan
    # early placement (10 pips) = PENDING orders only.  A market order is filled
    # at the live price, so there is nothing to shift.
    shift_pips = 0
    if pending and (category == "LIMIT" or SHIFT_MARKET_CHANNEL_PENDING):
        shift_pips = SHIFT_PIPS

    def sl_for(price: float) -> float:
        """Stop loss for an order placed at `price`.

        * signal wrote an SL -> that exact price (never shifted / recalculated)
        * no SL in the signal -> AUTO_SL_PIPS away from this entry
        """
        if sl_signal:
            return sl_signal
        if auto_sl:
            step = AUTO_SL_PIPS * pip
            return price - step if direction == "BUY" else price + step
        return 0.0

    def push(kind, otype, price, tp, tag, sl, src=None):
        price = rnd(price, br.digits)
        # ---- the SL is used EXACTLY as the signal wrote it ------------------
        #   (never shifted, never recalculated).  If the broker would refuse
        #   that pair, the order is skipped - the bot never trades without the
        #   signal's stop loss unless IF_SL_IMPOSSIBLE = "no-sl".
        sl_origin = "signal SL" if sl_signal else (f"auto {AUTO_SL_PIPS:g} pips" if sl else "")
        if sl:
            sl_ok = ((sl < price - br.min_dist) if direction == "BUY"
                     else (sl > price + br.min_dist))
            if kind == "PENDING" and not sl_ok:
                plan.append({"kind": "REVIEW", "type": otype, "price": price,
                             "sl": sl, "tp": tp, "tag": tag, "lot": lot,
                             "src_price": float(src) if src is not None else price,
                             "status": "manual_review",
                             "error": "original signal SL violates pending order constraints"})
                return False
            if not sl_ok:
                log(f"      {tag}: {sl_origin} {sl:g} cannot sit with entry {price:g} "
                    f"(wrong side / closer than the broker allows)", "warn")
                if IF_SL_IMPOSSIBLE == "skip":
                    log(f"      {tag}: ORDER SKIPPED - never trading without a stop loss", "err")
                    return False
                log(f"      {tag}: sending WITHOUT a stop loss (IF_SL_IMPOSSIBLE = 'no-sl')", "err")
                sl = 0.0
        if tp:
            if (direction == "BUY" and tp <= price + br.min_dist) or \
               (direction == "SELL" and tp >= price - br.min_dist):
                if kind == "PENDING":
                    plan.append({"kind": "REVIEW", "type": otype, "price": price,
                                 "sl": sl, "tp": tp, "tag": tag, "lot": lot,
                                 "src_price": float(src) if src is not None else price,
                                 "status": "manual_review",
                                 "error": "original pending TP violates broker distance constraints"})
                    return False
                log(f"      {tag}: TP {tp:g} is too close / wrong side of {price:g} -> TP dropped", "warn")
                tp = 0.0
        plan.append({"kind": kind, "type": otype, "price": price,
                     "sl": rnd(sl, br.digits) if sl else 0.0,
                     "tp": rnd(tp, br.digits) if tp else 0.0,
                     "tag": tag, "lot": lot,
                     # the entry price the CHANNEL wrote (before our 10-pip
                     # shift) - the duplicate filter compares this one
                     "src_price": float(src) if src else float(price)})
        return True

    # =============================== MARKET ORDER =========================== #
    if not pending:
        fill = ask if direction == "BUY" else bid
        if fill <= 0:
            log("      market price unknown -> cannot place a market order", "warn")
            return plan
        quick = fill + quick_pips * pip if direction == "BUY" else fill - quick_pips * pip
        tp2 = tp_signal
        if tp_signal:
            tp2, tp_note = shift_target_toward_entry(
                tp_signal, direction, fill, SHIFT_PIPS, pip, br.digits)
            log(f"      Layer 2 {tp_label} {tp_signal:g} -> {tp2:g} ({tp_note})", "info")
            bad_tp2 = ((direction == "BUY" and tp2 <= fill + br.min_dist) or
                       (direction == "SELL" and tp2 >= fill - br.min_dist))
            if bad_tp2:
                log("      shifted signal TP is no longer broker-valid from the live fill -> no orders", "warn")
                return plan
        sl_used = sl_for(fill)
        for _tp, _tag, _lab in layer_plan(fill, quick, tp2, tp_label,
                                          _layers, direction, br.digits, quick_pips):
            push("MARKET", direction, fill, _tp, _tag, sl_used)
        log(f"      market {fill:g} | {_layers} layer(s) | "
            + " | ".join(f"L{i + 1} TP {rnd(t, br.digits):g} ({l})" if t
                         else f"L{i + 1} RUNNER ({l})"
                         for i, (t, _g, l) in enumerate(
                             layer_plan(fill, quick, tp2, tp_label,
                                        _layers, direction, br.digits, quick_pips))), "info")
        return plan

    # =============================== PENDING ORDERS ========================= #
    if not levels:
        log("      this signal has no entry price -> nothing to wait for", "warn")
        return plan

    for entry in levels:
        if (symbol.upper().startswith("XAU") or symbol.upper() == "GOLD") and category == "LIMIT":
            price = rnd(entry + (0.99 if direction == "BUY" else -0.90), br.digits)
            note = "fixed XAUUSD LIMIT offset"
        else:
            price, note = shift_earlier(entry, market, shift_pips, pip, br.digits,
                                    always=SHIFT_ALWAYS, direction=direction)
        # Mandatory directional offset must never cross or invalidate the original signal SL.
        if sl_signal and ((direction == "BUY" and price <= sl_signal) or
                          (direction == "SELL" and price >= sl_signal)):
            log(f"      entry {entry:g}: {shift_pips:g}-pip directional shift would cross "
                f"the unchanged signal SL {sl_signal:g} -> this entry level is skipped", "warn")
            continue
        if note and "assumed" not in note:
            log(f"      entry {entry:g} -> {price:g}  ({note})", "info")
        elif note:
            log(f"      entry {entry:g} -> {price:g}  ({note})", "info")

        # Never move a pending entry to make it broker-valid. Flag for review.
        if (symbol.upper().startswith("XAU") or symbol.upper() == "GOLD") and category == "LIMIT":
            required = br.min_dist
            invalid = ((direction == "BUY" and price >= ask - required) or
                       (direction == "SELL" and price <= bid + required))
            if invalid:
                log(f"      entry {entry:g}: requested {direction} LIMIT {price:g} invalid against live quote; manual review required", "warn")
                plan.append({"kind": "REVIEW", "type": f"{direction}_LIMIT", "price": price,
                             "sl": sl_signal, "tp": tp_signal, "lot": lot,
                             "tag": "manual_review", "src_price": entry,
                             "status": "manual_review", "error": "pending entry violates broker distance/quote constraints"})
                continue
        elif market > 0 and abs(price - market) < br.min_dist:
            gap = br.min_dist * 1.05 if br.min_dist > 0 else pip
            price = rnd(market + gap if float(entry) >= market else market - gap, br.digits)
        if MAX_LEVEL_DISTANCE_PIPS > 0 and market > 0 and \
                abs(price - market) / pip > MAX_LEVEL_DISTANCE_PIPS:
            log(f"      level {entry:g} skipped: more than {MAX_LEVEL_DISTANCE_PIPS:g} pips "
                f"away from the market", "warn")
            continue

        otype = (f"{direction}_LIMIT" if (symbol.upper().startswith("XAU") or symbol.upper() == "GOLD") and category == "LIMIT" else pending_type_for(direction, price, ask, bid, br))
        quick = price + quick_pips * pip if direction == "BUY" else price - quick_pips * pip

        # Layer 2 uses TP3 when available (otherwise the last available target),
        # shifted 10 pips toward this entry. Never substitute another TP if that
        # adjustment would make the signal invalid.
        if not tp_signal:
            log("      signal TP missing -> no protected two-layer plan", "warn")
            continue
        if (symbol.upper().startswith("XAU") or symbol.upper() == "GOLD") and category == "LIMIT":
            tp2, tp_note = tp_signal, "original signal TP unchanged"
        else:
            tp2, tp_note = shift_target_toward_entry(
                tp_signal, direction, price, SHIFT_PIPS, pip, br.digits)
        bad_side = ((direction == "BUY" and tp2 <= price + br.min_dist) or
                    (direction == "SELL" and tp2 >= price - br.min_dist))
        if bad_side:
            log(f"      shifted signal TP {tp2:g} is too close / wrong side of shifted entry "
                f"{price:g} -> this entry level is skipped", "warn")
            continue

        sl_used = sl_for(price)
        _lay = layer_plan(price, quick, tp2, tp_label, _layers, direction,
                          br.digits, quick_pips)
        log(f"      entry {price:g}  {otype}  "
            f"SL {sl_used:g} ({'signal SL, unchanged' if sl_signal else 'AUTO ' + format(AUTO_SL_PIPS, 'g') + ' pips'})  "
            f"| {len(_lay)} layer(s)  "
            + " | ".join(f"L{i + 1} TP {rnd(t, br.digits):g}" for i, (t, _g, _l) in
                         enumerate(_lay)), "info")
        for _tp, _tag, _lab in _lay:
            push("PENDING", otype, price, _tp, _tag, sl_used, src=entry)

    return plan


# =========================================================================== #
#  PART 6 - METATRADER 5
# =========================================================================== #
try:
    import MetaTrader5 as mt5
    HAVE_MT5 = True
except ImportError:                                        # pragma: no cover
    mt5 = None
    HAVE_MT5 = False

try:
    from telethon import TelegramClient, events
    HAVE_TELETHON = True
except ImportError:                                        # pragma: no cover
    HAVE_TELETHON = False
    TelegramClient = None
    events = None

FILLINGS: list = []
GROUPS: list = []          # tickets of one signal -> used for break-even
RECENT: list = []          # exact Telegram chat/message identity guard


def signal_message_is_new(chat_id, message_id, *, recent=None, now=None) -> bool:
    """Exactly-once guard by Telegram event identity, never by signal content."""
    try:
        key = (int(chat_id or 0), int(message_id or 0))
    except (TypeError, ValueError):
        key = (0, 0)
    if not key[0] or key[1] <= 0:
        return True
    rows = RECENT if recent is None else recent
    current = time.time() if now is None else float(now)
    window = max(1.0, float(DUPLICATE_WINDOW_S or 0.0))
    rows[:] = [row for row in rows if current - float(row[1]) < window]
    if any(row[0] == key for row in rows):
        return False
    rows.append((key, current))
    return True


def signal_message_forget(chat_id, message_id, *, recent=None) -> None:
    """Release an ID reservation only after a no-order review-only decision."""
    try:
        key = (int(chat_id or 0), int(message_id or 0))
    except (TypeError, ValueError):
        return
    rows = RECENT if recent is None else recent
    rows[:] = [row for row in rows if row[0] != key]


def signal_message_review_edit_allowed(chat_id, message_id, *, journal_path=None,
                                       audit_path=None) -> bool:
    """Allow an edit only when every durable record for this exact ID is review-only.

    Any placement intent, blocked/uncertain outcome, or missing audit denies the
    edit. This is not content deduplication and cannot replay submitted orders.
    """
    try:
        cid, mid = int(chat_id or 0), int(message_id or 0)
    except (TypeError, ValueError):
        return False
    if not cid or mid <= 0:
        return False
    file = Path(journal_path) if journal_path is not None else HERE / JOURNAL
    actions = []
    try:
        with file.open("r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                try:
                    item = json.loads(line)
                    if (isinstance(item, dict) and
                            int(item.get("chat_id") or 0) == cid and
                            int(item.get("msg_id") or item.get("message_id") or 0) == mid):
                        actions.append(str(item.get("action") or "").strip().lower())
                except Exception:
                    continue
    except OSError:
        return False
    if not actions or any(action != "needs_review" for action in actions):
        return False
    audit = signal_audit_latest(cid, mid, path=audit_path)
    return str(audit.get("outcome") or "").strip().lower() == "needs_review"


# --------------------------------------------------------------------------- #
#  which MT5 terminal are we talking to ?   (one or more brokers)
# --------------------------------------------------------------------------- #
CURRENT_BROKER = {"name": None, "ready": False}



def accounts() -> list:
    """Saved MT5 accounts: static MT5_ACCOUNTS plus the app's broker file.

    An empty configuration falls back to the already-open MAIN terminal. If
    the user has saved an app broker, use those saved account(s) as-is instead
    of silently adding a second, phantom MAIN target.
    """
    merged = list(MT5_ACCOUNTS or [])
    app_accounts = brokers_file_read()
    have = {str((x.get("name") if isinstance(x, dict) else x)).strip().upper()
            for x in merged}
    for extra in app_accounts:
        if str(extra.get("name")).strip().upper() not in have:
            merged.append(extra)
    out = []
    for a in (merged or []):
        if isinstance(a, str):
            a = {"name": Path(a).stem or "MAIN", "path": a}
        name = str(a.get("name") or "MAIN").strip().upper()
        out.append({"name": name,
                    "path": str(a.get("path") or ""),
                    "login": int(a.get("login") or 0),
                    "password": str(a.get("password") or ""),
                    "server": str(a.get("server") or "")})
    if not out:
        out = [{"name": "MAIN", "path": "", "login": 0, "password": "", "server": ""}]
    return out


def brokers_file_read() -> list:
    """Read the existing saved account list (edgequant_brokers.json); safe if missing."""
    try:
        data = json.loads((HERE / BROKERS_FILE).read_text(encoding="utf-8"))
        if isinstance(data, dict):
            data = data.get("brokers") or []
        return [d for d in (data or []) if isinstance(d, dict) and d.get("name")]
    except Exception:
        return []


def _broker_symbol_map_read_strict(path=None) -> dict:
    """Read only the per-account instrument choices; malformed files are not overwritten."""
    file = Path(path) if path is not None else HERE / BROKER_SYMBOL_MAP_FILE
    if not file.exists():
        return {}
    raw = json.loads(file.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError("broker symbol map must be an object")
    rows = raw.get("broker_symbols", raw)
    if not isinstance(rows, dict):
        raise ValueError("broker_symbols must be an object")
    out = {}
    for broker, mapping in rows.items():
        name = str(broker or "").strip().upper()
        if not name or not isinstance(mapping, dict):
            continue
        clean = {}
        for base, symbol in mapping.items():
            canonical = str(base or "").strip().upper()
            exact = str(symbol or "").strip()
            if re.fullmatch(r"[A-Z0-9]{3,24}", canonical) and exact and exact.upper() != "AUTO":
                if len(exact) <= 64 and all(ord(c) >= 32 for c in exact) \
                        and "/" not in exact and "\\" not in exact:
                    clean[canonical] = exact
        if clean:
            out[name] = clean
    return out


def broker_symbol_map_read(path=None) -> dict:
    """User's explicit canonical->exact MT5 symbol choices, keyed by account name."""
    try:
        return _broker_symbol_map_read_strict(path)
    except Exception as exc:
        log(f"      broker symbol map could not be read: {type(exc).__name__}", "warn")
        return {}


def broker_symbol_map_write(mappings: dict, path=None) -> bool:
    """Atomically persist only the separate symbol map (never broker credentials/settings)."""
    file = Path(path) if path is not None else HERE / BROKER_SYMBOL_MAP_FILE
    try:
        clean = {}
        for broker, mapping in (mappings or {}).items():
            name = str(broker or "").strip().upper()
            if not name or not isinstance(mapping, dict):
                continue
            row = {}
            for base, symbol in mapping.items():
                canonical = str(base or "").strip().upper()
                exact = str(symbol or "").strip()
                if not re.fullmatch(r"[A-Z0-9]{3,24}", canonical):
                    continue
                if not exact or exact.upper() == "AUTO":
                    continue
                if len(exact) > 64 or any(ord(c) < 32 for c in exact) \
                        or "/" in exact or "\\" in exact:
                    continue
                row[canonical] = exact
            if row:
                clean[name] = row
        file.parent.mkdir(parents=True, exist_ok=True)
        tmp = file.with_name(file.name + ".new")
        tmp.write_text(json.dumps({"version": 1, "broker_symbols": clean},
                                  indent=2, ensure_ascii=False), encoding="utf-8")
        tmp.replace(file)
        return True
    except Exception as exc:
        log(f"      broker symbol map could not be saved: {type(exc).__name__}", "err")
        return False


def broker_symbol_map_get(broker=None, canonical="XAUUSD", path=None) -> str:
    """Return the exact broker symbol explicitly chosen for this account, if any."""
    name = str(broker or (CURRENT_BROKER or {}).get("name") or DEFAULT_BROKER or "MAIN").strip().upper()
    base = str(canonical or "").strip().upper()
    return str((broker_symbol_map_read(path).get(name) or {}).get(base) or "")


def broker_symbol_map_set(broker, canonical="XAUUSD", exact_symbol="AUTO", path=None) -> bool:
    """Save one broker's exact symbol choice; AUTO clears only that broker/base entry."""
    name = str(broker or "").strip().upper()
    base = str(canonical or "").strip().upper()
    value = str(exact_symbol or "AUTO").strip()
    if not name or len(name) > 64 or not re.fullmatch(r"[A-Z0-9]{3,24}", base):
        return False
    if value.upper() != "AUTO" and (
            len(value) > 64 or any(ord(c) < 32 for c in value)
            or "/" in value or "\\" in value):
        return False
    file = Path(path) if path is not None else HERE / BROKER_SYMBOL_MAP_FILE
    try:
        mappings = _broker_symbol_map_read_strict(file)
    except Exception as exc:
        log(f"      symbol selection refused; existing map is unreadable: {type(exc).__name__}", "err")
        return False
    row = dict(mappings.get(name) or {})
    if value.upper() == "AUTO":
        row.pop(base, None)
    else:
        row[base] = value
    if row:
        mappings[name] = row
    else:
        mappings.pop(name, None)
    return broker_symbol_map_write(mappings, file)


def broker_names() -> list:
    return [a["name"] for a in accounts()]


BROKERS_OFF: list = []            # names switched OFF (no NEW orders there)
_BROKERS_OFF_TS = 0.0


def brokers_off_load(force: bool = False) -> list:
    """Which brokers are switched OFF (re-read every 5s, like the channels)."""
    global BROKERS_OFF, _BROKERS_OFF_TS
    if not force and _BROKERS_OFF_TS and (time.time() - _BROKERS_OFF_TS) < 5.0:
        return BROKERS_OFF
    try:
        data = state_get("brokers_off", []) or []
        if isinstance(data, str):
            data = [data]
        BROKERS_OFF = [str(x).strip().upper() for x in data if str(x).strip()]
    except Exception:
        BROKERS_OFF = []
    _BROKERS_OFF_TS = time.time()
    return BROKERS_OFF


def broker_is_on(name) -> bool:
    return str(name or "").strip().upper() not in brokers_off_load()


def set_broker_on(name, on: bool, quiet: bool = False) -> bool:
    """Switch one MT5 account ON / OFF for NEW orders (open trades stay managed)."""
    nm = str(name or "").strip().upper()
    if not nm:
        return False
    off = list(brokers_off_load(force=True))
    if on:
        off = [x for x in off if x != nm]
    elif nm not in off:
        off.append(nm)
    globals()["BROKERS_OFF"] = off
    state_set("brokers_off", off)
    if not quiet:
        log(f"      broker [{nm}] is now "
            f"{'ON - new orders go there' if on else 'OFF - no NEW orders (open trades are still managed)'}",
            "ok" if on else "warn")
    return True


def broker_rows() -> list:
    """Every MT5 account with its switch - the app draws this."""
    off = brokers_off_load()
    rows = []
    for a in accounts():
        rows.append({"name": a["name"], "path": a["path"], "login": a["login"],
                     "server": a["server"], "on": a["name"] not in off,
                     "source": "app" if any(x["name"] == a["name"]
                                            for x in brokers_file_read()) else "file"})
    return rows


def broker_source(name) -> str:
    """'app' (saved in edgequant_brokers.json) or 'file' (MT5_ACCOUNTS constant)."""
    nm = str(name or "").strip().upper()
    if any(str(x.get("name")).upper() == nm for x in brokers_file_read()):
        return "app"
    return "file"


def brokers_text() -> str:
    """The /brokers answer."""
    rows = broker_rows()
    L = [tg_title("\U0001F3E6", "MT5 ACCOUNTS  (brokers)",
                  "an OFF account gets no NEW orders - open trades are still managed"),
         "  #   BROKER              LOGIN        SERVER                  STATE",
         "-" * 66]
    for i, r in enumerate(rows, 1):
        L.append(f"  {i:<3} {str(r['name'])[:18]:<19}{str(r['login'] or '-'):<12} "
                 f"{str(r['server'] or '-')[:22]:<23} {'ON' if r['on'] else 'OFF'}")
    off = [r["name"] for r in rows if not r["on"]]
    L += ["-" * 66,
          f"ON {len(rows) - len(off)}   OFF {len(off)}"
          + (f"   ({', '.join(off)})" if off else "   (every account gets the signals)"),
          "",
          "change it here:   /brokeroff EXNESS      /brokeron EXNESS",
          "the app does the same in the BROKERS tab (add + ON/OFF).",
          "",
          tg_foot()]
    return "\n".join(L)


def broker_set_command(args: str, on: bool) -> str:
    t = (args or "").strip().upper()
    if not t:
        return "tell me which account:\n   /brokeroff EXNESS     /brokeron EXNESS\n\n" + brokers_text()
    rows = broker_rows()
    hit = next((r for r in rows if r["name"] == t), None)
    if not hit:
        hit = next((r for r in rows if t in r["name"]), None)
    if not hit:
        return f"no MT5 account called '{t}'.\n\n{brokers_text()}"
    set_broker_on(hit["name"], on)
    return (f"[{hit['name']}] is now "
            f"{'ON - new orders go there' if on else 'OFF - no new orders'}"
            f"\n\n{brokers_text()}")


def broker_for_signal(title: str = "", chat_id=None) -> list:
    """Which broker(s) must get this signal -> a list of names (OFF ones skipped)."""
    names = [a["name"] for a in accounts() if broker_is_on(a["name"])]
    if not names:
        return []
    if SEND_TO_ALL_BROKERS:
        return names
    want = None
    table = CHANNEL_BROKER or {}
    for key in (chat_id, str(chat_id or ""), title, (title or "").strip()):
        if key in table:
            want = table[key]
            break
    if want is None:                       # try a loose name match
        low = (title or "").lower()
        for k, v in table.items():
            if isinstance(k, str) and k.lower() and k.lower() in low:
                want = v
                break
    want = str(want or DEFAULT_BROKER or names[0]).strip().upper()
    if want not in names:
        log(f"      broker '{want}' is switched OFF or not in the account list -> "
            f"using {names[0]}", "warn")
        want = names[0]
    return [want]


def broker_account(name=None) -> dict:
    accs = accounts()
    want = str(name or DEFAULT_BROKER or accs[0]["name"]).strip().upper()
    for a in accs:
        if a["name"] == want:
            return a
    return accs[0]


def select_broker(name=None) -> bool:
    """Point the MT5 API at the requested terminal (starts / logs in if needed)."""
    if not HAVE_MT5:
        return False
    acc = broker_account(name)
    if CURRENT_BROKER["name"] == acc["name"] and mt5.terminal_info() is not None:
        CURRENT_BROKER["ready"] = True
        return True
    try:
        mt5.shutdown()
    except Exception:
        pass
    kw = {}
    if acc["path"]:
        kw["path"] = acc["path"]
    if acc["login"] and acc["password"]:
        kw.update(login=acc["login"], password=acc["password"], server=acc["server"])
    ok = bool(mt5.initialize(**kw))
    if ok and acc["path"]:
        term = mt5.terminal_info()
        log(f"      MT5 [{acc['name']}] connected  "
            f"{'(terminal ' + str(getattr(term, 'name', '?')) + ')' if term else ''}", "info")
    CURRENT_BROKER["name"] = acc["name"] if ok else None
    CURRENT_BROKER["ready"] = ok
    return ok


def other_brokers(name: str) -> list:
    return [n for n in broker_names() if n != name]


def mt5_connection_probe(mt5_api=None) -> dict:
    """Read-only MT5 readiness details; never initializes, logs in, or places orders."""
    api = mt5 if mt5_api is None else mt5_api
    out = {"ready": False, "terminal_present": False, "terminal_connected": None,
           "account_present": False, "login": None, "server": "", "reason": ""}
    if api is None:
        out["reason"] = "MetaTrader5 Python API is unavailable."
        return out

    def last_error():
        try:
            return str(api.last_error())
        except Exception as exc:
            return f"{type(exc).__name__}: {exc}"

    try:
        terminal = api.terminal_info()
    except Exception as exc:
        out["reason"] = f"terminal_info() failed: {type(exc).__name__}: {exc}; last_error={last_error()}"
        return out
    if terminal is None:
        out["reason"] = f"terminal_info() returned None; last_error={last_error()}"
        return out
    out["terminal_present"] = True
    connected = getattr(terminal, "connected", None)
    out["terminal_connected"] = connected
    if connected is False:
        out["reason"] = ("MT5 terminal is open but disconnected from its broker/server; "
                         f"last_error={last_error()}")
        return out
    try:
        account = api.account_info()
    except Exception as exc:
        out["reason"] = f"account_info() failed: {type(exc).__name__}: {exc}; last_error={last_error()}"
        return out
    if account is None:
        out["reason"] = f"account_info() returned no logged-in account; last_error={last_error()}"
        return out
    out.update({"ready": True, "account_present": True,
                "login": getattr(account, "login", None),
                "server": str(getattr(account, "server", "") or "")})
    return out


def mt5_ready() -> bool:
    """Require a connected terminal AND logged-in account before engine work."""
    if not HAVE_MT5 or mt5 is None:
        return False
    names = list(broker_names() or [])
    if len(names) > 1:
        if not select_broker(DEFAULT_BROKER or names[0]):
            return False
        return bool(mt5_connection_probe(mt5).get("ready"))
    probe = mt5_connection_probe(mt5)
    if probe.get("ready"):
        return True
    # Re-initialize only when the terminal itself is absent/disconnected. If the
    # terminal is online but has no account_info(), fail closed rather than
    # repeatedly resetting a user's MT5 session on every readiness check.
    if probe.get("terminal_present") and probe.get("terminal_connected") is not False:
        return False
    try:
        if not mt5.initialize():
            return False
    except Exception:
        return False
    return bool(mt5_connection_probe(mt5).get("ready"))


def broker_of_ticket(ticket, symbol="") -> str:
    """Which broker does this ticket belong to ?  (for the journal)"""
    for name in broker_names():
        if ticket in BROKER_TICKETS.get(name, set()):
            return name
    if len(broker_names()) == 1:
        return broker_names()[0]
    if CURRENT_BROKER["name"]:
        return CURRENT_BROKER["name"]
    return symbol and "" or ""


BROKER_TICKETS: dict = {}      # broker name -> set of tickets we placed there


def broker_from_mt5(symbol: str):
    info = mt5.symbol_info(symbol)
    if info is None:
        return None
    return Broker(symbol=symbol, digits=info.digits, point=info.point,
                  stops_level=info.trade_stops_level, freeze_level=info.trade_freeze_level,
                  volume_min=info.volume_min, volume_step=info.volume_step,
                  volume_max=info.volume_max, tick_value=info.trade_tick_value,
                  tick_size=info.trade_tick_size, spread=info.spread)


def symbol_candidates(base: str, broker_name=None) -> list:
    """Exact per-account choice first; otherwise use the engine's legacy fallbacks."""
    requested = str(base or "").strip()
    key = requested.upper()
    selected = broker_symbol_map_get(broker_name, key)
    if selected:
        # An explicit choice is exact: if it is absent, fail closed rather than
        # silently trading a different suffix such as XAUUSD or XAUUSDm.
        return [selected]
    mapped = (SYMBOL_MAP or {}).get(requested) or (SYMBOL_MAP or {}).get(key)
    cands = [c for c in (mapped, requested) if c]
    if key == "XAUUSD":
        cands += ["XAUUSDm", "XAUUSDc", "XAUSDm", "XAUUSD.ecn", "XAUUSD.a",
                  "XAUUSD.r", "GOLD", "GOLD.m"]
    elif key == "US30":
        cands += ["US30.cash", "US30m", "DJ30", "DOW30"]
    elif key == "US100":
        cands += ["NAS100", "USTEC", "US100.cash", "US100m"]
    elif key == "XAGUSD":
        cands += ["XAGUSDm", "SILVER"]
    elif key == "BTCUSD":
        cands += ["BTCUSDm", "BTCUSD.ecn", "BTCUSD.a", "BITCOIN"]
    elif key in ("NAS100", "US100"):
        cands += ["USTEC", "US100.cash", "NAS100.cash", "USTEC.a"]
    elif key in ("US500", "SPX500"):
        cands += ["US500.cash", "SPX500", "US500m"]
    elif key in ("GER40", "DAX40"):
        cands += ["DE40", "GER40.cash", "DAX"]
    elif key == "ETHUSD":
        cands += ["ETHUSDm", "ETHUSD.ecn"]
    elif key in ("EURUSD", "GBPUSD", "USDJPY", "AUDUSD", "USDCAD", "USDCHF",
                 "NZDUSD", "EURJPY", "GBPJPY"):
        cands += [key + "m", key + ".a", key + ".ecn", key + ".r"]
    seen = set()
    out = []
    for symbol in cands:
        exact = str(symbol or "").strip()
        if exact and exact.casefold() not in seen:
            seen.add(exact.casefold())
            out.append(exact)
    return out


def resolve_symbol(base: str, broker_name=None):
    """Resolve a canonical signal symbol for the selected broker account."""
    for symbol in symbol_candidates(base, broker_name):
        info = mt5.symbol_info(symbol)
        if info is None:
            continue
        if not info.visible:
            mt5.symbol_select(symbol, True)
        return symbol
    return None


def mt5_provider_quote_snapshot(symbols, mt5_api=None, now=None) -> dict:
    """Return read-only bid/ask snapshots for Provider signal monitoring.

    This deliberately does NOT call mt5.initialize(), select/switch accounts,
    or order_send(). A terminal/account must already be connected. Selecting a
    resolved symbol may only add it to MT5 Market Watch.
    """
    api = mt5 if mt5_api is None else mt5_api
    now_ts = float(time.time() if now is None else now)
    out = {"status": "unavailable", "broker": str((CURRENT_BROKER or {}).get("name") or
            DEFAULT_BROKER or "active MT5 terminal"), "updated_ts": now_ts,
            "quotes": {}, "reason": ""}
    probe = mt5_connection_probe(api)
    if not probe.get("ready"):
        out.update({"status": "not_connected", "reason": str(probe.get("reason") or
                                                               "MT5 is not connected.")})
        return out
    out["status"] = "connected"
    out["login"] = probe.get("login")
    out["server"] = probe.get("server")

    def candidates(base):
        return symbol_candidates(base, (CURRENT_BROKER or {}).get("name"))

    for requested in dict.fromkeys(str(x or "").strip().upper() for x in (symbols or []) if str(x or "").strip()):
        picked, info = "", None
        for symbol in candidates(requested):
            try:
                info = api.symbol_info(symbol)
            except Exception:
                info = None
            if info is not None:
                picked = symbol
                if not bool(getattr(info, "visible", True)):
                    try:
                        api.symbol_select(symbol, True)
                    except Exception:
                        pass
                break
        if not picked:
            out["quotes"][requested] = {"error": "Symbol is not available in this MT5 terminal."}
            continue
        try:
            tick = api.symbol_info_tick(picked)
            bid, ask = float(getattr(tick, "bid", 0.0) or 0.0), float(getattr(tick, "ask", 0.0) or 0.0)
            if tick is None or bid <= 0 or ask <= 0:
                raise RuntimeError("MT5 returned no valid bid/ask quote")
            tick_ts = float(getattr(tick, "time_msc", 0) or 0) / 1000.0
            if tick_ts <= 0:
                tick_ts = float(getattr(tick, "time", 0) or 0)
            point = float(getattr(info, "point", 0.0) or 0.0)
            out["quotes"][requested] = {"symbol": picked, "bid": bid, "ask": ask,
                "mid": (bid + ask) / 2.0, "ts": tick_ts,
                "stale": bool(not tick_ts or now_ts - tick_ts > 120.0),
                "point": point, "digits": int(getattr(info, "digits", 0) or 0)}
        except Exception as exc:
            try:
                err = api.last_error()
            except Exception:
                err = ""
            out["quotes"][requested] = {"error": f"{type(exc).__name__}: {exc}" +
                                                (f"; last_error={err}" if err else "")}
    return out


def pick_filling(info) -> int:
    """Filling mode the broker supports ('Unsupported filling mode' = retcode 10030)."""
    global FILLINGS
    modes = []
    flags = int(getattr(info, "filling_mode", 0) or 0)
    if flags & 1:
        modes.append(mt5.ORDER_FILLING_FOK)
    if flags & 2:
        modes.append(mt5.ORDER_FILLING_IOC)
    modes.append(mt5.ORDER_FILLING_RETURN)
    FILLINGS = modes
    return modes[0]


def send_order(req: dict):
    """order_send + automatic filling-mode fallback."""
    tries = FILLINGS or [mt5.ORDER_FILLING_IOC]
    last = None
    for mode in tries:
        req["type_filling"] = mode
        res = mt5.order_send(req)
        if res is None:
            return None
        if res.retcode == mt5.TRADE_RETCODE_DONE:
            return res
        last = res
        if res.retcode not in (10030, int(getattr(mt5, "TRADE_RETCODE_INVALID_FILL", 10030))):
            break
    return last


def safe_comment(text: str) -> str:
    """MT5 only accepts a short, plain order comment."""
    return re.sub(r"[^A-Za-z0-9_-]", "", str(text))[:27]


def execute_plan(plan: list, symbol: str) -> list:
    """Submit a prepared plan, never resend after an ambiguous broker result.

    A definite rejection may get the existing one-time retry without the optional
    comment. A missing result, timeout, connection/error code, or partial execution
    is treated as uncertain and stops the remaining plan; blind resubmission could
    duplicate an order that the terminal accepted without returning a clear result.
    """
    tickets: list = []
    accepted = {int(getattr(mt5, "TRADE_RETCODE_DONE", 10009)),
                int(getattr(mt5, "TRADE_RETCODE_PLACED", 10008))}
    partial = int(getattr(mt5, "TRADE_RETCODE_DONE_PARTIAL", 10010))
    ambiguous = {int(getattr(mt5, "TRADE_RETCODE_ERROR", 10011)),
                 int(getattr(mt5, "TRADE_RETCODE_TIMEOUT", 10012)),
                 int(getattr(mt5, "TRADE_RETCODE_CONNECTION", 10031))}

    def _code(result):
        try:
            return int(getattr(result, "retcode")) if result is not None else None
        except (TypeError, ValueError, AttributeError):
            return None

    def _mark_unattempted(start, why):
        for later in plan[start:]:
            if not later.get("status"):
                later["status"] = "not_attempted"
                later["error"] = str(why)[:180]

    def _accept(order, result, state):
        try:
            ticket = int(getattr(result, "order", 0) or 0)
        except (TypeError, ValueError):
            ticket = 0
        if ticket <= 0:
            order["status"] = "uncertain"
            order["error"] = "broker returned an accepted result without an order ticket; verify broker history; no retry sent"
            return False
        order["ticket"] = ticket
        order["status"] = state
        order["sent_ts"] = time.time()
        order["fill_price"] = float(getattr(result, "price", 0.0) or order.get("price") or 0.0)
        order["fill_ts"] = order["sent_ts"] if order.get("kind") == "MARKET" else 0.0
        tickets.append(ticket)
        log(f"      OK  {order['type']:<11} {symbol}  {order.get('price', 0):g}  -> ticket {ticket}", "ord")
        return True

    for idx, order in enumerate(plan):
        if order.get("kind") == "REVIEW" or order.get("status") == "manual_review":
            log(f"      MANUAL REVIEW REQUIRED: {order.get('error', 'validation required')}", "warn")
            continue
        if DRY_RUN:
            log(f"      DRY-RUN  {order['type']:<11} {symbol}  lot={order['lot']}  price={order['price']:g}  "
                f"SL={order['sl'] or '-'}  TP={order['tp'] or '-'}   [{order['tag']}]", "ord")
            continue
        info = mt5.symbol_info(symbol)
        if info is None:
            order["status"] = "manual_review"
            order["error"] = "symbol specification unavailable; execution not attempted"
            continue
        if order["kind"] == "PENDING" and order["type"] in ("BUY_LIMIT", "SELL_LIMIT"):
            tick = mt5.symbol_info_tick(symbol)
            if tick is None or not getattr(tick, "ask", 0) or not getattr(tick, "bid", 0):
                order["status"] = "manual_review"
                order["error"] = "live quote unavailable; pending order not sent"
                continue
            point = float(getattr(info, "point", 0) or 0)
            required = max(float(getattr(info, "trade_stops_level", 0) or 0),
                           float(getattr(info, "trade_freeze_level", 0) or 0)) * point
            entry = float(order["price"])
            invalid = (entry >= float(tick.ask) - required if order["type"] == "BUY_LIMIT"
                       else entry <= float(tick.bid) + required)
            if invalid:
                order["status"] = "manual_review"
                order["error"] = "pending LIMIT entry invalid against refreshed broker quote"
                continue
            # Recheck the original price, SL and TP without changing any of them.
            # A pending LIMIT order must satisfy the broker's tick grid and stop distances.
            tick_size = float(getattr(info, "trade_tick_size", 0) or point)
            if tick_size <= 0 or point <= 0:
                order["status"] = "manual_review"
                order["error"] = "broker tick-size/point specification unavailable"
                continue
            values = [("entry", entry)]
            values.extend((key, float(order.get(key) or 0)) for key in ("sl", "tp")
                          if float(order.get(key) or 0) != 0)
            if any(abs(v / tick_size - round(v / tick_size)) > 1e-5
                   for _, v in values):
                order["status"] = "manual_review"
                order["error"] = "pending entry/SL/TP not aligned to broker tick size"
                continue
            sl = float(order.get("sl") or 0)
            tp = float(order.get("tp") or 0)
            is_buy = order["type"] == "BUY_LIMIT"
            if (sl and (sl >= entry - required if is_buy else sl <= entry + required)) or \
               (tp and (tp <= entry + required if is_buy else tp >= entry - required)):
                order["status"] = "manual_review"
                order["error"] = "pending SL/TP violates broker direction or stop distance"
                continue
            # Compare the actual live spread using the project's Gold pip convention.
            # The user-facing MAX_SPREAD_PIPS setting remains the source of truth.
            live_spread = float(tick.ask) - float(tick.bid)
            pip_unit = pip_size_of(symbol)
            if live_spread < 0 or pip_unit <= 0:
                order["status"] = "manual_review"
                order["error"] = "invalid live spread or pip specification"
                continue
            if MAX_SPREAD_PIPS > 0 and live_spread / pip_unit > MAX_SPREAD_PIPS:
                order["status"] = "manual_review"
                order["error"] = (f"live spread {live_spread / pip_unit:.2f} pips exceeds "
                                  f"configured {MAX_SPREAD_PIPS:g} pips")
                continue
        price = order["price"]
        if order["kind"] == "MARKET":
            tick = mt5.symbol_info_tick(symbol)
            if tick is None:
                log(f"      {symbol}: no tick -> order skipped", "err")
                order["status"] = "rejected"
                order["error"] = "no tick available before submission"
                continue
            price = tick.ask if order["type"] == "BUY" else tick.bid
        req = {
            "action": mt5.TRADE_ACTION_PENDING if order["kind"] == "PENDING" else mt5.TRADE_ACTION_DEAL,
            "symbol": symbol,
            "volume": float(order["lot"]),
            "type": getattr(mt5, "ORDER_TYPE_" + order["type"]),
            "price": float(price),
            "sl": float(order["sl"] or 0.0),
            "tp": float(order["tp"] or 0.0),
            "deviation": MAX_SLIPPAGE,
            "magic": MAGIC,
            "comment": safe_comment("EQ-" + str(order["tag"])),
        }
        if order["kind"] == "PENDING":
            req["type_time"] = mt5.ORDER_TIME_GTC
        req["type_filling"] = pick_filling(info)
        result = send_order(req)
        code = _code(result)

        # A missing result is not a definite rejection. Never retry it.
        if result is None or code is None or code in ambiguous:
            error = (f"ambiguous broker result retcode={code}; verify MT5 order history; "
                     "no automatic retry sent")
            order["status"] = "uncertain"
            order["error"] = error
            log(f"      UNCERTAIN {order['type']} {symbol}: {error}", "err")
            _mark_unattempted(idx + 1, "not attempted after an uncertain broker result")
            break

        if code == partial:
            try:
                ticket = int(getattr(result, "order", 0) or 0)
            except (TypeError, ValueError):
                ticket = 0
            order["status"] = "partial" if ticket > 0 else "uncertain"
            if ticket > 0:
                order["ticket"] = ticket
                tickets.append(ticket)
                order["sent_ts"] = time.time()
                order["fill_price"] = float(getattr(result, "price", 0.0) or price)
                order["fill_ts"] = order["sent_ts"] if order.get("kind") == "MARKET" else 0.0
            order["error"] = "partial execution result; verify broker history; no retry sent"
            log(f"      PARTIAL/UNCERTAIN {order['type']} {symbol}: {order['error']}", "warn")
            _mark_unattempted(idx + 1, "not attempted after a partial/uncertain broker result")
            break

        if code not in accepted:
            # Preserve the one-time comment-free retry only after the terminal
            # returned a definite rejection. A None/timeout/connection result
            # is handled above and is never retried.
            why = mt5.last_error()
            log(f"      retry after explicit rejection without comment ({why})", "warn")
            req.pop("comment", None)
            result = send_order(req)
            code = _code(result)
            if result is None or code is None or code in ambiguous:
                error = (f"ambiguous comment-free retry result retcode={code}; verify "
                         "MT5 order history; no further retry sent")
                order["status"] = "uncertain"
                order["error"] = error
                log(f"      UNCERTAIN {order['type']} {symbol}: {error}", "err")
                _mark_unattempted(idx + 1, "not attempted after an uncertain broker result")
                break
            if code == partial:
                try:
                    ticket = int(getattr(result, "order", 0) or 0)
                except (TypeError, ValueError):
                    ticket = 0
                order["status"] = "partial" if ticket > 0 else "uncertain"
                if ticket > 0:
                    order["ticket"] = ticket
                    tickets.append(ticket)
                    order["sent_ts"] = time.time()
                    order["fill_price"] = float(getattr(result, "price", 0.0) or price)
                    order["fill_ts"] = order["sent_ts"] if order.get("kind") == "MARKET" else 0.0
                order["error"] = "partial execution on comment-free retry; verify broker history; no retry sent"
                log(f"      PARTIAL/UNCERTAIN {order['type']} {symbol}: {order['error']}", "warn")
                _mark_unattempted(idx + 1, "not attempted after a partial/uncertain broker result")
                break

        if code in accepted:
            if not _accept(order, result, "pending" if order["kind"] == "PENDING" else "open"):
                log(f"      UNCERTAIN {order['type']} {symbol}: {order.get('error')}", "err")
                _mark_unattempted(idx + 1, "not attempted after an uncertain broker result")
                break
        else:
            extra = getattr(result, "comment", "") if result else ""
            hint = ""
            if code == int(getattr(mt5, "TRADE_RETCODE_INVALID_PRICE", 10015)):
                hint = " (price too close to the market / already passed)"
            elif code == int(getattr(mt5, "TRADE_RETCODE_INVALID_STOPS", 10016)):
                hint = " (SL or TP too close to the entry for this broker)"
            log(f"      FAIL {order['type']:<10} {symbol} {price:g}  retcode={code} {extra} "
                f"{mt5.last_error()}{hint}", "err")
            order["status"] = "rejected"
            order["error"] = f"retcode={code} {extra} {hint}".strip()[:180]

    want = len(plan)
    if len(tickets) < want:
        log(f"      [!] {len(tickets)} of {want} order(s) confirmed; check the "
            f"Trade tab and the reason above", "warn")
    return tickets


# --------------------------------------------------------------------------- #
#  management: channel update messages
# --------------------------------------------------------------------------- #
def my_positions(direction=None, symbol=None):
    out = []
    for p in (mt5.positions_get() or []):
        if MAGIC and p.magic != MAGIC:
            continue
        if symbol and p.symbol != symbol:
            continue
        if direction == "BUY" and p.type != mt5.POSITION_TYPE_BUY:
            continue
        if direction == "SELL" and p.type != mt5.POSITION_TYPE_SELL:
            continue
        out.append(p)
    return out


def my_pendings(direction=None, symbol=None):
    out = []
    for o in (mt5.orders_get() or []):
        if MAGIC and o.magic != MAGIC:
            continue
        if symbol and o.symbol != symbol:
            continue
        is_buy = o.type in (mt5.ORDER_TYPE_BUY_LIMIT, mt5.ORDER_TYPE_BUY_STOP)
        if direction == "BUY" and not is_buy:
            continue
        if direction == "SELL" and is_buy:
            continue
        out.append(o)
    return out


_BROKER_INNER = False


def each_broker(fn, *a, **kw):
    """Run a management function on EVERY broker.  None = just run it normally."""
    global _BROKER_INNER
    names = broker_names()
    if _BROKER_INNER or len(names) < 2 or not HAVE_MT5:
        return None
    total, keep = 0, CURRENT_BROKER["name"]
    _BROKER_INNER = True
    try:
        for name in names:
            if not select_broker(name):
                log(f"      [{name}] MT5 not reachable -> skipped", "warn")
                continue
            try:
                total += int(fn(*a, **kw) or 0)
            except Exception as exc:
                log(f"      [{name}] {exc}", "err")
    finally:
        _BROKER_INNER = False
        if keep:
            select_broker(keep)
    return total


def modify_tp(direction, new_tp: float, scope: str = "positions", symbol=None,
              src=None, cat=None, tickets=None, broker=None) -> int:
    if broker:
        keep = CURRENT_BROKER.get("name")
        if not select_broker(broker):
            log(f"      [{broker}] could not select account for scoped TP update", "warn")
            return 0
        global _BROKER_INNER
        was_inner = _BROKER_INNER
        _BROKER_INNER = True
        try:
            return modify_tp(direction, new_tp, scope, symbol, src, cat,
                             tickets=tickets, broker=None)
        finally:
            _BROKER_INNER = was_inner
            if keep and keep != broker:
                select_broker(keep)
    r = each_broker(modify_tp, direction, new_tp, scope, symbol, src, cat,
                    tickets=tickets, broker=None)
    if r is not None:
        return r
    if DRY_RUN:
        log(f"      DRY-RUN  would set TP {new_tp:g} on {scope} ({direction or 'BOTH'})", "mng")
        return 0
    try:
        wanted = {int(x) for x in tickets} if tickets is not None else None
    except Exception:
        wanted = set()
    n = 0
    if scope == "pending":
        for o in my_pendings(direction, symbol):
            if wanted is not None and int(getattr(o, "ticket", 0) or 0) not in wanted:
                continue
            res = mt5.order_send({"action": mt5.TRADE_ACTION_MODIFY, "order": o.ticket,
                                  "price": o.price_open, "sl": o.sl, "tp": new_tp,
                                  "type_time": mt5.ORDER_TIME_GTC})
            ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
            n += 1 if ok else 0
            if ok and TRADE_JOURNAL:
                jr_note_action(o.ticket, src, cat, note=f"TP -> {new_tp:g} (pending)")
    else:
        for p in my_positions(direction, symbol):
            if wanted is not None and int(getattr(p, "ticket", 0) or 0) not in wanted:
                continue
            res = mt5.order_send({"action": mt5.TRADE_ACTION_SLTP, "position": p.ticket,
                                  "symbol": p.symbol, "sl": p.sl, "tp": new_tp})
            ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
            n += 1 if ok else 0
            if ok and TRADE_JOURNAL:
                jr_note_action(p.ticket, src, cat, note=f"TP -> {new_tp:g}")
    log(f"      TP {new_tp:g} applied to {n} {scope}", "mng")
    if n and NOTIFY_ON.get("command"):
        notify_update("TP UPDATED   (channel eken aluth TP ekak awa)", src,
                      f"TP {new_tp:g} applied to {n} {scope}")
    return n


def _move_to_be_current(direction=None, symbol=None, src=None, cat=None,
                        note="break-even", tickets=None, only_profitable=True,
                        min_profit_pips=0.0) -> int:
    """Move eligible positions to entry without touching losses or profit locks."""
    if DRY_RUN:
        log(f"      DRY-RUN  would move {direction or 'BOTH'} positions to break-even", "mng")
        return 0
    try:
        wanted = ({int(x) for x in tickets} if tickets is not None else None)
    except Exception:
        wanted = None
    try:
        minimum = max(0.0, float(min_profit_pips or 0.0))
    except Exception:
        minimum = 0.0
    n = skipped = 0
    for p in my_positions(direction, symbol):
        if wanted is not None and int(getattr(p, "ticket", 0) or 0) not in wanted:
            continue
        try:
            profit_pips = pips_profit(p)
            if only_profitable and (profit_pips <= 0.0 or profit_pips + 1e-6 < minimum):
                skipped += 1
                continue
            entry = float(p.price_open)
            current_sl = float(p.sl or 0.0)
            buying = p.type == mt5.POSITION_TYPE_BUY
            # A BE command must never pull a stop backwards from already-locked
            # profit to the entry. Entry is only an improvement from the loss side.
            already_safe = (current_sl > 0 and
                            (current_sl >= entry - 1e-8 if buying
                             else current_sl <= entry + 1e-8))
            if already_safe:
                skipped += 1
                continue
            res = mt5.order_send({"action": mt5.TRADE_ACTION_SLTP, "position": p.ticket,
                                  "symbol": p.symbol, "sl": entry, "tp": p.tp})
            ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
            n += 1 if ok else 0
            skipped += 0 if ok else 1
            if ok and TRADE_JOURNAL:
                jr_note_action(p.ticket, src, cat, note=note, be=True)
        except Exception as exc:
            skipped += 1
            log(f"      BE skipped for ticket {getattr(p, 'ticket', '?')}: {exc}", "warn")
    log(f"      {n} order(s) moved to break-even; {skipped} unchanged "
        "(not profitable / already at or beyond BE / request refused)", "mng")
    if n and NOTIFY_ON.get("command"):
        notify_update("BE MOVED   (SL eka entry ekata genawa)", src,
                      f"{n} position(s) -> break-even; existing profit locks kept")
    return n


def move_to_be(direction, symbol=None, src=None, cat=None, note="break-even",
               tickets=None, only_profitable=True, min_profit_pips=0.0,
               broker=None) -> int:
    """Move selected profitable positions to BE, preserving profit-side stops.

    A single-position or signal-group caller supplies tickets (and its broker),
    preventing one trade's TP from moving unrelated trades of the same symbol.
    """
    args = (direction, symbol, src, cat, note)
    opts = {"tickets": tickets, "only_profitable": only_profitable,
            "min_profit_pips": min_profit_pips}
    if broker:
        keep = CURRENT_BROKER.get("name")
        if not select_broker(broker):
            log(f"      [{broker}] could not select broker for scoped BE", "warn")
            return 0
        try:
            return _move_to_be_current(*args, **opts)
        finally:
            if keep and keep != broker:
                select_broker(keep)
    r = each_broker(_move_to_be_current, *args, **opts)
    if r is not None:
        return r
    return _move_to_be_current(*args, **opts)


def mt5_edit_ticket(ticket, broker="", order_type=None, entry=None, sl=None, tp=None,
                    move_be=False) -> dict:
    """Safely edit exactly one live MT5 position or pending order.

    Called only by the local desktop editor after an explicit user confirmation;
    no Telegram/cloud command reaches this function. A BE move is profit-only and
    never moves an already protected stop backwards.
    """
    try:
        ticket = int(ticket)
    except Exception:
        return {"ok": False, "message": "Invalid ticket."}
    if ticket <= 0:
        return {"ok": False, "message": "Invalid ticket."}
    if not HAVE_MT5 or DRY_RUN or mt5 is None:
        return {"ok": False, "message": "MT5 editing is unavailable in this mode."}

    keep = CURRENT_BROKER.get("name")
    target_broker = str(broker or "").strip()
    try:
        if target_broker and len(broker_names()) > 1:
            if not select_broker(target_broker):
                return {"ok": False, "message": f"Could not connect to {target_broker}."}
        elif not mt5_ready():
            return {"ok": False, "message": "MT5 is not connected."}

        try:
            pos_rows = list(mt5.positions_get(ticket=ticket) or [])
        except TypeError:
            pos_rows = [p for p in (mt5.positions_get() or [])
                        if int(getattr(p, "ticket", 0) or 0) == ticket]
        except Exception:
            pos_rows = []
        try:
            order_rows = list(mt5.orders_get(ticket=ticket) or [])
        except TypeError:
            order_rows = [o for o in (mt5.orders_get() or [])
                          if int(getattr(o, "ticket", 0) or 0) == ticket]
        except Exception:
            order_rows = []
        pos = next((p for p in pos_rows if int(getattr(p, "ticket", 0) or 0) == ticket), None)
        order = next((o for o in order_rows if int(getattr(o, "ticket", 0) or 0) == ticket), None)
        if bool(pos) == bool(order):
            return {"ok": False, "message": "Ticket is not uniquely present as a position or pending order."}

        if pos is not None:
            kind = "OPEN"
            symbol = str(getattr(pos, "symbol", "") or "")
            side = ("BUY" if int(getattr(pos, "type", 0) or 0) ==
                    int(getattr(mt5, "POSITION_TYPE_BUY", 0)) else "SELL")
            current_entry = float(getattr(pos, "price_open", 0.0) or 0.0)
            current_sl = float(getattr(pos, "sl", 0.0) or 0.0)
            current_tp = float(getattr(pos, "tp", 0.0) or 0.0)
            current_price = float(getattr(pos, "price_current", 0.0) or 0.0)
        else:
            kind = "PENDING"
            symbol = str(getattr(order, "symbol", "") or "")
            otype = int(getattr(order, "type", -1))
            buy_types = {int(getattr(mt5, k, d)) for k, d in (
                ("ORDER_TYPE_BUY_LIMIT", 2), ("ORDER_TYPE_BUY_STOP", 4),
                ("ORDER_TYPE_BUY_STOP_LIMIT", 6))}
            side = "BUY" if otype in buy_types else "SELL"
            current_entry = float(getattr(order, "price_open", 0.0) or
                                  getattr(order, "price", 0.0) or 0.0)
            current_sl = float(getattr(order, "sl", 0.0) or 0.0)
            current_tp = float(getattr(order, "tp", 0.0) or 0.0)
            current_price = current_entry

        requested_kind = str(order_type or "").upper()
        aliases = ("OPEN", "POSITION", "LIVE") if kind == "OPEN" else ("PENDING", "ORDER")
        if requested_kind and requested_kind not in aliases:
            return {"ok": False, "message": "The ticket type changed; refresh and select it again."}
        if move_be and pos is None:
            return {"ok": False, "message": "Break-even applies only to a running position."}
        if pos is not None and entry is not None:
            try:
                if abs(float(entry) - current_entry) > 1e-8:
                    return {"ok": False, "message": "A filled position's entry price cannot be edited."}
            except Exception:
                return {"ok": False, "message": "Invalid entry price."}

        new_entry = current_entry
        new_sl = current_sl if sl is None else float(sl)
        new_tp = current_tp if tp is None else float(tp)
        if not all(math.isfinite(x) for x in (new_entry, new_sl, new_tp)):
            return {"ok": False, "message": "Price fields must be finite numbers."}
        if new_sl < 0 or new_tp < 0:
            return {"ok": False, "message": "SL/TP cannot be negative."}
        if current_sl > 0 and new_sl == 0:
            return {"ok": False, "message": "Removing an existing SL is blocked; enter a protective SL instead."}
        if order is not None and entry is not None:
            new_entry = float(entry)
            if not math.isfinite(new_entry) or new_entry <= 0:
                return {"ok": False, "message": "Pending entry price must be greater than zero."}

        if move_be:
            profit_pips = pips_profit(pos)
            if profit_pips <= 0:
                return {"ok": False, "message": "BE was not applied: the position must be in profit first."}
            entry_price = current_entry
            already_safe = (current_sl > 0 and
                            (current_sl >= entry_price - 1e-8 if side == "BUY"
                             else current_sl <= entry_price + 1e-8))
            if already_safe:
                return {"ok": False, "message": "SL is already at or beyond break-even; profit protection kept."}
            new_sl = entry_price

        if order is not None:
            reference = new_entry
            if reference <= 0:
                return {"ok": False, "message": "Pending order has no valid entry price."}
            if side == "BUY":
                if new_sl > 0 and new_sl >= reference:
                    return {"ok": False, "message": "BUY pending SL must be below its entry."}
                if new_tp > 0 and new_tp <= reference:
                    return {"ok": False, "message": "BUY pending TP must be above its entry."}
            else:
                if new_sl > 0 and new_sl <= reference:
                    return {"ok": False, "message": "SELL pending SL must be above its entry."}
                if new_tp > 0 and new_tp >= reference:
                    return {"ok": False, "message": "SELL pending TP must be below its entry."}
            request = {"action": mt5.TRADE_ACTION_MODIFY, "order": ticket,
                       "price": new_entry, "sl": new_sl, "tp": new_tp,
                       "type_time": getattr(order, "type_time", getattr(mt5, "ORDER_TIME_GTC", 0))}
            expiration = int(getattr(order, "time_expiration", 0) or 0)
            if expiration:
                request["expiration"] = expiration
            stoplimit = float(getattr(order, "price_stoplimit", 0.0) or 0.0)
            if stoplimit:
                request["stoplimit"] = stoplimit
        else:
            tick = mt5.symbol_info_tick(symbol)
            bid = float(getattr(tick, "bid", 0.0) or 0.0) if tick else current_price
            ask = float(getattr(tick, "ask", 0.0) or 0.0) if tick else current_price
            if side == "BUY":
                if new_sl > 0 and bid > 0 and new_sl >= bid:
                    return {"ok": False, "message": "BUY SL must remain below the current bid."}
                if new_tp > 0 and ask > 0 and new_tp <= ask:
                    return {"ok": False, "message": "BUY TP must remain above the current ask."}
            else:
                if new_sl > 0 and ask > 0 and new_sl <= ask:
                    return {"ok": False, "message": "SELL SL must remain above the current ask."}
                if new_tp > 0 and bid > 0 and new_tp >= bid:
                    return {"ok": False, "message": "SELL TP must remain below the current bid."}
            request = {"action": mt5.TRADE_ACTION_SLTP, "position": ticket,
                       "symbol": symbol, "sl": new_sl, "tp": new_tp}

        result = mt5.order_send(request)
        done = int(getattr(mt5, "TRADE_RETCODE_DONE", 10009))
        if not result or int(getattr(result, "retcode", -1)) != done:
            code = getattr(result, "retcode", "no response") if result else "no response"
            detail = getattr(result, "comment", "") if result else ""
            return {"ok": False, "message": f"MT5 rejected the edit ({code}). {detail}".strip()}

        for rec in TRADES:
            if int(rec.get("ticket") or 0) != ticket:
                continue
            rec_broker = str(rec.get("broker") or "").strip().casefold()
            if target_broker and rec_broker and rec_broker != target_broker.casefold():
                continue
            rec["sl_now"], rec["tp_now"] = new_sl, new_tp
            if order is not None:
                rec["price"] = new_entry
            if move_be:
                rec["be"] = True
            rec["managed_note"] = "manual desktop edit"
            break
        try:
            if _JR_LOADED:
                jr_save()
                jr_write_files()
        except Exception:
            pass
        return {"ok": True, "message": "MT5 updated.", "ticket": ticket,
                "kind": kind, "symbol": symbol, "direction": side,
                "entry": new_entry, "sl": new_sl, "tp": new_tp,
                "previous": {"entry": current_entry, "sl": current_sl, "tp": current_tp}}
    except Exception as exc:
        return {"ok": False, "message": f"Edit failed: {type(exc).__name__}: {exc}"}
    finally:
        if target_broker and keep and keep != target_broker:
            try:
                select_broker(keep)
            except Exception:
                pass


def be_ladder_target(p, step: float):
    """Where the SL must be for a trade that is `step`-pips laddered.

    +25 pips -> the entry (classic break-even)
    +50 pips -> +25 pips locked      +75 -> +50      +100 -> +75   ...
    Returns (new_sl, locked_pips) or (0.0, 0.0) when nothing has to change.
    """
    if not HAVE_MT5 or not step or step <= 0:
        return 0.0, 0.0
    try:
        prof = pips_profit(p)
        if prof < step:
            return 0.0, 0.0
        steps = int(prof // step)
        lock = (steps - 1) * step
        pip = pip_size_of(p.symbol)
        entry = float(p.price_open)
        buying = p.type == mt5.POSITION_TYPE_BUY
        new_sl = entry + lock * pip if buying else entry - lock * pip
        cur = float(p.sl or 0.0)
        if buying:
            better = (cur <= 0) or (new_sl > cur + pip / 2)
        else:
            better = (cur <= 0) or (new_sl < cur - pip / 2)
        if not better:
            return 0.0, 0.0
        tick = mt5.symbol_info_tick(p.symbol)
        if tick is None:
            return 0.0, 0.0
        if buying and new_sl >= float(tick.bid):          # the price has passed it
            return 0.0, 0.0
        if not buying and new_sl <= float(tick.ask):
            return 0.0, 0.0
        return float(new_sl), float(lock)
    except Exception:
        return 0.0, 0.0


def ladder_one(pos) -> bool:
    """Move one position's SL up the 25-pip ladder (all layers, on the way to TP)."""
    if not HAVE_MT5 or DRY_RUN or not BE_LADDER_PIPS or BE_LADDER_PIPS <= 0:
        return False
    bn = broker_of_ticket(pos.ticket)
    if bn and len(broker_names()) > 1:
        select_broker(bn)
    new_sl, lock = be_ladder_target(pos, float(BE_LADDER_PIPS))
    if not new_sl:
        return False
    info = mt5.symbol_info(pos.symbol)
    nd = int(getattr(info, "digits", 2) or 2)
    res = mt5.order_send({"action": mt5.TRADE_ACTION_SLTP, "position": pos.ticket,
                          "symbol": pos.symbol, "sl": round(new_sl, nd), "tp": pos.tp})
    ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
    if not ok:
        log(f"      ladder: SL move refused for {pos.symbol} ticket {pos.ticket} "
            f"({getattr(res, 'comment', '?')})", "warn")
        return False
    prof = pips_profit(pos)
    log(f"      LADDER {pos.symbol} ticket {pos.ticket}: +{prof:.0f} pips -> SL "
        f"{round(new_sl, nd):g}  ({lock:g} pips locked)", "mng")
    if TRADE_JOURNAL:
        jr_note_action(pos.ticket, None, None,
                       note=(f"auto BE at +{BE_LADDER_PIPS:g} pips" if lock == 0
                             else f"ladder: SL +{lock:g} pips"),
                       be=True)
    if BE_LADDER_NOTIFY and NOTIFY_ON.get("be"):
        notify("\n".join([
            tg_title(EV_ICON["be"],
                     ("BREAK-EVEN  (+" + format(BE_LADDER_PIPS, "g") + " pips)")
                      if lock == 0 else f"PROFIT LOCKED  +{lock:g} pips",
                     f"{pos.symbol}   {getattr(pos, 'ticket', '?')}   now +{prof:.0f} pips",
                     (f"SL moved to the entry - this trade can not lose now"
                      if lock == 0 else
                      f"SL moved to +{lock:g} pips - that much is safe whatever happens")),
            f"  ENTRY       {float(pos.price_open):g}",
            f"  NEW SL      {round(new_sl, nd):g}      TP {float(pos.tp or 0):g}",
            f"  NEXT STEP   at +{lock + 2 * BE_LADDER_PIPS:g} pips the SL goes to "
            f"+{lock + BE_LADDER_PIPS:g} pips",
            "",
            tg_foot(f"BE ladder every {BE_LADDER_PIPS:g} pips")]))
    return True


def cancel_pendings(symbol=None, src=None, cat=None, direction=None,
                    tickets=None, broker=None) -> int:
    if broker:
        keep = CURRENT_BROKER.get("name")
        if not select_broker(broker):
            log(f"      [{broker}] could not select account for scoped pending cancel", "warn")
            return 0
        global _BROKER_INNER
        was_inner = _BROKER_INNER
        _BROKER_INNER = True
        try:
            return cancel_pendings(symbol, src, cat, direction=direction,
                                   tickets=tickets, broker=None)
        finally:
            _BROKER_INNER = was_inner
            if keep and keep != broker:
                select_broker(keep)
    r = each_broker(cancel_pendings, symbol, src, cat,
                    direction=direction, tickets=tickets, broker=None)
    if r is not None:
        return r
    if DRY_RUN:
        log("      DRY-RUN  would cancel the pending orders", "mng")
        return 0
    try:
        wanted = {int(x) for x in tickets} if tickets is not None else None
    except Exception:
        wanted = set()
    n = 0
    for o in my_pendings(direction, symbol):
        if wanted is not None and int(getattr(o, "ticket", 0) or 0) not in wanted:
            continue
        res = mt5.order_send({"action": mt5.TRADE_ACTION_REMOVE, "order": o.ticket})
        ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        n += 1 if ok else 0
        if ok and TRADE_JOURNAL:
            jr_note_action(o.ticket, src, cat, note="cancelled by the channel")
    log(f"      {n} pending order(s) cancelled", "mng")
    if n and NOTIFY_ON.get("command"):
        notify_update("PENDING ORDERS CANCELLED", src,
                      f"{n} pending order(s) removed")
    return n


def close_positions(direction=None, symbol=None, fraction: float = 1.0,
                    src=None, cat=None, note="closed by the channel",
                    tickets=None, broker=None) -> int:
    if broker:
        keep = CURRENT_BROKER.get("name")
        if not select_broker(broker):
            log(f"      [{broker}] could not select account for scoped close", "warn")
            return 0
        global _BROKER_INNER
        was_inner = _BROKER_INNER
        _BROKER_INNER = True
        try:
            return close_positions(direction, symbol, fraction, src, cat, note,
                                   tickets=tickets, broker=None)
        finally:
            _BROKER_INNER = was_inner
            if keep and keep != broker:
                select_broker(keep)
    r = each_broker(close_positions, direction, symbol, fraction, src, cat, note,
                    tickets=tickets, broker=None)
    if r is not None:
        return r
    if DRY_RUN:
        log(f"      DRY-RUN  would close {fraction:.0%} of {direction or 'BOTH'} positions", "mng")
        return 0
    try:
        wanted = {int(x) for x in tickets} if tickets is not None else None
    except Exception:
        wanted = set()
    n = 0
    for p in my_positions(direction, symbol):
        if wanted is not None and int(getattr(p, "ticket", 0) or 0) not in wanted:
            continue
        info = mt5.symbol_info(p.symbol)
        br = broker_from_mt5(p.symbol)
        vol = normalize_lot(br, p.volume * fraction)
        if fraction < 1.0 and vol >= p.volume:
            vol = normalize_lot(br, p.volume - (br.volume_step or 0.01))
        if vol <= 0:
            continue
        tick = mt5.symbol_info_tick(p.symbol)
        req = {"action": mt5.TRADE_ACTION_DEAL, "position": p.ticket, "symbol": p.symbol,
               "volume": float(vol), "magic": MAGIC, "deviation": MAX_SLIPPAGE,
               "type": mt5.ORDER_TYPE_SELL if p.type == mt5.POSITION_TYPE_BUY else mt5.ORDER_TYPE_BUY,
               "price": tick.bid if p.type == mt5.POSITION_TYPE_BUY else tick.ask}
        req["type_filling"] = pick_filling(info)
        res = send_order(req)
        ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        n += 1 if ok else 0
        if ok and TRADE_JOURNAL and fraction >= 1.0:
            jr_note_action(p.ticket, src, cat, note=note)
    log(f"      {n} position(s) closed ({fraction:.0%})", "mng")
    if n and NOTIFY_ON.get("command"):
        notify_update("POSITION CLOSED   (channel / user command)", src,
                      f"{n} position(s) closed ({fraction:.0%})")
    return n


def close_position_partial(pos, fraction: float = 0.5) -> bool:
    """Close PART of one live position (keeps the rest running)."""
    if not HAVE_MT5:
        return False
    try:
        info = mt5.symbol_info(pos.symbol)
        vol = float(pos.volume) * max(0.01, min(0.99, fraction))
        step = float(getattr(info, "volume_step", 0.01) or 0.01)
        vol = max(float(getattr(info, "volume_min", 0.01) or 0.01),
                  round(vol / step) * step)
        vol = round(vol, 2)
        if vol >= float(pos.volume):                     # too small to split
            return False
        tick = mt5.symbol_info_tick(pos.symbol)
        if tick is None:
            return False
        buying = pos.type == mt5.POSITION_TYPE_BUY
        req = {"action": mt5.TRADE_ACTION_DEAL, "position": pos.ticket,
               "symbol": pos.symbol, "volume": vol,
               "type": mt5.ORDER_TYPE_SELL if buying else mt5.ORDER_TYPE_BUY,
               "price": float(tick.bid if buying else tick.ask),
               "deviation": 30, "magic": MAGIC,
               "comment": safe_comment("EQ-part")}
        res = mt5.order_send(req)
        ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        if ok:
            log(f"      PARTIAL close {vol} of {pos.volume} lot {pos.symbol} "
                f"(+{pips_profit(pos):.0f} pips)", "mng")
        else:
            err = getattr(res, "comment", "") or (mt5.last_error() if HAVE_MT5 else "")
            log(f"      partial close refused: {err}", "warn")
        return ok
    except Exception as exc:
        log(f"      partial close failed: {exc}", "err")
        return False


def trail_one(pos) -> bool:
    """Move the SL behind the price when the trade runs (TRAIL_*)."""
    if not HAVE_MT5:
        return False
    try:
        prof = pips_profit(pos)
        if prof < TRAIL_START_PIPS:
            return False
        pip = pip_size_of(pos.symbol)
        dist = TRAIL_DISTANCE_PIPS * pip
        buying = pos.type == mt5.POSITION_TYPE_BUY
        new_sl = pos.price_current - dist if buying else pos.price_current + dist
        cur = float(pos.sl or 0.0)
        better = (new_sl > cur + pip / 2) if buying else (new_sl < cur - pip / 2 or not cur)
        if not better:
            return False
        tick = mt5.symbol_info_tick(pos.symbol)
        if tick is None:
            return False
        if buying and new_sl >= float(tick.bid):
            return False
        if not buying and new_sl <= float(tick.ask):
            return False
        info = mt5.symbol_info(pos.symbol)
        nd = int(getattr(info, "digits", 2) or 2)
        res = mt5.order_send({"action": mt5.TRADE_ACTION_SLTP, "position": pos.ticket,
                              "symbol": pos.symbol, "sl": round(new_sl, nd), "tp": pos.tp})
        ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        if ok:
            log(f"      TRAIL SL {pos.symbol} -> {round(new_sl, nd)}  "
                f"(+{prof:.0f} pips)", "mng")
        return ok
    except Exception:
        return False


def expire_pendings() -> int:
    """Cancel pending orders older than PENDING_EXPIRY_HOURS (0 = off)."""
    if not PENDING_EXPIRY_HOURS or PENDING_EXPIRY_HOURS <= 0 or DRY_RUN:
        return 0
    if not HAVE_MT5:
        return 0
    try:
        if not mt5_ready():
            return 0
    except Exception:
        return 0
    gone = 0
    limit = float(PENDING_EXPIRY_HOURS) * 3600.0
    _src_of, _cfg_of = {}, {}
    if TRADE_JOURNAL:
        try:
            jr_load()
            for _t in TRADES:
                if _t.get("ticket"):
                    _src_of[int(_t["ticket"])] = str(_t.get("source") or "")
        except Exception:
            _src_of = {}
    for bname in broker_names():
        if len(broker_names()) > 1 and not select_broker(bname):
            continue
        for o in my_pendings():
            try:
                age = time.time() - float(getattr(o, "time_setup", 0) or 0)
            except Exception:
                continue
            _src = _src_of.get(int(getattr(o, "ticket", 0) or 0), "")
            _lim = limit
            if _src:                                   # v1.8.0 per channel expiry
                if _src not in _cfg_of:
                    _cfg_of[_src] = channel_cfg_of(_src)
                _h = _cfg_of[_src].get("expiry") or _cfg_of[_src].get("expiry_h")
                try:
                    if _h is not None and float(_h) > 0:
                        _lim = float(_h) * 3600.0
                except Exception:
                    pass
            if _lim <= 0:
                continue
            if age < _lim:
                continue
            res = mt5.order_send({"action": mt5.TRADE_ACTION_REMOVE, "order": o.ticket})
            if res and res.retcode == mt5.TRADE_RETCODE_DONE:
                gone += 1
                h = age / 3600.0
                log(f"      EXPIRED pending {o.symbol} #{o.ticket} ({h:.1f} h old) "
                    f"-> cancelled", "mng")
                if TRADE_JOURNAL:
                    jr_note_action(o.ticket, None, None,
                                   note=f"expired after {h:.1f} h", )
    if gone:
        notify("\n".join([
            tg_title(EV_ICON["expired"], "PENDING ORDERS EXPIRED",
                     f"{gone} order(s) did not trigger within "
                     f"{PENDING_EXPIRY_HOURS:g} h  ->  cancelled",
                     "only the orders EdgeQuant placed were touched"),
            tg_foot()]))
    return gone


def pips_profit(pos) -> float:
    pip = pip_size_of(pos.symbol)
    diff = pos.price_current - pos.price_open
    if pos.type != mt5.POSITION_TYPE_BUY:
        diff = -diff
    return diff / pip if pip else 0.0


