def _hours_window_ok(win: str, u=None) -> tuple:
    """(inside?, text) - is 'now' inside a window like '07:00-21:00' (UTC)?"""
    win = str(win or "").strip()
    if not win or "-" not in win:
        return True, ""
    try:
        a, b = [x.strip() for x in win.split("-", 1)]
        h1, m1 = [int(x) for x in (a.split(":") + ["0"])[:2]]
        h2, m2 = [int(x) for x in (b.split(":") + ["0"])[:2]]
        now = u or utc_now(None)
        mins = now.hour * 60 + now.minute
        lo, hi = h1 * 60 + m1, h2 * 60 + m2
        inside = (lo <= mins < hi) if hi > lo else (mins >= lo or mins < hi)
        return inside, f"{win} UTC (now {now.strftime('%H:%M')} UTC)"
    except Exception:
        return True, ""


def trade_hours_guard() -> tuple:
    """(ok, why) - the bot-wide trading window (empty = any hour)."""
    if not str(TRADE_HOURS or "").strip():
        return True, ""
    inside, text = _hours_window_ok(str(TRADE_HOURS))
    if not inside:
        return False, f"outside the trading hours {text} (TRADE_HOURS)"
    return True, ""


def jr_tag_of(ticket) -> str:
    """The layer tag of a ticket (quickN / tp3 / runner ...)."""
    try:
        rec = jr_get(int(ticket))
        if rec:
            return str(rec.get("tag") or "")
    except Exception:
        pass
    return ""


def partial_ladder_fraction(pos, done) -> float:
    """How much of this position to close NOW (0 = nothing, None = use the old rule).

    PARTIAL_LADDER = "50@50,25@80,15@120"  -> 50 % at +50 pips, 25 % at +80 ...
    """
    raw = str(PARTIAL_LADDER or "").strip()
    if not raw:
        return None
    pip = pip_size_of(getattr(pos, "symbol", "") or "XAUUSD")
    try:
        pips = pips_profit(pos)
    except Exception:
        return 0.0
    for step in raw.replace(";", ",").split(","):
        step = step.strip()
        if "@" not in step:
            continue
        try:
            pct, at = [float(x) for x in step.split("@", 1)]
        except Exception:
            continue
        if pips < at:
            continue
        key = f"{int(getattr(pos, 'ticket', 0))}@{at:g}"
        if key in done:
            continue
        return max(0.01, min(0.95, pct / 100.0))
    return 0.0


def runner_one(pos) -> bool:
    """RUNNER: keep RUNNER_KEEP_PCTS % of the profit locked as the price runs."""
    if not RUNNER_MODE:
        return False
    try:
        if pips_profit(pos) < float(RUNNER_START_PIPS):
            return False
        tick = mt5.symbol_info_tick(pos.symbol)
        if tick is None:
            return False
        is_buy = _pos_is_buy(pos)
        price = float(tick.bid if is_buy else tick.ask)
        entry = float(pos.price_open or 0.0)
        keep = max(0.0, min(0.95, float(RUNNER_KEEP_PCTS) / 100.0))
        want = entry + (price - entry) * keep if is_buy else entry - (entry - price) * keep
        cur = float(pos.sl or 0.0)
        better = (want > cur + 1e-9) if is_buy else (want < cur - 1e-9 or cur == 0.0)
        if not better:
            return False
        pi = mt5.symbol_info(pos.symbol)
        point = float(getattr(pi, "point", 0.01) or 0.01)
        digits = int(getattr(pi, "digits", 2) or 2)
        want = rnd(want, digits)
        if abs(price - want) < point * 2:
            return False
        req = {"action": mt5.TRADE_ACTION_SLTP, "position": int(pos.ticket),
               "symbol": pos.symbol, "sl": want, "tp": float(pos.tp or 0.0)}
        res = mt5.order_send(req)
        if not res or res.retcode != mt5.TRADE_RETCODE_DONE:
            return False
        locked = abs(want - entry) / pip_size_of(pos.symbol)
        log(f"      RUNNER {pos.symbol} #{pos.ticket}: SL -> {want:g} "
            f"({locked:.0f} pips locked, {RUNNER_KEEP_PCTS:g}% kept)", "mng")
        if TRADE_JOURNAL:
            jr_note_action(pos.ticket, None, None,
                           note=f"runner SL -> {want:g} ({locked:.0f} pips locked)")
        notify("\n".join([
            tg_title(ev_icon("peak", "\U0001F3C6"), "RUNNER LOCKING PROFIT",
                     f"{pos.symbol}   {locked:.0f} pips locked in",
                     f"SL {want:g}   the rest keeps running"),
            tg_foot()]))
        return True
    except Exception as exc:
        log(f"      runner: {exc}", "err")
        return False


# ---------------------------------------------------- animated streams -------
STREAM_FILE = "edgequant_streams.json"
_STREAM_CACHE = [None]


def stream_load(force: bool = False) -> list:
    if _STREAM_CACHE[0] is not None and not force:
        return _STREAM_CACHE[0]
    out = []
    try:
        path = HERE / STREAM_FILE
        if path.exists():
            raw = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(raw, list):
                out = raw
    except Exception:
        out = []
    _STREAM_CACHE[0] = out
    return out


def board_stream_record(kind: str, t: dict) -> None:
    """Remember one finished event so the dashboard can ANIMATE it channel-wise."""
    try:
        rec = {"ts": time.time(), "kind": str(kind), "channel": t.get("source") or "?",
               "cat": t.get("source_type") or "", "symbol": t.get("symbol") or "",
               "direction": t.get("direction") or "", "pips": round(trade_pips(t), 1),
               "usd": round(float(t.get("net") or 0.0), 2), "result": t.get("result") or "",
               "tag": t.get("tag") or "", "ticket": t.get("ticket"),
               "day": jr_day_key(t.get("closed_ts") or time.time())}
        data = list(stream_load(False))
        data.append(rec)
        data = data[-400:]
        _STREAM_CACHE[0] = data
        (HERE / STREAM_FILE).write_text(json.dumps(data, ensure_ascii=False),
                                        encoding="utf-8")
    except Exception:
        pass


def board_streams(period: str = "today", limit: int = 60) -> list:
    """The animated list for the dashboard: newest event per channel first."""
    try:
        lo, hi = jr_period_bounds(period if period != "today" else "today")
    except Exception:
        lo, hi = 0, 9e18
    rows = [r for r in stream_load() if lo <= float(r.get("ts") or 0) <= hi]
    rows.sort(key=lambda r: float(r.get("ts") or 0), reverse=True)
    return rows[:limit]


def stream_board_stats(period: str = "today") -> dict:
    """Channel-wise numbers the animated board shows (tp / sl / be / best TP)."""
    out = {}
    for r in board_streams(period, 400):
        ch = r.get("channel") or "?"
        d = out.setdefault(ch, {"channel": ch, "cat": r.get("cat") or "", "tp": 0,
                                "sl": 0, "be": 0, "manual": 0, "n": 0, "usd": 0.0,
                                "pips": 0.0, "best_pips": 0.0, "best_usd": 0.0,
                                "best_symbol": "", "last_ts": 0.0, "last_kind": ""})
        kind = str(r.get("kind") or "")
        if kind in d:
            d[kind] += 1
        d["n"] += 1
        d["usd"] = round(d["usd"] + float(r.get("usd") or 0.0), 2)
        d["pips"] = round(d["pips"] + float(r.get("pips") or 0.0), 1)
        if float(r.get("pips") or 0.0) > d["best_pips"]:
            d["best_pips"] = float(r.get("pips") or 0.0)
            d["best_usd"] = float(r.get("usd") or 0.0)
            d["best_symbol"] = r.get("symbol") or ""
        if float(r.get("ts") or 0.0) > d["last_ts"]:
            d["last_ts"] = float(r.get("ts") or 0.0)
            d["last_kind"] = kind
    rows = list(out.values())
    rows.sort(key=lambda r: (-r["usd"], -r["tp"]))
    return {"rows": rows, "total": len(rows),
            "best": (max(rows, key=lambda r: r["best_pips"]) if rows else None)}


# --------------------------------------------------------- TRADING PLAN ------
PLAN_DEFAULTS = {"capital": 500.0, "months": 6, "risk": 1.0, "target": 8.0,
                 "trades_day": 2, "win": 55.0, "rr": 1.6, "currency": "USD",
                 # ---- v1.9.1: the plan can be built DAY BY DAY --------------
                 "days": 20,          # how many TRADING DAYS the plan covers
                 "per": "DAYS",       # DAYS = day by day / MONTHS = month by month
                 "per_day": 0.0}      # the plan's money a day (the daily target)


def plan_settings(force: bool = False) -> dict:
    """The plan inputs (capital / months / risk / target) - remembered in state."""
    out = dict(PLAN_DEFAULTS)
    try:
        if not force:
            saved = state_get("plan")
            if isinstance(saved, dict):
                out.update({k: v for k, v in saved.items() if k in out})
    except Exception:
        pass
    try:
        acc = mt5.account_info() if (HAVE_MT5 and mt5_ready()) else None
        if acc and float(acc.balance or 0) > 0:
            out["live_balance"] = round(float(acc.balance), 2)
            out["currency"] = str(getattr(acc, "currency", "USD") or "USD")
    except Exception:
        pass
    return out


def plan_save(values: dict) -> None:
    try:
        cur = plan_settings()
        cur.update({k: v for k, v in (values or {}).items() if k in PLAN_DEFAULTS})
        state_set("plan", cur)
    except Exception:
        pass


def trading_plan(capital: float = None, months: int = None, risk: float = None,
                 target: float = None, win: float = None, rr: float = None,
                 trades_day: int = None, days: int = None,
                 per: str = None) -> dict:
    """The AI trading plan: money management + risk rules + compounding table.

    Everything is derived from YOUR numbers - the win rate and the reward/risk
    come from your own journal when it has enough trades.

    v1.9.1: **per="DAYS"** builds the table one TRADING DAY at a time, for
    `days` days (the user decides how many).  per="MONTHS" is the old view.
    """
    cfg = plan_settings()
    met = {}
    try:
        met = jr_metrics() or {}
    except Exception:
        met = {}
    cap = float(capital if capital is not None else cfg.get("capital") or 500.0)
    mon = int(months if months is not None else cfg.get("months") or 6)
    rp = float(risk if risk is not None else cfg.get("risk") or 1.0)
    tg = float(target if target is not None else cfg.get("target") or 8.0)
    w = float(win if win is not None else (met.get("win") or cfg.get("win") or 55.0))
    r = float(rr if rr is not None else (met.get("rr") or cfg.get("rr") or 1.6))
    td = int(trades_day if trades_day is not None else cfg.get("trades_day") or 2)
    # ---- v1.9.1: how many days / months, and which of the two the user wants --
    cnt = int(days if days is not None else cfg.get("days") or 20)
    unit = str(per if per is not None else cfg.get("per") or "DAYS")
    unit = "MONTHS" if unit.strip().upper().startswith("M") else "DAYS"
    cap = max(10.0, cap)
    cnt = max(1, min(400, cnt))
    mon = max(1, min(60, mon))
    rp = max(0.1, min(10.0, rp))
    w = max(1.0, min(95.0, w))
    r = max(0.2, min(10.0, r))
    td = max(1, min(20, td))

    risk_usd = round(cap * rp / 100.0, 2)
    day_stop = round(risk_usd * 2.0, 2)                 # two losses = stop the day
    week_stop = round(risk_usd * 4.0, 2)
    exp_r = (w / 100.0) * r - (1 - w / 100.0)            # expectancy in R
    exp_usd = round(risk_usd * exp_r, 2)
    per_day = round(exp_usd * td, 2)
    per_month = round(per_day * 21.0, 2)
    month_pct = round(per_month / cap * 100.0, 2) if cap else 0.0
    day_pct = round(per_day / cap * 100.0, 4) if cap else 0.0   # v1.9.1
    # gold: 1 pip = 0.1 and 1.00 lot = 10 USD per pip
    sl_pips = 50.0
    lot = round(risk_usd / (sl_pips * 10.0), 3)
    lot = max(0.01, lot)

    rows, bal = [], cap
    if unit == "MONTHS":
        for i in range(1, mon + 1):
            start = bal
            gain = start * (month_pct / 100.0)
            bal = round(start + gain, 2)
            rows.append({"month": i, "day": i * 21, "days": 21, "start": round(start, 2),
                         "gain": round(gain, 2), "end": bal, "pct": month_pct,
                         "label": f"M{i}", "target_hit": bool(month_pct >= tg)})
    else:
        # v1.9.1: one line per TRADING DAY (grouped when the run is very long
        # so the table + the chart stay readable)
        span = max(1, int(math.ceil(cnt / 60.0)))
        i = 1
        while i <= cnt:
            take = min(span, cnt - i + 1)
            start = bal
            for _k in range(take):
                bal = round(bal * (1.0 + day_pct / 100.0), 2)
            rows.append({"day": i, "days": take, "month": i * 21,
                         "start": round(start, 2), "gain": round(bal - start, 2),
                         "end": bal, "pct": round(day_pct * take, 4),
                         "label": (f"D{i}" if take == 1 else f"D{i}-{i + take - 1}"),
                         "target_hit": bool(day_pct * take >= tg)})
            i += take
    goal_days = 0
    if day_pct > 0 and tg > 0:
        goal_days = int(math.ceil(tg / day_pct))
    return {"capital": cap, "months": mon, "risk_pct": rp, "target_pct": tg,
            "win": w, "rr": r, "trades_day": td, "risk_usd": risk_usd,
            "day_stop": day_stop, "week_stop": week_stop, "expectancy_r": round(exp_r, 3),
            "expectancy_usd": exp_usd, "per_day": per_day, "per_month": per_month,
            "month_pct": month_pct, "day_pct": day_pct,
            "per": unit, "days": cnt, "span": (rows[0]["days"] if rows else 1),
            "sl_pips": sl_pips, "lot": lot,
            "table": rows, "goal_months": mon, "goal_days": goal_days,
            "goal_within": bool(goal_days and goal_days <= cnt),
            "from_journal": bool(met.get("n"))}


def plan_text(period_word: str = "") -> str:
    """The plan as a Telegram message (also used by the app + the PDF)."""
    pl = trading_plan()
    cur = plan_settings().get("currency", "USD")
    _cnt, _w = ((pl['days'], "trading day") if pl.get("per") == "DAYS"
                else (pl['months'], "month"))
    _scope = f"{_cnt} {_w}{'' if _cnt == 1 else 's'}"
    L = [tg_title(ev_icon("plan", "\U0001F3AF"), "AI TRADING PLAN",
                  f"capital {pl['capital']:,.0f} {cur}   |   "
                  f"{_scope}   |   risk {pl['risk_pct']:g}% per trade"),
         f"  MAX RISK / TRADE      {pl['risk_usd']:,.2f} {cur}   "
         f"({pl['risk_pct']:g}% of the capital)",
         f"  LAYERS               every signal is split - each layer risks "
         f"{pl['risk_usd']:,.2f} at most",
         f"  STOP THE DAY          after {pl['day_stop']:,.2f} {cur} down (2 losses)",
         f"  STOP THE WEEK         after {pl['week_stop']:,.2f} {cur} down (4 losses)",
         f"  POSITION SIZE         ~{pl['lot']:.3f} lot for a {pl['sl_pips']:g}-pip "
         f"stop on gold (100 pip = {pl['risk_usd']:,.2f} {cur} at "
         f"{pl['lot'] / 1.0 * 10:.2f} USD/pip per lot)",
         "",
         f"  win rate used         {pl['win']:.0f}%"
         + ("  (from your journal)" if pl["from_journal"] else "  (default)"),
         f"  reward / risk         {pl['rr']:.2f} : 1",
         f"  expectancy            {pl['expectancy_r']:+.3f} R = "
         f"{pl['expectancy_usd']:+,.2f} {cur} per trade",
         f"  signals a day         {pl['trades_day']}  ->  "
         f"{pl['per_day']:+,.2f} {cur}/day  ~  {pl['per_month']:+,.2f} {cur}/month",
         "",
         f"  WHAT THAT IS          {pl['month_pct']:+.2f}% a month",
         ""]
    if pl["month_pct"] <= 0:
        L.append("  [!] with these numbers the expectancy is NEGATIVE - "
                 "fix the win rate or the reward first")
    _per = pl.get("per", "DAYS")
    L.append(f"  COMPOUNDING PLAN  (profit stays in, the risk follows the balance)")
    L.append(f"  {pl['per_day']:+,.2f} {cur} a day  =  {pl['day_pct']:+.2f}% a day"
             + (f"   ->   the {pl['target_pct']:g}% target lands on day "
                f"{pl['goal_days']}" if (pl["goal_days"] and _per == "DAYS") else ""))
    if _per == "DAYS":
        L.append("      day     start         gain         end        %")
    else:
        L.append("      month   start         gain         end        %")
    for row in pl["table"]:
        L.append(f"      {str(row.get('label') or row['month']):>6}  "
                 f"{row['start']:>10,.2f}   {row['gain']:>+10,.2f}   "
                 f"{row['end']:>10,.2f}   {row['pct']:+.2f}%")
    L += ["",
          "  RULES THAT MAKE IT WORK",
          "      1. never risk more than the risk/trade number - not once",
          "      2. two losses = stop for the day (the bot does this for you)",
          "      3. withdraw profit at the end of every month (keep the plan honest)",
          "      4. if you withdraw, cut the risk to the SMALLER balance",
          "      5. review the plan every Sunday - /metrics shows the real numbers",
          "      6. one bad week is data, not a reason to double the risk",
          "",
          "  change it:  /plan 1000 20 1 8 days     (capital  TRADING DAYS  risk%  target%/month)",
          "              /plan 1000 6 1 8 months    (the same plan month by month)",
          "              /plan days 30              (only the number of days changes)",
          "", tg_foot()]
    return "\n".join(L)


def plan_apply_to_settings(pl: dict = None) -> str:
    """Write the plan's risk % + daily stop into the engine settings."""
    pl = pl or trading_plan()
    out = []
    try:
        if set_setting_in_file("RISK_PERCENT", f"{pl['risk_pct']:g}"):
            out.append(f"RISK_PERCENT = {pl['risk_pct']:g}")
        if set_setting_in_file("MAX_DAILY_LOSS", f"{pl['day_stop']:g}"):
            out.append(f"MAX_DAILY_LOSS = {pl['day_stop']:g}")
    except Exception as exc:
        return f"could not save: {exc}"
    try:
        _day_stop = float(pl["day_stop"])
        set_loss_limit_enabled(_day_stop > 0, amount=_day_stop if _day_stop > 0 else None)
    except Exception:
        pass
    return ("the plan is now in the settings:\n  "
            + "\n  ".join(out)
            + "\n(close the bot, change it with the app or /losslimit, then start again)")


# ------------------------------------------------------- HOUSEKEEPING --------
async def half_hour_update_loop() -> None:
    """Check the configured voice/text update interval every 30 seconds."""
    while not stop_requested():
        await asyncio.sleep(30)
        if stop_requested():
            break
        try:
            half_hour_update()
        except Exception as exc:
            log(f"half-hour update: {exc}", "err")


async def housekeeping_loop() -> None:
    """Daily/weekly jobs: backups, REAL P&L from MT5, auto channel check,
    weekend flat. Runs every 5 minutes and does nothing most of the time."""
    _last = {"backup": 0.0, "real": 0.0, "chan": 0.0, "plan": 0.0, "status": 0.0}
    while not stop_requested():
        await asyncio.sleep(300)
        try:
            now = time.time()
            if AUTO_BACKUP and now - _last["backup"] > 3600:
                _last["backup"] = now
                auto_backup()
            if now - _last["real"] > 900 and HAVE_MT5 and not DRY_RUN:
                _last["real"] = now
                got = real_pl_sync(7.0)
                if got.get("fixed"):
                    log(f"      REAL P&L: {got['fixed']} trade(s) updated from "
                        f"MT5 history (commission + swap)", "info")
            if now - _last.get("status", 0) > 240:
                _last["status"] = now
                tg_status_write()                     # v1.9.2: keep it fresh
            if now - _last["chan"] > 3600:
                _last["chan"] = now
                if TRADE_JOURNAL:
                    auto_channel_check()
            if TRADE_JOURNAL and not _JR_LOADED:
                jr_load()
            weekend_flat_check()
        except Exception as exc:
            log(f"housekeeping: {exc}", "err")


def ev_icon_placeholder() -> None:
    return None


# =========================================================================== #
#  v1.9.0  DAILY TARGET  -  capital -> target -> progress -> voice
# =========================================================================== #
DT_DAYS = "dt_days"            # state: {day: {target, net, achieved}}
DT_MILES = "dt_milestones"     # state: {day: [25, 50, ...]}
DT_LAST_UP = "dt_last_update"  # state: the time of the last half hour update
NEXT_PLAN_KEY = "next_plan"    # state: the AI AGENT's plan for tomorrow


def capital_now() -> float:
    """The money the target is calculated from: LIVE balance first."""
    try:
        if DAILY_TARGET_CAPITAL and float(DAILY_TARGET_CAPITAL) > 0:
            return float(DAILY_TARGET_CAPITAL)
    except Exception:
        pass
    try:
        if HAVE_MT5 and mt5_ready():
            acc = mt5.account_info()
            if acc and float(acc.balance or 0) > 0:
                return float(acc.balance)
    except Exception:
        pass
    try:
        cfg = state_get("plan") or {}
        if float(cfg.get("capital") or 0) > 0:
            return float(cfg["capital"])
    except Exception:
        pass
    return 0.0


def plan_capital_add(amount) -> float:
    """ADD money to the plan's capital (a deposit, or today's profit)."""
    try:
        amt = float(amount)
    except Exception:
        return 0.0
    if not amt:
        return 0.0
    cfg = {}
    try:
        cfg = dict(state_get("plan") or {})
    except Exception:
        cfg = {}
    cur = float(cfg.get("capital") or capital_now() or 0.0)
    cfg["capital"] = round(max(0.0, cur + amt), 2)
    try:
        state_set("plan", cfg)
    except Exception:
        pass
    log(f"      plan capital: {cur:,.2f} {'+' if amt >= 0 else '-'} {abs(amt):,.2f} "
        f"-> {cfg['capital']:,.2f} USD", "ok")
    return cfg["capital"]


def daily_target_apply(mode: str = "PCT", value=None, capital=None,
                       on: bool = True) -> str:
    """v1.9.4: whatever the user typed becomes the daily target.

    ONE function does the checking + the saving, so the app boxes and the
    Telegram commands behave exactly the same:

        daily_target_apply("PCT", 3)        -> 3 % of the capital a day
        daily_target_apply("USD", 25)       -> 25 USD a day
        daily_target_apply("PLAN")          -> the AI plan's own money a day
        daily_target_apply(..., capital=500)  -> use this capital (0 = live)

    It never raises (the settings must always save - v1.7.1) and it writes the
    numbers into edgequant_auto.py so they survive a restart.
    """
    want = str(mode or "PCT").strip().upper()
    if want.startswith("USD"):
        want = "USD"
    elif want.startswith("PL"):                 # PLAN (PCT must stay PCT!)
        want = "PLAN"
    else:
        want = "PCT"
    amt = None
    try:
        if value not in (None, ""):
            amt = float(str(value).replace(",", ".").strip())
    except Exception:
        amt = None
    if want in ("PCT", "USD") and (amt is None or amt <= 0):
        return (f"!! type a number bigger than 0  (you typed {value!r}) - "
                f"example: mode PCT + 3  (3 % a day)  or  mode USD + 25")
    out = []
    globals()["DAILY_TARGET_MODE"] = want
    globals()["DAILY_TARGET_ON"] = bool(on)
    try:
        state_set("daily_target_mode", want)
        state_set("daily_target_on", bool(on))
    except Exception:
        pass
    for name, lit in (("DAILY_TARGET_MODE", f'"{want}"'),
                      ("DAILY_TARGET_ON", "True" if on else "False")):
        try:
            set_setting_in_file(name, lit)
        except Exception:
            pass
    if want == "PCT":
        globals()["DAILY_TARGET_PCT"] = float(amt)
        try:
            set_setting_in_file("DAILY_TARGET_PCT", f"{float(amt):g}")
        except Exception:
            pass
        out.append(f"{float(amt):g} % of the capital a day")
    elif want == "USD":
        globals()["DAILY_TARGET_USD"] = float(amt)
        try:
            set_setting_in_file("DAILY_TARGET_USD", f"{float(amt):g}")
        except Exception:
            pass
        out.append(f"{float(amt):,.2f} USD a day")
    else:
        try:
            _amt = float(trading_plan()["per_day"])
            plan_save({"per_day": _amt})
            out.append(f"the AI plan's own number ({_amt:+,.2f} USD a day)")
        except Exception:
            out.append("the AI plan's own number (press GENERATE THE PLAN)")
    if capital is not None and str(capital).strip() != "":
        try:
            capv = float(str(capital).replace(",", ".").strip())
        except Exception:
            capv = 0.0
        globals()["DAILY_TARGET_CAPITAL"] = max(0.0, capv)
        try:
            set_setting_in_file("DAILY_TARGET_CAPITAL", f"{max(0.0, capv):g}")
        except Exception:
            pass
        out.append("capital " + (f"{capv:,.2f} (fixed)" if capv > 0
                                 else "= the live MT5 balance"))
    when = "OFF" if not on else "ON"
    log("      daily target: " + when + "  -  " + ";  ".join(out), "ok")
    try:
        txt = daily_target_text().strip()
    except Exception:
        txt = ""
    return (f"daily target {when}:  " + ";  ".join(out) + ("\n\n" + txt if txt else ""))


def daily_target_value(day: str = "") -> dict:
    """(mode, target, capital, pct) - what today's target is."""
    mode = str(DAILY_TARGET_MODE or "PCT").strip().upper()
    capital = capital_now()
    pct = float(DAILY_TARGET_PCT or 0.0)
    target = 0.0
    if mode == "USD":
        target = float(DAILY_TARGET_USD or 0.0)
    elif mode == "PLAN":
        try:
            target = float((state_get("plan") or {}).get("per_day") or 0.0)
        except Exception:
            target = 0.0
        if target <= 0:
            # v1.9.1: the plan was never generated on this PC yet - work it out
            # once (and remember it) instead of silently using the % number
            try:
                target = float(trading_plan()["per_day"])
                if target > 0:
                    plan_save({"per_day": target})
            except Exception:
                target = 0.0
        if target <= 0:
            target = capital * pct / 100.0
    else:
        target = capital * pct / 100.0
    if not DAILY_TARGET_ON:
        target = 0.0
    return {"mode": mode, "target": round(max(0.0, target), 2),
            "capital": round(capital, 2), "pct": pct}


def dt_days_load() -> dict:
    try:
        data = state_get(DT_DAYS)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {}


def dt_day_record(day: str, target: float, net: float, achieved: bool) -> dict:
    """Archive a target the first time realized P/L reaches it; keep 60 days."""
    data = dt_days_load()
    rec = dict(data.get(day) or {})
    archived = bool(rec.get("archived") or rec.get("achieved") or achieved)
    rec.update({"target": round(float(target), 2), "net": round(float(net), 2),
                "achieved": archived, "archived": archived,
                "ts": rec.get("ts") or time.time()})
    if archived:
        rec["archived_at"] = rec.get("archived_at") or time.time()
    data[day] = rec
    try:
        keys = sorted(data)
        for old in keys[:-60]:
            data.pop(old, None)
        state_set(DT_DAYS, data)
    except Exception:
        pass
    return rec


def dt_streak(until_day: str = "") -> int:
    """How many days in a row the target was reached (yesterday backwards)."""
    data = dt_days_load()
    try:
        d = datetime.strptime(until_day or jr_today_key(), "%Y-%m-%d")
    except Exception:
        return 0
    n = 0
    for i in range(1, 61):
        key = (d - timedelta(days=i)).strftime("%Y-%m-%d")
        rec = data.get(key)
        if rec and rec.get("achieved"):
            n += 1
        else:
            break
    return n


def dt_hours_traded(day: str = "") -> float:
    """Hours since the first closed trade of the day (used for the pace)."""
    try:
        rows = [t for t in TRADES
                if jr_day_key(t.get("closed_ts")) == (day or jr_today_key())
                and t.get("closed_ts")]
        if not rows:
            return 0.0
        first = min(float(t["closed_ts"]) for t in rows)
        return max(0.05, (time.time() - first) / 3600.0)
    except Exception:
        return 0.0


def daily_target_state(day: str = "") -> dict:
    """Everything about today's target: progress, pace, milestones, streak."""
    day = day or jr_today_key()
    info = daily_target_value(day)
    target = float(info["target"])
    net = 0.0
    counts = {"n": 0, "tp": 0, "sl": 0, "be": 0, "manual": 0, "placed": 0, "filled": 0}
    try:
        if TRADE_JOURNAL and not _JR_LOADED:
            jr_load()
        counts = jr_daily(day) or counts
        net = float(counts.get("net") or 0.0)
    except Exception:
        pass
    floating = 0.0
    try:
        if HAVE_MT5 and mt5_ready():
            for p in (mt5.positions_get() or []):
                if MAGIC and p.magic != MAGIC:
                    continue
                floating += float(p.profit or 0.0)
    except Exception:
        floating = 0.0
    # Show live progress using realized + floating P/L, but only archive a
    # target once realized P/L reaches it. Floating profit can reverse.
    progress_net = net + floating
    done_pct = (progress_net / target * 100.0) if target > 0 else 0.0
    achieved_now = bool(target > 0 and net >= target)
    previous_record = (dt_days_load().get(day) or {})
    archived = bool(previous_record.get("archived") or previous_record.get("achieved")
                    or achieved_now)
    remaining = (0.0 if archived else max(0.0, target - progress_net)) if target > 0 else 0.0
    achieved = archived
    hours = dt_hours_traded(day)
    pace = (net / hours) if hours > 0 else 0.0
    eta_min = None
    if target > 0 and not achieved and pace > 0.01:
        eta_min = max(0, int(remaining / pace * 60))
    seen = {}
    try:
        seen = state_get(DT_MILES) or {}
    except Exception:
        seen = {}
    hit = list((seen.get(day) or [])) if isinstance(seen, dict) else []
    closed = int(counts.get("tp", 0)) + int(counts.get("sl", 0)) + \
        int(counts.get("be", 0)) + int(counts.get("manual", 0))
    rec = dt_day_record(day, target, net, achieved_now)
    return {"day": day, "mode": info["mode"], "capital": info["capital"],
            "pct": info["pct"], "target": target, "net": round(net, 2),
            "floating": round(floating, 2), "progress_net": round(progress_net, 2),
            "done_pct": round(done_pct, 1), "archived": bool(rec.get("archived")),
            "archived_at": rec.get("archived_at"),
            "floating_target": bool(target > 0 and progress_net >= target and net < target),
            "remaining": round(remaining, 2), "achieved": bool(rec.get("archived")),
            "counts": counts, "closed": closed, "hours": round(hours, 2),
            "pace": round(pace, 2), "eta_min": eta_min, "hit": hit,
            "streak": dt_streak(day), "milestones": list(TARGET_MILESTONES),
            "stop_after": bool(DAILY_TARGET_STOP_AFTER),
            "next_target": round(float(rec.get("target") or target), 2),
            "record": rec}


def dt_bar(pct: float, width: int = 22) -> str:
    """A progress bar that reads well in the console + Telegram."""
    try:
        p = max(0.0, min(100.0, float(pct)))
    except Exception:
        p = 0.0
    fill = int(round(width * p / 100.0))
    return "[" + "\u2588" * fill + "\u00B7" * (width - fill) + "]"


def daily_target_text(state: dict = None) -> str:
    """/target - the whole day on one screen."""
    st = state or daily_target_state()
    if not DAILY_TARGET_ON or st["target"] <= 0:
        return ("DAILY TARGET is OFF (or the capital is unknown).\n\n"
                "turn it on:\n"
                "      /target on\n"
                "      /target 3          (3% of the capital a day)\n"
                "      /target usd 25     (a fixed 25 USD a day)\n"
                "      /target plan       (the AI plan's per-day number)")
    if st["mode"] != "USD":
        sub_line = (f"{st['day']}   {st['mode']}   "
                    f"({st['pct']:g}% of {st['capital']:,.2f})")
    else:
        sub_line = f"{st['day']}   fixed money target"
    if st["achieved"]:
        bar_line = "DONE - well done"
    else:
        bar_line = f"{st['remaining']:,.2f} USD to go"
    L = [tg_title(ev_icon("plan", "\U0001F3AF"), "DAILY TARGET", sub_line),
         f"  TARGET      {st['target']:,.2f} USD",
         f"  TODAY       {st['net']:+,.2f} USD   ({st['done_pct']:+.1f}%)",
         f"  {dt_bar(st['done_pct'])}   {bar_line}",
         "",
         "",
         f"  trades      {st['counts'].get('placed', 0)} placed   "
         f"{st['counts'].get('filled', 0)} triggered   "
         f"TP {st['counts'].get('tp', 0)} | SL {st['counts'].get('sl', 0)} | "
         f"BE {st['counts'].get('be', 0)} | man {st['counts'].get('manual', 0)}",
         f"  floating    {st['floating']:+,.2f} USD   (open trades)"]
    if st["pace"]:
        L.append(f"  pace        {st['pace']:+,.2f} USD/hour"
                 + (f"   -> about {st['eta_min']} min to the target"
                    if st["eta_min"] else ""))
    if st["streak"]:
        L.append(f"  streak      {st['streak']} day(s) in a row the target was reached")
    L += ["",
          "  WHAT THE VOICE DOES  it calls the milestones "
          + " / ".join(f"{m}%" for m in st["milestones"]) + "  and the update every "
          + f"{UPDATE_EVERY_MIN:g} min",
          "",
          "  /target 5   /target usd 25   /target plan   /target stop on|off",
          "  /update     (send today's update right now)   /plan next (tomorrow)",
          tg_foot()]
    return "\n".join(L)


def dt_milestone_voice(pct: float, st: dict) -> None:
    """The voice steps: 25% -> ... -> 100% -> 150%."""
    step = None
    for m in sorted(st.get("milestones") or [], reverse=True):
        if pct >= m:
            step = m
            break
    if not step:
        return
    seen = {}
    try:
        seen = dict(state_get(DT_MILES) or {})
    except Exception:
        seen = {}
    got = list(seen.get(st["day"]) or [])
    if step in got:
        return
    got.append(step)
    seen[st["day"]] = got
    try:
        state_set(DT_MILES, seen)
    except Exception:
        pass
    if dt_voice_lang() == "SI":
        extra = (f"ඉලක්කය {float(st.get('target') or 0.0):.2f} USD. "
                 f"ප්‍රගතිය {float(st.get('done_pct') or pct):.1f}%. ")
        if st.get("achieved"):
            extra += "වසාගත් ලාභයෙන් ඉලක්කය සම්පූර්ණයි."
        elif st.get("floating_target"):
            extra += "පාවෙන ලාභය සමඟ සීමාවට ළඟයි; වසාගත් ලාභයෙන් තවම සම්පූර්ණ නැහැ."
        else:
            extra += f"තව {float(st.get('remaining') or 0.0):.2f} USDයි."
    else:
        extra = (f"{step} percent of the daily target"
                 if step < 100 else
                 ("Daily target achieved" if st.get("achieved") else
                  "Floating profit reached the target level; closed profit has not yet reached it"
                  if st.get("floating_target") else "Far above the daily target"))
    say("target", extra)                       # v1.9.0 voice step
    state_tag = ("REACHED" if st.get("achieved") else
                 "FLOATING LEVEL" if st.get("floating_target") else
                 "PROGRESS" if step < 100 else "PASSED")
    notify("\n".join([
        tg_title(ev_icon("plan", "\U0001F3AF"),
                 f"DAILY TARGET  {step}%  {state_tag}",
                 f"{st['net']:+,.2f} of {st['target']:,.2f} USD   ({st['day']})"),
        "  " + dt_bar(pct) + f"   {pct:.1f}%",
        (f"  still to go   {st['remaining']:,.2f} USD" if not st["achieved"]
         else "  the day is DONE - the next day's target is being prepared"),
        "",
        "  /target        (the full picture)      /plan next   (tomorrow)",
        tg_foot()]))


def daily_target_check(speak: bool = True) -> dict:
    """Called after every closed trade: milestones, voice, next day readiness."""
    st = daily_target_state()
    if st["target"] <= 0:
        return st
    dt_milestone_voice(st["done_pct"], st)
    if st["achieved"]:
        try:
            if state_get("dt_done_day") != st["day"]:
                state_set("dt_done_day", st["day"])
                log(f"      DAILY TARGET REACHED: {st['net']:+,.2f} of "
                    f"{st['target']:,.2f} USD", "ok")
                # The completion call is an explicit user-requested alert: it
                # stays audible even if ordinary event speech was switched off.
                if dt_voice_lang() == "SI":
                    _done_voice = (f"ඉලක්කය {st['target']:.2f} USD. "
                                   f"අද වසාගත් ලාභය {st['net']:.2f} USD. "
                                   f"TP {st['counts'].get('tp', 0)}, "
                                   f"SL {st['counts'].get('sl', 0)}, "
                                   f"BE {st['counts'].get('be', 0)}.")
                else:
                    _done_voice = (f"Target {st['target']:.2f} USD. "
                                   f"Today's realized P and L {st['net']:.2f} USD. "
                                   f"TP {st['counts'].get('tp', 0)}, "
                                   f"SL {st['counts'].get('sl', 0)}, "
                                   f"BE {st['counts'].get('be', 0)}.")
                say("target_done", extra=_done_voice, force=True)
                notify("\n".join([
                    tg_title(ev_icon("peak", "\U0001F3C6"), "DAILY TARGET ACHIEVED",
                             f"{st['net']:+,.2f} USD   (target "
                             f"{st['target']:,.2f})",
                             f"{st['counts'].get('tp', 0)} TP / "
                             f"{st['counts'].get('sl', 0)} SL today"),
                    "  " + dt_bar(100.0) + "   100%",
                    "  " + ("NEW ORDERS ARE OFF for today (DAILY_TARGET_STOP_AFTER)"
                            if st["stop_after"] else
                            "you can stop here - or keep going "
                            "(/target stop on to stop by itself)"),
                    "  NEXT        tomorrow's target is prepared by the AI AGENT "
                    "at the evening summary",
                    tg_foot()]))
                next_day_plan()          # prepare it right away
        except Exception:
            pass
    return st


def half_hour_best_channel(day: str = "") -> dict:
    """The channel with the highest realized net P/L from today's closed trades."""
    day = day or jr_today_key()
    groups = {}
    try:
        if TRADE_JOURNAL and not _JR_LOADED:
            jr_load()
        for trade in TRADES:
            if trade.get("status") != "closed" or not trade.get("closed_ts"):
                continue
            if jr_day_key(trade.get("closed_ts")) != day:
                continue
            name = str(trade.get("source") or "Unknown channel")
            row = groups.setdefault(name, {"name": name, "net": 0.0, "n": 0})
            row["net"] += float(trade.get("net") or 0.0)
            row["n"] += 1
    except Exception:
        return {}
    return sorted(groups.values(), key=lambda r: (-float(r["net"]), r["name"].lower()))[0] \
        if groups else {}


def mt5_capital_snapshot() -> list:
    """Read balance/equity per reachable local MT5 account without mixing currencies."""
    if not HAVE_MT5 or mt5 is None:
        return []
    try:
        names = list(broker_names() or [str(CURRENT_BROKER.get("name") or "MAIN")])
    except Exception:
        names = [str(CURRENT_BROKER.get("name") or "MAIN")]
    keep = str((CURRENT_BROKER or {}).get("name") or "")
    rows = []
    try:
        for name in names:
            try:
                ready = select_broker(name) if len(names) > 1 else mt5_ready()
                if not ready:
                    continue
                acc = mt5.account_info()
                if not acc:
                    continue
                rows.append({"name": str(getattr(acc, "name", "") or name),
                             "broker": str(getattr(acc, "company", "") or
                                           getattr(acc, "server", "") or name),
                             "currency": str(getattr(acc, "currency", "") or ""),
                             "balance": float(getattr(acc, "balance", 0.0) or 0.0),
                             "equity": float(getattr(acc, "equity", 0.0) or 0.0),
                             "login": str(getattr(acc, "login", "") or "")})
            except Exception as exc:
                log(f"      account capital read ({name}): {exc}", "warn")
    finally:
        if keep and len(names) > 1 and keep in names:
            try:
                select_broker(keep)
            except Exception:
                pass
    return rows


def half_hour_voice_details(st: dict, best_trade: dict = None,
                            best_channel: dict = None, lang: str = "EN",
                            channel_rows: list = None, account_rows: list = None) -> str:
    """Dynamic 30-minute voice report: target, live P/L, outcomes and source."""
    counts = st.get("counts") or {}
    net = float(st.get("net") or 0.0)
    floating = float(st.get("floating") or 0.0)
    target = float(st.get("target") or 0.0)
    progress = float(st.get("done_pct") or 0.0)
    remaining = float(st.get("remaining") or 0.0)
    achieved = bool(st.get("achieved"))
    floating_target = bool(st.get("floating_target"))
    placed, filled = int(counts.get("placed", 0) or 0), int(counts.get("filled", 0) or 0)
    tp, sl = int(counts.get("tp", 0) or 0), int(counts.get("sl", 0) or 0)
    be, manual = int(counts.get("be", 0) or 0), int(counts.get("manual", 0) or 0)
    closed = int(counts.get("closed", tp + sl + be + manual) or 0)
    best_trade = best_trade or {}
    best_channel = best_channel or {}
    channel_rows = [r for r in (channel_rows or []) if isinstance(r, dict)]
    account_rows = [r for r in (account_rows or []) if isinstance(r, dict)]
    open_now = int(counts.get("open_now", 0) or 0)
    pending_now = int(counts.get("pending_now", counts.get("still", 0)) or 0)

    def short_name(value, limit: int = 24) -> str:
        value = re.sub(r"[\r\n\x00-\x1f]+", " ", str(value or "-"))
        return re.sub(r"\s+", " ", value).strip()[:max(1, int(limit))] or "-"

    def side_name(value, sinhala=False) -> str:
        side = str(value or "").strip().upper()
        if sinhala:
            return "මිලදී ගැනීමේ" if side == "BUY" else "විකිණීමේ" if side == "SELL" else ""
        return side

    if str(lang or "EN").strip().upper()[:2] == "SI":
        # Spoken as a short market recap, with connective phrasing rather than
        # reading dashboard labels. Every figure below is EdgeQuant-only.
        def money(value):
            return f"{abs(float(value or 0.0)):,.2f}"

        pl_text = ("ආයුබෝවන්! අද වෙළඳාම ගැන කෙටියෙන් බලමු. "
                   "මේ වාර්තාව EdgeQuant කළමනාකරණය කරන ගනුදෙනු ගැන විතරයි.")
