def voice_sentence(event: str, trade: dict = None, extra: str = "",
                   lang: str = None) -> str:
    """What the voice SAYS: which channel, which event, how many pips.

    v1.9.0: VOICE_LANG = "SI" -> the Sinhala sentence (see voice_sentence_si).
    lang="EN"/"SI" forces that language (the self test uses it, so a user who
    switches to SI still gets a clean --selftest).
    """
    _want = str(lang if lang else (VOICE_LANG or "EN")).strip().upper()[:2]
    if _want.startswith("SI"):
        return voice_sentence_si(event, trade, extra)
    t = trade or {}
    ch = ("" if str(event or "").strip().lower() == "update" else
          str(t.get("source") or _CUR_CHANNEL[0] or "").strip())
    ch = re.sub(r"(?i)\bchannel\b", "", ch).strip(" -|.")
    pips = None
    try:
        if t.get("close_price") and t.get("open_price"):
            pip = float(t.get("pip") or pip_size_of(t.get("symbol") or "XAUUSD") or 0.1)
            d = float(t["close_price"]) - float(t["open_price"])
            if str(t.get("direction") or "BUY").upper() == "SELL":
                d = -d
            pips = d / pip if pip else None
        elif "pips" in t:
            pips = float(t["pips"])
        else:
            pips = trade_pips(t) if t else None
    except Exception:
        pips = None
    what = {"tp": "Take profit hit", "sl": "Stop loss hit", "be": "Break even",
            "manual": "Trade closed", "filled": "Order filled", "placed": "Orders placed",
            "signal": "New signal received",
            "loss_limit": "Daily loss limit reached", "weekend": "Market closing for the weekend",
            "summary": "Daily summary is ready", "online": "EdgeQuant Sentinel is online",
            "bigwin": "Big win", "target_done": "Daily target reached"}.get(
                str(event).lower(), "EdgeQuant update")
    bits = [what]
    if ch:
        bits.append(ch)
    if pips is not None and abs(float(pips)) >= 1:
        p = float(pips)
        bits.append(f"{'plus' if p > 0 else 'minus'} {abs(p):.0f} pips")
    if str(event or "").strip().lower() == "filled":
        side = str(t.get("direction") or "").strip().upper()
        symbol = str(t.get("symbol") or "").strip()
        if symbol or side:
            bits.append(" ".join(x for x in (symbol, side) if x))
        for key, label in (("signal_ts", "signal received at"),
                           ("placed_ts", "order placed at"),
                           ("activated_ts", "activated at")):
            try:
                value = float(t.get(key) or
                              (t.get("opened_ts") if key == "activated_ts" else 0) or 0)
                if value:
                    bits.append(f"{label} {datetime.fromtimestamp(value).strftime('%H:%M:%S')}")
            except (TypeError, ValueError, OSError):
                pass
        try:
            lot = float(t.get("lot") or 0.0)
            if lot:
                bits.append(f"lot {lot:g}")
            price = float(t.get("open_price") or t.get("price") or 0.0)
            if price:
                bits.append(f"entry price {price:g}")
            sl = float(t.get("sl_now") or t.get("sl") or 0.0)
            tp = float(t.get("tp_now") or t.get("tp") or 0.0)
            if sl:
                bits.append(f"stop loss {sl:g}")
            if tp:
                bits.append(f"take profit {tp:g}")
            ticket = str(t.get("ticket") or "").strip()
            if ticket:
                bits.append(f"ticket {ticket}")
        except (TypeError, ValueError):
            pass
    if extra:
        bits.append(str(extra))
    text = ". ".join(b for b in bits if b).strip()
    if not text.endswith((".", "!", "?")):
        text += "."
    return text


SAPI_VOICE_CACHE = [None]
LOCAL_SINHALA_TTS_PROCESS = [None]
LOCAL_SINHALA_TTS_LOCK = threading.RLock()
LOCAL_SINHALA_TTS_MONITOR_PID = [None]
VOICE_LAST_DISPATCH = [{"state": "idle", "route": "", "id": "", "lang": ""}]
VOICE_DISPATCH_BY_EVENT = {}
VOICE_DISPATCH_BY_ID = {}


def _sapi_voice_records() -> list:
    """Enumerate installed Windows voices with culture and gender metadata."""
    if SAPI_VOICE_CACHE[0] is None:
        records = []
        if os.name == "nt":
            try:
                import subprocess as _sp
                script = (
                    "Add-Type -AssemblyName System.Speech; "
                    "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer; "
                    "$s.GetInstalledVoices() | ForEach-Object { "
                    "$v=$_.VoiceInfo; "
                    "Write-Output ($v.Name + '|' + $v.Culture.Name + '|' + $v.Gender.ToString()) }"
                )
                out = _sp.run(["powershell", "-NoProfile", "-Command", script],
                              capture_output=True, text=True, timeout=8)
                for line in (out.stdout or "").splitlines():
                    bits = line.strip().split("|", 2)
                    if len(bits) >= 2 and bits[0].strip():
                        records.append({"name": bits[0].strip(),
                                        "culture": bits[1].strip().lower(),
                                        "gender": bits[2].strip().lower() if len(bits) > 2 else ""})
            except Exception:
                records = []
        SAPI_VOICE_CACHE[0] = records
    cached = SAPI_VOICE_CACHE[0]
    if isinstance(cached, dict):           # v4.7 cache shape / injected tests
        return [{"culture": str(k).lower(), "name": str(v), "gender": ""}
                for k, v in cached.items()]
    return [r for r in (cached or []) if isinstance(r, dict)]


def voice_sapi_pick(lang: str) -> str:
    """Choose a matching installed Windows voice; Sinhala requires FEMALE SAPI."""
    lang = (lang or dt_voice_lang()).strip().upper()[:2]
    records = _sapi_voice_records()
    if lang == "SI":
        candidates = [r for r in records if
                      str(r.get("culture") or "").startswith("si") or
                      "sinhala" in str(r.get("name") or "").lower()]
        female = [r for r in candidates
                  if "female" in str(r.get("gender") or "").lower()]
        return str(female[0].get("name") or "") if female else ""
    if lang == "EN":
        candidates = [r for r in records if str(r.get("culture") or "").startswith("en")]
        return str(candidates[0].get("name") or "") if candidates else ""
    return ""


def voice_sapi_gender(lang: str = None) -> str:
    """Gender of the selected Windows SAPI voice, if the OS reports it."""
    want = str(lang or dt_voice_lang()).strip().upper()[:2]
    pick = voice_sapi_pick(want)
    for record in _sapi_voice_records():
        if str(record.get("name") or "") == pick:
            return str(record.get("gender") or "unknown")
    return ""


def voice_sapi_refresh(lang: str = None, scan: bool = True) -> str:
    """Refresh installed Windows voice inventory."""
    SAPI_VOICE_CACHE[0] = None
    return voice_sapi_pick(lang or dt_voice_lang()) if scan else ""


def voice_sapi_cached(lang: str = None) -> str:
    """Read the cached voice choice without launching a subprocess."""
    if SAPI_VOICE_CACHE[0] is None:
        return ""
    return voice_sapi_pick(lang or dt_voice_lang())


def local_sinhala_voice_paths() -> dict:
    """Expected isolated Python 3.11 runtime, worker, model, and private queue."""
    model_dir = HERE / str(VOICE_DIR or "voice") / "si" / "female_vits"
    env_dir = HERE / ".sinhala-voice-env"
    py = env_dir / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
    queue_root = Path(os.environ.get("LOCALAPPDATA") or tempfile.gettempdir())
    queue_dir = queue_root / "EdgeQuantSentinel" / "sinhala_voice_queue"
    return {"model_dir": model_dir, "model": model_dir / "Nipunika_210000.pth",
            "config": model_dir / "Nipunika_config.json",
            "romanizer": model_dir / "romanizer.py", "python": py,
            "runtime_marker": env_dir / ".edgequant_sinhala_voice_ready",
            "worker": HERE / "edgequant_sinhala_voice_worker.py",
            "queue_dir": queue_dir}


def local_sinhala_voice_status() -> dict:
    """Report optional offline female TTS readiness without loading the model."""
    paths = local_sinhala_voice_paths()
    installed = all(paths[k].is_file() for k in
                    ("model", "config", "romanizer", "python", "runtime_marker", "worker"))
    queue_dir = paths["queue_dir"]
    state = {"state": "not installed" if not installed else "installed",
             "error": "", "ts": 0.0}
    try:
        status_path = queue_dir / "status.json"
        if status_path.is_file():
            loaded = json.loads(status_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                state.update(loaded)
    except Exception:
        pass
    return {"available": bool(installed), "voice": "Nipunika (female Sinhala)",
            "state": str(state.get("state") or "installed"),
            "error": str(state.get("error") or ""),
            "model_dir": str(paths["model_dir"]), "python": str(paths["python"]),
            "queue_dir": str(queue_dir)}


def _monitor_local_sinhala_worker(proc, queue_dir: Path) -> None:
    """Report actual local playback completion/errors back into the app log."""
    status_seen = ""
    while proc.poll() is None:
        try:
            results = queue_dir / "results"
            if results.is_dir():
                for result_file in sorted(results.glob("*.json")):
                    try:
                        result = json.loads(result_file.read_text(encoding="utf-8"))
                        if result.get("id"):
                            dispatch = VOICE_DISPATCH_BY_ID.get(result.get("id"))
                            if dispatch is not None:
                                dispatch["state"] = "played" if result.get("ok") else "failed"
                                dispatch["error"] = str(result.get("error") or "")
                                dispatch["completed_ts"] = time.time()
                            VOICE_DISPATCH_BY_ID.pop(result.get("id"), None)
                        if result.get("ok"):
                            log("      voice: offline female Sinhala narration played", "ok")
                        else:
                            log("      voice: offline Sinhala narration failed: "
                                + str(result.get("error") or "unknown error"), "err")
                        result_file.unlink(missing_ok=True)
                    except Exception:
                        pass
            status_file = queue_dir / "status.json"
            if status_file.is_file():
                status = json.loads(status_file.read_text(encoding="utf-8"))
                error = str(status.get("error") or "")
                if status.get("state") == "error" and error and error != status_seen:
                    status_seen = error
                    log("      voice: offline Sinhala voice worker error: " + error, "err")
        except Exception:
            pass
        time.sleep(0.25)
    try:
        status_file = queue_dir / "status.json"
        if status_file.is_file():
            status = json.loads(status_file.read_text(encoding="utf-8"))
            error = str(status.get("error") or "")
            if status.get("state") == "error" and error:
                for dispatch in list(VOICE_DISPATCH_BY_ID.values()):
                    if dispatch.get("state") == "queued":
                        dispatch["state"] = "failed"
                        dispatch["error"] = error
                        dispatch["completed_ts"] = time.time()
                VOICE_DISPATCH_BY_ID.clear()
                if error != status_seen:
                    log("      voice: offline Sinhala voice worker error: " + error, "err")
        results = queue_dir / "results"
        for result_file in sorted(results.glob("*.json")) if results.is_dir() else []:
            result = json.loads(result_file.read_text(encoding="utf-8"))
            if result.get("id"):
                dispatch = VOICE_DISPATCH_BY_ID.get(result.get("id"))
                if dispatch is not None:
                    dispatch["state"] = "played" if result.get("ok") else "failed"
                    dispatch["error"] = str(result.get("error") or "")
                    dispatch["completed_ts"] = time.time()
                VOICE_DISPATCH_BY_ID.pop(result.get("id"), None)
            log("      voice: offline Sinhala narration " +
                ("played" if result.get("ok") else
                 "failed: " + str(result.get("error") or "unknown error")),
                "ok" if result.get("ok") else "err")
            result_file.unlink(missing_ok=True)
    except Exception:
        pass


def local_sinhala_voice_speak(text: str) -> str:
    """Queue a dynamic report for the private, offline female VITS worker."""
    paths = local_sinhala_voice_paths()
    ready = local_sinhala_voice_status()
    if not ready.get("available") or not text:
        return ""
    queue_dir = paths["queue_dir"]
    requests_dir = queue_dir / "requests"
    results_dir = queue_dir / "results"
    try:
        requests_dir.mkdir(parents=True, exist_ok=True)
        results_dir.mkdir(parents=True, exist_ok=True)
        with LOCAL_SINHALA_TTS_LOCK:
            proc = LOCAL_SINHALA_TTS_PROCESS[0]
            if proc is None or proc.poll() is not None:
                # Old requests must never be replayed after a crash/restart.
                for old_dispatch in list(VOICE_DISPATCH_BY_ID.values()):
                    if old_dispatch.get("state") == "queued":
                        old_dispatch["state"] = "failed"
                        old_dispatch["error"] = "voice worker restarted; old request was not replayed"
                        old_dispatch["completed_ts"] = time.time()
                VOICE_DISPATCH_BY_ID.clear()
                for folder in (requests_dir, results_dir, queue_dir / "audio"):
                    if folder.is_dir():
                        for stale in folder.iterdir():
                            if stale.is_file():
                                try:
                                    stale.unlink()
                                except OSError:
                                    pass
                (queue_dir / "STOP").unlink(missing_ok=True)
                flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
                worker_env = os.environ.copy()
                worker_env["PYTHONUTF8"] = "1"
                worker_env["PYTHONIOENCODING"] = "utf-8"
                proc = subprocess.Popen(
                    [str(paths["python"]), str(paths["worker"]), "--serve",
                     "--model-dir", str(paths["model_dir"]),
                     "--queue-dir", str(queue_dir)],
                    cwd=str(HERE), stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL, env=worker_env, creationflags=flags)
                LOCAL_SINHALA_TTS_PROCESS[0] = proc
                if LOCAL_SINHALA_TTS_MONITOR_PID[0] != proc.pid:
                    LOCAL_SINHALA_TTS_MONITOR_PID[0] = proc.pid
                    threading.Thread(target=_monitor_local_sinhala_worker,
                                     args=(proc, queue_dir), daemon=True,
                                     name="edgequant-sinhala-voice-monitor").start()
        request_id = f"{time.time_ns()}-{threading.get_ident()}"
        request_path = requests_dir / f"{request_id}.json"
        temp_path = requests_dir / f".{request_id}.tmp"
        temp_path.write_text(json.dumps({"id": request_id,
            "created_ts": time.time(), "text": str(text)[:7000]}, ensure_ascii=False),
            encoding="utf-8")
        temp_path.replace(request_path)
        VOICE_LAST_DISPATCH[0] = {"state": "queued", "route": "offline-local",
                                  "id": request_id, "lang": "SI", "error": "",
                                  "requested_ts": time.time()}
        VOICE_DISPATCH_BY_ID[request_id] = VOICE_LAST_DISPATCH[0]
        log("      voice: offline female Sinhala narration queued locally; report text stays on this PC",
            "info")
        return request_id
    except Exception as exc:
        log(f"      voice: could not queue the offline Sinhala female voice: {exc}", "err")
        return ""


def local_sinhala_voice_stop(timeout: float = 3.0) -> None:
    """Stop the private speech worker when the desktop closes."""
    proc = LOCAL_SINHALA_TTS_PROCESS[0]
    if proc is None or proc.poll() is not None:
        LOCAL_SINHALA_TTS_PROCESS[0] = None
        return
    try:
        queue_dir = local_sinhala_voice_paths()["queue_dir"]
        queue_dir.mkdir(parents=True, exist_ok=True)
        (queue_dir / "STOP").write_text(str(time.time()), encoding="ascii")
        proc.wait(timeout=max(0.1, float(timeout)))
    except Exception:
        try:
            proc.terminate()
            proc.wait(timeout=1.0)
        except Exception:
            pass
    LOCAL_SINHALA_TTS_PROCESS[0] = None

def voice_sapi(text: str, lang: str = None) -> bool:
    """Speak with a matching Windows voice; Sinhala never falls back to English."""
    if os.name != "nt" or not text:
        return False
    try:
        lang = (lang or dt_voice_lang()).strip().upper()[:2]
        pick = voice_sapi_pick(lang)
        if lang == "SI" and not pick:
            log("      voice: no Sinhala Windows voice found; English fallback is disabled",
                "warn")
            return False
        # Full human-readable Sinhala updates need more room than event alerts.
        # The limit is still small for a PowerShell invocation and is applied
        # after preserving Unicode and escaping quotes.
        safe = str(text).replace("'", "''")[:7000]
        vol = max(0, min(100, int(VOICE_VOLUME or 85)))
        sel = f"try {{ $s.SelectVoice('{pick}') }} catch {{ }};" if pick else ""
        cmd = ("Add-Type -AssemblyName System.Speech; "
               "$s = New-Object System.Speech.Synthesis.SpeechSynthesizer; "
               f"$s.Volume = {vol}; $s.Rate = 0; {sel} "
               f"$s.Speak('{safe}')")
        subprocess.Popen(["powershell", "-NoProfile", "-WindowStyle", "Hidden",
                          "-Command", cmd],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        return True
    except Exception:
        return False


def voice_play_file(path) -> bool:
    """Play a wav on Windows (winsound = no install).  False = could not."""
    if os.name != "nt" or not path:
        return False
    try:
        import winsound
        winsound.PlaySound(str(path), winsound.SND_FILENAME | winsound.SND_ASYNC
                           | winsound.SND_NODEFAULT)
        return True
    except Exception:
        return False


def voice_welcome_sentence(name: str = "", telegram: bool = False,
                           lang: str = None) -> str:
    """A login greeting in one selected language; Sinhala never contains English copy."""
    want = str(lang or dt_voice_lang()).strip().upper()[:2]
    clean = re.sub(r"[\r\n\x00-\x1f]", " ", str(name or ""))
    clean = re.sub(r"\s+", " ", clean).strip()[:64]
    if want == "SI":
        # Only include a name written in Sinhala script; do not ask a Sinhala
        # speech voice to pronounce an English display name as English speech.
        si_name = clean if any("\u0d80" <= ch <= "\u0dff" for ch in clean) else ""
        greeting = "ආයුබෝවන්" + (f", {si_name}" if si_name else "")
        if telegram:
            return greeting + "! ඔබගේ ටෙලිග්‍රෑම් ගිණුම සාර්ථකව සම්බන්ධ වුණා."
        return greeting + "! ඔබගේ වෙළෙඳ යෙදුම සූදානම්."
    greeting = "Welcome" + (f", {clean}" if clean else "")
    if telegram:
        return greeting + ". Your Telegram account is connected."
    return greeting + ". EdgeQuant Sentinel is ready."


def voice_welcome(name: str = "", telegram: bool = False, force: bool = False) -> str:
    """Speak the personalized login greeting in VOICE_LANG; never cross-fallback to English."""
    if not VOICE_ON and not force:
        return "off"
    lang = dt_voice_lang()
    text = voice_welcome_sentence(name, telegram=telegram, lang=lang)
    clip = voice_clip("online", lang=lang)
    mode = str(VOICE_MODE or "AI").strip().upper()
    played, spoke, queued = False, False, False
    if lang == "SI":
        # The selected Sinhala voice is female-only: prefer a matching female
        # SAPI voice, then the optional offline Nipunika VITS model. A static
        # clip is the final Sinhala-only fallback; English is never substituted.
        if voice_sapi_pick("SI"):
            spoke = bool(voice_sapi(text, lang=lang))
            if spoke:
                VOICE_LAST_DISPATCH[0] = {"state": "dispatched", "route": "windows-sapi",
                                          "id": "", "lang": "SI", "error": ""}
        if not spoke:
            queued = bool(local_sinhala_voice_speak(text))
        if not spoke and not queued:
            played = voice_play_file(clip) if clip else False
            VOICE_LAST_DISPATCH[0] = {"state": "started" if played else "unavailable",
                                      "route": "sinhala-clip" if played else "none",
                                      "id": "", "lang": "SI", "error": ""}
    else:
        if mode in ("AI", "BOTH"):
            played = voice_play_file(clip) if clip else False
        if mode in ("WINDOWS", "BOTH") or (mode == "AI" and not played):
            spoke = bool(voice_sapi(text, lang=lang))
    route = ("  [offline female Sinhala queued]" if queued else
             "  [female Windows voice dispatched]" if spoke and lang == "SI" else
             "  [clip started]" if played else "")
    log(f"      VOICE welcome ({lang}): {text}{route}"
        + ("  [clip]" if played and lang != "SI" else "")
        + ("  [windows voice]" if spoke and lang != "SI" else ""),
        "info" if (played or spoke or queued) else "warn")
    return text


def say(event: str, extra: str = "", trade: dict = None, force: bool = False) -> str:
    """Speak selected-language event text; Sinhala prefers the local female voice."""
    ev = str(event or "").strip().lower()
    if not VOICE_ON and not force:
        VOICE_LAST_DISPATCH[0] = {"state": "off", "route": "none", "id": "",
                                  "lang": dt_voice_lang(), "error": "voice is disabled",
                                  "event": ev}
        VOICE_DISPATCH_BY_EVENT[ev] = VOICE_LAST_DISPATCH[0]
        return "off"
    events = voice_events()
    # The periodic report has its own UPDATE_VOICE toggle; the ordinary
    # per-event filter must not suppress its requested live figures.
    if not force and ev != "update" and (not events or ev not in events):
        VOICE_LAST_DISPATCH[0] = {"state": "skipped", "route": "none", "id": "",
                                  "lang": dt_voice_lang(), "error": "event disabled",
                                  "event": ev}
        VOICE_DISPATCH_BY_EVENT[ev] = VOICE_LAST_DISPATCH[0]
        return "not an event"
    mode = str(VOICE_MODE or "AI").strip().upper()
    lang = dt_voice_lang()
    text = voice_sentence(ev, trade, extra, lang=lang)
    clip = voice_clip(ev, lang=lang)
    played, spoke, queued = False, False, False
    dynamic_event = (ev in ("update", "placed", "signal", "filled") or bool(extra) or
                     (lang == "SI" and bool(trade)))

    if lang == "SI":
        # Always use a language-matched female voice when available. The VITS
        # route synthesizes the changing report/order text locally; it never
        # sends P&L, prices, or channel names to a cloud service.
        if voice_sapi_pick("SI"):
            spoke = bool(voice_sapi(text, lang=lang))
            if spoke:
                VOICE_LAST_DISPATCH[0] = {"state": "dispatched", "route": "windows-sapi",
                                          "id": "", "lang": "SI", "error": "",
                                          "requested_ts": time.time()}
        if not spoke:
            queued = bool(local_sinhala_voice_speak(text))
        if not spoke and not queued:
            # Never use a static clip for a changing report. It cannot state
            # the figures that were just calculated.
            played = (voice_play_file(clip) if clip and not dynamic_event else False)
            state = "started" if played else "unavailable"
            VOICE_LAST_DISPATCH[0] = {"state": state,
                                      "route": "sinhala-clip" if played else "none",
                                      "id": "", "lang": "SI", "error": ""}
            if dynamic_event:
                local_ready = local_sinhala_voice_status().get("available")
                detail = ("no female Sinhala Windows voice was found and the offline female voice "
                          "model is not installed; click INSTALL OFFLINE VOICE in the Voice panel"
                          if not local_ready and not voice_sapi_pick("SI") else
                          "the offline Sinhala voice worker could not accept the report")
                VOICE_LAST_DISPATCH[0].update({"state": "unavailable", "route": "none",
                                               "lang": "SI", "event": ev,
                                               "error": detail, "requested_ts": time.time()})
                log(f"      voice: dynamic Sinhala {ev} not spoken; {detail}; "
                    "static clips and English fallback are disabled for this report", "warn")
            elif not played:
                log("      voice: no usable female Sinhala voice or Sinhala clip; "
                    "English fallback is disabled", "warn")
    else:
        if dynamic_event:
            if voice_sapi_pick(lang):
                spoke = bool(voice_sapi(text, lang=lang))
                if not spoke:
                    played = voice_play_file(clip) if clip else False
                    log(f"      voice: dynamic {ev} speech dispatch failed; "
                        "a static clip cannot read changing figures", "warn")
            else:
                played = voice_play_file(clip) if clip else False
                log(f"      voice: {lang} dynamic {ev} speech requires a matching Windows "
                    "speech voice; the event clip alone cannot read changing figures", "warn")
        else:
            if mode in ("AI", "BOTH"):
                played = voice_play_file(clip) if clip else False
            want_sapi = (mode in ("WINDOWS", "BOTH") or
                         (VOICE_SAY_PIPS and mode == "AI" and not played) or
                         (ev == "target_done" and not played))
            if want_sapi:
                spoke = bool(voice_sapi(text, lang=lang))

    VOICE_LAST_DISPATCH[0].update({"lang": lang, "event": ev,
                                   "text_length": len(text or "")})
    VOICE_DISPATCH_BY_EVENT[ev] = VOICE_LAST_DISPATCH[0]
    route = ("  [offline female Sinhala queued; awaiting playback result]" if queued else
             "  [female Windows voice dispatched]" if spoke and lang == "SI" else
             "  [clip started]" if played else
             "  [Windows voice dispatched]" if spoke else "")
    log(f"      VOICE {ev} ({lang}): {text}{route}",
        "info" if (played or spoke or queued) else "warn")
    return text


def voice_last_dispatch(event: str = "") -> dict:
    """A truthful event snapshot: queued/dispatched is not confirmed playback."""
    try:
        item = VOICE_DISPATCH_BY_EVENT.get(str(event or "").strip().lower()) if event else None
        return dict(item or VOICE_LAST_DISPATCH[0])
    except Exception:
        return {"state": "unknown", "route": "", "id": "", "lang": ""}


def voice_test(event: str = "tp") -> str:
    """Test one event once; do not replay the clip after say()."""
    if not VOICE_ON:
        return "VOICE_ON = False -> turn it on in the settings first"
    lang = dt_voice_lang()
    clip = voice_clip(event, lang=lang)
    text = voice_sentence(event, {"source": "TEST LIMIT CHANNEL"}, lang=lang)
    say(event, trade={"source": "TEST LIMIT CHANNEL"}, force=True)
    clip_note = clip.name if clip else ("Sinhala recording unavailable" if lang == "SI"
                                        else "recording unavailable")
    local = local_sinhala_voice_status()
    if voice_sapi_pick("SI"):
        sapi_note = "matching female Sinhala Windows voice found"
    elif local.get("available"):
        sapi_note = "offline female Nipunika voice installed"
    else:
        sapi_note = "female Sinhala voice not installed; dynamic speech stays off"
    dispatch = voice_last_dispatch(event)
    return (f"voice test '{event}' ({lang}):\n"
            f"  clip      {clip_note}\n"
            f"  sentence  {text}\n"
            f"  mode      {VOICE_MODE}   volume {VOICE_VOLUME}\n"
            f"  route     {dispatch.get('state', 'unknown')} via {dispatch.get('route', 'none')}\n"
            f"  Sinhala   {sapi_note if lang == 'SI' else 'not selected'}")


def voice_status() -> dict:
    """What the app shows in the VOICE box."""
    d = HERE / str(VOICE_DIR or "voice")
    files = sorted(x.name for x in d.glob("*.wav")) if d.exists() else []
    lang = dt_voice_lang()
    lang_clips = sorted(x.name for x in (d / lang.lower()).glob("*.wav")) \
        if lang == "SI" and (d / "si").exists() else files if lang == "EN" else []
    local = local_sinhala_voice_status()
    return {"on": bool(VOICE_ON), "mode": str(VOICE_MODE), "lang": lang,
            "dir": str(d), "files": files, "count": len(files),
            "lang_clips": lang_clips, "events": voice_events(),
            "say_pips": bool(VOICE_SAY_PIPS), "volume": VOICE_VOLUME,
            "sapi_voice": voice_sapi_cached(lang) if os.name == "nt" else "",
            "sapi_gender": voice_sapi_gender(lang) if os.name == "nt" else "",
            "local_sinhala": local, "last_dispatch": voice_last_dispatch(),
            "windows": os.name == "nt"}


# =========================================================================== #
#  PART 7 - ONE SIGNAL -> ORDERS
# =========================================================================== #
PAUSED = False                 # /pause -> True   (management keeps running)
_LOSS_LOCKED = ""              # day key of the day the loss limit was hit
PARTIAL_DONE: set = set()      # tickets that already had their partial close
_AGENT_LAST: dict = {}         # ticket -> last time the AI agent looked at it
_LAST_EXPIRY = [0.0]           # last time we checked for expired pending orders


def is_weekend_market_closed_reason(reason) -> bool:
    """Only the explicit weekend-closure reason may enter the deferred queue."""
    return str(reason or "").strip().casefold() == "the weekend (market closed)"


def market_open(symbol: str = "") -> tuple:
    """Is the market open?  (weekend / broker switched the symbol off / no ticks)"""
    if not SESSION_GUARD:
        return True, ""
    if not HAVE_MT5:
        return True, ""
    try:
        info = mt5.symbol_info(symbol) if symbol else None
        if info is not None and hasattr(info, "trade_mode") and info.trade_mode == 0:
            return False, "the broker switched this symbol off (trade_mode=disabled)"
        # Only the configured FX weekend itself is eligible for the deferred
        # queue. A stale tick or the Friday pre-close guard is not proof that
        # the market is closed for the weekend.
        try:
            _week_open, _week_reason = fx_open(utc_now())
            if not _week_open:
                return False, "the weekend (market closed)"
        except Exception:
            pass
        tick = mt5.symbol_info_tick(symbol) if symbol else None
        if tick is not None and getattr(tick, "time", 0):
            fresh = time.time() - float(tick.time)
            if fresh > max(1, int(SESSION_STALE_MIN)) * 60:
                mins = fresh / 60.0
                return False, f"no fresh price for {mins:.0f} min"
    except Exception:
        return True, ""
    return True, ""


def open_trade_count() -> int:
    """How many live + pending orders this bot holds (all brokers)."""
    n = 0
    if not HAVE_MT5:
        return 0
    for bname in broker_names():
        if len(broker_names()) > 1 and not select_broker(bname):
            continue
        try:
            n += len(my_positions()) + len(my_pendings())
        except Exception:
            pass
    return n


def day_net_pl(day: str = "") -> float:
    """Net P/L of one day (default today) - what the loss limit looks at."""
    return float(day_stats(day)["net"])


def loss_limit_amount() -> float:
    """Remembered daily loss-cap amount, even while the protection is OFF."""
    for key in ("max_daily_loss", "max_daily_loss_last_on"):
        try:
            value = float(state_get(key, None) or 0.0)
            if math.isfinite(value) and value > 0:
                return value
        except (TypeError, ValueError):
            pass
    try:
        value = float(MAX_DAILY_LOSS or 0.0)
        return value if math.isfinite(value) and value > 0 else 0.0
    except (TypeError, ValueError):
        return 0.0


def loss_limit_enabled() -> bool:
    """Whether the daily drawdown/loss protection is enabled."""
    flag = state_get("max_daily_loss_enabled", None)
    amount = loss_limit_amount()
    if flag is not None:
        return bool(flag) and amount > 0
    # Backward compatibility: older state used max_daily_loss=0 to mean OFF.
    old = state_get("max_daily_loss", None)
    if old is not None:
        try:
            return float(old) > 0
        except (TypeError, ValueError):
            return False
    return amount > 0


def set_loss_limit_enabled(enabled: bool, amount=None) -> bool:
    """Save the daily cap and ON/OFF state without discarding the last amount."""
    try:
        if amount is not None:
            cap = float(amount)
            if not math.isfinite(cap) or cap < 0 or cap > 1_000_000_000:
                return False
            if cap > 0:
                if not state_set("max_daily_loss", round(cap, 2)):
                    return False
                if not state_set("max_daily_loss_last_on", round(cap, 2)):
                    return False
                enabled = bool(enabled)
            else:
                enabled = False
        else:
            cap = loss_limit_amount()
        if enabled and cap <= 0:
            return False
        if enabled:
            if not state_set("max_daily_loss", round(cap, 2)):
                return False
            if not state_set("max_daily_loss_last_on", round(cap, 2)):
                return False
            # Explicitly turning protection back ON cancels a same-day unlock.
            state_set("loss_unlocked_day", "")
        return state_set("max_daily_loss_enabled", bool(enabled))
    except Exception:
        return False


def loss_limit_value() -> float:
    """Active daily loss cap in USD (0 = protection OFF)."""
    return loss_limit_amount() if loss_limit_enabled() else 0.0


def loss_unlocked_today() -> bool:
    """True when you unlocked today with /resetloss (it comes back tomorrow)."""
    try:
        return str(state_get("loss_unlocked_day", "")) == jr_today_key()
    except Exception:
        return False


def loss_limit_state() -> dict:
    """Everything the app / /status needs about the daily loss limit."""
    lim = loss_limit_value()
    try:
        if TRADE_JOURNAL and not _JR_LOADED:
            jr_load()
        net = day_net_pl()
    except Exception:
        net = 0.0
    hit = bool(lim > 0 and net <= -abs(lim) and not loss_unlocked_today())
    return {"limit": lim, "net": net, "hit": hit,
            "unlocked": loss_unlocked_today(), "left": (abs(lim) - abs(net)) if lim else 0.0}


def can_trade_now(symbol: str = "") -> tuple:
    """(ok, reason) - every guard in one place, checked before a new order."""
    global _LOSS_LOCKED
    if PAUSED:
        return False, "the bot is PAUSED (/resume in Telegram)"
    _lim = loss_limit_value()
    if _lim > 0 and not loss_unlocked_today():
        try:
            if TRADE_JOURNAL and not _JR_LOADED:
                jr_load()
            net = day_net_pl()
            if net <= -abs(_lim):
                if _LOSS_LOCKED != jr_today_key():
                    _LOSS_LOCKED = jr_today_key()
                    notify("\n".join([
                        tg_title(EV_ICON["losslimit"], "DAILY LOSS LIMIT HIT",
                                 f"today  {net:+.2f} USD   (limit -{abs(_lim):.2f})",
                                 "no NEW orders today - open trades are still managed"),
                        "  STOP and think for a minute - this is the protection working.",
                        "  want to trade anyway ?   /resetloss   (unlocks TODAY only)",
                        "  a smaller/bigger limit ?  /losslimit 50     (0 = no limit)",
                        "  or just wait - it starts again by itself tomorrow.",
                        tg_foot()]))
                return False, (f"daily loss limit hit (today {net:+.2f} USD, "
                               f"limit -{abs(_lim):.2f})   -   /resetloss to trade today")
        except Exception:
            pass
    if DAILY_TARGET_ON and DAILY_TARGET_STOP_AFTER:
        try:
            _dt = daily_target_state()
            if _dt["achieved"]:
                return False, (f"today's target is DONE ({_dt['net']:+,.2f} of "
                               f"{_dt['target']:,.2f} USD) - no NEW orders today "
                               f"(/target stop off to keep trading)")
        except Exception:
            pass
    ok, why = loss_streak_guard()                   # v1.8.0
    if not ok:
        return False, why
    ok, why = friday_guard()                        # v1.8.0 - weekend gap
    if not ok:
        return False, why
    if MAX_OPEN_ORDERS and MAX_OPEN_ORDERS > 0:
        n = open_trade_count()
        if n >= int(MAX_OPEN_ORDERS):
            return False, (f"already holding {n} order(s) (MAX_OPEN_ORDERS = "
                           f"{MAX_OPEN_ORDERS})")
    ok, why = market_open(symbol)
    if not ok:
        return False, why
    return True, ""


def incomplete_signal_review_reason(sig, message_text: str = "") -> str:
    """Review any placed signal missing SL or TP, independent of source/channel."""
    if getattr(sig, "action", "") != "place":
        return ""
    try:
        has_sl = float(getattr(sig, "sl", None) or 0) > 0
    except (TypeError, ValueError):
        has_sl = False
    try:
        has_tp = any(float(tp) > 0 for tp in (getattr(sig, "tps", None) or []))
    except (TypeError, ValueError):
        has_tp = False
    if has_sl and has_tp:
        return ""
    # Preserve the explicit immediate-market instruction path; all bare or
    # unprotected pending/limit signals wait for human review before auto defaults.
    if re.search(r"\b(?:MARKET|INSTANT|NOW)\b", str(message_text or ""), re.I):
        return ""
    missing = []
    if not has_sl:
        missing.append("SL")
    if not has_tp:
        missing.append("TP")
    missing_text = " and ".join(missing)
    return (f"signal is missing {missing_text}; saved for manual review only, "
            "no order sent (applies to every user-added signal source)")

_FOLLOWUP_ACTIONS = {"move_be", "modify_tp", "cancel_pending", "close_all", "close_symbol", "close_partial"}


def _followup_symbol_matches(stored: str, requested: str) -> bool:
    """Canonical symbol equality with only the broker suffixes EdgeQuant supports."""
    a = re.sub(r"[.#].*$", "", str(stored or "").strip().upper())
    b = re.sub(r"[.#].*$", "", str(requested or "").strip().upper())
    if a == b:
        return True
    # Broker suffixes such as XAUUSDm / XAUUSD.a are explicitly supported.
    return bool(b and a.startswith(b) and len(a) <= len(b) + 4)


def match_followup_entry_records(source, chat_id, category, symbol, direction, entry,
                                 records=None) -> dict:
    """Match one exact original signal entry; return its layers grouped by broker.

    A single original Telegram signal may own multiple layer tickets. Repeated
    signals with the same entry remain distinct message IDs and are ambiguous.
    No fuzzy price, content, or cross-channel matching is allowed.
    """
    try:
        cid = int(chat_id)
        target = float(entry)
    except (TypeError, ValueError):
        return {"ok": False, "reason": "invalid chat ID or entry"}
    if cid == 0 or target <= 0 or not math.isfinite(target):
        return {"ok": False, "reason": "missing chat ID or exact entry"}
    src_key = str(source or "").strip().casefold()
    cat_key = str(category or "").strip().upper()
    side_key = str(direction or "").strip().upper()
    sym_key = str(symbol or "").strip().upper()
    rows = list(TRADES if records is None else records)
    eligible = []
    active = {"open", "pending", "partial"}
    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            if int(row.get("chat_id") or 0) != cid:
                continue
            message_id = int(row.get("message_id") or 0)
            ticket = int(row.get("ticket") or 0)
            saved_entry = float(row.get("sig_entry") or 0.0)
        except (TypeError, ValueError):
            continue
        if message_id <= 0 or ticket <= 0 or saved_entry <= 0:
            continue
        if str(row.get("source") or "").strip().casefold() != src_key:
            continue
        if str(row.get("source_type") or "").strip().upper() != cat_key:
            continue
        if str(row.get("direction") or "").strip().upper() != side_key:
            continue
        if not _followup_symbol_matches(row.get("symbol"), sym_key):
            continue
        if abs(saved_entry - target) > 1e-8:
            continue
        if str(row.get("status") or "").strip().lower() not in active:
            continue
        eligible.append((message_id, str(row.get("broker") or "").strip(), ticket, row))
    signal_ids = {item[0] for item in eligible}
    if not eligible:
        return {"ok": False, "reason": "no open journaled signal has this exact channel/side/symbol/entry"}
    if len(signal_ids) != 1:
        return {"ok": False, "reason": "multiple original signal IDs match this entry; manual review required"}
    by_broker = {}
    for _, broker, ticket, _ in eligible:
        if not broker:
            return {"ok": False, "reason": "matched trade has no broker/account record"}
        by_broker.setdefault(broker, [])
        if ticket not in by_broker[broker]:
            by_broker[broker].append(ticket)
    return {"ok": True, "message_id": next(iter(signal_ids)), "tickets_by_broker": by_broker,
            "reason": "one original signal entry matched"}


def parse_followup_management(text: str, parsed=None) -> dict | None:
    """Recognize explicit trade-management text, never a fully protected new signal."""
    raw = _clean(str(text or ""))
    t = raw.upper()
    sig = parsed or parse_signal(text)
    # A complete signal with protected levels is a new signal, even if it also
    # includes an advisory BE note. It must stay on the normal order path.
    if (sig.action == "place" and sig.direction and sig.entries and sig.sl is not None and sig.tps):
        return None
    action = sig.action if sig.action in _FOLLOWUP_ACTIONS else ""
    if not action:
        if BE_RE.search(t) or BE_ENTRY_RE.search(t) or re.search(
                r"\bBE\b[^\n]{0,40}\b(?:SL|TRADE|TRADES|POSITION|BUY|SELL)\b", t):
            action = "move_be"
        elif CANCEL_RE.search(t) or ENTRY_MISSED_RE.search(t):
            action = "cancel_pending"
        elif PARTIAL_RE.search(t):
            action = "close_partial"
        elif CLOSE_RE.search(t):
            action = "close_all" if CLOSE_ALL_RE.search(t) else "close_symbol"
        elif MODIFY_VERB_RE.search(t) and TARGET_RE.search(t):
            action = "modify_tp"
    if action not in _FOLLOWUP_ACTIONS:
        return None

    dm = DIRECTION_RE.search(t)
    direction = ("BUY" if dm and dm.group(1) in ("BUY", "LONG") else
                 "SELL" if dm else "")
    # Do not borrow DEFAULT_SYMBOL_WHEN_MISSING for management; the message
    # itself must identify the symbol to avoid touching a different instrument.
    symbol = str(find_symbol(t, list(FALLBACK_SYMBOLS), DEFAULT_ALIASES) or "").upper()
    entries = list(getattr(sig, "entries", []) or [])
    # Some parser management branches return early before collecting prices.
    if not entries and direction:
        marker = re.search(r"\bENTRY(?:\s+PRICE)?\s*[:=@]?\s*(" + NUM + r")", t)
        if marker:
            value = choose_price(marker.group(1))
            if value and plausible_price(symbol, value):
                entries = [value]
        else:
            dm = DIRECTION_RE.search(t)
            if dm:
                for token in re.findall(NUM, t[dm.end():]):
                    value = choose_price(token)
                    if value and plausible_price(symbol, value):
                        entries = [value]
                        break
    try:
        entries = [float(x) for x in entries if math.isfinite(float(x)) and float(x) > 0]
    except Exception:
        entries = []
    target_tp = getattr(sig, "tp", None)
    if action == "modify_tp" and not target_tp:
        vals = list(getattr(sig, "tps", []) or [])
        target_tp = vals[-1] if vals else None
    explicit_scope = "pending" if PENDING_SCOPE_RE.search(t) else "positions"
    return {"action": action, "symbol": symbol, "direction": direction,
            "entries": entries, "tp": target_tp,
            "fraction": (max(0.01, min(0.99, float(getattr(sig, "fraction", 0.5) or 0.5)))
                         if action == "close_partial" else 1.0),
            "scope": explicit_scope,
            "be_pips": None}


def _handle_scoped_followup(update, text, chat_title, chat_id, category, msg_id,
                            msg_ts, allow_review_edit, audit_callback) -> None:
    """Apply a clear management update only to one exact source-signal entry group."""
    try:
        cid, mid = int(chat_id or 0), int(msg_id or 0)
    except (TypeError, ValueError):
        cid, mid = 0, 0

    def review(reason):
        signal_review_add(source=chat_title, chat_id=cid, message_id=mid,
                          category=category, message_ts=msg_ts, reason=reason,
                          text=text, kind="followup_management")
        journal({"ts": time.time(), "source": chat_title, "chat_id": cid, "msg_id": mid,
                 "action": "needs_review", "reason": reason,
                 "symbol": update.get("symbol"), "direction": update.get("direction"),
                 "entry": (update.get("entries") or [None])[0]}, durable=True)
        audit_callback("needs_review", reason, action=update.get("action"), needs_review=True)
        log(f"      FOLLOW-UP REVIEW REQUIRED: {reason}; no trade changed", "warn")

    if not cid or mid <= 0:
        review("follow-up has no exact Telegram chat/message ID; manual review only")
        return
    review_edit_allowed = False
    if allow_review_edit:
        if not signal_message_review_edit_allowed(cid, mid):
            audit_callback("duplicate_guard", "follow-up edit blocked; prior event was not review-only")
            log("      edited follow-up ID is not safely review-only -> no action", "warn")
            return
        signal_message_forget(cid, mid)
        review_edit_allowed = True
    prior = signal_audit_latest(cid, mid)
    if (not review_edit_allowed and prior and
            str(prior.get("outcome") or "").strip().lower() in (
                "management", "skipped", "blocked", "needs_review", "duplicate_guard")):
        log("      same Telegram follow-up ID already recorded -> no second action", "info")
        audit_callback("duplicate_guard", "same chat/message ID already handled")
        return
    if not signal_message_is_new(cid, mid):
        log("      same Telegram follow-up ID already handled -> no second action", "info")
        audit_callback("duplicate_guard", "same chat/message ID already handled")
        return

    entries = list(update.get("entries") or [])
    if (update.get("direction") not in ("BUY", "SELL") or not update.get("symbol")
            or len(entries) != 1):
        review("need one explicit BUY/SELL, symbol and exact entry price to identify the affected signal")
        return
    target_entry = float(entries[0])
    matched = match_followup_entry_records(
        chat_title, cid, category, update["symbol"], update["direction"], target_entry)
    if not matched.get("ok"):
        review(str(matched.get("reason") or "exact trade match failed"))
        return
    if re.search(r"\b(?:IF|WHEN|WHENEVER|MAYBE|MIGHT|COULD|OPTIONAL|IF NEEDED)\b", _clean(text).upper()):
        review("conditional or advisory follow-up wording is not an immediate instruction")
        return
    tickets_by_broker = matched.get("tickets_by_broker") or {}
    all_tickets = [ticket for tickets in tickets_by_broker.values() for ticket in tickets]
    action = str(update.get("action") or "")
    if action == "move_be":
        try:
            be_trigger_pips = float(AUTO_BE_PIPS or 0.0)
        except (TypeError, ValueError):
            be_trigger_pips = 0.0
        if not AUTO_BE_ENABLED or be_trigger_pips <= 0:
            reason = ("AUTO BE is OFF" if not AUTO_BE_ENABLED else
                      "owner AUTO BE trigger is zero/invalid")
            audit_callback("skipped", f"{reason}; channel cannot override owner settings",
                           action=action, tickets=all_tickets)
            log(f"      {reason} -> matched trade left unchanged", "warn")
            return
    if action == "modify_tp":
        try:
            target_tp = float(update.get("tp"))
        except (TypeError, ValueError):
            target_tp = 0.0
        if not math.isfinite(target_tp) or target_tp <= 0:
            review("TP update has no single valid target price")
            return
        if ((update["direction"] == "BUY" and target_tp <= target_entry) or
                (update["direction"] == "SELL" and target_tp >= target_entry)):
            review("TP update is on the wrong side of the exact entry")
            return
    else:
        target_tp = None

    intent_ok = journal({"ts": time.time(), "source": chat_title, "chat_id": cid,
                         "msg_id": mid, "action": "management_intent",
                         "management_action": action, "symbol": update["symbol"],
                         "direction": update["direction"], "entry": target_entry,
                         "tickets": all_tickets, "original_message_id": matched.get("message_id")},
                        durable=True)
    if not intent_ok:
        audit_callback("blocked", "durable follow-up intent could not be written; no MT5 action attempted",
                       action=action, tickets=all_tickets)
        log("      could not write durable follow-up intent -> fail-closed, no MT5 action", "err")
        return
    if not HAVE_MT5 or not mt5_ready():
        audit_callback("blocked", "MT5 is not ready; exact follow-up was not applied",
                       action=action, tickets=all_tickets)
        log("      MT5 is not ready -> exact follow-up not applied", "warn")
        return

    changed = 0
    for broker, tickets in tickets_by_broker.items():
        if action == "move_be":
            changed += move_to_be(update["direction"], symbol=update["symbol"],
                                  src=chat_title, cat=category,
                                  note="exact-entry channel BE update",
                                  tickets=tickets, only_profitable=True,
                                  min_profit_pips=AUTO_BE_PIPS, broker=broker)
        elif action == "modify_tp":
            changed += modify_tp(update["direction"], target_tp, update.get("scope") or "positions",
                                 symbol=update["symbol"], src=chat_title, cat=category,
                                 tickets=tickets, broker=broker)
        elif action == "cancel_pending":
            changed += cancel_pendings(symbol=update["symbol"], src=chat_title, cat=category,
                                       direction=update["direction"], tickets=tickets, broker=broker)
        elif action in ("close_all", "close_symbol", "close_partial"):
            fraction = (max(0.01, min(1.0, float(update.get("fraction") or 0.5)))
                        if action == "close_partial" else 1.0)
            changed += close_positions(update["direction"], update["symbol"], fraction,
                                       src=chat_title, cat=category,
                                       note="exact-entry channel follow-up",
                                       tickets=tickets, broker=broker)

    outcome = "management" if changed else "skipped"
    reason = (f"{action} applied to {changed} exact matched ticket(s)" if changed else
              "exact signal matched, but no eligible live ticket was changed; inspect MT5 locally")
    audit_callback(outcome, reason, action=action, tickets=all_tickets)
    log(f"      exact-entry follow-up: {reason}", "mng" if changed else "warn")


def handle_signal(text: str, chat_title: str, chat_id, category: str, msg_id=0,
                  msg_ts: float = 0.0, deferred_id: str = "",
                  provider_quick_tp_pips: float = None,
                  allow_review_edit: bool = False) -> None:
    _CUR_CHANNEL[0] = str(chat_title or "")          # v1.8.0 - per channel rules
    sig = parse_signal(text,
                       default_order_type="LIMIT" if category == "LIMIT" else "MARKET",
                       default_symbol=(DEFAULT_SYMBOL_WHEN_MISSING or None),
                       fix_direction=FIX_DIRECTION_MISMATCH)
    try:
        sig.msg_ts = float(msg_ts or 0.0)
    except (TypeError, ValueError):
        sig.msg_ts = 0.0
    parsed_signature = signal_signature(sig, category)
    deferred_record = signal_deferred_get(deferred_id) if deferred_id else {}
    weekend_limit_deferred = signal_deferred_uses_weekend_limit_policy(
        deferred_record, category)
    deferred_age_limit = (signal_deferred_age_limit_min(category, deferred_record)
                          if deferred_id else None)

    def _audit(outcome, reason="", *, action=None, broker="", tickets=None,
               needs_review=False):
        signal_audit("decision", source=chat_title, chat_id=chat_id,
                     message_id=msg_id, category=category, message_ts=sig.msg_ts,
                     action=action if action is not None else sig.action,
                     confidence=sig.confidence, symbol=sig.symbol,
                     direction=sig.direction, outcome=outcome, reason=reason,
                     broker=broker, tickets=tickets, needs_review=needs_review,
                     message_text=text)

    followup_update = parse_followup_management(text, sig)
    if followup_update is not None:
        _handle_scoped_followup(followup_update, text, chat_title, chat_id, category,
                                msg_id, sig.msg_ts, allow_review_edit, _audit)
        return

    if (weekend_limit_deferred and
            signal_deferred_is_expired(deferred_record, category)):
        hours = WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS
        why = (f"Weekend LIMIT queue exceeded its {hours:g}-hour maximum age; "
               "manual review only, no automatic order sent.")
        signal_review_add(source=chat_title, chat_id=chat_id, message_id=msg_id,
                          category=category, message_ts=sig.msg_ts, reason=why,
                          text=text, kind="deferred_expired")
        signal_deferred_update(deferred_id, status="review_required",
                               reason=why, outcome="needs_review")
        _audit("needs_review", why, needs_review=True)
        channel_alert_once(chat_title, "deferred-expired",
                           f"Signal #{msg_id} exceeded the weekend LIMIT queue window; review it locally.")
        log(f"      REVIEW REQUIRED: {why}", "warn")
        return

    log(f"[{chat_title}]  {category}   parsed: action={sig.action}  confidence={sig.confidence}", "sig")
    for issue in sig.issues:
        log(f"      note: {issue}", "info")
    for note in sig.notes:
        log(f"      note: {note}", "info")

    if sig.action == "ignore" or sig.confidence == "low":
        log("      not a signal -> ignored", "info")
        journal({"ts": time.time(), "source": chat_title, "action": "ignored", "raw": text})
        # A message that looks like a signal but could not be read is queued for
        # human inspection only. It is never sent back through the order path.
        _flat = " ".join(str(text or "").split()).upper()
        _looks = bool(re.search(r"\b(BUY|SELL)\b", _flat) and
                      re.search(r"\d", _flat) and
                      re.search(r"\bSL|STOP LOST|STOPLOSS|ENTRY|ENTRY|TP\s*\d?\b", _flat))
        if channel_is_on(chat_title, category, chat_id) and (_looks or sig.confidence == "low"):
            reason = (sig.issues[0] if getattr(sig, "issues", None)
                      else "the parser could not find a direction / entry / SL / TP")
            catch_unknown(text, chat_title, category, reason,
                          chat_id=chat_id, message_id=msg_id,
                          message_ts=sig.msg_ts)
            _audit("needs_review", reason, needs_review=True)
        else:
            _audit("ignored", (sig.issues[0] if getattr(sig, "issues", None)
                                else "not recognized as a signal"))
        return

    # ---- v1.6.6 : is this channel switched OFF ? ---------------------------
    if sig.action == "place" and not channel_is_on(chat_title, category, chat_id):
        log(f"      channel '{chat_title}' is switched OFF -> this signal is NOT traded "
            f"(send /on {chat_title}  or use the CHANNELS tab button)", "warn")
        journal({"ts": time.time(), "source": chat_title, "chat_id": chat_id,
                 "msg_id": msg_id, "action": "channel_off", "symbol": sig.symbol,
                 "direction": sig.direction, "entries": sig.entries, "raw": text,
                 "reason": "channel switched OFF"})
        _k = (channel_key(chat_title), jr_today_key())
        if CHANNEL_OFF_NOTIFY and _k not in _CH_OFF_TOLD:
            _CH_OFF_TOLD.add(_k)
            notify("\n".join([
                tg_title(EV_ICON["off"], "CHANNEL IS OFF - SIGNAL SKIPPED",
                         f"{chat_title}   [{str(category or '').upper()} channel]"),
                f"  SIGNAL     {symbol_emoji(sig.symbol)} {sig.direction} {sig.symbol}   "
                f"{' '.join(str(text).split())[:58]}",
                "  NOTHING was sent to MT5.",
                f"  TO TRADE IT   /on {chat_title}   (or the CHANNELS tab button)",
                "",
                tg_foot()]))
        _audit("skipped", "channel switched OFF")
        return

    # "After TP1 ... move SL to entry/BE" -> arm the break-even on open groups
    flat = _clean(text).upper()
    if sig.action == "move_be" and AUTO_BE_ENABLED and BE_AFTER_TP1 and BE_AFTER_TP1_RE.search(flat) \
            and (BE_RE.search(flat) or BE_ENTRY_RE.search(flat)):
        for g in GROUPS:
            g["be_on_tp1"] = True
        log(f"      armed: break-even after TP1 on {len(GROUPS)} open group(s)", "mng")
        _audit("management", f"break-even after TP1 armed on {len(GROUPS)} open group(s)")
        return

    # Idempotency is by Telegram message identity, not by parsed signal content.
    # Two separate posts with identical entries (including posts from different
    # channels) are two distinct signals; catch-up/reconnect replay of the SAME
    # chat/message ID remains protected. Deferred revalidation is the same event.
    now = time.time()
    if not deferred_id:
        if allow_review_edit:
            if not signal_message_review_edit_allowed(chat_id, msg_id):
                log("      edited Telegram post is not a review-only ID -> no replay", "warn")
                _audit("duplicate_guard", "edit blocked: prior event was not safely review-only")
                return
            signal_message_forget(chat_id, msg_id)
        if not signal_message_is_new(chat_id, msg_id, now=now):
            log("      same Telegram post already handled -> no second submission", "info")
            _audit("duplicate_guard", "same chat/message ID already handled; replay suppressed")
            return

    # Any placed signal missing either SL or TP from ANY user-added source is
    # held before auto defaults are applied. Persist it for human review; fully
    # protected signals continue through the ordinary safety gates.
    incomplete_reason = incomplete_signal_review_reason(sig, text)
    if incomplete_reason:
        signal_review_add(source=chat_title, chat_id=chat_id, message_id=msg_id,
                          category=category, message_ts=sig.msg_ts,
                          reason=incomplete_reason, text=text,
                          kind="incomplete_signal")
        journal({"ts": now, "source": chat_title, "chat_id": chat_id, "msg_id": msg_id,
                 "action": "needs_review", "reason": incomplete_reason,
                 "symbol": sig.symbol, "direction": sig.direction,
                 "entries": sig.entries, "sl": sig.sl, "tps": sig.tps, "raw": text},
                durable=True)
        log(f"      REVIEW REQUIRED: {incomplete_reason}", "warn")
        _audit("needs_review", incomplete_reason, needs_review=True)
        if not deferred_id:
            # This ID has no order intent; a genuine Telegram edit may correct it.
            signal_message_forget(chat_id, msg_id)
        return

    _intent_recorded = journal({"ts": now, "source": chat_title, "chat_id": chat_id, "msg_id": msg_id,
                                "action": sig.action, "symbol": sig.symbol,
                                "direction": sig.direction, "entries": sig.entries,
                                "sl": sig.sl, "tps": sig.tps, "raw": text},
                               durable=True)
    if not _intent_recorded:
        _audit("blocked", "processing intent could not be written durably; no MT5 action attempted")
        log("      could not write durable processing intent -> fail-closed, no MT5 action", "err")
        return

    if not HAVE_MT5:
        log("      MetaTrader5 package is missing -> pip install MetaTrader5", "err")
        _audit("blocked", "MetaTrader5 package is missing")
        return
    if not mt5_ready():
        log(f"      MT5 is not running / not connected: {mt5.last_error()}", "err")
        _audit("blocked", "MT5 is not running or not connected")
        return

    # ---- channel update messages -----------------------------------------
    if sig.action == "modify_tp" and sig.tp:
        modify_tp(sig.direction, sig.tp, sig.scope or "positions",
                  src=chat_title, cat=category)
        _audit("management", "modify TP command handled")
        return
    if sig.action == "move_be":
        if AUTO_BE_ENABLED:
            move_to_be(sig.direction, src=chat_title, cat=category,
                       note="channel said BE", min_profit_pips=AUTO_BE_PIPS)
            _audit("management", "break-even command handled under the user-enabled BE gate")
        else:
            log("      BE is OFF in Settings -> channel BE instruction was not applied", "warn")
            _audit("skipped", "automatic BE is OFF")
        return
    if sig.action == "cancel_pending":
        cancel_pendings(src=chat_title, cat=category)
        _audit("management", "cancel pending command handled")
        return
    if sig.action in ("close_all", "close_symbol"):
        close_positions(sig.direction, None, 1.0, src=chat_title, cat=category)
        _audit("management", f"{sig.action} command handled")
        return
    if sig.action == "close_partial":
        close_positions(sig.direction, None, sig.fraction or 0.5,
                        src=chat_title, cat=category, note="channel said close partial")
        if sig.be_pips is not None and AUTO_BE_ENABLED:
            move_to_be(sig.direction, min_profit_pips=AUTO_BE_PIPS)
        _audit("management", "partial-close command handled")
        return
    if sig.action != "place":
        log("      nothing to execute", "info")
        _audit("ignored", "parsed action has no execution handler")
        return

    # ---- v1.5.0 guards: paused / daily loss limit / max orders / market closed ---
    base = sig.symbol or "XAUUSD"
    try:
        _sym = resolve_symbol(base) or base if HAVE_MT5 else base
    except Exception:
        _sym = base
    ok, why = can_trade_now(_sym)
    if ok:
        ok, why = extra_guards(_sym, sig.direction)     # v1.8.0 guard pack
    if not ok:
        if is_weekend_market_closed_reason(why) and sig.action == "place":
            initial_age_limit = signal_age_limit_min(category) or float(CATCHUP_BOOTSTRAP_MINUTES)
            age_limit = (signal_deferred_age_limit_min(category, deferred_record)
                         if weekend_limit_deferred else initial_age_limit)
            age_now = (time.time() - sig.msg_ts) / 60.0 if sig.msg_ts else float("inf")
            queue_policy = (WEEKEND_LIMIT_QUEUE_POLICY
                            if weekend_limit_deferred or str(category).upper() == "LIMIT"
                            else "")
            if weekend_limit_deferred:
                expires_at = signal_deferred_expiry_ts(deferred_record, category)
            else:
                queue_age_limit = (WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS * 60.0
                                   if queue_policy else age_limit)
                expires_at = (sig.msg_ts + queue_age_limit * 60.0) if sig.msg_ts else 0.0
            already_expired = (not sig.msg_ts or age_now > age_limit or
                               (expires_at > 0 and time.time() >= expires_at))
            if already_expired:
                if weekend_limit_deferred:
                    review_reason = (f"Weekend LIMIT queue exceeded its "
                                     f"{WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS:g}-hour maximum age "
                                     "or has no valid timestamp; human review only, no order sent")
                else:
                    review_reason = (f"weekend market closure prevented submission, and the signal "
                                     f"is already beyond the {age_limit:g}-minute freshness limit "
                                     "or has no timestamp; human review only, no order sent")
                signal_review_add(source=chat_title, chat_id=chat_id, message_id=msg_id,
                                  category=category, message_ts=sig.msg_ts,
                                  reason=review_reason, text=text, kind="stale_signal")
                if deferred_id:
                    signal_deferred_update(deferred_id, status="review_required",
                                           reason=review_reason, outcome="needs_review")
                _audit("needs_review", review_reason, needs_review=True)
                log(f"      REVIEW REQUIRED: {review_reason}", "warn")
                channel_alert_once(chat_title, "weekend-stale",
                                   f"Signal #{str(msg_id or 0)[:32]} is outside its deferred window or has no timestamp. "
                                   "No order was sent; review the local queue.")
                return
            queued = signal_deferred_add(
                source=chat_title, chat_id=chat_id, message_id=msg_id,
                category=category, message_ts=sig.msg_ts, text=text,
                reason=str(why), signature=parsed_signature, expires_ts=expires_at,
                queue_policy=queue_policy,
                next_check_ts=time.time() + SIGNAL_DEFERRED_RECHECK_S)
            if queued:
                if queue_policy:
                    log(f"      DEFERRED: fresh weekend LIMIT signal saved locally until market reopens, "
                        f"up to {WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS:g} hours from the original post; "
                        "the normal price, TP, risk, account and broker guards will run again. "
                        "No order can be sent while closed.", "warn")
                    deferred_audit = (f"{why}; weekend LIMIT queue expires within "
                                      f"{WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS:g} hours and is revalidated at open")
                    alert_text = (f"Signal #{str(msg_id or 0)[:32]} is saved in the weekend LIMIT queue "
                                  f"for up to {WEEKEND_LIMIT_QUEUE_MAX_AGE_HOURS:g} hours. It will be submitted "
                                  "only after market open and if every normal safety check passes.")
                else:
                    log(f"      DEFERRED: market is closed for the weekend; queued for revalidation "
                        f"until the {age_limit:g}-minute freshness limit; no order can be sent while closed.", "warn")
                    deferred_audit = f"{why}; queued until market reopens, expires at the signal freshness limit"
                    alert_text = (f"Signal #{str(msg_id or 0)[:32]} is queued for market-open revalidation. "
                                  "It will be sent only if still fresh and every safety check passes.")
                _audit("deferred", deferred_audit)
                channel_alert_once(chat_title, "weekend-deferred", alert_text)
                return
            review_reason = "weekend signal could not be persisted to the deferred queue; manual review required"
            signal_review_add(source=chat_title, chat_id=chat_id, message_id=msg_id,
                              category=category, message_ts=sig.msg_ts,
                              reason=review_reason, text=text, kind="deferred_queue_error")
            if deferred_id:
                signal_deferred_update(deferred_id, status="review_required",
                                       reason=review_reason, outcome="needs_review")
            _audit("needs_review", review_reason, needs_review=True)
            return
        if str(why).startswith("NEWS GUARD"):
            say("news", str(why))
        note_skip(chat_title, why, base, text)          # v1.9.3
        log(f"      SKIPPED: {why}", "warn")
        notify("\n".join([
            tg_title(EV_ICON["skip"], "SIGNAL SKIPPED",
                     f"{chat_title}   ({category})",
                     f"{sig.direction} {base}   -   reason: {why}"),
            "  nothing was sent to MT5.",
            tg_foot()]))
        journal({"ts": time.time(), "source": chat_title, "action": "skipped",
                 "reason": why, "symbol": base, "raw": text})
        _audit("blocked", why)
        return

    # Do not compare signal prices/content across different Telegram posts.
    # Each distinct chat/message ID remains an independent signal; exact replay
    # of the same message was handled above.

    # ---- which MT5 account(s) ? -------------------------------------------
    targets = broker_for_signal(chat_title, chat_id)
    if not targets:
        log("      every MT5 account is switched OFF -> nothing was placed "
            "(open trades are still managed)", "warn")
        journal({"ts": time.time(), "source": chat_title, "action": "broker_off",
                 "symbol": base, "direction": sig.direction, "entries": sig.entries,
                 "raw": text, "reason": "all brokers switched off"})
        _bk = ("brokers", jr_today_key())
        if _bk not in _CH_OFF_TOLD:
            _CH_OFF_TOLD.add(_bk)
            notify("\n".join([
                tg_title(EV_ICON["off"], "ALL MT5 ACCOUNTS ARE OFF",
                         "a signal arrived but no account may take new orders"),
                f"  SIGNAL     {symbol_emoji(base)} {sig.direction} {base}   "
                f"{' '.join(str(text).split())[:58]}",
                "  NOTHING was sent to MT5.",
                "  TO TRADE IT   /brokeron <name>   (or the BROKERS tab button)",
                "",
                tg_foot()]))
        _audit("blocked", "all MT5 accounts are switched OFF")
        return
    log(f"      broker(s) for this channel: {', '.join(targets)}", "info")
    placed_any = False
    submission_uncertain = False
    uncertain_reason = ""
    uncertain_broker = ""
    confirmed_tickets = []
    broker_notes = []
    rejected_orders = 0
    partial_orders = 0
    confirmed_order_count = 0
    attempted_orders = 0

    for bname in list(targets) + (other_brokers(targets[0]) if BROKER_FALLBACK else []):
        if not select_broker(bname):
            why_broker = "broker was not reachable"
            broker_notes.append(f"{bname}: {why_broker}")
            log(f"      MT5 [{bname}] is not reachable -> skipped "
                f"({mt5.last_error() if HAVE_MT5 else 'no MetaTrader5 package'})", "err")
            continue
        symbol = resolve_symbol(base, broker_name=bname)
        if not symbol:
            chosen = broker_symbol_map_get(bname, base)
            why_symbol = (f"selected symbol {chosen} for {base} is not available"
                          if chosen else f"symbol {base} does not exist")
            broker_notes.append(f"{bname}: {why_symbol}")
            log(f"      [{bname}] {why_symbol} here", "warn")
            continue
        tick = mt5.symbol_info_tick(symbol)
        if tick is None or not tick.ask:
            broker_notes.append(f"{bname}: no price available for {symbol}")
            log(f"      [{bname}] {symbol}: no price yet (Market Watch?)", "warn")
            continue
        ask, bid = float(tick.ask), float(tick.bid)
        br = broker_from_mt5(symbol) or Broker(symbol=symbol)
        acc = mt5.account_info()
        balance = float(acc.balance) if acc else 0.0

        log(f"      [{bname}] {base} -> {symbol}   {sig.direction}   entries={sig.entries}   "
            f"SL={sig.sl}   TPs={sig.tps}   market={ask:g}", "sig")

        # Recheck freshness, price-run and TP-hit immediately before planning.
        _stale, _swhy = stale_signal(
            sig, ask, bid, source=chat_title, category=category,
            age_limit_min=(deferred_age_limit if weekend_limit_deferred else None))
        if _stale:
            note_skip(chat_title, f"late signal: {_swhy}", base, text)   # v1.9.3
            log(f"      SKIPPED (late signal): {_swhy}", "warn")
            notify("\n".join([
                tg_title(ev_icon("skip", "\u26A0\uFE0F"), "SIGNAL TOO LATE - NOT TAKEN",
                         f"{chat_title}   {sig.direction} {base}"),
                f"  reason     {_swhy}",
                "  nothing was sent to MT5 - a late entry is a bad entry.",
                tg_foot()]))
            journal({"ts": time.time(), "source": chat_title, "action": "late_skip",
                     "reason": _swhy, "symbol": base, "raw": text})
            _audit("skipped", f"late signal: {_swhy}", broker=bname)
            return

        plan = build_plan(sig, category, br, ask, bid, balance,
                          quick_tp_pips=provider_quick_tp_pips)
        if not plan:
            broker_notes.append(f"{bname}: no broker-valid orders in the plan")
            log(f"      [{bname}] no order to place", "warn")
            continue

        attempted_orders += len(plan)
        log(f"      [{bname}] placing {len(plan)} order(s)  (lot {plan[0]['lot']} each)", "ord")
        tickets = execute_plan(plan, symbol)
        confirmed_tickets.extend(int(t) for t in tickets if int(t or 0) > 0)
        placement_records = []
        if TRADE_JOURNAL:
            exec_id = datetime.now().strftime("%y%m%d-%H%M%S") + f"-{msg_id}"
            placement_records = jr_place(
                exec_id, chat_title, category, symbol, sig.direction, plan, raw=text,
                broker=bname, signal_ts=sig.msg_ts or time.time(), message_id=msg_id,
                chat_id=chat_id)
        BROKER_TICKETS.setdefault(bname, set()).update(int(t) for t in tickets)
        if tickets and AUTO_BE_ENABLED and BE_AFTER_TP1:
            GROUPS.append({"symbol": symbol, "direction": sig.direction, "tickets": tickets,
                           "be_on_tp1": True, "created": time.time(), "broker": bname})

        statuses = [str(order.get("status") or "").lower() for order in plan]
        confirmed_order_count += sum(1 for status in statuses if status in ("pending", "open"))
        if any(status in ("uncertain", "partial") for status in statuses):
            submission_uncertain = True
            uncertain_broker = bname
            uncertain_reason = next((str(order.get("error") or "ambiguous order result")
                                     for order in plan
                                     if str(order.get("status") or "").lower()
                                     in ("uncertain", "partial")),
                                    "ambiguous broker submission result")
            partial_orders += sum(1 for status in statuses if status == "partial")
            placed_any = placed_any or bool(tickets)
            log("      automatic fallback/retry is blocked until the broker history "
                "is checked", "warn")
            break
        rejected_orders += sum(1 for status in statuses if status == "rejected")
        if tickets:
            placed_any = True
            _voice_orders = [dict(r) for r in placement_records
                             if str(r.get("status") or "").lower() in ("pending", "open")]
            if not _voice_orders:
                _voice_orders = [dict(o) for o in plan
                                 if o.get("ticket") and str(o.get("status") or "").lower()
                                 in ("pending", "open")]
            if _voice_orders:
                _voice_first = dict(_voice_orders[0])
                _voice_first.update({"source": chat_title, "source_type": category,
                                     "broker": bname, "signal_ts": sig.msg_ts or time.time()})
                _spoken = signal_order_voice_detail(
                    category, _voice_orders, sig.msg_ts or time.time(), bname,
                    lang=dt_voice_lang())
                say("placed", _spoken, trade=_voice_first)
            if len(targets) == 1:
                break                    # done - no need for the fallback broker
        elif not tickets and statuses and all(status == "rejected" for status in statuses):
            broker_notes.append(f"{bname}: every planned order was explicitly rejected")

    if not placed_any:
        log("      no order went through on any broker", "err")

    if DRY_RUN:
        _audit("dry_run", "DRY-RUN plan only; no broker submission was made")
    elif submission_uncertain:
        reason = ("MT5 returned an ambiguous or partial submission result; "
                  "no automatic resubmission was made. Verify MT5 order history "
                  f"before any action. Detail: {uncertain_reason}")
        signal_review_add(source=chat_title, chat_id=chat_id, message_id=msg_id,
                          category=category, message_ts=sig.msg_ts, reason=reason,
                          text=text, kind="execution_uncertain")
        channel_alert_once(chat_title, "submission-uncertain",
                           f"Signal #{str(msg_id or 0)[:32]} has an ambiguous/partial MT5 result. "
                           "Check the broker order history before any manual action.")
        _audit("submission_uncertain", reason, broker=uncertain_broker,
               tickets=confirmed_tickets, needs_review=True)
    elif placed_any:
        if rejected_orders or partial_orders or confirmed_order_count < attempted_orders:
            outcome = "partially_placed"
            details = f"{len(confirmed_tickets)} confirmed ticket(s); some planned orders were not confirmed"
        else:
            outcome = "placed"
            details = f"{len(confirmed_tickets)} confirmed ticket(s)"
        if dedup_note:
            details += "; " + dedup_note
        _audit(outcome, details, tickets=confirmed_tickets)
    else:
        reason = "; ".join(broker_notes)[:220] or "no broker submission was confirmed"
        outcome = "rejected" if rejected_orders else "not_placed"
        _audit(outcome, reason)


# =========================================================================== #
#  PART 8 - POSITION MANAGER (optional break-even, user-enabled at +50 pips)
# =========================================================================== #
async def manage_positions() -> None:
    while True:
        await asyncio.sleep(5)
        try:
            if not HAVE_MT5 or DRY_RUN or not mt5_ready():
                continue
            by_ticket = {}
            for bname in broker_names():
                if len(broker_names()) > 1 and not select_broker(bname):
                    continue
                for p in (mt5.positions_get() or []):
                    if MAGIC and p.magic != MAGIC:
                        continue
                    by_ticket[p.ticket] = p
            # Break-even is user-controlled; OFF guarantees no automatic SL-to-entry moves.
            if AUTO_BE_ENABLED and BE_LADDER_PIPS and BE_LADDER_PIPS > 0:
                for p in list(by_ticket.values()):
                    try:
                        ladder_one(p)
                    except Exception as exc:
                        log(f"      ladder: {exc}", "err")

            # ---- v1.5.0: partial close / trailing stop / pending expiry ----
            for p in by_ticket.values():
                _frac = partial_ladder_fraction(p, PARTIAL_DONE)
                if _frac and close_position_partial(p, _frac):
                    PARTIAL_DONE.add(f"{int(p.ticket)}@{pips_profit(p):.0f}")
                    if TRADE_JOURNAL:
                        jr_note_action(p.ticket, None, None,
                                       note=f"partial {_frac:.0%} at "
                                            f"+{pips_profit(p):.0f} pips")
                    notify("\n".join([
                        tg_title(EV_ICON["partial"],
                                 f"PARTIAL CLOSE   (+{pips_profit(p):.0f} pips)",
                                 f"{p.symbol}   {_frac:.0%} of the position is out "
                                 f"- profit locked",
                                 "the rest is still running"),
                        tg_foot()]))
                    if AUTO_BE_ENABLED and PARTIAL_BE_AFTER:
                        move_to_be(None, p.symbol, note="BE after partial close",
                                   tickets=[p.ticket], only_profitable=True,
                                   min_profit_pips=AUTO_BE_PIPS,
                                   broker=broker_of_ticket(p.ticket))
                elif _frac is None and PARTIAL_CLOSE_PIPS and PARTIAL_CLOSE_PIPS > 0 and \
                        p.ticket not in PARTIAL_DONE and \
                        pips_profit(p) >= PARTIAL_CLOSE_PIPS:
                    if close_position_partial(p, PARTIAL_CLOSE_FRACTION):
                        PARTIAL_DONE.add(int(p.ticket))
                        if TRADE_JOURNAL:
                            jr_note_action(p.ticket, None, None,
                                           note=f"partial close at "
                                                f"+{pips_profit(p):.0f} pips")
                        notify("\n".join([
                            tg_title(EV_ICON["partial"],
                                     f"PARTIAL CLOSE   (+{pips_profit(p):.0f} pips)",
                                     f"{p.symbol}   {PARTIAL_CLOSE_FRACTION:.0%} of the "
                                     f"position is out - profit locked",
                                     "the rest is still running"),
                            tg_foot()]))
                        if AUTO_BE_ENABLED and PARTIAL_BE_AFTER:
                            move_to_be(None, p.symbol, note="BE after partial close",
                                       tickets=[p.ticket], only_profitable=True,
                                       min_profit_pips=AUTO_BE_PIPS,
                                       broker=broker_of_ticket(p.ticket))
                if RUNNER_MODE and str(jr_tag_of(p.ticket)) == "runner":
                    runner_one(p)                       # v1.8.0 - let it run
                elif TRAILING_STOP:
                    trail_one(p)

            # ---- v1.6.0: the AI AGENT watches every trade -------------------
            if AGENT_ENABLED and not DRY_RUN:
                now_a = time.time()
                for p in by_ticket.values():
                    tk = int(getattr(p, "ticket", 0) or 0)
                    if now_a - _AGENT_LAST.get(tk, 0.0) < max(5, int(AGENT_EVERY_S)):
                        continue
                    _AGENT_LAST[tk] = now_a
                    try:
                        agent_act(p)
                    except Exception as exc:
                        log(f"      agent: {exc}", "err")

            now_m = time.time()
            if PENDING_EXPIRY_HOURS and now_m - _LAST_EXPIRY[0] > 60:
                _LAST_EXPIRY[0] = now_m
                expire_pendings()

            for g in list(GROUPS):
                mine = [by_ticket[t] for t in g["tickets"] if t in by_ticket]
                closed = [t for t in g["tickets"] if t not in by_ticket]
                if AUTO_BE_ENABLED and g.get("be_on_tp1") and closed and mine:
                    if BE_LADDER_PIPS and BE_LADDER_PIPS > 0:
                        # ladder_one() has already handled each open ticket above;
                        # never reset a profit-side ladder stop back to entry.
                        log(f"[BE] a layer hit TP for {g['symbol']}; the profit ladder "
                            "manages only this signal's remaining tickets (no stop downgrade).",
                            "mng")
                    else:
                        _group_tickets = [int(p.ticket) for p in mine]
                        moved = move_to_be(
                            g["direction"], g["symbol"], note="auto BE after TP1",
                            tickets=_group_tickets, only_profitable=True,
                            min_profit_pips=AUTO_BE_PIPS,
                            broker=g.get("broker"))
                        log(f"[BE] TP1 group: moved {moved} profitable remaining layer(s) "
                            "to entry; losing/other trades and profit-side stops untouched.", "mng")
                    g["be_on_tp1"] = False
                if not mine:
                    GROUPS.remove(g)
                    continue
            if AUTO_BE_ENABLED and AUTO_BE_PIPS > 0 and not (BE_LADDER_PIPS and BE_LADDER_PIPS > 0):
                for p in by_ticket.values():
                    if pips_profit(p) >= AUTO_BE_PIPS and abs(p.sl - p.price_open) > 1e-6:
                        log(f"[BE] +{AUTO_BE_PIPS:g} pips -> SL to entry "
                            f"on ticket {p.ticket} only ({p.symbol})", "mng")
                        move_to_be(None, p.symbol,
                                   note=f"auto BE at +{AUTO_BE_PIPS:g} pips",
                                   tickets=[p.ticket], only_profitable=True,
                                   min_profit_pips=AUTO_BE_PIPS,
                                   broker=broker_of_ticket(p.ticket))
        except Exception as exc:                            # pragma: no cover
            log(f"position manager: {exc}", "err")


# =========================================================================== #
#  PART 8b - TRADE JOURNAL   (every order -> how it ended -> channel win %)   #
# =========================================================================== #
TRADE_LOG = "edgequant_trades.jsonl"            # raw record (one line per order)
TRADE_CSV = "EDGEQUANT-TRADE-JOURNAL.csv"       # open this with Excel
TRADE_REPORT = "EDGEQUANT-JOURNAL-REPORT.txt"   # readable summary
TRADE_PDF = "EDGEQUANT-TRADE-JOURNAL.pdf"       # same report, as a PDF

TRADES: list = []               # every order this bot placed (dicts)
PENDING_ACTIONS: dict = {}      # ticket -> which channel touched it (attribution)
_JR_LOADED = False

JR_COLS = [("#", 3), ("CHANNEL", 22), ("TYPE", 7), ("ORD", 5), ("TRIG", 5),
           ("MISS", 5), ("TP", 4), ("SL", 4), ("BE", 4), ("WIN%", 7),
           ("PIPS", 8), ("P/L(USD)", 10)]

MEDALS = ("#1", "#2", "#3")


def jr_num(value) -> str:
    try:
        return f"{float(value or 0):g}"
    except Exception:
        return str(value)


def jr_stamp(ts) -> str:
    try:
        return datetime.fromtimestamp(float(ts)).strftime("%Y-%m-%d %H:%M:%S") if ts else ""
    except Exception:
        return ""


def jr_load() -> None:
    """Read what the previous runs recorded (the journal survives restarts)."""
    global TRADES, _JR_LOADED
    TRADES = []
    _JR_LOADED = True
    path = HERE / TRADE_LOG
    if path.exists():
        for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                TRADES.append(json.loads(line))
            except Exception:
                pass
    log(f"TRADE JOURNAL : {len(TRADES)} order(s) loaded from {TRADE_LOG}", "info")


def jr_save() -> None:
    if not _JR_LOADED:
        return
    try:
        tmp = (HERE / TRADE_LOG).with_suffix(".tmp")
        with tmp.open("w", encoding="utf-8") as fh:
            for t in TRADES:
                fh.write(json.dumps(t, ensure_ascii=False) + "\n")
        tmp.replace(HERE / TRADE_LOG)
    except Exception as exc:
        log(f"trade journal: cannot save ({exc})", "err")


def jr_get(ticket):
    for t in TRADES:
        if t.get("ticket") == ticket:
            return t
    return None


def jr_ticket_record(ticket, broker: str = ""):
    """Find an order/position journal row without mixing tickets across brokers."""
    try:
        wanted = int(ticket)
    except (TypeError, ValueError):
        return None
    broker_key = str(broker or "").strip().casefold()
    records = list(reversed(TRADES))

    def same_account(rec):
        rec_broker = str(rec.get("broker") or "").strip().casefold()
        return not (broker_key and rec_broker and rec_broker != broker_key)

    # Prefer the exact order ticket; only then try the broker position identifier
    # aliases recorded when MT5 reports a pending order as filled.
    for rec in records:
        try:
            exact = int(rec.get("ticket") or 0) == wanted
        except (TypeError, ValueError):
            exact = False
        if exact and same_account(rec):
            return rec
    for rec in records:
        if not same_account(rec):
            continue
        for field in ("position_id", "identifier", "order"):
            try:
                if int(rec.get(field) or 0) == wanted:
                    return rec
            except (TypeError, ValueError):
                pass
    return None


def jr_place(exec_id: str, source: str, category: str, symbol: str, direction: str,
             orders: list, raw: str = "", broker: str = "",
             signal_ts: float = 0.0, message_id: int = 0, chat_id: int = 0) -> list:
    """Store every order of one signal - the accepted ones AND the rejects."""
    out = []
    for o in orders:
        if not o.get("status"):
            continue                                # dry-run -> nothing was sent
        rec = {
            "id": f"{exec_id}-{len(TRADES) + 1}",
            "placed_ts": o.get("sent_ts") or time.time(),
            "signal_ts": float(signal_ts or 0.0),
            "signal_received_ts": float(signal_ts or 0.0),
            "message_id": int(message_id or 0), "chat_id": int(chat_id or 0),
            "source": source, "source_type": category,
            "owner": source, "owner_type": category,
            "broker": broker or CURRENT_BROKER["name"] or "",
            "symbol": symbol, "direction": direction,
            "kind": o.get("kind"), "order_type": o.get("type"), "tag": o.get("tag"),
            "lot": o.get("lot"),
            "price": o.get("price"), "sig_entry": o.get("src_price") or o.get("price"),
            "sl": o.get("sl") or 0.0, "tp": o.get("tp") or 0.0,
            "sl_now": o.get("sl") or 0.0, "tp_now": o.get("tp") or 0.0,
            "pip": pip_size_of(symbol),
            "ticket": o.get("ticket"),
            "status": o.get("status"),
            "open_price": o.get("fill_price") or o.get("price"),
            "error": (o.get("error") or "")[:180],
            "signal": (raw or "")[:300].replace("\n", " | "),
            "be": False, "result": "", "net": 0.0,
        }
        if rec["status"] == "open":
            rec["opened_ts"] = float(o.get("fill_ts") or rec["placed_ts"])
            rec["activated_ts"] = rec["opened_ts"]
        if str(o.get("tag") or "") == "runner":
            rec["runner"] = True
        TRADES.append(rec)
        out.append(rec)
    if out:
        jr_save()
        jr_write_files()
    return out


def jr_note_action(ticket, src=None, scope=None, note="", be=False) -> None:
    """Remember WHICH channel (and which command) touched this trade."""
    if not ticket:
        return
    rec = PENDING_ACTIONS.setdefault(int(ticket), {})
    rec["ts"] = time.time()
    if src:
        rec["src"] = src
    if scope:
        rec["scope"] = scope
    if note:
        rec["note"] = note
    if be:
        rec["be"] = True


def jr_reason(t: dict, price: float) -> str:
    """How did the trade end?  tp / sl / be / manual"""
    pip = t.get("pip") or 0.1
    tol = max(5.0 * float(pip), 1e-9)
    openp = float(t.get("open_price") or 0.0)
    tp = float(t.get("tp_now") or t.get("tp") or 0.0)
    sl = float(t.get("sl_now") or t.get("sl") or 0.0)
    if tp and abs(price - tp) <= tol:
        return "tp"
    if sl and abs(price - sl) <= tol:
        return "be" if (t.get("be") and abs(sl - openp) <= tol) else "sl"
    if t.get("be") and openp and abs(price - openp) <= tol:
        return "be"
    return "manual"


def mt5_external_trade_snapshot(mt5_api=None, broker: str = "", now=None,
                                journal_trades=None, positions=None, orders=None,
                                deals_today=None, tracked_external_ids=None) -> dict:
    """Read today's non-EdgeQuant MT5 history + today's open manual/external trades.

    The importer is read-only. It deliberately excludes any position that matches
    the EdgeQuant journal (including a trade manually closed in MT5), so channel
    P&L is not double-counted. IDs in `tracked_external_ids` let an opted-in mirror
    reconcile older orders that closed while the app was offline. MT5 objects can
    be injected for offline tests.
    """
    api = mt5_api or mt5
    out = {"broker": str(broker or "MAIN"), "trades": [], "manage_rows": [],
           "net_today": 0.0, "float": 0.0, "closed_today": 0,
           "open_today": 0, "pending_today": 0, "deal_count": 0,
           "status": "unavailable"}
    if api is None:
        return out

    try:
        local_now = datetime.now().astimezone() if now is None else now
        if local_now.tzinfo is None:
            local_now = local_now.astimezone()
        else:
            local_now = local_now.astimezone()
        day = local_now.date()
        local_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        utc_start = local_start.astimezone(timezone.utc).replace(tzinfo=None)
        utc_end = local_now.astimezone(timezone.utc).replace(tzinfo=None)
        if positions is None:
            positions = api.positions_get() or []
        if orders is None:
            orders = api.orders_get() or []
        if deals_today is None:
            deals_today = api.history_deals_get(utc_start, utc_end) or []
        positions, orders, deals_today = list(positions or []), list(orders or []), list(deals_today or [])
    except Exception as exc:
        out["status"] = f"error: {type(exc).__name__}: {exc}"
        return out

    def as_int(value, default=0):
        try:
            return int(value)
        except Exception:
            return default

    def number(obj, name, default=0.0):
        try:
            return float(getattr(obj, name, default) or 0.0)
        except Exception:
            return float(default or 0.0)

    def ts(obj):
        try:
            return float(getattr(obj, "time", 0) or 0)
        except Exception:
            return 0.0

    def date_is_today(epoch):
        try:
            return bool(epoch and datetime.fromtimestamp(float(epoch)).date() == day)
        except Exception:
            return False

    def net_of(deal):
        return sum(number(deal, k) for k in ("profit", "commission", "swap", "fee"))

    def entry_code(deal):
        return as_int(getattr(deal, "entry", -1), -1)

    def magic_of(obj):
        return as_int(getattr(obj, "magic", 0), 0)

    broker_key = str(broker or "").strip().casefold()
    known_ids = set()
    tracked_ids = set()
    for value in tracked_external_ids or []:
        try:
            value = int(value)
            if value > 0:
                tracked_ids.add(value)
        except Exception:
            pass
    journal_by_ticket = {}
    journal_rows = list(TRADES if journal_trades is None else (journal_trades or []))
    for rec in journal_rows:
        rec_broker = str(rec.get("broker") or "").strip().casefold()
        if broker_key and rec_broker and rec_broker != broker_key:
            continue
        rec_ticket = as_int(rec.get("ticket"), 0)
        if rec_ticket > 0:
            known_ids.add(rec_ticket)
            journal_by_ticket[rec_ticket] = rec
        for field_name in ("position_id", "identifier"):
            value = as_int(rec.get(field_name), 0)
            if value > 0:
                known_ids.add(value)

    edge_magic = as_int(MAGIC, 0)
    manage_rows = []
    buy_position = as_int(getattr(api, "POSITION_TYPE_BUY", 0), 0)
    for pos in positions:
        ticket = as_int(getattr(pos, "ticket", 0), 0)
        if ticket <= 0:
            continue
        magic = magic_of(pos)
        rec = journal_by_ticket.get(ticket) or {}
        side = "BUY" if as_int(getattr(pos, "type", 0), 0) == buy_position else "SELL"
        live_price = number(pos, "price_current")
        manage_rows.append({
            "uid": f"{broker}:{ticket}:open", "broker": broker or "MAIN",
            "ticket": ticket, "position_id": as_int(getattr(pos, "identifier", 0), 0) or ticket,
            "identifier": as_int(getattr(pos, "identifier", 0), 0) or ticket,
            "kind": "OPEN", "state": "LIVE", "symbol": str(getattr(pos, "symbol", "") or ""),
            "direction": side, "order_type": "MARKET", "order_kind": "MARKET",
            "lot": number(pos, "volume"),
            "entry": number(pos, "price_open"), "current": live_price,
            "market_price": live_price, "sl": number(pos, "sl"), "tp": number(pos, "tp"),
            "pl": number(pos, "profit"), "magic": magic,
            "source": str(rec.get("source") or
                           ("EdgeQuant" if magic == edge_magic else "MT5 Manual / External")),
            "source_type": str(rec.get("source_type") or ""),
            "opened_ts": number(pos, "time")})
    _order_type_codes = {
        "BUY": as_int(getattr(api, "ORDER_TYPE_BUY", 0), 0),
        "SELL": as_int(getattr(api, "ORDER_TYPE_SELL", 1), 1),
        "BUY_LIMIT": as_int(getattr(api, "ORDER_TYPE_BUY_LIMIT", 2), 2),
        "SELL_LIMIT": as_int(getattr(api, "ORDER_TYPE_SELL_LIMIT", 3), 3),
        "BUY_STOP": as_int(getattr(api, "ORDER_TYPE_BUY_STOP", 4), 4),
        "SELL_STOP": as_int(getattr(api, "ORDER_TYPE_SELL_STOP", 5), 5),
        "BUY_STOP_LIMIT": as_int(getattr(api, "ORDER_TYPE_BUY_STOP_LIMIT", 6), 6),
        "SELL_STOP_LIMIT": as_int(getattr(api, "ORDER_TYPE_SELL_STOP_LIMIT", 7), 7),
    }
    buy_order_types = {_order_type_codes[k] for k in
                       ("BUY_LIMIT", "BUY_STOP", "BUY_STOP_LIMIT")}
    limit_order_types = {_order_type_codes[k] for k in ("BUY_LIMIT", "SELL_LIMIT")}
    stop_order_types = {_order_type_codes[k] for k in ("BUY_STOP", "SELL_STOP")}
    stop_limit_order_types = {_order_type_codes[k] for k in
                              ("BUY_STOP_LIMIT", "SELL_STOP_LIMIT")}
    order_type_by_code = {value: key for key, value in _order_type_codes.items()}
    for order in orders:
        ticket = as_int(getattr(order, "ticket", 0), 0)
        if ticket <= 0:
            continue
        magic = magic_of(order)
        rec = journal_by_ticket.get(ticket) or {}
        type_code = as_int(getattr(order, "type", -1), -1)
        side = "BUY" if type_code in buy_order_types else "SELL"
        entry_price = number(order, "price_open") or number(order, "price")
        symbol = str(getattr(order, "symbol", "") or "")
        order_type = order_type_by_code.get(type_code, "PENDING")
        order_kind = ("LIMIT" if type_code in limit_order_types else
                      "STOP LIMIT" if type_code in stop_limit_order_types else
                      "STOP" if type_code in stop_order_types else "PENDING")
        market_price = 0.0
        try:
            tick = api.symbol_info_tick(symbol) if symbol else None
            market_price = number(tick, "ask" if side == "BUY" else "bid") if tick else 0.0
        except Exception:
            market_price = 0.0
        manage_rows.append({
            "uid": f"{broker}:{ticket}:pending", "broker": broker or "MAIN",
            "ticket": ticket, "order_ticket": ticket, "position_id": 0,
            "kind": "PENDING", "state": "PENDING", "symbol": symbol,
            "direction": side, "order_type": order_type, "order_kind": order_kind,
            "lot": number(order, "volume_current") or number(order, "volume_initial"),
            "entry": entry_price, "current": market_price or entry_price,
            "market_price": market_price,
            "sl": number(order, "sl"), "tp": number(order, "tp"),
            "pl": 0.0, "magic": magic,
            "source": str(rec.get("source") or
                           ("EdgeQuant" if magic == edge_magic else "MT5 Manual / External")),
            "source_type": str(rec.get("source_type") or ""),
            "opened_ts": number(order, "time_setup")})

    live_by_id = {}
    manual_float = 0.0
    for pos in positions:
        pid = as_int(getattr(pos, "identifier", 0), 0) or as_int(getattr(pos, "ticket", 0), 0)
        ticket = as_int(getattr(pos, "ticket", 0), 0)
        if magic_of(pos) == edge_magic or pid in known_ids or ticket in known_ids:
            continue
        if pid > 0:
            live_by_id[pid] = pos
        manual_float += number(pos, "profit")

    today_by_id = {}
    manual_net_today = 0.0
    for deal in deals_today:
        pid = as_int(getattr(deal, "position_id", 0), 0)
        ticket = as_int(getattr(deal, "ticket", 0), 0)
        if (pid <= 0 or pid in known_ids or ticket in known_ids
                or magic_of(deal) == edge_magic):
            continue
        # A history query may include a boundary tick from the prior local day.
        if not date_is_today(ts(deal)):
            continue
        today_by_id.setdefault(pid, []).append(deal)

    pending_rows = []
    for order in orders:
        ticket = as_int(getattr(order, "ticket", 0), 0)
        order_setup_ts = number(order, "time_setup") or ts(order)
        if (magic_of(order) == edge_magic or ticket in known_ids
                or not date_is_today(order_setup_ts)):
            continue
        otype = as_int(getattr(order, "type", -1), -1)
        buy_types = {as_int(getattr(api, "ORDER_TYPE_BUY_LIMIT", 2), 2),
                     as_int(getattr(api, "ORDER_TYPE_BUY_STOP", 4), 4),
                     as_int(getattr(api, "ORDER_TYPE_BUY_STOP_LIMIT", 6), 6)}
        direction = "BUY" if otype in buy_types else "SELL"
        pending_rows.append({
            "uid": f"{broker}:{ticket}:pending", "broker": broker or "MAIN",
            "ticket": ticket, "position_id": 0, "magic": magic_of(order),
            "status": "PENDING", "result": "pending", "symbol": str(getattr(order, "symbol", "") or ""),
            "direction": direction, "lot": (number(order, "volume_current") or
                                              number(order, "volume_initial")),
            "entry": number(order, "price_open", number(order, "price")),
            "current": number(order, "price_open", number(order, "price")),
            "sl": number(order, "sl"), "tp": number(order, "tp"),
            "net_today": 0.0, "floating": 0.0, "opened_ts": order_setup_ts,
            "closed_ts": 0.0, "source": "MT5 EXTERNAL", "kind": "PENDING"})

    out_deal = as_int(getattr(api, "DEAL_ENTRY_OUT", 1), 1)
    out_by = as_int(getattr(api, "DEAL_ENTRY_OUT_BY", 3), 3)
    inout = as_int(getattr(api, "DEAL_ENTRY_INOUT", 2), 2)
    in_code = as_int(getattr(api, "DEAL_ENTRY_IN", 0), 0)
    close_codes = {out_deal, out_by, inout}
    entry_codes = {in_code, inout}
    closed_today_ids = set()
    trade_rows = []
    all_ids = set(today_by_id) | set(live_by_id) | tracked_ids
    for pid in sorted(all_ids):
        live_pos = live_by_id.get(pid)
        hist = today_by_id.get(pid, [])
        full = []
        try:
            full = list(api.history_deals_get(position=int(pid)) or [])
        except Exception:
            full = []
        if not full:
            full = list(hist)
        if any(magic_of(d) == edge_magic for d in full):
            continue
        # Today's realized MT5 P&L includes exits of positions opened on earlier days.
        manual_net_today += sum(net_of(d) for d in hist if date_is_today(ts(d)))
        if any(entry_code(d) in close_codes and date_is_today(ts(d)) for d in hist):
            if live_pos is None:
                closed_today_ids.add(pid)

        opening = sorted((d for d in full if entry_code(d) in entry_codes), key=ts)
        closing = sorted((d for d in full if entry_code(d) in close_codes), key=ts)
        first_in = opening[0] if opening else None
        if live_pos is not None and magic_of(live_pos) == 0 and first_in is not None:
            origin_order = as_int(getattr(first_in, "order", 0), 0)
            if origin_order > 0:
                for manage_row in manage_rows:
                    if (manage_row.get("kind") == "OPEN" and
                            as_int(manage_row.get("position_id"), 0) == pid):
                        manage_row["order_ticket"] = origin_order
                        manage_row["origin_order_ticket"] = origin_order
                        break
        opened_ts = (number(live_pos, "time") if live_pos is not None else
                     (ts(first_in) if first_in is not None else 0.0))
        if not date_is_today(opened_ts) and pid not in tracked_ids:
            continue
        if live_pos is None and not hist and not full:
            continue

        if live_pos is not None:
            ptype = as_int(getattr(live_pos, "type", 0), 0)
            direction = "BUY" if ptype == as_int(getattr(api, "POSITION_TYPE_BUY", 0), 0) else "SELL"
            entry_price = number(live_pos, "price_open")
            current_price = number(live_pos, "price_current", entry_price)
            sl, tp = number(live_pos, "sl"), number(live_pos, "tp")
            volume = number(live_pos, "volume")
            status = "OPEN"
            close_deal = closing[-1] if closing else None
            if date_is_today(opened_ts):
                out["open_today"] += 1
        else:
            deal_type = as_int(getattr(first_in, "type", 0), 0) if first_in is not None else 0
            direction = "BUY" if deal_type == as_int(getattr(api, "DEAL_TYPE_BUY", 0), 0) else "SELL"
            entry_price = number(first_in, "price") if first_in is not None else 0.0
            close_deal = closing[-1] if closing else (hist[-1] if hist else None)
            current_price = number(close_deal, "price") if close_deal is not None else 0.0
            level_ref = close_deal if close_deal is not None else first_in
            sl, tp = number(level_ref, "sl"), number(level_ref, "tp")
            volume = (number(first_in, "volume") if first_in is not None else
                      sum(number(d, "volume") for d in opening))
            status = "CLOSED"
            if any(entry_code(d) in close_codes and date_is_today(ts(d)) for d in hist):
                closed_today_ids.add(pid)

        if close_deal is not None:
            reason = as_int(getattr(close_deal, "reason", -1), -1)
            reason_tp = as_int(getattr(api, "DEAL_REASON_TP", 5), 5)
            reason_sl = as_int(getattr(api, "DEAL_REASON_SL", 4), 4)
            pip = pip_size_of(str(getattr(live_pos, "symbol", "") if live_pos is not None
                                         else getattr(first_in, "symbol", "")))
            tolerance = max(5.0 * float(pip or 0.1), 1e-9)
            close_price = number(close_deal, "price")
            if reason == reason_tp or (tp and abs(close_price - tp) <= tolerance):
                result = "tp"
            elif reason == reason_sl:
                result = "be" if entry_price and abs(close_price - entry_price) <= tolerance else "sl"
            elif entry_price and abs(close_price - entry_price) <= tolerance:
                result = "be"
            else:
                result = "manual"
        else:
            result = "running"

        net_today = sum(net_of(d) for d in hist if date_is_today(ts(d)))
        net_total = sum(net_of(d) for d in full)
        symbol = str(getattr(live_pos, "symbol", "") if live_pos is not None
                     else getattr(first_in, "symbol", "") if first_in is not None else "")
        trade_rows.append({
            "uid": f"{broker}:{pid}", "broker": broker or "MAIN",
            "ticket": as_int(getattr(live_pos, "ticket", pid), pid) if live_pos is not None
                      else as_int(getattr(close_deal, "ticket", pid), pid),
            "position_id": pid, "magic": magic_of(live_pos) if live_pos is not None
                          else magic_of(first_in) if first_in is not None else 0,
            "status": status, "result": result, "symbol": symbol,
            "direction": direction, "lot": volume, "entry": entry_price,
            "current": current_price, "sl": sl, "tp": tp,
            "net_today": round(net_today, 2), "net_total": round(net_total, 2),
            "floating": number(live_pos, "profit") if live_pos is not None else 0.0,
            "opened_ts": opened_ts,
            "closed_ts": ts(close_deal) if live_pos is None and close_deal is not None else 0.0,
            "source": "MT5 EXTERNAL", "kind": "LIVE" if live_pos is not None else "CLOSED"})

    out["trades"] = sorted(trade_rows + pending_rows,
                           key=lambda r: (r.get("opened_ts") or 0.0, r.get("ticket") or 0),
                           reverse=True)
    out["manage_rows"] = sorted(manage_rows,
                                key=lambda r: (r.get("opened_ts") or 0.0, r.get("ticket") or 0),
                                reverse=True)
    out["net_today"] = round(manual_net_today, 2)
    out["float"] = round(manual_float, 2)
    out["closed_today"] = len(closed_today_ids)
    out["pending_today"] = len(pending_rows)
    out["deal_count"] = sum(len(x) for x in today_by_id.values())
    out["status"] = "connected"
    return out


def mt5_account_history_snapshot(mt5_api=None, broker: str = "", journal_trades=None,
                                 deals=None, positions=None, account=None,
                                 start=None, end=None) -> dict:
    """Read all MT5 trade history available in the selected terminal, grouped by position.

    This is read-only. Journal ticket/order/position identifiers are used to
    attribute EdgeQuant rows to their Telegram source; unlinked positions are
    explicitly labeled MT5 Manual / Other EA rather than guessed.
    """
    api = mt5_api or mt5
    out = {"broker": str(broker or "MAIN"), "trades": [], "deal_count": 0,
           "balance": None, "equity": None, "currency": "", "status": "unavailable",
           "updated_ts": time.time()}
    if api is None:
        return out

    def as_int(value, default=0):
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    def number(obj, key, default=0.0):
        try:
            return float(getattr(obj, key, default) or 0.0)
        except (TypeError, ValueError):
            return float(default or 0.0)

    def stamp(obj):
        try:
            return float(getattr(obj, "time", 0) or 0.0)
        except Exception:
            return 0.0

    def net_of(deal):
        return sum(number(deal, key) for key in ("profit", "commission", "swap", "fee"))

    try:
        if account is None:
            account = api.account_info()
        if account is not None:
            out["balance"] = number(account, "balance")
            out["equity"] = number(account, "equity")
            out["currency"] = str(getattr(account, "currency", "") or "")
        if positions is None:
            positions = api.positions_get() or []
        if deals is None:
            start = start or datetime(2000, 1, 1)
            end = end or datetime.now(_timezone.utc).replace(tzinfo=None)
            deals = api.history_deals_get(start, end) or []
        positions, deals = list(positions or []), list(deals or [])
    except Exception as exc:
        out["status"] = f"error: {type(exc).__name__}: {exc}"
        return out

    journal_by_key = {}
    for rec in list(TRADES if journal_trades is None else (journal_trades or [])):
        if not isinstance(rec, dict):
            continue
        rec_broker = str(rec.get("broker") or "").strip().casefold()
        broker_key = str(broker or "").strip().casefold()
        if broker_key and rec_broker and rec_broker != broker_key:
            continue
        for field in ("ticket", "position_id", "identifier", "order"):
            value = as_int(rec.get(field), 0)
            if value > 0:
                journal_by_key[value] = rec

    close_codes = {as_int(getattr(api, "DEAL_ENTRY_OUT", 1), 1),
                   as_int(getattr(api, "DEAL_ENTRY_OUT_BY", 3), 3),
                   as_int(getattr(api, "DEAL_ENTRY_INOUT", 2), 2)}
    open_codes = {as_int(getattr(api, "DEAL_ENTRY_IN", 0), 0),
                  as_int(getattr(api, "DEAL_ENTRY_INOUT", 2), 2)}
    buy_code = as_int(getattr(api, "DEAL_TYPE_BUY", 0), 0)
    pos_buy_code = as_int(getattr(api, "POSITION_TYPE_BUY", 0), 0)
    edge_magic = as_int(MAGIC, 0)
    positions_by_id = {}
    for pos in positions:
        pid = as_int(getattr(pos, "identifier", 0), 0) or as_int(getattr(pos, "ticket", 0), 0)
        if pid > 0:
            positions_by_id[pid] = pos

    grouped = {}
    for deal in deals:
        pid = as_int(getattr(deal, "position_id", 0), 0)
        if pid > 0:
            grouped.setdefault(pid, []).append(deal)
    for pid in positions_by_id:
        grouped.setdefault(pid, [])

    trade_rows = []
    for pid, items in grouped.items():
        items = sorted(items, key=stamp)
        opening = [d for d in items if as_int(getattr(d, "entry", -1), -1) in open_codes]
        closing = [d for d in items if as_int(getattr(d, "entry", -1), -1) in close_codes]
        pos = positions_by_id.get(pid)
        if not items and pos is None:
            continue
        first_in = opening[0] if opening else (items[0] if items else None)
        last_close = closing[-1] if closing else None
        live_direction = ("BUY" if as_int(getattr(pos, "type", -1), -1) == pos_buy_code
                          else "SELL") if pos is not None else ""
        deal_direction = ("BUY" if as_int(getattr(first_in, "type", -1), -1) == buy_code
                          else "SELL") if first_in is not None else ""
        direction = live_direction or deal_direction
        entry_volume = sum(number(d, "volume") for d in opening)
        entry_value = sum(number(d, "price") * number(d, "volume") for d in opening)
        entry_price = (entry_value / entry_volume) if entry_volume else (
            number(pos, "price_open") if pos is not None else 0.0)
        close_volume = sum(number(d, "volume") for d in closing)
        close_value = sum(number(d, "price") * number(d, "volume") for d in closing)
        close_price = (close_value / close_volume) if close_volume else (
            number(last_close, "price") if last_close is not None else 0.0)
        opened_ts = (number(pos, "time") if pos is not None else
                     (stamp(opening[0]) if opening else (stamp(items[0]) if items else 0.0)))
        closed_ts = stamp(last_close) if last_close is not None else 0.0
        status = "OPEN" if pos is not None else ("CLOSED" if closing else "HISTORY")
        net = sum(net_of(d) for d in items)
        sl = number(pos, "sl") if pos is not None else 0.0
        tp = number(pos, "tp") if pos is not None else 0.0
        if not sl:
            sl = next((number(d, "sl") for d in reversed(items) if number(d, "sl")), 0.0)
        if not tp:
            tp = next((number(d, "tp") for d in reversed(items) if number(d, "tp")), 0.0)
        matching = None
        match_keys = {pid}
        for deal in items:
            for field in ("order", "ticket", "position_id"):
                ident = as_int(getattr(deal, field, 0), 0)
                if ident > 0:
                    match_keys.add(ident)
        for ident in match_keys:
            if ident in journal_by_key:
                matching = journal_by_key[ident]
                break
        magic = (as_int(getattr(pos, "magic", 0), 0) if pos is not None else
                 next((as_int(getattr(d, "magic", 0), 0) for d in items
                       if as_int(getattr(d, "magic", 0), 0)), 0))
        source = str((matching or {}).get("source") or
                     ("EdgeQuant (source not matched)" if edge_magic and magic == edge_magic
                      else "MT5 Manual / Other EA"))
        source_type = str((matching or {}).get("source_type") or
                          ("EdgeQuant" if edge_magic and magic == edge_magic else "EXTERNAL"))
        symbol = str((getattr(pos, "symbol", "") if pos is not None else "") or
                     (getattr(first_in, "symbol", "") if first_in is not None else "") or "")
        reference = pos or first_in
        ticket = (as_int(getattr(pos, "ticket", 0), 0) if pos is not None else
                  as_int(getattr(first_in, "order", 0), 0) if first_in is not None else pid)
        if not ticket:
            ticket = pid
        reason = as_int(getattr(last_close, "reason", -1), -1) if last_close is not None else -1
        reason_tp = as_int(getattr(api, "DEAL_REASON_TP", 5), 5)
        reason_sl = as_int(getattr(api, "DEAL_REASON_SL", 4), 4)
        pip = pip_size_of(symbol) if symbol else 0.0
        result = "running" if pos is not None else "manual"
        if last_close is not None:
            close_reason = reason
            if close_reason == reason_tp or (tp and abs(close_price - tp) <= max(5 * pip, 1e-9)):
                result = "tp"
            elif close_reason == reason_sl:
                result = "be" if entry_price and abs(close_price - entry_price) <= max(5 * pip, 1e-9) else "sl"
            elif entry_price and abs(close_price - entry_price) <= max(5 * pip, 1e-9):
                result = "be"
        pips = 0.0
        if closing and entry_price and close_price and pip:
            sign = -1.0 if direction == "SELL" else 1.0
            pips = round((close_price - entry_price) / pip * sign, 1)
        rec = matching or {}
        trade_rows.append({
            "uid": f"{broker or 'MAIN'}:{pid}:history", "broker": str(broker or "MAIN"),
            "ticket": ticket, "position_id": pid, "status": status, "result": result,
            "source": source, "source_type": source_type, "magic": magic,
            "symbol": symbol, "direction": direction,
            "lot": number(pos, "volume") if pos is not None else entry_volume,
            "entry": entry_price, "current": number(pos, "price_current") if pos is not None else close_price,
            "close_price": close_price, "sl": sl, "tp": tp,
            "net": round(net, 2), "realized_net": round(net, 2),
            "floating": number(pos, "profit") if pos is not None else 0.0,
            "currency": out.get("currency") or "", "opened_ts": opened_ts,
            "closed_ts": closed_ts, "signal_ts": float(rec.get("signal_ts") or 0.0),
            "placed_ts": float(rec.get("placed_ts") or 0.0),
            "activated_ts": opened_ts, "deal_count": len(items), "pips": pips,
            "comment": str(getattr(reference, "comment", "") or "") if reference is not None else ""})

    trade_rows.sort(key=lambda r: (r.get("closed_ts") or r.get("opened_ts") or 0.0,
                                   r.get("ticket") or 0), reverse=True)
    out["trades"] = trade_rows
    out["deal_count"] = len(deals)
    out["status"] = "connected"
    out["updated_ts"] = time.time()
    return out


def mt5_merge_external_snapshots(snapshots) -> dict:
    """Combine read-only per-account MT5 snapshots without mixing ticket IDs."""
    parts = [x for x in (snapshots or []) if isinstance(x, dict)]
    connected = [x for x in parts if x.get("status") == "connected"]
    trades = [row for x in connected for row in (x.get("trades") or [])]
    manage = [row for x in connected for row in (x.get("manage_rows") or [])]
    return {
        "trades": sorted(trades, key=lambda r: (r.get("opened_ts") or 0, r.get("ticket") or 0), reverse=True),
        "manage_rows": sorted(manage, key=lambda r: (r.get("opened_ts") or 0, r.get("ticket") or 0), reverse=True),
        "net_today": round(sum(float(x.get("net_today") or 0.0) for x in connected), 2),
        "float": round(sum(float(x.get("float") or 0.0) for x in connected), 2),
        "closed_today": sum(int(x.get("closed_today") or 0) for x in connected),
        "open_today": sum(int(x.get("open_today") or 0) for x in connected),
        "pending_today": sum(int(x.get("pending_today") or 0) for x in connected),
        "deal_count": sum(int(x.get("deal_count") or 0) for x in connected),
        "status": "connected" if connected else "unavailable",
        "accounts": [x.get("broker") for x in connected if x.get("broker")],
        "updated_ts": time.time(),
    }


def jr_sync(positions: dict, orders: dict, close_info, broker: str = "") -> list:
    """Compare MT5 with the journal -> fills, closes, cancellations.

    positions / orders are {ticket: {...}} of our own (MAGIC) orders.
    close_info(ticket) -> {"price","profit","commission","swap","ts"} or None
    """
    events = []
    now = time.time()
    for t in TRADES:
        if t.get("status") not in ("pending", "open"):
            continue
        tk = t.get("ticket")
        if not tk:
            continue
        tk = int(tk)
        if broker and t.get("broker") and t["broker"] != broker:
            continue                       # this ticket belongs to another broker
        pos = positions.get(tk)
        od = orders.get(tk)
        act = PENDING_ACTIONS.get(tk)
        if act:
            if act.get("src"):
                t["owner"] = act["src"]
                t["owner_type"] = act.get("scope") or t.get("owner_type")
            t["managed_note"] = act.get("note") or t.get("managed_note", "")
            if act.get("be"):
                t["be"] = True

        if t["status"] == "pending":
            if pos:
                t["status"] = "open"
                t["opened_ts"] = float(pos.get("time") or pos.get("opened_ts") or now)
                t["activated_ts"] = t["opened_ts"]
                t["position_id"] = int(pos.get("identifier") or pos.get("position_id") or tk)
                t["open_price"] = float(pos.get("open") or t.get("price") or 0.0)
                events.append({"kind": "filled", "trade": t})
            elif od is None:
                t["status"] = "cancelled"
                t["closed_ts"] = now
                t["result"] = "cancelled"
                events.append({"kind": "cancelled", "trade": t})
            else:
                t["sl_now"] = od.get("sl", t.get("sl_now"))
                t["tp_now"] = od.get("tp", t.get("tp_now"))
        elif t["status"] == "open":
            if pos is None:
                info = close_info(tk) or {}
                price = float(info.get("price") or 0.0)
                t["close_price"] = price
                t["profit"] = float(info.get("profit") or 0.0)
                t["commission"] = float(info.get("commission") or 0.0)
                t["swap"] = float(info.get("swap") or 0.0)
                t["net"] = round(t["profit"] + t["commission"] + t["swap"], 2)
                t["closed_ts"] = float(info.get("ts") or now)
                t["result"] = jr_reason(t, price)
                openp = float(t.get("open_price") or 0.0)
                sl = float(t.get("sl") or 0.0)
                if openp and sl and abs(openp - sl) > 1e-9:
                    # SELL: reward and risk are both negative -> the sign is right
                    t["r"] = round((price - openp) / (openp - sl), 2)
                else:
                    t["r"] = None
                t["status"] = "closed"
                events.append({"kind": "closed", "trade": t})
            else:
                t["sl_now"] = pos.get("sl", t.get("sl_now"))
                t["tp_now"] = pos.get("tp", t.get("tp_now"))

        if act and t.get("status") in ("closed", "cancelled"):
            PENDING_ACTIONS.pop(tk, None)
        elif act and now - float(act.get("ts") or now) > 1800:
            PENDING_ACTIONS.pop(tk, None)

    if events:
        jr_save()
        jr_write_files()
    return events


def jr_trade_pips(trade: dict) -> float:
    """Signed closed-trade pips (BUY positive on a rise; SELL positive on a fall)."""
    try:
        if trade.get("status") != "closed":
            return 0.0
        entry = float(trade.get("open_price") or trade.get("price") or 0.0)
        close = float(trade.get("close_price") or 0.0)
        pip = float(trade.get("pip") or pip_size_of(str(trade.get("symbol") or "")))
        if not entry or not close or not pip:
            return 0.0
        direction = str(trade.get("direction") or "BUY").upper()
        sign = -1.0 if direction == "SELL" else 1.0
        return round((close - entry) / pip * sign, 1)
    except Exception:
        return 0.0


def jr_stats(recs: list) -> dict:
    """Counts for one channel / one order type / one day."""
    st = {"n": len(recs), "tp": 0, "sl": 0, "be": 0, "manual": 0,
          "cancelled": 0, "rejected": 0, "pending": 0, "open": 0, "pl": 0.0,
          "pips": 0.0, "trig": 0, "miss": 0, "float": 0.0}
    for t in recs:
        stt = t.get("status")
        if stt in ("pending", "open"):
            st[stt] += 1
            if stt == "open":
                st["trig"] += 1                  # a pending order that filled
            st["float"] += float(t.get("profit") or 0.0)
        elif stt == "cancelled":
            st["cancelled"] += 1
            st["miss"] += 1                      # never triggered
        elif stt == "rejected":
            st["rejected"] += 1
        else:
            res = t.get("result") or "manual"
            st[res] = st.get(res, 0) + 1
            st["pl"] += float(t.get("net") or 0.0)
            st["pips"] += jr_trade_pips(t)
            if t.get("opened_ts"):
                st["trig"] += 1
    decided = st["tp"] + st["sl"]
    st["win"] = (100.0 * st["tp"] / decided) if decided else None
    return st


def jr_day_key(ts) -> str:
    try:
        return datetime.fromtimestamp(float(ts)).strftime("%Y-%m-%d") if ts else ""
    except Exception:
        return ""


def jr_today_key() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def jr_daily(day: str = "") -> dict:
    """Everything that happened on one day (default = today)."""
    day = day or jr_today_key()
    out = {"day": day, "placed": 0, "filled": 0, "missed": 0, "rejected": 0,
           "tp": 0, "sl": 0, "be": 0, "manual": 0, "net": 0.0,
           "pips": 0.0, "still": 0}
    for t in TRADES:
        if t.get("status") == "pending":
            out["still"] += 1
        if jr_day_key(t.get("placed_ts")) == day:
            out["placed"] += 1
            if t.get("status") == "rejected":
                out["rejected"] += 1
        if t.get("opened_ts") and jr_day_key(t.get("opened_ts")) == day:
            out["filled"] += 1
        if jr_day_key(t.get("closed_ts")) == day:
            if t.get("status") == "cancelled":
                out["missed"] += 1
            elif t.get("status") == "closed":
                res = t.get("result") or "manual"
                out[res] = out.get(res, 0) + 1
                out["net"] += float(t.get("net") or 0.0)
                out["pips"] += jr_trade_pips(t)
    out["closed"] = out["tp"] + out["sl"] + out["be"] + out["manual"]
    return out


def jr_week_start(dt=None):
    dt = dt or datetime.now()
    return (dt - timedelta(days=dt.weekday())).replace(hour=0, minute=0, second=0,
                                                       microsecond=0)


def jr_month_start(dt=None):
    dt = dt or datetime.now()
    return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)


def jr_period_bounds(period: str):
    """('today' / 'week' / 'month' / 'all') -> (start, end, label)"""
    now = datetime.now()
    end = now + timedelta(seconds=1)
    period = (period or "today").lower()
    if period in ("today", "day", "daily"):
        start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        return start, end, "TODAY  " + start.strftime("%Y-%m-%d")
    if period in ("week", "weekly", "7d"):
        start = jr_week_start(now)
        return start, end, "THIS WEEK  " + start.strftime("%d %b") + " - " + \
            now.strftime("%d %b %Y")
    if period in ("month", "monthly", "30d"):
        start = jr_month_start(now)
        return start, end, "THIS MONTH  " + start.strftime("%B %Y")
    return None, end, "ALL TIME"


def jr_in(ts, start, end) -> bool:
    try:
        ts = float(ts or 0)
    except Exception:
        return False
    if not ts:
        return False
    if start is not None and ts < start.timestamp():
        return False
    return ts <= end.timestamp()


def jr_range(period="today", recs=None) -> dict:
    """How did the bot do in one period (today / week / month / all)."""
    start, end, label = jr_period_bounds(period)
    recs = TRADES if recs is None else recs
    out = {"label": label, "period": period, "placed": 0, "filled": 0, "missed": 0,
           "rejected": 0, "tp": 0, "sl": 0, "be": 0, "manual": 0, "net": 0.0,
           "pips": 0.0, "closed": 0, "still": 0, "orders": len(recs)}
    for t in recs:
        if t.get("status") == "pending" and (start is None or jr_in(t.get("placed_ts"), start, end)):
            out["still"] += 1
        if jr_in(t.get("placed_ts"), start, end):
            out["placed"] += 1
            if t.get("status") == "rejected":
                out["rejected"] += 1
        if jr_in(t.get("opened_ts"), start, end):
            out["filled"] += 1
        if jr_in(t.get("closed_ts"), start, end):
            if t.get("status") == "cancelled":
                out["missed"] += 1
            elif t.get("status") == "closed":
                res = t.get("result") or "manual"
                out[res] = out.get(res, 0) + 1
                out["net"] += float(t.get("net") or 0.0)
                out["pips"] += jr_trade_pips(t)
    out["closed"] = out["tp"] + out["sl"] + out["be"] + out["manual"]
    dec = out["tp"] + out["sl"]
    out["win"] = (100.0 * out["tp"] / dec) if dec else None
    return out


def jr_calendar(year=None, month=None, recs=None) -> dict:
    """Profit calendar: net P/L for every day of one month."""
    now = datetime.now()
    year, month = int(year or now.year), int(month or now.month)
    first = datetime(year, month, 1)
    nxt = datetime(year + (month == 12), (month % 12) + 1, 1)
    days, weeks = {}, {}
    for t in (TRADES if recs is None else recs):
        if t.get("status") != "closed" and t.get("status") != "cancelled":
            continue
        ts = t.get("closed_ts") or t.get("placed_ts")
        if not jr_in(ts, first, nxt):
            continue
        d = datetime.fromtimestamp(float(ts))
        day = d.day
        st = days.setdefault(day, {"net": 0.0, "pips": 0.0, "n": 0,
                                   "tp": 0, "sl": 0, "be": 0})
        st["n"] += 1
        if t.get("status") == "cancelled":
            st["missed"] = st.get("missed", 0) + 1
            continue
        st["net"] += float(t.get("net") or 0.0)
        st["pips"] += jr_trade_pips(t)
        res = t.get("result") or "manual"
        st[res] = st.get(res, 0) + 1
        wk = (day + first.weekday() - 1) // 7
        weeks[wk] = weeks.get(wk, 0.0) + float(t.get("net") or 0.0)
    total = sum(v["net"] for v in days.values())
    best = max(days.items(), key=lambda kv: kv[1]["net"], default=(0, {"net": 0.0}))
    worst = min(days.items(), key=lambda kv: kv[1]["net"], default=(0, {"net": 0.0}))
    return {"year": year, "month": month, "name": first.strftime("%B %Y"),
            "days": days, "weeks": weeks, "total": total,
            "first_weekday": first.weekday(), "days_in_month": (nxt - first).days,
            "best": best, "worst": worst}


def jr_metrics(recs=None) -> dict:
    """Profit factor, expectancy, drawdown - the numbers a prop desk looks at."""
    recs = TRADES if recs is None else recs
    closed = [t for t in recs if t.get("status") == "closed"]
    closed.sort(key=lambda t: t.get("closed_ts") or t.get("placed_ts") or 0)
    nets = [float(t.get("net") or 0.0) for t in closed]
    wins = [n for n in nets if n > 0]
    losses = [n for n in nets if n < 0]
    gross_w, gross_l = sum(wins), abs(sum(losses))
    pf = (gross_w / gross_l) if gross_l else (None if not wins else float("inf"))
    peak, dd, dd_pct_peak = 0.0, 0.0, 0.0
    run = 0.0
    for n in nets:
        run += n
        peak = max(peak, run)
        drop = peak - run
        if drop > dd:
            dd, dd_pct_peak = drop, (drop / peak * 100.0) if peak > 0 else 0.0
    return {"n": len(closed), "wins": len(wins), "losses": len(losses),
            "gross_win": gross_w, "gross_loss": gross_l,
            "profit_factor": pf,
            "expectancy": (sum(nets) / len(nets)) if nets else 0.0,
            "avg_win": (sum(wins) / len(wins)) if wins else 0.0,
            "avg_loss": (sum(losses) / len(losses)) if losses else 0.0,
            "best": max(nets) if nets else 0.0, "worst": min(nets) if nets else 0.0,
            "net": sum(nets), "max_dd": dd, "max_dd_pct": dd_pct_peak,
            "win_rate": (100.0 * len(wins) / (len(wins) + len(losses)))
            if (wins or losses) else None}


def jr_hours(recs=None) -> list:
    """Which hour of the day is good?  -> [{hour, n, tp, sl, net, win}]"""
    recs = TRADES if recs is None else recs
    buckets = {}
    for t in recs:
        ts = t.get("closed_ts") or t.get("placed_ts")
        if not ts:
            continue
        h = datetime.fromtimestamp(float(ts)).hour
        b = buckets.setdefault(h, {"hour": h, "n": 0, "tp": 0, "sl": 0, "net": 0.0})
        b["n"] += 1
        res = t.get("result") or ""
        if res == "tp":
            b["tp"] += 1
        elif res == "sl":
            b["sl"] += 1
        b["net"] += float(t.get("net") or 0.0)
    out = []
    for h in sorted(buckets):
        b = buckets[h]
        dec = b["tp"] + b["sl"]
        b["win"] = (100.0 * b["tp"] / dec) if dec else None
        out.append(b)
    return out


def jr_compare(recs=None) -> dict:
    """This month vs last month, per channel."""
    recs = TRADES if recs is None else recs
    now = datetime.now()
    this_start, this_end = jr_month_start(now), now + timedelta(seconds=1)
    prev_end = this_start
    prev = (this_start - timedelta(days=1))
    last_start = prev.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    out = {}
    for (name, cat), rows in jr_group(recs).items():
        cur = [t for t in rows if jr_in(t.get("closed_ts") or t.get("placed_ts"),
                                        this_start, this_end)]
        old = [t for t in rows if jr_in(t.get("closed_ts") or t.get("placed_ts"),
                                        last_start, prev_end)]
        if not cur and not old:
            continue
        a, b = jr_stats(cur), jr_stats(old)
        out[(name, cat)] = {"this": a, "last": b, "delta": a["pl"] - b["pl"]}
    return out


def jr_group(recs=None) -> dict:
    groups = {}
    for t in (TRADES if recs is None else recs):
        groups.setdefault((t.get("source") or "?", t.get("source_type") or ""), []).append(t)
    return groups


def jr_rank(day: str = "", top=None, period: str = "", closed_only: bool = False) -> list:
    """Channels ranked by realized net P&L; win rate breaks ties."""
    start = end = None
    if period:
        start, end, _ = jr_period_bounds(period)
    rows = []
    for (name, cat), recs in jr_group().items():
        if closed_only:
            recs = [t for t in recs if t.get("status") == "closed" and t.get("closed_ts")]
        st = jr_stats(recs)
        if day:
            recs_today = [t for t in recs if jr_day_key(t.get("closed_ts") or t.get("placed_ts")) == day]
            if not recs_today:
                continue
            st = jr_stats(recs_today)
        elif start is not None:
            in_range = [t for t in recs if jr_in(
                t.get("closed_ts") if closed_only else
                (t.get("closed_ts") or t.get("placed_ts")), start, end)]
            if not in_range:
                continue
            st = jr_stats(in_range)
        rows.append({"name": name, "type": cat, "stats": st})
    closed_keys = ("tp", "sl", "be", "manual")
    rows.sort(key=lambda r: (
        not any(int(r["stats"].get(k) or 0) for k in closed_keys),
        -float(r["stats"].get("pl") or 0.0),
        r["stats"]["win"] is None,
        -(r["stats"]["win"] or 0.0),
        -sum(int(r["stats"].get(k) or 0) for k in closed_keys),
        r["name"].lower()))
    for i, r in enumerate(rows):
        r["rank"] = i + 1
        r["medal"] = MEDALS[i] if i < len(MEDALS) else f"#{i + 1}"
    return rows[:top] if top else rows


def jr_pending_stats(recs=None) -> dict:
    recs = TRADES if recs is None else recs
    pend = [t for t in recs if t.get("kind") == "PENDING"]
    st = jr_stats(pend)
    st["rate"] = (100.0 * st["trig"] / len(pend)) if pend else None
    st["miss_rate"] = (100.0 * st["miss"] / len(pend)) if pend else None
    return st


def jr_row_cells(r: dict) -> list:
    st = r["stats"]
    win = "-" if st["win"] is None else f"{st['win']:.1f}%"
    return [r.get("medal") or "", r["name"], r.get("type", ""), st["n"], st["trig"], st["miss"],
            st["tp"], st["sl"], st["be"], win, f"{st.get('pips', 0):+.1f}", f"{st['pl']:+.2f}"]


def jr_table(title: str, rows: list, note: str = "") -> list:
    out = [""]
    if note:
        out.append(note)
    out.append(title)
    out.append("-" * 106)
    out.append("  " + "  ".join(c[:w].ljust(w) for c, w in JR_COLS))
    for r in rows:
        out.append("  " + "  ".join(str(c)[:w].ljust(w)
                                    for c, w in zip(jr_row_cells(r), [w for _, w in JR_COLS])))
    return out


def jr_report() -> str:
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    tot = jr_stats(TRADES)
    win_txt = "-" if tot["win"] is None else f"{tot['win']:.1f} %   (TP / (TP+SL); BE ignored)"
    L = ["=" * 88,
         f"   {BOT_NAME}   TRADE JOURNAL  &  CHANNEL PERFORMANCE      (v{VERSION})",
         f"   {BOT_TAGLINE}",
         f"   updated : {now}",
         f"   raw     : {TRADE_LOG}      excel : {TRADE_CSV}",
         "=" * 88, "", "NUMBERS", "-" * 88,
         f"  orders placed ..................... {tot['n']}",
         f"  waiting (pending, not filled yet) . {tot['pending']}",
         f"  live now (open) ................... {tot['open']}",
         f"  closed (TP+SL+BE+manual) .......... {tot['tp'] + tot['sl'] + tot['be'] + tot['manual']}",
         f"        TP hit ..................... {tot['tp']}",
         f"        SL hit ..................... {tot['sl']}",
         f"        break-even (BE) ............ {tot['be']}",
         f"        closed by hand/channel ..... {tot['manual']}",
         f"  cancelled (pending removed) ....... {tot['cancelled']}",
         f"  rejected by the broker ............ {tot['rejected']}",
         "  WIN RATE .......................... " + win_txt,
         f"  net P/L ........................... {tot['pl']:+.2f} USD",
         f"  realized pips ..................... {tot['pips']:+.1f} pips",
         "",
         "  (WIN RATE = TP / (TP+SL).  BE trades and cancelled orders are not counted.)",
         ""]

    # ---- today / week / month / all ---------------------------------------
    L += ["", "DAILY  /  WEEKLY  /  MONTHLY  /  ALL TIME", "-" * 106,
          "  PERIOD".ljust(26) + "ORDERS".rjust(8) + "TRIG".rjust(7) + "MISS".rjust(7) +
          "TP".rjust(5) + "SL".rjust(5) + "BE".rjust(5) + "MAN".rjust(5) +
          "WIN%".rjust(8) + "PIPS".rjust(10) + "NET P/L".rjust(13)]
    for per in ("today", "week", "month", "all"):
        r = jr_range(per)
        L.append("  " + r["label"][:23].ljust(24) + str(r["placed"]).rjust(8) +
                 str(r["filled"]).rjust(7) + str(r["missed"]).rjust(7) +
                 str(r["tp"]).rjust(5) + str(r["sl"]).rjust(5) + str(r["be"]).rjust(5) +
                 str(r["manual"]).rjust(5) +
                 ("-" if r["win"] is None else f"{r['win']:.1f}%").rjust(8) +
                 f"{r.get('pips', 0):+.1f}".rjust(10) + f"{r['net']:+.2f}".rjust(13))

    # ---- profit calendar (this month) --------------------------------------
    cal = jr_calendar()
    L += ["", f"PROFIT CALENDAR   ({cal['name']})", "-" * 106,
          "  " + "".join(x.rjust(13) for x in ("MON", "TUE", "WED", "THU", "FRI",
                                               "SAT", "SUN", "WEEK"))]
    week_row = []
    for wk in range(6):
        cells = []
        net = cal["weeks"].get(wk)
        for wd in range(7):
            dayno = wk * 7 + wd - cal["first_weekday"] + 1
            if 1 <= dayno <= cal["days_in_month"]:
                st = cal["days"].get(dayno)
                cells.append("" if not st else f"{dayno} {st['net']:+.0f}")
            else:
                cells.append("")
        if not any(cells):
            continue
        row = "  " + "".join(c.rjust(13) for c in cells)
        row += ("" if net is None else f"{net:+.0f}".rjust(13))
        L.append(row)
        week_row.append(row)
    L.append("  " + f"MONTH TOTAL   {cal['total']:+.2f} USD".rjust(104))
    if cal["days"]:
        L.append(f"  best day: {cal['best'][0]:02d} ({cal['best'][1]['net']:+.2f})   |   "
                 f"worst day: {cal['worst'][0]:02d} ({cal['worst'][1]['net']:+.2f})")

    # ---- per channel, this week + this month -------------------------------
    for per, title in (("week", "CHANNEL EKEN - THIS WEEK"),
                       ("month", "CHANNEL EKEN - THIS MONTH")):
        rows = jr_rank(period=per)
        if rows:
            L += jr_table(title, rows,
                          "# ranked by realized net P&L for this period (highest first; win rate breaks ties)")

    # ---- pending / limit orders -------------------------------------------
    ps = jr_pending_stats()
    if ps["n"]:
        L += ["", "PENDING (LIMIT / STOP) ORDERS", "-" * 106,
              f"  placed .................... {ps['n']}",
              f"  triggered (became a trade)  {ps['trig']}"
              f"{'' if ps['rate'] is None else f'   ({ps["rate"]:.1f} %)'}",
              f"  waiting for the price ..... {ps['pending']}",
              f"  missed (never triggered) .. {ps['miss']}"
              f"{'' if ps['miss_rate'] is None else f'   ({ps["miss_rate"]:.1f} %)'}",
              f"  refused by the broker ..... {ps['rejected']}"]

    # ---- per channel (ranked: highest realized net P&L first) -------------------------
    rows = jr_rank()
    L += jr_table("CHANNEL RANKING   (#1 = highest realized net P&L, all time)",
                  rows, "# rank | channel | LIMIT/MARKET | orders | triggered | missed | "
                        "TP | SL | BE | win % | P/L")
    bro = {}
    for t in TRADES:
        bro.setdefault(t.get("broker") or "MAIN", []).append(t)
    if len(bro) > 1:
        rows = [{"name": k, "type": "", "stats": jr_stats(v)} for k, v in bro.items()]
        rows.sort(key=lambda r: -(r["stats"]["net"] if False else r["stats"]["pl"]))
        L += jr_table("BROKER EKEN   (IC Markets / Exness ...)",
                      rows, "# which MT5 account the orders went to")

    # ---- per order type ----------------------------------------------------
    rows = []
    for label, kinds in (("LIMIT (pending orders)", ("PENDING",)),
                         ("MARKET (instant orders)", ("MARKET",)),
                         ("TOTAL ALL ORDERS", ("PENDING", "MARKET"))):
        recs = [t for t in TRADES if t.get("kind") in kinds]
        rows.append({"name": label, "type": "", "stats": jr_stats(recs)})
    L += jr_table("ORDER TYPE EKEN   (limit orders da market orders da)",
                  rows, "# pending (limit/stop) orders vs instant market orders")

    # ---- who managed a trade that came from another channel ----------------
    managed = {}
    for t in TRADES:
        if t.get("owner") and t.get("owner") != t.get("source"):
            managed.setdefault(t["owner"], []).append(t)
    if managed:
        rows = [{"name": k, "type": "", "stats": jr_stats(v)} for k, v in managed.items()]
        rows.sort(key=lambda r: -(r["stats"]["win"] or 0))
        L += jr_table("MANAGE KARA CHANNEL   (TP change / BE / close dun channel eka)",
                      rows, "# me channel ekak denne, wena channel ekak manage karanawa (take-over)")

    # ---- in progress -------------------------------------------------------
    L += ["", "IN PROGRESS   (dhemata MT5 eke thiyena orders)", "-" * 106]
    live = [t for t in TRADES if t.get("status") in ("pending", "open")]
    if not live:
        L.append("  (none)")
    else:
        L.append("  " + "  ".join(c[:w].ljust(w) for c, w in
                                  [("TICKET", 10), ("TYPE", 11), ("SYMBOL", 8), ("DIR", 4),
                                   ("ENTRY", 9), ("SL", 9), ("TP", 9), ("CHANNEL", 20),
                                   ("STATUS", 8)]))
        for t in live[:60]:
            L.append("  " + "  ".join(str(c)[:w].ljust(w) for c, w in zip(
                [t.get("ticket"), t.get("order_type"), t.get("symbol"), t.get("direction"),
                 jr_num(t.get("price")), jr_num(t.get("sl_now") or t.get("sl")),
                 jr_num(t.get("tp_now") or t.get("tp")), t.get("source"), t.get("status")],
                [10, 11, 8, 4, 9, 9, 9, 20, 8])))

    # ---- last closed -------------------------------------------------------
    done = [t for t in TRADES if t.get("status") == "closed"]
    done.sort(key=lambda t: t.get("closed_ts") or 0, reverse=True)
    L += ["", "LAST 15 CLOSED TRADES", "-" * 106]
    if not done:
        L.append("  (none)")
    else:
        L.append("  " + "  ".join(c[:w].ljust(w) for c, w in
                                  [("CLOSED AT", 19), ("CHANNEL", 22), ("SYMBOL", 8), ("DIR", 4),
                                   ("ENTRY", 9), ("CLOSE", 9), ("RESULT", 8), ("P/L", 9)]))
        for t in done[:15]:
            L.append("  " + "  ".join(str(c)[:w].ljust(w) for c, w in zip(
                [jr_stamp(t.get("closed_ts")), t.get("source"), t.get("symbol"),
                 t.get("direction"), jr_num(t.get("open_price")), jr_num(t.get("close_price")),
                 str(t.get("result") or "").upper(), f"{float(t.get('net') or 0):+.2f}"],
                [19, 22, 8, 4, 9, 9, 8, 9])))

    # ---- best signals / executions ---------------------------------------
    best_trades = [t for t in done if float(t.get("net") or 0) > 0]
    best_trades.sort(key=lambda t: float(t.get("net") or 0), reverse=True)
    L += ["", "BEST 5 SIGNALS BY REALIZED NET P/L", "-" * 112,
          "  " + "  ".join(x.ljust(w) for x, w in zip(
              ["CLOSED AT", "CHANNEL", "SYMBOL", "DIR", "ENTRY", "SL", "TP", "EXIT", "RESULT", "NET USD"],
              [19, 15, 7, 4, 8, 8, 8, 8, 6, 9]))]
    if not best_trades:
        L.append("  (no positive closed trades yet)")
    for t in best_trades[:5]:
        L.append("  " + "  ".join(str(x)[:w].ljust(w) for x, w in zip(
            [jr_stamp(t.get("closed_ts")), t.get("source") or "-", t.get("symbol") or "-",
             t.get("direction") or "-", jr_num(t.get("open_price") or t.get("price")),
             jr_num(t.get("sl_now") or t.get("sl")), jr_num(t.get("tp_now") or t.get("tp")),
             jr_num(t.get("close_price")), str(t.get("result") or "").upper(),
             f"{float(t.get('net') or 0):+.2f}"], [19, 15, 7, 4, 8, 8, 8, 8, 6, 9])))
    L.append("")
    L.append("=" * 88)
    return "\n".join(L)


def jr_write_csv() -> None:
    cols = [("id", "id"), ("placed_ts", "signal_time"), ("source", "channel"),
            ("source_type", "channel_type"), ("symbol", "symbol"), ("direction", "direction"),
            ("kind", "order_kind"), ("order_type", "order_type"), ("ticket", "ticket"),
            ("lot", "lots"), ("price", "entry"), ("sl", "sl_initial"), ("tp", "tp_initial"),
            ("sl_now", "sl_now"), ("tp_now", "tp_now"), ("tag", "layer"), ("status", "status"),
            ("opened_ts", "filled_time"), ("open_price", "fill_price"),
            ("closed_ts", "close_time"), ("close_price", "close_price"),
            ("result", "result"), ("profit", "profit"), ("commission", "commission"),
            ("swap", "swap"), ("net", "net_pl"), ("r", "r_multiple"),
            ("owner", "managed_by"), ("error", "reject_reason")]
    try:
        with (HERE / TRADE_CSV).open("w", encoding="utf-8-sig", newline="") as fh:
            w = csv.writer(fh)
            w.writerow([c for _, c in cols])
            for t in TRADES:
                row = []
                for k, _ in cols:
                    v = t.get(k, "")
                    if k in ("placed_ts", "opened_ts", "closed_ts"):
                        v = jr_stamp(v)
                    elif isinstance(v, float):
                        v = round(v, 2)
                    row.append(v)
                w.writerow(row)
    except Exception as exc:
        log(f"trade journal: csv not written ({exc})", "err")


TRADE_XLSX = "EDGEQUANT-TRADE-JOURNAL.xlsx"      # real Excel file (no library needed)


def _xlsx_esc(text) -> str:
    return (str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def _xlsx_cell(col: int, row: int, value, style: int = 0) -> str:
    ref = f"{_xlsx_col(col)}{row}"
    st = f' s="{style}"' if style else ""
    if value is None or value == "":
        return f'<c r="{ref}"{st}/>'
    if isinstance(value, bool):
        value = "yes" if value else "no"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return f'<c r="{ref}"{st}><v>{value}</v></c>'
    return (f'<c r="{ref}"{st} t="inlineStr"><is><t xml:space="preserve">'
            f'{_xlsx_esc(value)}</t></is></c>')


def _xlsx_col(n: int) -> str:
    out = ""
    while n > 0:
        n, rem = divmod(n - 1, 26)
        out = chr(65 + rem) + out
    return out


def xlsx_write(path, sheets: list) -> Path:
    """Create a validated, Excel-compatible workbook with openpyxl.

    The previous hand-built OOXML writer could fail on unusual journal text,
    non-finite numeric values, XML control characters, and some Excel builds.
    openpyxl is already a required project dependency, so use its supported
    workbook serializer and validate the saved ZIP before publishing it.

    sheets = [(name, headers, rows, widths, money_cols, optional_conditions), ...]
    """
    import math
    import os
    import tempfile
    import zipfile
    from openpyxl import Workbook, load_workbook
    from openpyxl.styles import Font, PatternFill, Border, Side, Alignment
    from openpyxl.formatting.rule import DataBarRule, ColorScaleRule
    from openpyxl.utils import get_column_letter
    from openpyxl.worksheet.table import Table, TableStyleInfo

    path = Path(path).expanduser()
    path.parent.mkdir(parents=True, exist_ok=True)

    def clean(value):
        if value is None:
            return None
        if isinstance(value, bool):
            return 'Yes' if value else 'No'
        if isinstance(value, (int, float)):
            if isinstance(value, float) and not math.isfinite(value):
                return None
            return value
        text = str(value)
        # XML 1.0 disallows most C0 controls; remove them before serialization.
        text = ''.join(ch for ch in text if ch in '\t\n\r' or ord(ch) >= 32)
        return text[:32767]

    wb = Workbook()
    default = wb.active
    wb.remove(default)
    wb.properties.creator = 'EdgeQuant Sentinel'
    wb.properties.title = 'EdgeQuant Trade Journal'
    wb.properties.subject = 'Trading performance and execution journal'
    wb.properties.description = 'Generated by EdgeQuant Sentinel.'

    navy = '101620'
    cyan = '39C5CF'
    white = 'FFFFFF'
    muted = '8B98AB'
    line = '26364B'
    header_fill = PatternFill('solid', fgColor=navy)
    alternate_fill = PatternFill('solid', fgColor='F1F5F9')
    header_font = Font(name='Aptos', size=10, bold=True, color=white)
    body_font = Font(name='Aptos', size=10, color='172334')
    header_border = Border(bottom=Side(style='medium', color=cyan))
    thin_border = Border(bottom=Side(style='hair', color='D8E0EA'))

    used_titles = set()
    for item in sheets:
        name, headers, rows, widths, money_cols = item[:5]
        conditions = item[5] if len(item) > 5 else []
        base = re.sub(r'[\\/*?:\[\]]', '-', str(name or 'Sheet')).strip("' ") or 'Sheet'
        base = base[:31]
        title = base
        suffix = 2
        while title.casefold() in used_titles:
            tail = f' ({suffix})'
            title = base[:31-len(tail)] + tail
            suffix += 1
        used_titles.add(title.casefold())
        ws = wb.create_sheet(title)
        ws.sheet_view.showGridLines = False
        ws.freeze_panes = 'A2'
        ws.sheet_properties.pageSetUpPr.fitToPage = True
        ws.page_setup.fitToWidth = 1
        ws.page_setup.fitToHeight = 0
        ws.sheet_properties.outlinePr.summaryBelow = True

        safe_headers = [clean(h) or '' for h in headers]
        ws.append(safe_headers)
        for cell in ws[1]:
            cell.fill = header_fill
            cell.font = header_font
            cell.border = header_border
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        ws.row_dimensions[1].height = 25

        for row_index, row in enumerate(rows or [], start=2):
            values = list(row or [])
            if len(values) < len(safe_headers):
                values.extend([None] * (len(safe_headers) - len(values)))
            values = values[:len(safe_headers)]
            ws.append([clean(v) for v in values])
            for cell in ws[row_index]:
                cell.font = body_font
                cell.border = thin_border
                if row_index % 2 == 0:
                    cell.fill = alternate_fill
                cell.alignment = Alignment(vertical='center')
                if isinstance(cell.value, (int, float)) and not isinstance(cell.value, bool):
                    cell.number_format = '#,##0.00;[Red]-#,##0.00;–'

        for idx, width in enumerate(widths or [], start=1):
            try:
                ws.column_dimensions[get_column_letter(idx)].width = max(8, min(60, float(width)))
            except Exception:
                ws.column_dimensions[get_column_letter(idx)].width = 14
        if not widths:
            for idx in range(1, max(1, len(safe_headers)) + 1):
                ws.column_dimensions[get_column_letter(idx)].width = 16

        for col in money_cols or ():
            try:
                for row_idx in range(2, ws.max_row + 1):
                    ws.cell(row_idx, int(col)).number_format = '#,##0.00;[Red]-#,##0.00;–'
            except Exception:
                pass

        last_col = max(1, len(safe_headers))
        last_letter = get_column_letter(last_col)
        if safe_headers and ws.max_row >= 1:
            ws.auto_filter.ref = f'A1:{last_letter}{ws.max_row}'
        for col, kind in conditions or []:
            try:
                letter = get_column_letter(int(col))
                ref = f'{letter}2:{letter}{max(2, ws.max_row)}'
                if kind == 'bar':
                    ws.conditional_formatting.add(ref, DataBarRule(start_type='min', end_type='max', color='4EA8DE', showValue=True))
                elif kind in ('scale', 'win'):
                    ws.conditional_formatting.add(ref, ColorScaleRule(
                        start_type='min', start_color='F8696B',
                        mid_type='percentile', mid_value=50, mid_color='FFEB84',
                        end_type='max', end_color='63BE7B'))
            except Exception:
                continue

        # Excel tables provide consistent filters and a professional table style.
        if safe_headers and ws.max_row >= 2:
            try:
                table_ref = f'A1:{last_letter}{ws.max_row}'
                table_name = 'EQ_' + re.sub(r'[^A-Za-z0-9_]', '_', title)[:20]
                if not table_name[3:4].isalpha():
                    table_name = 'EQ_T_' + table_name[3:]
                table = Table(displayName=table_name, ref=table_ref)
                table.tableStyleInfo = TableStyleInfo(name='TableStyleMedium2',
                    showFirstColumn=False, showLastColumn=False,
                    showRowStripes=True, showColumnStripes=False)
                ws.add_table(table)
            except Exception:
                # AutoFilter remains available if a sheet cannot be table-wrapped.
                pass

    if not wb.sheetnames:
        wb.create_sheet('TRADE JOURNAL')

    fd, temp_name = tempfile.mkstemp(prefix=f'.{path.stem}-', suffix='.xlsx', dir=str(path.parent))
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        wb.save(str(temp_path))
        # Validate the container and reopen the workbook before replacing a prior report.
        with zipfile.ZipFile(temp_path, 'r') as archive:
            bad_member = archive.testzip()
            if bad_member:
                raise RuntimeError(f'Excel workbook integrity check failed at {bad_member}')
        check_wb = load_workbook(str(temp_path), read_only=True, data_only=False)
        try:
            if len(check_wb.sheetnames) != len(wb.sheetnames):
                raise RuntimeError('Excel workbook validation failed: worksheet count mismatch')
        finally:
            check_wb.close()
        os.replace(temp_path, path)
    except Exception:
        try:
            temp_path.unlink(missing_ok=True)
        except Exception:
            pass
        raise
    return path

def excel_charts(path) -> str:
    """Add REAL Excel charts with openpyxl (optional).  Returns a status line.

    No internet / no openpyxl -> the workbook keeps everything except the native
    chart objects (it still has data bars and colour scales).
    """
    try:
        import openpyxl                                     # optional, not shipped
    except Exception:
        return ("excel charts: skipped (openpyxl is not installed - run:  "
                "python -m pip install openpyxl  and press EXCEL again)")
    try:
        from openpyxl.chart import BarChart, LineChart, PieChart, Reference
        wb = openpyxl.load_workbook(str(path))
        made = []

        def _num(ws, row, col):
            try:
                return float(ws.cell(row=row, column=col).value or 0)
            except Exception:
                return 0.0

        # --- channel net P&L (bar) -------------------------------------
        rank = jr_rank(top=12)
        if rank:
            ws = wb.create_sheet("CHARTS")
            ws["A1"] = "CHANNEL"
            ws["B1"] = "NET USD"
            ws["D1"] = "TRADES"
            ws["E1"] = "WIN %"
            for i, r in enumerate(rank, start=2):
                ws.cell(row=i, column=1, value=r["name"][:28])
                ws.cell(row=i, column=2, value=float(r["stats"]["pl"]))
                ws.cell(row=i, column=4, value=int(r["stats"]["n"]))
                ws.cell(row=i, column=5,
                        value=(None if r["stats"]["win"] is None
                               else round(float(r["stats"]["win"]), 1)))
            bc = BarChart()
            bc.type, bc.style, bc.title = "col", 10, "NET P&L BY CHANNEL (USD)"
            bc.y_axis.title, bc.x_axis.title = "USD", None
            bc.add_data(Reference(ws, min_col=2, min_row=1, max_row=len(rank) + 1),
                        titles_from_data=True)
            bc.set_categories(Reference(ws, min_col=1, min_row=2, max_row=len(rank) + 1))
            bc.height, bc.width = 9.5, 20
            ws.add_chart(bc, "G2")
            made.append("bar")

            wc = BarChart()
            wc.type, wc.style, wc.title = "col", 12, "WIN RATE PER CHANNEL (%)"
            wc.add_data(Reference(ws, min_col=5, min_row=1, max_row=len(rank) + 1),
                        titles_from_data=True)
            wc.set_categories(Reference(ws, min_col=1, min_row=2, max_row=len(rank) + 1))
            wc.height, wc.width = 9.5, 20
            ws.add_chart(wc, "G22")
            made.append("win")

            # --- equity curve (line) -----------------------------------
            pts = equity_curve(0)
            if len(pts) > 1:
                ws2 = wb.create_sheet("EQUITY")
                ws2["A1"], ws2["B1"] = "TRADE #", "CLOSED P&L"
                for i, (_ts, v) in enumerate(pts, start=2):
                    ws2.cell(row=i, column=1, value=i - 1)
                    ws2.cell(row=i, column=2, value=float(v))
                lc = LineChart()
                lc.style, lc.title = 12, "EQUITY CURVE (closed P&L)"
                lc.add_data(Reference(ws2, min_col=2, min_row=1,
                                      max_row=len(pts) + 1), titles_from_data=True)
                lc.set_categories(Reference(ws2, min_col=1, min_row=2,
                                            max_row=len(pts) + 1))
                lc.height, lc.width = 9.5, 22
                ws2.add_chart(lc, "D2")
                made.append("equity")

            # --- result mix (pie) --------------------------------------
            st = jr_stats(TRADES)
            ws2["A1"] = ws2["B1"] = None
            base = len(pts) + 4
            ws2.cell(row=base, column=1, value="RESULT")
            ws2.cell(row=base, column=2, value="COUNT")
            for k, label in enumerate(("TP", "SL", "BE", "MANUAL")):
                ws2.cell(row=base + k + 1, column=1, value=label)
                ws2.cell(row=base + k + 1, column=2,
                         value=int(st[{"TP": "tp", "SL": "sl", "BE": "be",
                                       "MANUAL": "manual"}[label]]))
            pc = PieChart()
            pc.title = "RESULT MIX"
            pc.add_data(Reference(ws2, min_col=2, min_row=base,
                                  max_row=base + 4), titles_from_data=True)
            pc.set_categories(Reference(ws2, min_col=1, min_row=base + 1,
                                        max_row=base + 4))
            pc.height, pc.width = 9.0, 12
            ws2.add_chart(pc, "D22")
            made.append("mix")

            # --- the trading plan (compounding) ------------------------
            pl = trading_plan()
            ws3 = wb.create_sheet("PLAN")
            _u = "DAY" if pl.get("per") == "DAYS" else "MONTH"
            for j, head in enumerate((_u, "START", "GAIN", "END", "RATE %"), start=1):
                ws3.cell(row=1, column=j, value=head)
            for i, r in enumerate(pl["table"], start=2):
                ws3.cell(row=i, column=1, value=r.get("label") or r["month"])
                ws3.cell(row=i, column=2, value=r["start"])
                ws3.cell(row=i, column=3, value=r["gain"])
                ws3.cell(row=i, column=4, value=r["end"])
                ws3.cell(row=i, column=5, value=r["pct"])
            cc = LineChart()
            cc.style, cc.title = 12, "COMPOUNDING PLAN"
            cc.add_data(Reference(ws3, min_col=4, min_row=1,
                                  max_row=len(pl["table"]) + 1), titles_from_data=True)
            cc.set_categories(Reference(ws3, min_col=1, min_row=2,
                                        max_row=len(pl["table"]) + 1))
            cc.height, cc.width = 9.5, 20
            ws3.add_chart(cc, "G2")
            made.append("plan")

        # keep the colour scales / data bars when openpyxl re-saves the file
        try:
            from openpyxl.formatting.rule import ColorScaleRule, DataBarRule
            for ws in wb.worksheets:
                heads = [str(ws.cell(row=1, column=c).value or "").upper()
                         for c in range(1, (ws.max_column or 0) + 1)]
                nrow = max(2, ws.max_row or 2)
                for col, name in enumerate(heads, start=1):
                    if not name:
                        continue
                    ref = f"{ws.cell(row=2, column=col).coordinate}:{ws.cell(row=nrow, column=col).coordinate}"
                    if "WIN %" in name:
                        ws.conditional_formatting.add(ref, ColorScaleRule(
                            start_type="num", start_value=0, start_color="FFFF8A8A",
                            mid_type="num", mid_value=50, mid_color="FFFFE08A",
                            end_type="num", end_value=100, end_color="FF7ED694"))
                    elif any(k in name for k in ("P/L", "NET", "GAIN", "END", "USD",
                                                 "AVG SLIP", "WORST", "DELTA", "RATE")):
                        ws.conditional_formatting.add(ref, DataBarRule(
                            start_type="min", end_type="max", color="FF4EA8DE"))
        except Exception:
            pass
        for ws in wb.worksheets:
            ws.sheet_view.showGridLines = False
            ws.freeze_panes = "A2"
        wb.save(str(path))
        return f"excel charts: added ({', '.join(made)})"
    except Exception as exc:
        return f"excel charts: could not be added ({exc})"


def jr_excel(path=None) -> Path:
    """The whole journal as a REAL .xlsx (sheets, colours, filters, charts)."""
    path = Path(path) if path else (HERE / TRADE_XLSX)
    closed = [t for t in TRADES if t.get("status") == "closed"]
    rows = []
    for t in sorted(TRADES, key=lambda x: x.get("placed_ts") or 0, reverse=True):
        rows.append([t.get("id"), t.get("source"), t.get("source_type"),
                     t.get("broker"), t.get("symbol"), t.get("direction"),
                     t.get("kind"), t.get("order_type"), t.get("ticket"),
                     t.get("lot"), t.get("open_price") or t.get("price"),
                     t.get("sl_now") or t.get("sl"), t.get("tp_now") or t.get("tp"),
                     str(t.get("status") or "").upper(),
                     {True: "BE", False: ""}[bool(t.get("be"))] or t.get("result", ""),
                     t.get("close_price"), float(t.get("net") or 0.0),
                     (datetime.fromtimestamp(t["placed_ts"]).strftime("%Y-%m-%d %H:%M")
                      if t.get("placed_ts") else ""),
                     (datetime.fromtimestamp(t["closed_ts"]).strftime("%Y-%m-%d %H:%M")
                      if t.get("closed_ts") else ""),
                     (t.get("signal") or "")[:120]])
    heads = ["ID", "CHANNEL", "TYPE", "BROKER", "SYMBOL", "DIR", "KIND", "ORDER",
             "TICKET", "LOT", "ENTRY", "SL", "TP", "STATUS", "RESULT", "CLOSE",
             "NET USD", "PLACED", "CLOSED", "SIGNAL"]
    widths = [14, 22, 7, 10, 9, 6, 8, 12, 11, 6, 10, 10, 10, 9, 8, 10, 10, 17, 17, 60]

    ch_rows = []
    for r in jr_rank():
        st = r["stats"]
        ch_rows.append([r.get("medal", ""), r["name"], r["type"], st["n"], st["trig"],
                        st["miss"], st["tp"], st["sl"], st["be"], st["manual"],
                        None if st["win"] is None else round(st["win"], 1),
                        float(st["pl"])])
    days = {}
    for t in TRADES:
        k = jr_day_key(t.get("closed_ts") or t.get("placed_ts"))
        if k:
            days.setdefault(k, []).append(t)
    day_rows = []
    for k in sorted(days, reverse=True):
        st = jr_stats(days[k])
        day_rows.append([k, st["n"], st["trig"], st["miss"], st["tp"], st["sl"],
                         st["be"], st["manual"],
                         None if st["win"] is None else round(st["win"], 1),
                         float(st["pl"])])
    per_rows = []
    for per in ("today", "week", "month", "all"):
        r = jr_range(per)
        per_rows.append([r["label"], r["placed"], r["filled"], r["missed"], r["tp"],
                         r["sl"], r["be"], r["manual"],
                         None if r["win"] is None else round(r["win"], 1),
                         float(r["net"])])
    m = jr_metrics()
    per_rows += [["", "", "", "", "", "", "", "", "", ""],
                 ["PROFIT FACTOR", None if m["profit_factor"] is None
                  else round(m["profit_factor"], 2), "", "", "", "", "", "", "", ""],
                 ["EXPECTANCY / trade", round(m["expectancy"], 2), "", "", "", "", "", "",
                  "", ""],
                 ["MAX DRAWDOWN", round(m["max_dd"], 2), "", "", "", "", "", "", "", ""],
                 ["AVG WIN", round(m["avg_win"], 2), "", "", "", "", "", "", "", ""],
                 ["AVG LOSS", round(m["avg_loss"], 2), "", "", "", "", "", "", "", ""],
                 ["BEST / WORST", round(m["best"], 2), round(m["worst"], 2), "", "", "",
                  "", "", "", ""]]
    hour_rows = [[b["hour"], b["n"], b["tp"], b["sl"],
                  None if b["win"] is None else round(b["win"], 1), round(b["net"], 2)]
                 for b in jr_hours()]
    cmp_rows = []
    for (name, cat), d in sorted(jr_compare().items(),
                                 key=lambda kv: -kv[1]["this"]["pl"]):
        a, b = d["this"], d["last"]
        cmp_rows.append([name, cat, a["n"], round(a["pl"], 2), a["tp"], a["sl"],
                         b["n"], round(b["pl"], 2), round(d["delta"], 2)])

    # ---- v1.8.0 extra sheets: quality / protection / the plan ------------
    sl = slippage_stats()
    slip_rows = [[k, v["n"], v["avg"], v["best"], v["worst"]]
                 for k, v in sorted(sl["brokers"].items(), key=lambda kv: -kv[1]["n"])]
    slip_rows += [["ALL", sl["all"]["n"], sl["all"]["avg"], sl["all"]["best"],
                   sl["all"]["worst"]]]
    pl = trading_plan()
    plan_rows = [[r["month"], r["start"], r["gain"], r["end"], r["pct"]]
                 for r in pl["table"]]
    prot_rows = [["friday flat", "ON" if FRIDAY_FLAT else "off",
                  f"{FRIDAY_FLAT_MIN:g} min before the close"],
                 ["news guard", "ON" if NEWS_GUARD else "off",
                  f"+-{NEWS_BEFORE_MIN:g}/{NEWS_AFTER_MIN:g} min"],
                 ["loss-streak entry pause", "OFF",
                  "disabled; daily loss cap is separate"],
                 ["daily loss limit", f"{loss_limit_state()['limit']:.2f}",
                  "USD - stops new orders"],
                 ["signal freshness",
                  "price-run skip OFF",
                  f"max age {MAX_SIGNAL_AGE_MIN:g} min; TP-hit check ON"],
                 ["max spread", f"{MAX_SPREAD_PIPS:g} pips" if MAX_SPREAD_PIPS else "off",
                  "skip when wider"],
                 ["opposite-direction hedge block", "off",
                  "disabled by owner request"],
                 ["per symbol cap", str(MAX_TRADES_PER_SYMBOL or "-"),
                  "live + pending orders"],
                 ["be ladder", f"{BE_LADDER_PIPS:g} pips" if BE_LADDER_PIPS else "off",
                  "every layer"],
                 ["runner mode", "ON" if RUNNER_MODE else "off",
                  f"trail {RUNNER_KEEP_PCTS:g}% of the profit"],
                 ["partial ladder", PARTIAL_LADDER or "off", "percent@pips"],
                 ["trading hours", TRADE_HOURS or "any hour", "UTC"],
                 ["voice", "ON" if VOICE_ON else "off", str(VOICE_MODE)],
                 ["auto backup", "ON" if AUTO_BACKUP else "off",
                  f"keep {BACKUP_KEEP} days"]]
    stream_rows = [[
        datetime.fromtimestamp(float(r.get("ts") or 0)).strftime("%d %b %H:%M:%S"),
        r.get("channel"), r.get("cat"), r.get("kind"), r.get("symbol"),
        r.get("direction"), r.get("pips"), r.get("usd"), r.get("tag")]
        for r in board_streams("all" if False else "month", 300)] or [["-"] * 9]

    path = xlsx_write(path, [
        ("TRADES", heads, rows, widths, (10, 11, 12, 13, 16, 17),
         [(10, "scale"), (17, "scale")]),
        ("CHANNELS", ["#", "CHANNEL", "TYPE", "ORDERS", "TRIGGERED", "MISSED", "TP",
                      "SL", "BE", "MANUAL", "WIN %", "P/L USD"], ch_rows,
         [5, 24, 8, 8, 10, 8, 6, 6, 6, 8, 8, 11], (12,),
         [(11, "win"), (12, "scale")]),
        ("DAILY", ["DAY", "ORDERS", "TRIGGERED", "MISSED", "TP", "SL", "BE", "MANUAL",
                   "WIN %", "NET USD"], day_rows,
         [14, 8, 10, 8, 6, 6, 6, 8, 8, 11], (10,),
         [(9, "win"), (10, "scale")]),
        ("PERIODS", ["PERIOD", "ORDERS", "TRIGGERED", "MISSED", "TP", "SL", "BE",
                     "MANUAL", "WIN %", "NET USD"], per_rows,
         [26, 8, 10, 8, 6, 6, 6, 8, 8, 11], (10,),
         [(9, "win"), (10, "scale")]),
        ("HOURS", ["HOUR", "TRADES", "TP", "SL", "WIN %", "NET USD"], hour_rows,
         [8, 8, 6, 6, 8, 11], (6,), [(5, "win"), (6, "scale")]),
        ("MONTH vs MONTH", ["CHANNEL", "TYPE", "THIS n", "THIS P/L", "THIS TP", "THIS SL",
                            "LAST n", "LAST P/L", "DELTA"], cmp_rows,
         [24, 8, 8, 11, 8, 8, 8, 11, 11], (4, 8, 9), [(9, "scale")]),
        ("FILL QUALITY", ["GROUP", "FILLS", "AVG SLIP", "BEST", "WORST"], slip_rows,
         [22, 9, 11, 9, 9], (3, 4, 5), [(3, "scale"), (5, "scale")]),
        ("PROTECTION", ["GUARD", "STATE", "DETAIL"], prot_rows,
         [22, 12, 42], ()),
        ("TRADING PLAN", ["MONTH", "START", "GAIN", "END", "RATE %"], plan_rows,
         [8, 12, 12, 12, 10], (2, 3, 4), [(4, "scale")]),
        ("ANIMATED BOARD", ["TIME", "CHANNEL", "TYPE", "EVENT", "SYMBOL", "DIR",
                            "PIPS", "USD", "LAYER"], stream_rows,
         [17, 22, 8, 9, 9, 6, 8, 10, 12], (8,), [(7, "scale"), (8, "scale")]),
    ])
    try:
        note = excel_charts(path)
        if note:
            log("      " + note, "info")
    except Exception as exc:
        log(f"      excel charts: {exc}", "warn")
    return path


def jr_export(path=None) -> Path:
    """Write all three files at once (txt report + excel + pdf) and return the PDF."""
    jr_write_files()
    return jr_pdf(path)


def jr_write_files() -> None:
    try:
        (HERE / TRADE_REPORT).write_text(jr_report(), encoding="utf-8")
    except Exception as exc:
        log(f"trade journal: report not written ({exc})", "err")
    jr_write_csv()
    try:
        jr_excel()
    except Exception as exc:
        log(f"trade journal: excel not written ({exc})", "warn")


def jr_console() -> None:
    """Short summary for the console window (plain text, any code page)."""
    tot = jr_stats(TRADES)
    win = "-" if tot["win"] is None else f"{tot['win']:.1f}%"
    log(f"TRADE JOURNAL : placed {tot['n']} | pending {tot['pending']} | open {tot['open']} | "
        f"closed {tot['tp'] + tot['sl'] + tot['be'] + tot['manual']}", "ok")
    log(f"                TP {tot['tp']} | SL {tot['sl']} | BE {tot['be']} | "
        f"manual {tot['manual']} | cancelled {tot['cancelled']} | rejected {tot['rejected']}", "ok")
    log(f"                WIN RATE {win} | net {tot['pl']:+.2f} USD   "
        f"(TP/(TP+SL); BE not counted)", "ok")
    for r in jr_rank(top=8):
        st = r["stats"]
        w = "-" if st["win"] is None else f"{st['win']:.1f}%"
        log(f"                {r['medal']:<4}{r['name'][:26]:<28}{r['type']:<7} n={st['n']:<4} "
            f"TP={st['tp']:<4} SL={st['sl']:<4} BE={st['be']:<4} win={w:<7} "
            f"{st['pl']:+.2f} USD", "info")
    d = jr_daily()
    log(f"                TODAY {d['day']} : placed {d['placed']} | triggered {d['filled']} | "
        f"missed {d['missed']} | TP {d['tp']} SL {d['sl']} BE {d['be']} | "
        f"net {d['net']:+.2f} USD", "info")
    log(f"                report : {TRADE_REPORT}", "info")
    log(f"                excel  : {TRADE_CSV}", "info")


def mt5_close_info(ticket: int):
    """How a position ended: last closing deal + money.  (None = no history yet)"""
    try:
        deals = mt5.history_deals_get(position=int(ticket)) or []
    except Exception:
        deals = []
    if not deals:
        return None
    outs = [d for d in deals if d.entry in (mt5.DEAL_ENTRY_OUT,
                                            getattr(mt5, "DEAL_ENTRY_OUT_BY", 3))]
    last = outs[-1] if outs else deals[-1]
    return {"price": float(last.price), "ts": float(last.time),
            "profit": sum(float(d.profit) for d in deals),
            "commission": sum(float(d.commission) for d in deals),
            "swap": sum(float(d.swap) for d in deals)}


# --------------------------------------------------------------------------- #
#  a tiny PDF writer (Courier, A4) - works offline, needs no extra package    #
# --------------------------------------------------------------------------- #
def _pdf_esc(text: str) -> str:
    return text.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")


def _pdf_ascii(text: str) -> str:
    """PDF built-in fonts are latin-1 only -> drop emoji / other scripts."""
    return text.encode("ascii", "ignore").decode("ascii").rstrip()


def _pdf_is_heading(line: str) -> bool:
    body = line.strip()
    if len(body) < 4 or line.startswith(" "):
        return False
    return all(ch.isupper() or ch in " ()&/%+.,:'-0123456789()" for ch in body) and any(
        c.isalpha() for c in body)


# --------------------------------------------------------------------------- #
#  PREMIUM PDF REPORT   (light, printable, logo + colours + calendar)         #
# --------------------------------------------------------------------------- #
PDF_F = {1: "Helvetica", 2: "Helvetica-Bold", 3: "Courier", 4: "Courier-Bold"}
PDF_NAVY = (0.059, 0.075, 0.106)
PDF_PANEL = (0.086, 0.110, 0.157)
PDF_GOLD = (0.890, 0.702, 0.255)
PDF_GREEN = (0.180, 0.627, 0.263)
PDF_RED = (0.973, 0.318, 0.286)
PDF_GREY = (0.545, 0.596, 0.671)
PDF_LIGHT = (0.945, 0.957, 0.973)
PDF_ZEBRA = (0.976, 0.980, 0.988)
PDF_WHITE = (1, 1, 1)

# ---- v1.8.0  DARK theme (the institutional look) --------------------------
PDF_DARK = True               # the PDF/app report is dark by default
DARK_BG = (0.043, 0.055, 0.078)       # page
DARK_PANEL = (0.078, 0.098, 0.137)    # cards
DARK_CARD = (0.098, 0.122, 0.165)
DARK_LINE = (0.165, 0.196, 0.247)     # hairlines
DARK_TEXT = (0.902, 0.925, 0.949)
DARK_MUTED = (0.545, 0.596, 0.671)
DARK_ZEBRA = (0.063, 0.078, 0.110)
DARK_GRID = (0.090, 0.110, 0.145)
PDF_SECTIONS = ("cover", "kpi", "period", "chart", "channels", "quality", "hours",
                "calendar", "risk", "slippage", "plan", "trades")


def _pdf_width(font: int, size: float, text: str) -> float:
    """Exact for Courier (0.6 em), close enough for Helvetica."""
    if font in (3, 4):
        return 0.6 * size * len(text)
    bold = 1.10 if font == 2 else 1.03
    return 0.5 * size * len(text) * bold


class PremiumPDF:
    """A very small PDF writer with colours, rectangles and one image."""

    def __init__(self, logo_jpeg: bytes = None, logo_px: int = 0, dark: bool = None,
                 title: str = "", subtitle: str = "", by: str = "",
                 brand_name: str = ""):
        self.pages = []           # list of list-of-ops
        self.cur = []
        self.logo = logo_jpeg
        self.logo_px = logo_px
        self.page_no = 0
        # ---- v1.8.0 dark institutional theme ------------------------------
        self.dark = bool(PDF_DARK if dark is None else dark)
        self.title = title or "EDGEQUANT SENTINEL"
        self.subtitle = subtitle
        self.by = by
        # Provider exports may show the provider's supplied brand on the cover;
        # the footer remains the EdgeQuant Sentinel software credit.
        self.brand_name = str(brand_name or BOT_NAME).strip() or BOT_NAME
        self.t = ({"bg": DARK_BG, "panel": DARK_PANEL, "card": DARK_CARD,
                   "line": DARK_LINE, "head": DARK_PANEL, "text": DARK_TEXT,
                   "muted": DARK_MUTED, "zebra": DARK_ZEBRA, "grid": DARK_GRID,
                   "white": PDF_WHITE, "gold": PDF_GOLD, "green": (0.298, 0.831, 0.478),
                   "red": (0.976, 0.404, 0.369), "amber": (0.949, 0.702, 0.286)}
                  if self.dark else
                  {"bg": PDF_WHITE, "panel": PDF_PANEL, "card": PDF_LIGHT,
                   "line": (0.871, 0.898, 0.937), "head": PDF_NAVY, "text": PDF_NAVY,
                   "muted": PDF_GREY, "zebra": PDF_ZEBRA, "grid": (0.945, 0.957, 0.973),
                   "white": PDF_WHITE, "gold": PDF_GOLD, "green": PDF_GREEN,
                   "red": PDF_RED, "amber": (0.749, 0.478, 0.106)})

    def T(self, key: str):
        """One colour of the active theme."""
        return self.t.get(key) or PDF_NAVY

    def _bg_ops(self) -> list:
        """The dark page background (drawn under everything else)."""
        if not self.dark:
            return []
        ops = [f"q {self._c(self.t['bg'])} 0 0 595 842 re f Q"]
        grid = []
        for x in range(0, 596, 30):
            grid.append(f"q {self._c(self.t['grid'], True)} 0.18 w {x} 0 m {x} 842 l S Q")
        for yy in range(0, 843, 30):
            grid.append(f"q {self._c(self.t['grid'], True)} 0.18 w 0 {yy} m 595 {yy} l S Q")
        ops += grid
        ops.append(f"q {self._c(PDF_GOLD)} 0 0 595 3 re f Q")
        ops.append(f"q {self._c((0.10, 0.12, 0.16))} 0 0 595 1.2 re f Q")
        return ops

    # ------------------------------------------------------------ primitives
    def _c(self, rgb, stroke=False):
        return f"{rgb[0]:.3f} {rgb[1]:.3f} {rgb[2]:.3f} " + ("RG" if stroke else "rg")

    def rect(self, x, y, w, h, colour, stroke=None, lw=0.6):
        if stroke:
            self.cur.append(f"q {self._c(colour)} {self._c(stroke, True)} {lw:.2f} w "
                            f"{x:.2f} {y:.2f} {w:.2f} {h:.2f} re B Q")
        else:
            self.cur.append(f"q {self._c(colour)} {x:.2f} {y:.2f} {w:.2f} {h:.2f} re f Q")

    def line(self, x1, y1, x2, y2, colour, lw=0.8):
        self.cur.append(f"q {self._c(colour, True)} {lw:.2f} w {x1:.2f} {y1:.2f} m "
                        f"{x2:.2f} {y2:.2f} l S Q")

    def text(self, x, y, txt, font=1, size=9, colour=None, align="l"):
        if colour is None:
            colour = self.T("text")
        txt = _pdf_ascii(str(txt))
        if align == "r":
            x = x - _pdf_width(font, size, txt)
        elif align == "c":
            x = x - _pdf_width(font, size, txt) / 2.0
        self.cur.append(f"BT {self._c(colour)} /F{font} {size:g} Tf {x:.2f} {y:.2f} Td "
                        f"({_pdf_esc(txt)}) Tj ET")

    def image(self, x, y, w, h):
        if not self.logo:
            return
        self.cur.append(f"q {w:.2f} 0 0 {h:.2f} {x:.2f} {y:.2f} cm /Im0 Do Q")

    def new_page(self):
        if self.cur:
            self.pages.append(self.cur)
        self.cur = []
        self.page_no += 1

    # --------------------------------------------------------- cover + charts
    def cover(self, lines: list = None, badge: str = "INSTITUTIONAL GRADE"):
        """A dark cover page (page 1 of the report)."""
        self.new_page()
        self.rect(0, 0, 595, 842, self.T("bg") if self.dark else PDF_LIGHT)
        self.rect(0, 640, 595, 202, self.T("head") if self.dark else PDF_NAVY)
        self.rect(0, 637, 595, 3, PDF_GOLD)
        if self.logo:
            self.image(44, 736, 92, 92)
        x = 152 if self.logo else 44
        self.text(x, 800, self.brand_name, 2, 30,
                  self.T("white") if self.dark else PDF_WHITE)
        self.text(x, 780, BOT_TAGLINE, 1, 11.5, PDF_GOLD)
        self.text(x, 760, "Telegram  ->  MetaTrader 5      automatic execution engine",
                  1, 8.5, PDF_GREY)
        self.text(x, 700, badge, 2, 9, PDF_GOLD)
        y = 590
        for i, (label, value) in enumerate(lines or []):
            self.rect(40, y - 6, 515, 26, self.T("card"))
            self.rect(40, y - 6, 3, 26, PDF_GOLD if i == 0 else self.T("line"))
            self.text(54, y + 4, str(label).upper(), 2, 8, self.T("muted"))
            self.text(551, y + 3, str(value), 2, 13, self.T("text"), align="r")
            y -= 32
        self.text(40, 120, "PREPARED FOR", 2, 7.5, self.T("muted"))
        self.text(40, 106, self.by or "-", 1, 11, self.T("text"))
        self.text(551, 106, datetime.now().strftime("%d %B %Y  %H:%M"), 1, 9,
                  self.T("text"), align="r")
        self.text(40, 70, f"{BOT_NAME}  v{VERSION}", 1, 7.5, self.T("muted"))
        self.text(551, 70, "page " + str(self.page_no), 1, 7.5, self.T("muted"), align="r")
        return y

    def bars(self, y, rows: list, title: str = "", note: str = "", h: float = 96.0,
             unit: str = "USD"):
        """rows = [(label, value)] - a horizontal bar chart (channel net P&L)."""
        y = self.section(y, title or "BAR CHART", note) if title else y
        if not rows:
            self.text(38, y, "no data yet", 1, 8, self.T("muted"))
            return y - 16
        top = max(abs(float(v)) for _l, v in rows) or 1.0
        x0, w = 150.0, 340.0
        step = h / max(1, len(rows))
        for i, (label, value) in enumerate(rows):
            value = float(value)
            yy = y - i * step
            mid = x0 + w
            bw = abs(value) / top * (w / 2.0)
            self.text(x0 - 8, yy - step / 2.0 + 1.5, str(label)[:26], 1, 7.2,
                      self.T("text"), align="r")
            col = self.T("green") if value >= 0 else self.T("red")
            self.rect(mid if value >= 0 else mid - bw, yy - step + 3, bw, step - 7, col)
            tx = (mid + bw + 5) if value >= 0 else (mid - bw - 5)
            self.text(tx, yy - step / 2.0 + 1.5, f"{value:+,.2f} {unit}", 1, 6.8,
                      col, align="l" if value >= 0 else "r")
        self.line(x0 + w / 2.0, y - len(rows) * step - 2, x0 + w / 2.0, y + 2,
                  self.T("line"), 0.5)
        return y - len(rows) * step - 8

    def curve(self, y, pts: list, title: str = "", note: str = "", h: float = 100.0):
        """pts = [(ts, value)] - the equity curve (closed P&L over time)."""
        y = self.section(y, title or "EQUITY CURVE", note) if title else y
        if len(pts) < 2:
            self.text(38, y, "not enough closed trades for a curve yet", 1, 8,
                      self.T("muted"))
            return y - 16
        x0, w = 40.0, 512.0
        vals = [float(v) for _t, v in pts]
        lo, hi = min(vals + [0.0]), max(vals + [0.0])
        span = (hi - lo) or 1.0
        def X(i): return x0 + i * w / max(1, len(pts) - 1)
        def Y(v): return (y - h) + 8 + (v - lo) / span * (h - 16)   # bigger = higher
        self.rect(x0, y - h, w, h, self.T("card") if self.dark else (0.98, 0.98, 0.99))
        for k in range(1, 4):
            yy = y - h + h * k / 4.0
            self.line(x0, yy, x0 + w, yy, self.T("grid") if self.dark else PDF_ZEBRA, 0.4)
        self.line(x0, Y(0), x0 + w, Y(0), self.T("line"), 0.6)
        last = None
        for i, (_t, v) in enumerate(pts):
            x, yy = X(i), Y(float(v))
            if last is not None:
                col = self.T("green") if float(v) >= 0 else self.T("red")
                self.line(last[0], last[1], x, yy, col, 1.4)
            last = (x, yy)
        self.text(x0 + w, y - h - 9, f"max {hi:+,.2f}", 1, 6.6, self.T("muted"),
                  align="r")
        self.text(x0, y - h - 9, f"min {lo:+,.2f}", 1, 6.6, self.T("muted"))
        self.text(x0 + w / 2.0, y - h - 9, f"last {vals[-1]:+,.2f}", 1, 6.6,
                  self.T("green") if vals[-1] >= 0 else self.T("red"), align="c")
        return y - h - 24

    def donut(self, y, parts: list, title: str = "", note: str = ""):
        """parts = [(label, count, colour)] - a stacked bar (TP / SL / BE mix)."""
        y = self.section(y, title or "MIX", note) if title else y
        total = sum(max(0, int(c)) for _l, c, _c in parts) or 1
        x0, w, h = 40.0, 512.0, 16.0
        xx = x0
        for label, count, colour in parts:
            bw = w * max(0, int(count)) / float(total)
            if bw > 0:
                self.rect(xx, y - h, bw, h, colour)
                if bw > 34:
                    self.text(xx + bw / 2.0, y - h + 5, str(count), 2, 7.6,
                              PDF_WHITE, align="c")
            xx += bw
        self.text(x0, y - h - 11,
                  "   ".join(f"{l} {c}" for l, c, _c in parts), 1, 7.2, self.T("text"))
        return y - h - 20

    # ---------------------------------------------------------------- helpers
    def header(self, title, subtitle="", right="", date=""):
        head = self.T("head") if self.dark else PDF_NAVY
        self.rect(0, 754, 595, 88, head)
        self.rect(0, 754, 595, 3, PDF_GOLD)
        if self.logo:
            self.image(30, 768, 60, 60)
        x = 104 if self.logo else 34
        self.text(x, 806, self.brand_name, 2, 17, PDF_WHITE)
        self.text(561, 790, f"v{VERSION}", 1, 7.5, PDF_GREY, align="r")
        self.text(x, 793, BOT_TAGLINE, 1, 8.5, PDF_GOLD)
        self.text(x, 780, "Telegram  ->  MetaTrader 5      automatic execution engine",
                  1, 7.5, PDF_GREY)
        if right:
            self.text(561, 806, right, 2, 11.5, PDF_GOLD, align="r")
        self.text(561, 793, date or datetime.now().strftime("%d %b %Y  %H:%M"), 1, 8,
                  PDF_GREY, align="r")
        self.text(561, 780, f"version {VERSION}", 1, 7.5, PDF_GREY, align="r")
        return 736

    def small_header(self):
        self.rect(0, 800, 595, 42, self.T("head") if self.dark else PDF_NAVY)
        self.rect(0, 800, 595, 3, PDF_GOLD)
        if self.logo:
            self.image(30, 806, 30, 30)
        self.text(68, 818, f"{self.brand_name}   -   TRADE JOURNAL", 2, 10.5, PDF_WHITE)
        self.text(561, 818, f"{BOT_TAGLINE}", 1, 7.5, PDF_GREY, align="r")
        return 782

    def section(self, y, title, note=""):
        y -= 2
        self.rect(34, y - 1, 3, 12, PDF_GOLD)
        self.text(43, y + 1, title, 2, 10.5, self.T("text"))
        if note:
            self.text(561, y + 1, note, 1, 7.5, PDF_GREY, align="r")
        return y - 14

    def kpis(self, y, items):
        """items = [(label, value, colour), ...]  -> a row of 4 cards."""
        n = max(1, len(items))
        gap = 8
        w = (527 - gap * (n - 1)) / n
        for i, (label, value, colour) in enumerate(items):
            x = 34 + i * (w + gap)
            self.rect(x, y - 56, w, 56, self.T("card") if self.dark
                      else PDF_LIGHT, stroke=self.T("line"))
            self.rect(x, y - 3, w, 3, colour)
            self.text(x + 9, y - 20, label.upper(), 2, 6.6, self.T("muted"))
            self.text(x + 9, y - 40, value, 2, 14.5, colour)
        return y - 68

    COLS = [("rank", 26, "l"), ("channel", 150, "l"), ("type", 50, "l"), ("orders", 44, "r"),
            ("trig", 42, "r"), ("miss", 42, "r"), ("tp", 28, "r"), ("sl", 28, "r"),
            ("be", 28, "r"), ("win", 44, "r"), ("pl", 45, "r")]

    def table(self, y, rows, headers, colours=None, min_y=80):
        """rows: list of lists (strings).  colours: list of RGB or None per row."""
        x0 = 34
        self.rect(x0, y - 14, 527, 14, self.T("head") if self.dark else PDF_NAVY)
        cx = x0 + 4
        for (key, w, al), head in zip(self.COLS, headers):
            self.text(cx if al == "l" else cx + w - 4, y - 10, head, 2, 6.8, PDF_WHITE,
                      align=al)
            cx += w
        y -= 20
        for i, row in enumerate(rows):
            if y < min_y:
                self.new_page()
                y = self.small_header()
            if i % 2:
                self.rect(x0, y - 9, 527, 13, self.T("zebra"))
            cx = x0 + 4
            for j, ((key, w, al), cell) in enumerate(zip(self.COLS, row)):
                col = self.T("text")
                if colours and colours[i] and key in ("win", "pl"):
                    col = colours[i]
                elif key == "rank" and str(cell) in ("#1", "#2", "#3"):
                    col = PDF_GOLD if str(cell) == "#1" else (PDF_GREY if str(cell) == "#2"
                                                              else (0.804, 0.498, 0.196))
                fnt = 4 if key in ("rank", "orders", "trig", "miss", "tp", "sl", "be", "win",
                                   "pl") else 3
                self.text(cx if al == "l" else cx + w - 4, y, str(cell), fnt, 7.4, col,
                          align=al)
                cx += w
            y -= 13
        return y - 6

    def calendar(self, y, cal, min_y=70):
        """Profit calendar of one month (7 columns + a weekly total column)."""
        cw, ch = 62, 38
        x0 = 34
        heads = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN", "WEEK")
        for i, h in enumerate(heads):
            self.text(x0 + i * cw + cw / 2, y - 8, h, 2, 6.6, PDF_GREY, align="c")
        y -= 16
        for wk in range(6):
            cells = []
            for wd in range(7):
                cells.append(wk * 7 + wd - cal["first_weekday"] + 1)
            if all(not (1 <= d <= cal["days_in_month"]) for d in cells):
                continue
            if y - ch < min_y:
                self.new_page()
                y = self.small_header()
            for wd, day in enumerate(cells):
                x = x0 + wd * cw
                if not (1 <= day <= cal["days_in_month"]):
                    self.rect(x + 1, y - ch + 1, cw - 2, ch - 2, PDF_ZEBRA)
                    continue
                st = cal["days"].get(day)
                net = st["net"] if st else 0.0
                if self.dark:
                    fill = (self.T("zebra") if not st else
                            ((0.075, 0.180, 0.122) if net >= 0 else (0.196, 0.090, 0.098)))
                else:
                    fill = PDF_ZEBRA if not st else ((0.90, 0.97, 0.92) if net >= 0
                                                     else (0.99, 0.92, 0.91))
                self.rect(x + 1, y - ch + 1, cw - 2, ch - 2, fill)
                self.text(x + 5, y - 10, str(day), 4, 7.2, PDF_GREY)
                if st:
                    self.text(x + cw - 5, y - 10,
                              f"{net:+.1f}", 4, 7.6,
                              PDF_GREEN if net > 0 else (PDF_RED if net < 0 else PDF_GREY),
                              align="r")
                    self.text(x + 5, y - ch + 8,
                              f"{st['n']} tr   {st.get('tp', 0)}TP/{st.get('sl', 0)}SL",
                              3, 5.8, PDF_GREY)
            wk_net = cal["weeks"].get(wk)
            xw = x0 + 7 * cw
            self.rect(xw + 1, y - ch + 1, cw - 2, ch - 2, PDF_LIGHT)
            if wk_net is not None:
                self.text(xw + cw - 5, y - 16,
                          f"{wk_net:+.1f}", 4, 8.2,
                          PDF_GREEN if wk_net > 0 else (PDF_RED if wk_net < 0 else PDF_GREY),
                          align="r")
                self.text(xw + 5, y - 30, "week", 3, 5.8, PDF_GREY)
            y -= ch
        return y - 6

    def footer(self, page=True):
        y = 26
        self.line(34, y + 10, 561, y + 10, self.T("line"))
        self.text(34, y, f"{BOT_NAME}  v{VERSION}   -   {BOT_TAGLINE}", 1, 6.8, PDF_GREY)
        self.text(561, y, f"page {self.page_no}", 1, 6.8, PDF_GREY, align="r")

    # ------------------------------------------------------------------ save
    def save(self, path):
        if self.cur:
            self.pages.append(self.cur)
            self.cur = []
        if self.dark:                    # the background goes UNDER every page
            self.pages = [self._bg_ops() + ops for ops in self.pages]
        n = len(self.pages)
        base = 7                                # 1 catalog, 2 pages, 3-6 fonts
        objs = {
            1: "<< /Type /Catalog /Pages 2 0 R >>",
            2: "<< /Type /Pages /Count %d /Kids [%s] >>" % (
                n, " ".join(f"{base + 3 * i} 0 R" for i in range(n))),
            3: "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
            4: "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
            5: "<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>",
            6: "<< /Type /Font /Subtype /Type1 /BaseFont /Courier-Bold >>",
        }
        # base..: page, content, ...  -> the image object goes last
        img_obj = base + 3 * n
        xobj = ""
        if self.logo:
            objs[img_obj] = ("image",
                             ("<< /Type /XObject /Subtype /Image /Width %d /Height %d "
                              "/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode "
                              "/Length %d >>\nstream\n"
                              % (self.logo_px, self.logo_px, len(self.logo))
                              ).encode("latin-1") + self.logo + b"\nendstream")
            xobj = f" /XObject << /Im0 {img_obj} 0 R >>"
        for i, ops in enumerate(self.pages):
            pnum, cnum = base + 3 * i, base + 3 * i + 1
            data = ("\n".join(ops)).encode("latin-1", "replace")
            objs[cnum] = data
            objs[pnum] = ("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources "
                          "<< /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R /F4 6 0 R >>"
                          f"{xobj} >> /Contents {cnum} 0 R >>")
        total = max(objs)
        out = bytearray(b"%PDF-1.4\n")
        offs = {}
        for num in range(1, total + 1):
            if num not in objs:
                continue
            offs[num] = len(out)
            out += b"%d 0 obj\n" % num
            val = objs[num]
            if isinstance(val, tuple):
                out += val[1]                    # ready-made blob (the logo image)
            elif isinstance(val, bytes):
                out += b"<< /Length %d >>\nstream\n" % len(val) + val + b"\nendstream"
            else:
                out += val.encode("latin-1", "replace")
            out += b"\nendobj\n"
        xref = len(out)
        out += b"xref\n0 %d\n" % (total + 1)
        out += b"0000000000 65535 f \n"
        for num in range(1, total + 1):
            out += b"%010d 00000 n \n" % offs.get(num, 0)
        out += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (
            total + 1, xref)
        Path(path).write_bytes(bytes(out))
        return Path(path)


def _logo_jpeg(px=120):
    """The app logo as JPEG bytes for the PDF (needs Pillow - optional)."""
    try:
        from io import BytesIO
        from PIL import Image
        for name in ("edgequant-logo-mark.png", "edgequant-logo-small.png",
                     "edgequant-icon.png"):
            f = HERE / name
            if f.exists():
                im = Image.open(f).convert("RGB").resize((px, px), Image.LANCZOS)
                buf = BytesIO()
                im.save(buf, "JPEG", quality=88)
                return buf.getvalue(), px
    except Exception:
        try:
            if not globals().get("_LOGO_WARNED"):
                globals()["_LOGO_WARNED"] = True
                log("PDF: report eke logo eka daanna Pillow oni  ->  "
                    "python -m pip install Pillow   (ithuru okkoma weda karanawa)", "info")
        except Exception:
            pass
    return None, 0


def pdf_report(path=None, owner: str = "Duminda Miyuranga") -> Path:
    """The INSTITUTIONAL PDF: dark theme, cover page, charts, every section.

    Sections can be switched in the settings:  PDF_SECTIONS = ( ... )
    """
    path = Path(path) if path else (HERE / TRADE_PDF)
    jpeg, px = _logo_jpeg()
    want = [x.strip().lower() for x in (PDF_SECTIONS or ()) if str(x).strip()]
    def has(name: str) -> bool:
        return (not want) or (name in want)
    allst0 = jr_stats(TRADES)
    met0 = jr_metrics()
    day0, week0, month0 = jr_range("today"), jr_range("week"), jr_range("month")
    pdf = PremiumPDF(jpeg, px, dark=PDF_DARK, by=owner,
                     title="TRADE JOURNAL", subtitle=datetime.now().strftime("%B %Y"))
    if has("cover"):
        pdf.cover([("closed P&L (all time)", f"{allst0['pl']:+,.2f} USD"),
                   ("this month", f"{month0['net']:+,.2f} USD"),
                   ("win rate", "-" if allst0["win"] is None else f"{allst0['win']:.1f}%"),
                   ("profit factor", "-" if met0.get("profit_factor") is None
                    else f"{met0['profit_factor']:.2f}"),
                   ("orders", f"{allst0['n']}"),
                   ("report", datetime.now().strftime("%d %b %Y  %H:%M"))])
        pdf.new_page()               # push the cover, start the report on page 2
    y = pdf.header("TRADE JOURNAL", right="TRADE JOURNAL")
    allst = jr_stats(TRADES)
    day, week, month = jr_range("today"), jr_range("week"), jr_range("month")
    floating = sum(float(t.get("profit") or 0.0) for t in TRADES if t.get("status") == "open")
    total = allst["pl"] + floating
    pdf.kpis(y, [("CURRENT P&L  (closed + float)", f"{total:+,.2f} USD",
                  PDF_GREEN if total >= 0 else PDF_RED),
                 ("DAILY P&L  (today)", f"{day['net']:+,.2f} USD",
                  PDF_GREEN if day["net"] >= 0 else PDF_RED),
                 ("THIS WEEK", f"{week['net']:+,.2f} USD",
                  PDF_GREEN if week["net"] >= 0 else PDF_RED),
                 ("THIS MONTH", f"{month['net']:+,.2f} USD",
                  PDF_GREEN if month["net"] >= 0 else PDF_RED)])
    y = pdf.kpis(y, [("orders all time", f"{allst['n']}", pdf.T("text")),
                     ("win rate  TP/(TP+SL)", "-" if allst["win"] is None
                      else f"{allst['win']:.1f}%", PDF_GOLD),
                     ("trades this week", f"{week['placed']}", pdf.T("text")),
                     ("trades this month", f"{month['placed']}", pdf.T("text"))])

    # ---- period table ------------------------------------------------------
    y = pdf.section(y, "DAILY / WEEKLY / MONTHLY / ALL TIME",
                    "orders | triggered | missed | TP | SL | BE | win% | net")
    pdf.rect(34, y - 13, 527, 13, pdf.T("text"))
    heads = ("PERIOD", "ORDERS", "TRIG", "MISS", "TP", "SL", "BE", "MAN", "WIN%", "NET P/L")
    xs = [38, 235, 292, 340, 378, 414, 452, 488, 524, 558]
    for x, h in zip(xs, heads):
        pdf.text(x if h in ("PERIOD",) else x, y - 9, h, 2, 6.8, PDF_WHITE,
                 align="l" if h == "PERIOD" else "r")
    y -= 19
    for per in ("today", "week", "month", "all"):
        r = jr_range(per)
        vals = [r["label"][:24], str(r["placed"]), str(r["filled"]), str(r["missed"]),
                str(r["tp"]), str(r["sl"]), str(r["be"]), str(r["manual"]),
                "-" if r["win"] is None else f"{r['win']:.1f}%", f"{r['net']:+,.2f}"]
        for x, v, h in zip(xs, vals, heads):
            col = pdf.T("text")
            if h == "NET P/L":
                col = PDF_GREEN if r["net"] > 0 else (PDF_RED if r["net"] < 0 else pdf.T("muted"))
            pdf.text(x, y, v, 4 if h != "PERIOD" else 3, 7.4, col,
                     align="l" if h == "PERIOD" else "r")
        y -= 13
    y -= 10

    # ---- channel ranking ---------------------------------------------------
    y = pdf.section(y, "CHANNEL RANKING", "#1 = highest realized net P&L")
    rows, cols = [], []
    for r in jr_rank():
        st = r["stats"]
        rows.append([r.get("medal", ""), r["name"], r["type"], st["n"], st["trig"], st["miss"],
                     st["tp"], st["sl"], st["be"], "-" if st["win"] is None
                     else f"{st['win']:.1f}%", f"{st['pl']:+,.2f}"])
        cols.append(PDF_GREEN if st["pl"] > 0 else (PDF_RED if st["pl"] < 0 else pdf.T("muted")))
    if rows:
        y = pdf.table(y, rows, ["#", "CHANNEL", "LIMIT/MKT", "ORDERS", "TRIG", "MISS", "TP",
                                "SL", "BE", "WIN%", "P/L"], colours=cols)
    else:
        pdf.text(38, y, "no trades recorded yet", 1, 8, pdf.T("muted"))
        y -= 16

    # ---- order type --------------------------------------------------------
    y = pdf.section(y, "LIMIT  vs  MARKET ORDERS", "pending orders / instant orders")
    rows, cols = [], []
    for label, kinds in (("LIMIT orders (pending)", ("PENDING",)),
                         ("MARKET orders (instant)", ("MARKET",)),
                         ("TOTAL", ("PENDING", "MARKET"))):
        st = jr_stats([t for t in TRADES if t.get("kind") in kinds])
        rows.append(["", label, "LIMIT" if kinds == ("PENDING",) else
                     ("MARKET" if kinds == ("MARKET",) else "BOTH"), st["n"], st["trig"],
                     st["miss"], st["tp"], st["sl"], st["be"],
                     "-" if st["win"] is None else f"{st['win']:.1f}%", f"{st['pl']:+,.2f}"])
        cols.append(PDF_GREEN if st["pl"] > 0 else (PDF_RED if st["pl"] < 0 else pdf.T("muted")))
    y = pdf.table(y, rows, ["#", "GROUP", "TYPE", "ORDERS", "TRIG", "MISS", "TP", "SL", "BE",
                            "WIN%", "P/L"], colours=cols)
    ps = jr_pending_stats()
    if ps["n"]:
        rate = "-" if ps["rate"] is None else f"{ps['rate']:.1f}%"
        txt = (f"pending trigger rate {rate}   |   "
               f"placed {ps['n']}   triggered {ps['trig']}   waiting {ps['pending']}   "
               f"missed {ps['miss']}   refused {ps['rejected']}")
        pdf.text(38, y, txt, 1, 7.6, pdf.T("muted"))
        y -= 12

    pdf.footer()

    # ================== v1.8.0  VISUALS + QUALITY + RISK + PLAN ============
    if has("chart") or has("quality") or has("risk") or has("plan"):
        pass
    if has("chart"):
        pdf.new_page()
        y = pdf.small_header()
        y = pdf.curve(y, equity_curve(0), "EQUITY CURVE  (closed P&L)",
                      "every closed trade, oldest first")
        chan_rows = [(r["name"], r["stats"]["pl"]) for r in jr_rank(top=10)]
        y = pdf.bars(y, chan_rows, "NET P&L BY CHANNEL", "which channel really pays")
        if y < 300:
            pdf.new_page()
            y = pdf.small_header()
        st_mix = jr_stats(TRADES)
        y = pdf.donut(y, [("TP", st_mix["tp"], PDF_GREEN),
                          ("SL", st_mix["sl"], PDF_RED),
                          ("BE", st_mix["be"], (0.949, 0.702, 0.286)),
                          ("manual", st_mix["manual"], (0.545, 0.596, 0.671))],
                      "RESULT MIX", "how the closed orders ended")
        dd = drawdown_state()
        y = pdf.kpis(y, [("drawdown now", f"{dd['dd']:,.2f}",
                          PDF_RED if dd["dd"] else PDF_GREEN),
                         ("worst drawdown", f"{dd['max_dd']:,.2f}", PDF_RED),
                         ("expectancy / trade", f"{met0.get('expectancy', 0):+,.2f}",
                          PDF_GREEN if met0.get("expectancy", 0) >= 0 else PDF_RED),
                         ("peak closed P&L", f"{dd['peak']:+,.2f}", PDF_GREEN)])
        pdf.footer()
    if has("quality"):
        pdf.new_page()
        y = pdf.small_header()
        bests = best_trades("all", limit=8)
        y = pdf.section(y, "WHERE THE PROFIT CAME FROM",
                        "biggest wins first - the trades that paid for the month")
        rows, cols = [], []
        for t in bests:
            rows.append([str(t.get("source") or "")[:22], t.get("symbol") or "",
                         str(t.get("direction") or ""), f"{trade_pips(t):+.1f}",
                         f"{float(t.get('net') or 0):+,.2f}",
                         (datetime.fromtimestamp(float(t.get("closed_ts") or 0))
                          .strftime("%d %b %H:%M") if t.get("closed_ts") else "-")])
            cols.append(PDF_GREEN if float(t.get("net") or 0) >= 0 else PDF_RED)
        if rows:
            y = pdf.table(y, rows, ["#", "CHANNEL", "SYMBOL", "DIR", "PIPS", "NET USD",
                                    "CLOSED"], colours=cols)
        else:
            pdf.text(38, y, "no closed trades yet", 1, 8, pdf.T("muted"))
            y -= 16
        y = pdf.section(y, "BEST HOURS  (your kill zones)", "net P&L per hour of the day")
        hz = jr_hours() or []
        y = pdf.bars(y, [(str(h.get("hour", "?")), float(h.get("net") or 0.0))
                         for h in hz[:8]], "", "", h=88)
        y = pdf.section(y, "SLIPPAGE / FILL QUALITY", "asked price vs the real fill")
        sl = slippage_stats()
