def tg_bar() -> str:
    return "\u2550" * 56


def tg_title(icon: str, headline: str, sub: str = "", sub2: str = "") -> str:
    """The head of EVERY Telegram message: EdgeQuant + the bull/bear logo,
    the event with its own emoji, and the channel."""
    L = [tg_bar(),
         f"  {BRAND_EMOJI}  {BOT_NAME.upper()}  {BRAND_EMOJI}",
         f"  {icon}  {headline}"]
    if sub:
        L.append(f"  {sub}")
    if sub2:
        L.append(f"  {sub2}")
    L.append(tg_bar())
    return "\n".join(L)


def tg_foot(extra: str = "") -> str:
    when = datetime.now().strftime("%d %b %Y   %H:%M")
    L = [tg_bar(), f"  {BRAND_EMOJI}  {BOT_NAME}  v{VERSION}   -   {when}"]
    if extra:
        L.append(f"  {extra}")
    L.append(f"  {BOT_TAGLINE}")
    return "\n".join(L)


def plain_text(text: str) -> str:
    """The same message without emoji (for the Windows console / log files)."""
    t = str(text).replace("\u2550", "=")
    return "".join(c for c in t if ord(c) < 0x2000)


def notify_update(title: str, src: str, detail: str) -> None:
    """A management action (TP changed / BE moved / cancelled / closed)."""
    if not (NOTIFY_TELEGRAM and NOTIFY_ON.get("command")):
        return
    notify("\n".join([tg_title(EV_ICON["command"], title,
                               f"{src or 'the bot'} : {detail}"),
                       tg_foot()]))


def notify(text: str, photo: bool = False) -> None:
    if not NOTIFY_TELEGRAM:
        return
    NOTIFY_Q.append((text, bool(photo), time.time()))          # v1.6.7: keeps the age
    while NOTIFY_Q_MAX and len(NOTIFY_Q) > int(NOTIFY_Q_MAX):
        _old = NOTIFY_Q.popleft()
        globals()["_NOTIFY_DROPPED"] = int(globals().get("_NOTIFY_DROPPED", 0)) + 1
        log(f"notify: the queue is full ({NOTIFY_Q_MAX}) -> the oldest note was dropped "
            f"({q_unpack(_old)[0][:40]!r})", "warn")
    first = next((l.strip() for l in str(text).splitlines()
                  if l.strip() and l.strip().strip("=\u2550")), str(text)[:60])
    log(f"notify: {plain_text(first)[:70]}", "note")


def pl_usd(value) -> str:
    """+10.02 USD  /  -9.82 USD  (never anything else)."""
    try:
        return f"{float(value):+,.2f} USD"
    except (TypeError, ValueError):
        return "0.00 USD"


def _ev_signals(recs: list) -> int:
    """How many SIGNALS (not orders) are behind these records?"""
    return len({str(t.get("id", "")).rsplit("-", 1)[0] for t in recs if t.get("id")})


def ev_tag_text(t: dict) -> str:
    """Which of the two layers is this order?"""
    tag = str(t.get("tag") or "").strip()
    if tag.lower().startswith("quick"):
        try:
            pips = float(tag[5:])
        except Exception:
            pips = float(LAYER1_TP_PIPS)
        return f"LAYER 1  (quick TP - {pips:g} pips)"
    if tag:
        return f"LAYER 2  (channel TP - {tag})"
    return "single order"


def _ev_clock(ts) -> str:
    try:
        return datetime.fromtimestamp(float(ts)).strftime("%H:%M:%S") if ts else "-"
    except Exception:
        return "-"


def _ev_mins(a, b) -> str:
    try:
        m = (float(b) - float(a)) / 60.0
        if m < 1:
            return f"{m * 60:.0f}s"
        if m < 90:
            return f"{m:.0f} min"
        return f"{m / 60:.1f} h"
    except Exception:
        return "-"


