def symbol_emoji(symbol: str) -> str:
    """Every instrument gets its own emoji: gold, silver, crypto, indices ..."""
    up = str(symbol or "").upper()
    if not up:
        return "\U0001F4C8"
    if "BTC" in up or "BITCOIN" in up:
        return "\u20BF"
    if "ETH" in up and "ETHUSD" in up.replace(".", "").replace("M", ""):
        return "\U0001FA99"
    for key, emo in SYM_EMOJI.items():
        if key in up:
            return emo
    return "\U0001F4C8"


def channel_symbol_of(name: str) -> str:
    """The instrument a channel trades most (from the journal)."""
    seen: dict = {}
    for (cname, _c), recs in jr_group().items():
        if cname != name:
            continue
        for t in recs:
            sym = (t.get("symbol") or "").upper()
            if sym:
                seen[sym] = seen.get(sym, 0) + 1
    if not seen:
        return ""
    return sorted(seen.items(), key=lambda kv: -kv[1])[0][0]


def trade_mix_line(st: dict) -> str:
    """One modern line: how many are open / pending / closed and how they ended."""
    bits = []
    live, pend = int(st.get("open") or 0), int(st.get("pending") or 0)
    closed = sum(int(st.get(k) or 0) for k in ("tp", "sl", "be", "manual"))
    if live:
        bits.append(f"\U0001F7E2 open {live}")
    if pend:
        bits.append(f"\u23F3 pending {pend}")
    if closed:
        bits.append(f"\u2705 closed {closed}")
    for key, emo, label in (("tp", "\U0001F3AF", "TP"), ("sl", "\U0001F6D1", "SL"),
                            ("be", "\U0001F6E1\uFE0F", "BE"),
                            ("manual", "\u270B", "manual")):
        n = int(st.get(key) or 0)
        if n:
            bits.append(f"{emo} {label} {n}")
    if st.get("cancelled"):
        bits.append(f"\u231B expired {int(st['cancelled'])}")
    if st.get("rejected"):
        bits.append(f"\u26A0\uFE0F refused {int(st['rejected'])}")
    return "   ".join(bits) or "no trades yet"


def money_win_line(st: dict) -> str:
    """Net P/L + win rate, emoji styled."""
    win = "-" if st.get("win") is None else f"{st['win']:.1f}%"
    return (f"\U0001F4B0 net {pl_usd(st.get('pl', 0.0))}      "
            f"\U0001F4CA win {win}")


def channel_block(name: str, st: dict, cat: str = "", medal: str = "",
                  symbol: str = "", period: str = "") -> list:
    """A modern, channel-wise block used in every report and alert."""
    sym = symbol or channel_symbol_of(name)
    head = f"  {symbol_emoji(sym)} {name}"
    if cat:
        head += f"   [{str(cat).upper()}]"
    if medal:
        head += f"   \U0001F3C6 {medal}"
    if period:
        head += f"   ({period})"
    L = [head,
         f"     {symbol_emoji(sym)} {sym or '-'}      {money_win_line(st)}",
         f"     {trade_mix_line(st)}"]
    return L


def portfolio_emoji_lines(st: dict, label: str = "NOW") -> list:
    """The whole account at a glance: open / pending / closed + every result."""
    live, pend = int(st.get("open") or 0), int(st.get("pending") or 0)
    closed = sum(int(st.get(k) or 0) for k in ("tp", "sl", "be", "manual"))
    L = [f"  \U0001F4CA {label}      \U0001F7E2 open {live}   \u23F3 pending {pend}"
         f"   \u2705 closed {closed}   \U0001F4E6 orders {int(st.get('n') or 0)}",
         f"  \U0001F3AF TP {int(st.get('tp') or 0)}   \U0001F6D1 SL {int(st.get('sl') or 0)}"
         f"   \U0001F6E1\uFE0F BE {int(st.get('be') or 0)}"
         f"   \u270B manual {int(st.get('manual') or 0)}"
         f"   \u231B expired {int(st.get('cancelled') or 0)}"
         f"   \u26A0\uFE0F refused {int(st.get('rejected') or 0)}",
         f"  {money_win_line(st)}"]
    return L


def ev_memory_lines(src: str, cat: str = "") -> list:
    """This channel's record (channel-wise, with counts) + the whole day."""
    if not (CHANNEL_MEMORY_IN_ALERTS and src):
        return []
    mine = []
    for (name, _c), recs in jr_group().items():
        if name == src:
            mine += recs
    out = ["  \U0001F9E0 CHANNEL MEMORY   (this channel - you never watch a chart)"]
    if mine:
        out += channel_block(src, jr_stats(mine), cat)
    else:
        out.append(f"  \U0001F4E1 {src}   (no trade recorded yet)")
    for label, per in (("today", "today"), ("this week", "week")):
        start, end, _t = jr_period_bounds(per)
        sub = [t for t in mine
               if jr_in(t.get("closed_ts") or t.get("placed_ts"), start, end)]
        if not sub:
            out.append(f"     \u2B1C {label:<9} nothing yet")
            continue
        st = jr_stats(sub)
        out.append(f"     \U0001F4C5 {label:<9} {trade_mix_line(st)}")
        out.append(f"                {money_win_line(st)}")
    try:
        rows = jr_rank(period="week")
        me = [r for r in rows if r["name"] == src]
        if me:
            out.append(f"     \U0001F3C6 rank     {me[0].get('medal', '')} of "
                       f"{len(rows)} channel(s) this week")
    except Exception:
        pass
    try:
        ds = day_stats()
        run = sum(1 for t in TRADES if t.get("status") == "open")
        out.append("-" * 56)
        out += portfolio_emoji_lines({"n": ds.get("placed", 0), "open": run,
                                      "pending": ds.get("waiting", 0),
                                      "tp": ds.get("tp", 0), "sl": ds.get("sl", 0),
                                      "be": ds.get("be", 0), "manual": ds.get("manual", 0),
                                      "cancelled": ds.get("missed", 0),
                                      "rejected": ds.get("rejected", 0),
                                      "pl": ds.get("net", 0.0), "win": ds.get("win")},
                                     "ALL CHANNELS TODAY")
    except Exception:
        pass
    return out


def ev_next_lines(t: dict, what: str) -> list:
    """What happens from here (the other layer, break-even, ...)."""
    ident = str(t.get("id", "")).rsplit("-", 1)[0]
    sib = [x for x in TRADES
           if str(x.get("id", "")).rsplit("-", 1)[0] == ident
           and x.get("ticket") != t.get("ticket")]
    out = []
    if sib:
        for x in sib:
            st = x.get("status")
            pip = pip_size_of(t.get("symbol") or "XAUUSD")
            tgt = x.get("tp") or 0.0
            if st in ("open", "pending"):
                dist = ""
                try:
                    if tgt and float(x.get("open_price") or x.get("price")):
                        dist = (f"   ({abs(float(tgt) - float(x.get('open_price') or x.get('price'))) / pip:.0f}"
                                f" pips away)")
                except Exception:
                    dist = ""
                out.append(f"    {ev_tag_text(x).split('  (')[0]} is still {st} -> "
                           f"TP {jr_num(tgt)}{dist}   SL stays {jr_num(x.get('sl_now') or x.get('sl'))}")
            else:
                out.append(f"    {ev_tag_text(x).split('  (')[0]} finished: "
                           f"{(x.get('result') or 'closed').upper()} "
                           f"{pl_usd(x.get('net'))}")
    else:
        out.append("    this was the only layer of that signal")
    if what == "tp" and BE_AFTER_TP1 and any(
            x.get("status") in ("open", "pending") for x in sib):
        out.append("    BE_AFTER_TP1 = ON -> the running layer is moved to break-even")
    if what == "sl" and AUTO_BE_PIPS:
        out.append(f"    reminder: every order was placed with the SIGNAL's SL - the "
                   f"bot only moves it for break-even (+{AUTO_BE_PIPS:g} pips) or "
                   f"after a partial close")
    return out


def ev_price(value) -> str:
    """4110.00 / 1.0834 - prices always line up in a message."""
    try:
        v = float(value or 0.0)
    except (TypeError, ValueError):
        return str(value)
    if abs(v) >= 100:
        return f"{v:.2f}"                  # 4110.00 - no thousands comma on prices
    if abs(v) >= 1:
        t = f"{v:,.4f}"
    else:
        t = f"{v:.5f}"
    return t.rstrip("0").rstrip(".") if "." in t else t


def ev_sl_text(t: dict) -> str:
    """The SL line: the signal's SL, and whether it was moved."""
    sl_sig = float(t.get("sl") or 0.0)
    sl_now = float(t.get("sl_now") or sl_sig or 0.0)
    if sl_sig and sl_now and abs(sl_now - sl_sig) > 1e-9:
        return f"SL {ev_price(sl_now)}   (signal SL {ev_price(sl_sig)} - moved)"
    return f"SL {ev_price(sl_now)}   (the signal's SL - never moved)"


def event_report(ev: dict) -> str:
    """The professional, categorized Telegram alert for one event."""
    t = ev.get("trade") or {}
    kind = ev.get("kind")
    what = kind if kind != "closed" else (t.get("result") or "manual")
    src = t.get("source") or "the bot"
    cat = (t.get("source_type") or "").upper()
    cat_txt = f" [{cat} channel]" if cat else ""
    entry = float(t.get("open_price") or t.get("price") or 0.0)
    close = float(t.get("close_price") or 0.0)
    net = float(t.get("net") or 0.0)
    pip = pip_size_of(t.get("symbol") or "XAUUSD")
    pips = ((close - entry) / pip) if (close and entry and pip) else 0.0
    if (t.get("direction") or "").upper() == "SELL":
        pips = -pips
    r = t.get("r")
    r_txt = f", {r:+.2f}R" if isinstance(r, (int, float)) else ""

    head = {"filled": "ORDER FILLED  |  the trade is RUNNING now",
            "tp": f"TAKE PROFIT HIT  |  {pl_usd(net)}",
            "sl": f"STOP LOSS HIT  |  {pl_usd(net)}",
            "be": "BREAK-EVEN  |  stopped at entry - no profit, no loss",
            "manual": f"POSITION CLOSED  |  {pl_usd(net)}",
            "cancelled": "PENDING ORDER CANCELLED / EXPIRED"}.get(what)
    if head is None:
        head = f"TRADE UPDATE  |  {(what or '').upper()}"
    if what in ("tp", "sl", "manual"):
        head += f"   ({pips:+.0f} pips{r_txt})"

    L = [tg_title(EV_ICON.get(what, "\u2139\uFE0F"), head, f"{src}{cat_txt}"),
         f"  CHANNEL    {src}   ({cat or '-'} channel)",
         f"  SIGNAL     {symbol_emoji(t.get('symbol'))} {t.get('direction')} "
         f"{t.get('symbol')}   {(t.get('signal') or '')[:66]}".rstrip(),
         f"  ORDER      {ev_tag_text(t)}   lot {t.get('lot')}   ticket "
         f"{t.get('ticket')}"
         f"{'   [' + str(t.get('broker')) + ']' if t.get('broker') else ''}"]
    tp_now = float(t.get("tp_now") or t.get("tp") or 0.0)
    if what == "filled":
        tp_txt = (f"TP {ev_price(tp_now)}   "
                  f"({abs(tp_now - entry) / pip:.0f} pips away)") if tp_now else "TP -"
        L += ["-" * 64,
              f"  ENTRY      {ev_price(entry)}   (filled - the signal price was "
              f"{ev_price(t.get('price'))})",
              f"  {ev_sl_text(t)}",
              f"  {tp_txt}",
              f"  TIMES      placed {_ev_clock(t.get('placed_ts'))}  ->  filled "
              f"{_ev_clock(t.get('opened_ts') or time.time())}   "
              f"({_ev_mins(t.get('placed_ts'), t.get('opened_ts') or time.time())} later)"]
    elif what == "cancelled":
        L += ["-" * 64,
              f"  NEVER TRIGGERED   the price never reached "
              f"{ev_price(t.get('price'))}",
              f"  {ev_sl_text(t)}   TP {ev_price(t.get('tp'))}",
              "  nothing was lost - this order expired or the channel cancelled it",
              f"  TIMES      placed {_ev_clock(t.get('placed_ts'))}  ->  gone "
              f"{_ev_clock(t.get('closed_ts') or time.time())}"]
    else:
        r_show = "" if not isinstance(r, (int, float)) else f"      {r:+.2f}R"
        L += ["-" * 64,
              f"  RESULT     {what.upper()}      {pl_usd(net)}      "
              f"{pips:+.0f} pips{r_show}",
              f"  ENTRY      {ev_price(entry)}          CLOSED AT  {ev_price(close)}",
              f"  {ev_sl_text(t)}   TP {ev_price(tp_now)}",
              f"  TIMES      placed {_ev_clock(t.get('placed_ts'))}  ->  filled "
              f"{_ev_clock(t.get('opened_ts'))}  ->  closed "
              f"{_ev_clock(t.get('closed_ts'))}   (in the trade "
              f"{_ev_mins(t.get('opened_ts') or t.get('placed_ts'), t.get('closed_ts'))})"]
    if t.get("owner") and t.get("owner") != t.get("source"):
        L.append(f"  MANAGED BY a command from {t.get('owner')}   "
                 f"({t.get('managed_note') or '-'})")
    mem = ev_memory_lines(src, cat)
    if mem:
        L += ["-" * 64] + mem
    nxt = ev_next_lines(t, what)
    if nxt:
        L += ["-" * 64, "  WHAT NEXT"] + nxt
    L += [tg_foot()]
    return "\n".join(L)


def _short_note(ev: dict) -> str:
    """The old, few-line alert (NOTIFY_STYLE = "SHORT")."""
    t = ev.get("trade") or {}
    kind = ev.get("kind")
    what = kind if kind != "closed" else (t.get("result") or "manual")
    head = {"filled": "PENDING ORDER FILLED  (order eka trigger una)",
            "tp": "TP HIT  (take profit eka awa)",
            "sl": "SL HIT  (stop loss eka awa)",
            "be": "BREAK-EVEN  (SL eka hit una - loss nahi)",
            "manual": "CLOSED  (channel/user command eken)",
            "cancelled": "PENDING ORDER CANCELLED"}.get(what, "TRADE UPDATE")
    lines = [head,
             f"{t.get('direction')} {t.get('symbol')}   {t.get('lot')} lot"
             f"{'   [' + str(t.get('broker')) + ']' if t.get('broker') else ''}",
             f"entry {jr_num(t.get('open_price') or t.get('price'))}  |  "
             f"SL {jr_num(t.get('sl_now') or t.get('sl'))}  |  "
             f"TP {jr_num(t.get('tp_now') or t.get('tp'))}"]
    if what in ("tp", "sl", "be", "manual"):
        lines.append(f"close {jr_num(t.get('close_price'))}   "
                     f"P/L {float(t.get('net') or 0):+.2f} USD")
        extra = f"   R {t['r']:+}" if isinstance(t.get("r"), (int, float)) else ""
        lines.append(f"result: {what.upper()}{extra}")
    lines.append(f"channel: {t.get('source')} ({t.get('source_type')})   "
                 f"ticket {t.get('ticket')}")
    lines.append(f"{BOT_NAME} v{VERSION}")
    return "\n".join(lines)


def jr_event_note(ev: dict) -> None:
    """Turn a journal event into a Telegram message."""
    t = ev.get("trade") or {}
    kind = ev.get("kind")
    what = kind if kind != "closed" else (t.get("result") or "manual")
    if not NOTIFY_ON.get(what, True):
        return
    say(str(what).lower(), trade=t)                    # v1.8.0 - the voice
    notify(event_report(ev) if str(NOTIFY_STYLE).upper().startswith("PROF")
           else _short_note(ev))


def jr_note_console(events) -> None:
    _closed = False
    for ev in events:
        t = ev.get("trade") or {}
        if ev.get("kind") in ("closed", "filled", "cancelled"):
            board_stream_record(ev.get("kind"), t)     # v1.8.0 animated board
        if ev.get("kind") == "closed":
            _closed = True
    if _closed:
        try:
            daily_target_check()                       # v1.9.0 target + voice
        except Exception as exc:
            log(f"      daily target: {exc}", "warn")
        what = ev.get("kind") if ev.get("kind") != "closed" else (t.get("result") or "manual")
        extra = ""
        if ev.get("kind") == "closed":
            extra = f"  close {jr_num(t.get('close_price'))}  {float(t.get('net') or 0):+.2f} USD"
        elif ev.get("kind") == "filled":
            extra = f"  fill {jr_num(t.get('open_price'))}"
        log(f"[{str(what).upper()}] {t.get('direction')} {t.get('symbol')} {t.get('lot')} lot  "
            f"ticket {t.get('ticket')}  |  {t.get('source')}{extra}", "mng")


def set_setting_in_file(name: str, literal, as_str: bool = False, path=None) -> bool:
    """Change ONE setting line inside this file (keeps a .bak copy).

    as_str=True -> the value is written as a QUOTED string, so a group id like
    910000005 becomes '910000005' and not the number 910000005.
    """
    path = Path(path or __file__)
    try:
        literal = str(literal)
        if as_str:
            if not (len(literal) >= 2 and literal[0] == literal[-1]
                    and literal[0] in "\"'"):
                literal = repr(literal)
        src = path.read_text(encoding="utf-8")
        m = re.search(r"(?m)^%s\s*=" % re.escape(name), src)
        if not m:
            return False
        i = m.end()
        j = src.find("\n", i)
        if j < 0:
            j = len(src)
        new = src[:i] + " " + literal + src[j:]
        compile(new, str(path), "exec")
        path.with_name(path.name + ".bak").write_text(src, encoding="utf-8")
        path.write_text(new, encoding="utf-8")
        return True
    except Exception as exc:
        log(f"      could not update {name}: {exc}", "err")
        return False


def notify_want() -> str:
    """NOTIFY_CHAT as text - it may be 'me', a name, an id (also as a number)."""
    try:
        return str(NOTIFY_CHAT if NOTIFY_CHAT is not None else "me").strip() or "me"
    except Exception:
        return "me"


async def resolve_notify_target(client) -> str:
    """NOTIFY_CHAT can be 'me', an id, @username or a GROUP NAME (like EdgeQuant Alerts)."""
    global _notify_target
    want = notify_want()
    log(f"notify: target setting = {want!r}", "info")
    if want.lower() in ("me", "self", ""):
        _notify_target = "me"
        return "me"
    if want.lstrip("-").isdigit():
        _notify_target = int(want)                 # Telethon wants the id as a number
        log(f"notify: sending to chat id {_notify_target}", "ok")
        return _notify_target
    if want.startswith("@"):
        _notify_target = want
        log(f"notify: sending to {want}", "ok")
        return want
    try:
        async for d in client.iter_dialogs():
            if (d.name or "").strip().lower() == want.lower():
                _notify_target = d.id
                log(f"notify: sending to '{d.name}' (id={d.id})", "ok")
                return _notify_target
    except Exception as exc:
        log(f"notify: could not look up '{want}' ({exc})", "warn")
    log(f"notify: no chat/group called '{want}' found -> using Saved Messages", "warn")
    _notify_target = "me"
    return "me"


async def make_notify_group(name=None) -> str:
    """Create the Telegram group the notifications go to (and use it)."""
    name = (name or NOTIFY_GROUP_NAME or "EdgeQuant Alerts").strip()
    client = _notify_client
    if client is None:
        log("notify: Telegram is not connected", "err")
        return ""
    try:
        from telethon.tl.functions.channels import CreateChannelRequest
        res = await client(CreateChannelRequest(
            title=name, about="EdgeQuant Sentinel - trade notifications", megagroup=True))
        chat = res.chats[0]
        cid = int(chat.id)
        try:                                   # -100.... = the id Telegram uses in the app
            from telethon import utils as _tutils
            full = int(_tutils.get_peer_id(chat))
        except Exception:
            full = int(f"-100{cid}") if cid > 0 else cid
        log(f"notify group created: '{name}'   id={full}   ({chat.title})", "ok")
        if set_setting_in_file("NOTIFY_CHAT", str(full), as_str=True):
            log(f"NOTIFY_CHAT = '{full}' saved (with quotes - that is what matters)",
                "ok")
        else:
            log(f"add this to SETTINGS by hand:   NOTIFY_CHAT = '{full}'", "warn")
        global _notify_target
        _notify_target = full
        try:
            await client.send_message(full, f"{BOT_NAME} notifications start here.\n"
                                            f"{BOT_TAGLINE}\n"
                                            f"{'=' * 30}\n"
                                            f"ENTRY HIT / TP HIT / SL HIT / BE MOVED "
                                            f"messages will appear in this group.")
            log("test message sent - open Telegram and look at the group", "ok")
        except Exception as exc:
            log(f"could not send the test message: {exc}", "warn")
        return str(full)
    except Exception as exc:
        log(f"notify group could not be created: {exc}", "err")
        log("(you can also create a group by hand and put its name in NOTIFY_CHAT)", "info")
        return ""


_NOTIFY_FAILS: dict = {}       # text -> how many times it was put back


def notify_requeue(text: str, photo: bool = False) -> bool:
    """Put a note back in the queue (max 3 tries) instead of losing it."""
    n = _NOTIFY_FAILS.get(text, 0)
    if n >= 3:
        _NOTIFY_FAILS.pop(text, None)
        return False
    _NOTIFY_FAILS[text] = n + 1
    notify(text, photo=photo)
    return True


async def notify_worker() -> None:
    """Send the queued notes to Telegram: rate limited + FLOOD AWARE.

    v1.6.7: when Telegram says "a wait of 140 seconds is required" we really wait
    (the old code kept retrying every 2 seconds, which made the block longer and
    spammed the log).  Nothing is lost: the notes wait in the queue and go out in
    order afterwards.  Notes older than NOTIFY_MAX_AGE_S are dropped as stale.
    """
    global _NOTIFY_LAST_SENT, _NOTIFY_FLOOD_UNTIL, _NOTIFY_FLOOD_LOGGED, _NOTIFY_DROPPED
    while True:
        await asyncio.sleep(1.0)
        try:
            notify_flush_agent()                       # bundled AI AGENT news
        except Exception as exc:
            log(f"notify: agent bundle failed ({exc})", "warn")
        now = time.time()

        # ---- Telegram asked us to wait (flood control) ---------------------
        if now < _NOTIFY_FLOOD_UNTIL:
            if now - _NOTIFY_FLOOD_LOGGED > 30:
                _NOTIFY_FLOOD_LOGGED = now
                log(f"notify: Telegram flood control - waiting "
                    f"{int(_NOTIFY_FLOOD_UNTIL - now)}s, {len(NOTIFY_Q)} note(s) queued "
                    f"(nothing is lost, they go out in order)", "warn")
            continue

        if not NOTIFY_TELEGRAM or _notify_client is None:
            continue                                   # silent: log spam helps nobody

        # ---- our own rate limit (stay under Telegram's ~20/minute) ---------
        while _NOTIFY_SENT_TIMES and (now - _NOTIFY_SENT_TIMES[0]) > 60:
            _NOTIFY_SENT_TIMES.popleft()
        if NOTIFY_Q and _NOTIFY_SENT_TIMES and (now - _NOTIFY_LAST_SENT) < float(NOTIFY_MIN_GAP_S):
            continue
        if NOTIFY_Q and len(_NOTIFY_SENT_TIMES) >= int(NOTIFY_MAX_PER_MIN):
            if now - _NOTIFY_FLOOD_LOGGED > 30:
                _NOTIFY_FLOOD_LOGGED = now
                log(f"notify: {len(_NOTIFY_SENT_TIMES)} messages in the last minute "
                    f"(our safe limit) - {len(NOTIFY_Q)} note(s) wait a moment", "warn")
            continue

        while NOTIFY_Q:
            item = NOTIFY_Q.popleft()
            text, photo, ts = q_unpack(item)
            if NOTIFY_MAX_AGE_S and (now - ts) > float(NOTIFY_MAX_AGE_S):
                _NOTIFY_DROPPED += 1
                log(f"notify: a note from {int((now - ts) / 60)} min ago is too old -> "
                    f"dropped (better than a flood); {_NOTIFY_DROPPED} dropped so far",
                    "warn")
                continue
            try:
                target = _notify_target
                if target is None:
                    target = await resolve_notify_target(_notify_client)
                sent_photo = False
                logo = HERE / NOTIFY_LOGO_FILE
                if photo and NOTIFY_LOGO and logo.exists() and len(text) <= 1024:
                    try:
                        await _notify_client.send_file(target, str(logo),
                                                       caption=text)
                        sent_photo = True
                    except Exception as exc:
                        if flood_wait_seconds(exc):
                            raise
                        log(f"notify: logo failed ({exc}) -> sending as text", "warn")
                if not sent_photo:
                    await _notify_client.send_message(target, text)
                _NOTIFY_LAST_SENT = time.time()
                _NOTIFY_SENT_TIMES.append(_NOTIFY_LAST_SENT)
                _NOTIFY_FAILS.pop(text, None)
                if len(text) > 4096:
                    log("notify: sent to Telegram", "ok")
            except Exception as exc:
                wait_s = flood_wait_seconds(exc)
                if wait_s:
                    _NOTIFY_FLOOD_UNTIL = time.time() + min(wait_s, 1800) + 1
                    _NOTIFY_FLOOD_LOGGED = _NOTIFY_FLOOD_UNTIL - 30
                    NOTIFY_Q.appendleft(item)          # same order, no retry used up
                    log(f"notify: Telegram is blocking us for {wait_s:.0f}s (too many "
                        f"messages) -> waiting, {len(NOTIFY_Q)} note(s) queued", "warn")
                elif notify_requeue(text, photo=photo):
                    log(f"notify: could not send ({exc}) -> will try again", "warn")
                else:
                    log(f"notify: could not send ({exc}) -> note dropped", "warn")
                break
            break


