# =========================================================================== #
# the numbers you set (AGENT_LOCK_PIPS / AGENT_CUT_LOSS_FRACTION /
# AGENT_REVERSAL_PIPS) are the BALANCED baseline - the style scales them
AGENT_STYLES = {
    "CAREFUL":    {"lock_mult": 0.80, "cut_mult": 1.25, "turn_mult": 1.20,
                   "give_back": 0.55, "keep": 0.0},
    "BALANCED":   {"lock_mult": 1.00, "cut_mult": 1.00, "turn_mult": 1.00,
                   "give_back": 0.50, "keep": 0.0},
    "AGGRESSIVE": {"lock_mult": 1.40, "cut_mult": 0.85, "turn_mult": 0.80,
                   "give_back": 0.40, "keep": 0.5},
}
AGENT_ACTION_TEXT = {
    "be": "LOCKED THE PROFIT   (SL moved to the entry)",
    "lock_more": "LOCKED MORE PROFIT   (SL moved further)",
    "close": "CLOSED THE TRADE   (the agent took the money / saved the rest)",
    "trail": "TIGHTENED THE SL   (trailing behind the price)",
    "partial": "TOOK HALF OFF   (profit locked)",
    "hold": "HOLDING   (letting it run)",
}


def agent_log_path() -> Path:
    return HERE / AGENT_LOG


def agent_params() -> dict:
    """The numbers behind the chosen style."""
    style = str(AGENT_STYLE or "BALANCED").upper()
    if style not in AGENT_STYLES:
        style = "BALANCED"
    st = AGENT_STYLES[style]
    return {"style": style,
            "lock": round(float(AGENT_LOCK_PIPS or 25.0) * st["lock_mult"], 1),
            "cut": min(0.95, round(float(AGENT_CUT_LOSS_FRACTION or 0.6)
                                   * st["cut_mult"], 3)),
            "turn": round(float(AGENT_REVERSAL_PIPS or 25.0) * st["turn_mult"], 1),
            "give_back": st["give_back"], "keep": st["keep"]}


def _pos_is_buy(pos) -> bool:
    t = getattr(pos, "type", 0)
    buy_const = getattr(mt5, "POSITION_TYPE_BUY", 0) if HAVE_MT5 else 0
    return int(t) == int(buy_const)


def agent_pips(pos, pip=None) -> float:
    """Profit of one position in pips (works with or without MT5)."""
    pip = pip or pip_size_of(getattr(pos, "symbol", "") or "XAUUSD")
    d = (float(getattr(pos, "price_current", 0) or 0)
         - float(getattr(pos, "price_open", 0) or 0))
    if not _pos_is_buy(pos):
        d = -d
    return (d / pip) if pip else 0.0


def agent_locked_pips(pos, pip=None) -> float:
    """How far the SL already protects the trade (0 = nothing is locked)."""
    pip = pip or pip_size_of(getattr(pos, "symbol", "") or "XAUUSD")
    entry = float(getattr(pos, "price_open", 0) or 0)
    sl = float(getattr(pos, "sl", 0) or 0)
    if not (entry and sl and pip):
        return 0.0
    lock = (sl - entry) / pip if _pos_is_buy(pos) else (entry - sl) / pip
    return lock


def agent_turned_pips(pos, closes, pip=None) -> float:
    """How far the price came back after its best point (positive = against us)."""
    if not closes or len(closes) < 3:
        return 0.0
    pip = pip or pip_size_of(getattr(pos, "symbol", "") or "XAUUSD")
    buying = _pos_is_buy(pos)
    best = max(closes) if buying else min(closes)
    now = closes[-1]
    back = (best - now) if buying else (now - best)
    return (back / pip) if pip else 0.0


def agent_decide(pos, closes=None, pip=None) -> dict:
    """What would a careful human do with this trade right now?

    Returns {"action", "why", "pips", "lock", "turned"} - nothing is sent here.
    """
    par = agent_params()
    pip = pip or pip_size_of(getattr(pos, "symbol", "") or "XAUUSD")
    pips = agent_pips(pos, pip)
    locked = agent_locked_pips(pos, pip)
    turned = agent_turned_pips(pos, closes or [], pip)
    entry = float(getattr(pos, "price_open", 0) or 0)
    sl = float(getattr(pos, "sl", 0) or 0)
    risk = abs(entry - sl) / pip if (entry and sl and pip) else 0.0
    dec = {"action": "hold", "pips": round(pips, 1), "lock": round(locked, 1),
           "turned": round(turned, 1), "risk_pips": round(risk, 1),
           "why": "nothing to do - let it run"}
    if not risk:
        dec["why"] = "no SL on this trade yet - watching it"
        return dec

    # 1) a good profit that is being given back -> take the money (keep the profit)
    if pips > 0 and locked < pips * par["give_back"] and turned >= par["turn"]:
        dec.update(action="close",
                   why=f"it was +{pips:.0f} pips and turned back {turned:.0f} pips - "
                       f"better to keep the profit than to watch it go")
        return dec

    # 2) in profit -> lock it (SL to the entry, or further in AGGRESSIVE style)
    if pips >= par["lock"]:
        want = 0.0
        if par.get("keep"):
            want = round(pips * par["keep"])             # keep part of the profit
        if locked < max(1.0, want):
            dec.update(action="be" if want <= 0 else "lock_more",
                       why=f"profit is +{pips:.0f} pips - the SL moves to the entry"
                           + (f" +{want:.0f} pips" if want else "")
                           + " so this trade can no longer lose")
            return dec

    # 3) not working: the loss is already deep AND the price keeps going against
    if AGENT_CUT_LOSS and pips < 0 and risk and abs(pips) >= par["cut"] * risk:
        against = bool(closes) and len(closes) >= 2 and (
            (closes[-1] < closes[0]) if _pos_is_buy(pos) else (closes[-1] > closes[0]))
        if against or not closes:
            dec.update(action="close",
                       why=f"-{abs(pips):.0f} pips of a {risk:.0f}-pip risk and still "
                           f"moving against - cutting it here saves the rest")
            return dec

    # 4) trailing stop (only if it is switched on in the settings)
    if TRAILING_STOP and pips >= TRAIL_START_PIPS and locked < pips - TRAIL_DISTANCE_PIPS:
        dec.update(action="trail",
                   why=f"+{pips:.0f} pips - keeping the SL {TRAIL_DISTANCE_PIPS:.0f} pips "
                       f"behind the price")
        return dec

    # 5) small profit / small loss -> leave it alone
    if pips > 0:
        dec["why"] = f"+{pips:.0f} pips - too early to touch it, letting it run"
    else:
        dec["why"] = (f"{pips:+.0f} pips - still inside the risk "
                      f"({risk:.0f} pips), holding")
    return dec


def agent_rates(symbol: str, n=None) -> list:
    """Close prices of the last N one-minute candles ([] when MT5 is missing)."""
    if not HAVE_MT5:
        return []
    n = int(n or max(4, AGENT_REVERSAL_LOOKBACK))
    try:
        r = mt5.copy_rates_from_pos(symbol, mt5.TIMEFRAME_M1, 0, n)
        if r is None or not len(r):
            return []
        return [float(x["close"]) for x in r]      # type: ignore[index]
    except Exception:
        return []


def agent_close(pos) -> bool:
    """Close ONE position completely (the agent's own close)."""
    if not HAVE_MT5 or DRY_RUN:
        log(f"      DRY-RUN  agent would CLOSE {getattr(pos, 'symbol', '')} "
            f"ticket {getattr(pos, 'ticket', '')}", "mng")
        return False
    try:
        tick = mt5.symbol_info_tick(pos.symbol)
        if tick is None:
            return False
        buying = _pos_is_buy(pos)
        req = {"action": mt5.TRADE_ACTION_DEAL, "position": pos.ticket,
               "symbol": pos.symbol, "volume": float(pos.volume),
               "type": mt5.ORDER_TYPE_SELL if buying else mt5.ORDER_TYPE_BUY,
               "price": float(tick.bid if buying else tick.ask),
               "deviation": 30, "magic": MAGIC,
               "comment": safe_comment("EQ-agent")}
        res = mt5.order_send(req)
        ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        if not ok:
            req.pop("comment", None)
            res = mt5.order_send(req)
            ok = bool(res and res.retcode == mt5.TRADE_RETCODE_DONE)
        return ok
    except Exception as exc:
        log(f"      agent close failed: {exc}", "err")
        return False


def agent_log_add(dec: dict, pos=None) -> None:
    """Remember every decision (the app shows them in the AI AGENT tab)."""
    rec = {"ts": time.time(), "action": dec.get("action"), "why": dec.get("why"),
           "pips": dec.get("pips"), "turned": dec.get("turned"),
           "style": agent_params()["style"],
           "ticket": int(getattr(pos, "ticket", 0) or 0) or None,
           "symbol": getattr(pos, "symbol", "") if pos is not None else "",
           "direction": "BUY" if (pos is not None and _pos_is_buy(pos)) else "SELL",
           "entry": float(getattr(pos, "price_open", 0) or 0) if pos is not None else 0.0,
           "price": float(getattr(pos, "price_current", 0) or 0) if pos is not None else 0.0,
           "pl": float(getattr(pos, "profit", 0) or 0) if pos is not None else 0.0}
    try:
        with agent_log_path().open("a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        lines = agent_log_path().read_text(encoding="utf-8").splitlines()
        if len(lines) > 800:                       # keep the file small
            agent_log_path().write_text("\n".join(lines[-600:]) + "\n", encoding="utf-8")
    except Exception:
        pass


def agent_recent(n: int = 40) -> list:
    """The last N decisions (newest first)."""
    out = []
    try:
        lines = agent_log_path().read_text(encoding="utf-8").splitlines()
    except Exception:
        return out
    for line in lines[-max(1, int(n)):]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    out.reverse()
    return out


def agent_source_of(ticket) -> tuple:
    """Which channel does this ticket belong to?  (from the journal)"""
    rec = jr_get(ticket) if ticket else None
    if not rec:
        return ("", "", "")
    return (rec.get("source") or "", (rec.get("source_type") or "").upper(),
            rec.get("tag") or "")


def agent_alert(dec: dict, pos, extra: str = "") -> str:
    """The Telegram message for one agent decision."""
    src, cat, tag = agent_source_of(getattr(pos, "ticket", None))
    cat_txt = f" [{cat} channel]" if cat else ""
    pips = dec.get("pips") or 0.0
    pl = float(getattr(pos, "profit", 0) or 0.0)
    L = [tg_title(EV_ICON["agent"],
                  "AI AGENT   |   " + str(AGENT_ACTION_TEXT.get(
                      dec.get("action"), str(dec.get("action")).upper())),
                  f"{src or 'this trade'}{cat_txt}"),
         f"  TRADE      {'BUY' if _pos_is_buy(pos) else 'SELL'} "
         f"{getattr(pos, 'symbol', '')}   lot {getattr(pos, 'volume', '')}   "
         f"ticket {getattr(pos, 'ticket', '')}"
         + (f"   ({tag})" if tag else ""),
         f"  NOW        {pips:+.0f} pips   {pl:+,.2f} USD   "
         f"(price {jr_num(getattr(pos, 'price_current', 0))})",
         f"  ENTRY      {jr_num(getattr(pos, 'price_open', 0))}      "
         f"SL {jr_num(getattr(pos, 'sl', 0))}      TP {jr_num(getattr(pos, 'tp', 0))}",
         "-" * 64,
         f"  WHY        {dec.get('why', '')}"]
    if extra:
        L.append(f"  DONE       {extra}")
    if dec.get("action") == "close":
        L.append("  NOTE       the profit is now safe - it cannot turn into a loss")
    elif dec.get("action") in ("be", "lock_more"):
        L.append("  NOTE       from here the worst case is a small win / break-even")
    L += [tg_foot(f"AGENT {agent_params()['style']}")]
    return "\n".join(L)


def agent_act(pos) -> dict:
    """Decide AND do it (used by the position manager every cycle)."""
    closes = agent_rates(getattr(pos, "symbol", ""))
    dec = agent_decide(pos, closes=closes)
    if dec["action"] == "hold":
        return dec
    src, _cat, _tag = agent_source_of(getattr(pos, "ticket", None))
    did = ""
    try:
        if dec["action"] == "close":
            if agent_close(pos):
                did = "the position is closed"
                if TRADE_JOURNAL:
                    jr_note_action(pos.ticket, src or AGENT_NOTIFY and "AI AGENT",
                                   "AI", note=dec.get("why") or "agent close")
        elif dec["action"] in ("be", "lock_more"):
            direction = "BUY" if _pos_is_buy(pos) else "SELL"
            n = move_to_be(direction, pos.symbol, note="AI agent lock",
                           tickets=[pos.ticket], only_profitable=True,
                           min_profit_pips=float(AGENT_LOCK_PIPS or 0.0),
                           broker=broker_of_ticket(pos.ticket))
            did = f"SL moved on {n} position(s); other trades and profit locks preserved"
        elif dec["action"] == "trail":
            if trail_one(pos):
                did = f"SL is now {jr_num(pos.sl)}"
        elif dec["action"] == "partial":
            if close_position_partial(pos, PARTIAL_CLOSE_FRACTION):
                did = "half of the position is out"
                PARTIAL_DONE.add(int(getattr(pos, "ticket", 0) or 0))
    except Exception as exc:
        log(f"      agent action failed: {exc}", "err")
        return dec
    log(f"      AI AGENT {dec['action'].upper()}  {getattr(pos, 'symbol', '')} "
        f"ticket {getattr(pos, 'ticket', '')}   {dec['why']}", "mng")
    agent_log_add(dec, pos)
    if AGENT_NOTIFY and dec["action"] != "hold":
        notify_agent_digest(agent_alert(dec, pos, did))     # v1.6.7: bundled
    return dec


def agent_report_text(limit: int = 12) -> str:
    """--agent / AI AGENT tab : the rules + the last decisions."""
    par = agent_params()
    L = [tg_title(EV_ICON["agent"], "AI AGENT",
                  "the manager that watches every trade"),
         f"state: {'ON' if AGENT_ENABLED else 'OFF'}   style: {par['style']}",
         "",
         "WHAT IT DOES (like a person watching the charts for you)",
         f"  1. +{par['lock']:.0f} pips in profit      -> SL moves to the entry (never lose again)",
         f"  2. a good profit turning back   -> closes and KEEPS the money",
         f"  3. losing {par['cut'] * 100:.0f}% of the SL distance and still going against",
         "                                   -> closes early, saves the rest",
         f"  4. trailing {'ON' if TRAILING_STOP else 'off'}   "
         f"partial close at +{PARTIAL_CLOSE_PIPS:.0f} pips",
         f"  5. it looks at the last {int(AGENT_REVERSAL_LOOKBACK)} one-minute candles "
         f"before every decision",
         ""]
    rows = agent_recent(limit)
    L.append(f"LAST {len(rows)} DECISION(S)   (newest first)")
    if not rows:
        L.append("  no decision yet - the agent only speaks when it does something")
    for r in rows:
        when = datetime.fromtimestamp(r.get("ts") or 0).strftime("%d %b %H:%M")
        src, cat, _tag = agent_source_of(r.get("ticket"))
        L.append(f"  {when}  {str(r.get('action') or '').upper():<10} "
                 f"{r.get('symbol') or '':<8} {r.get('pips') or 0:+6.0f} pips  "
                 f"{pl_usd(r.get('pl')):<16} {src or '-'}")
        L.append(f"              {r.get('why') or ''}")
    L += ["", BOT_TAGLINE]
    return "\n".join(L)


# =========================================================================== #
#  PART 12c - LIVE BOARD  (what is running right now, real time)
# =========================================================================== #
def live_flags(pips: float, dist_tp=None, dist_sl=None, locked: float = 0.0,
               kind: str = "LIVE") -> list:
    """Plain labels for one trade: is it winning / losing / near TP / near SL ..."""
    out = []
    if kind != "LIVE":
        return ["WAITING" if kind == "PENDING" else kind]
    if pips >= 100:
        out.append("+100 PIPS")
    if pips > 0:
        out.append("IN PROFIT")
    elif pips < 0:
        out.append("IN LOSS")
    else:
        out.append("FLAT")
    if locked > 0.5:
        out.append("PROFIT LOCKED")
    if dist_tp is not None and dist_tp <= 15:
        out.append("TP NEAR")
    if dist_sl is not None and dist_sl <= 15:
        out.append("SL NEAR")
    if locked == 0 and abs(pips) <= 10:
        out.append("AT BE")
    return out


def live_rows(include_pending: bool = True) -> list:
    """Every live + pending order of this bot, with channel + real numbers.

    Used by the app (LIVE TRADES board) and by  --live .  [] when MT5 is off.
    """
    rows: list = []
    if not HAVE_MT5:
        return rows
    try:
        if not mt5_ready():
            if not mt5.initialize():
                return rows
    except Exception:
        return rows
    try:
        for p in (mt5.positions_get() or []):
            if MAGIC and p.magic != MAGIC:
                continue
            broker_name = str((CURRENT_BROKER or {}).get("name") or "MAIN")
            rec = (jr_ticket_record(p.ticket, broker_name) or
                   jr_ticket_record(getattr(p, "identifier", 0), broker_name))
            src, cat, tag = agent_source_of(p.ticket)
            if rec:
                src = str(rec.get("source") or src or "")
                cat = str(rec.get("source_type") or cat or "").upper()
                tag = str(rec.get("tag") or tag or "")
            pip = pip_size_of(p.symbol)
            pips = agent_pips(p, pip)
            entry = float(p.price_open or 0)
            price = float(p.price_current or 0)
            tp = float(p.tp or 0)
            sl = float(p.sl or 0)
            dist_tp = abs(tp - price) / pip if (tp and pip) else None
            dist_sl = abs(price - sl) / pip if (sl and pip) else None
            locked = agent_locked_pips(p, pip)
            rows.append({
                "kind": "LIVE", "ticket": int(p.ticket), "symbol": p.symbol,
                "broker": broker_name, "source_type": cat,
                "signal_ts": float((rec or {}).get("signal_ts") or 0.0),
                "placed_ts": float((rec or {}).get("placed_ts") or 0.0),
                "opened_ts": float((rec or {}).get("opened_ts") or getattr(p, "time", 0.0) or 0.0),
                "activated_ts": float((rec or {}).get("activated_ts") or
                                       (rec or {}).get("opened_ts") or
                                       getattr(p, "time", 0.0) or 0.0),
                "direction": "BUY" if _pos_is_buy(p) else "SELL",
                "lot": float(p.volume or 0), "channel": src, "channel_type": cat,
                "tag": tag, "layer": ("layer 1 (quick)" if tag.lower().startswith("quick")
                                      else (f"layer 2 ({tag})" if tag else "-")),
                "entry": entry, "price": price, "sl": sl, "tp": tp,
                "pips": round(pips, 1), "pl": round(float(p.profit or 0), 2),
                "locked": round(locked, 1),
                "dist_tp": None if dist_tp is None else round(dist_tp, 1),
                "dist_sl": None if dist_sl is None else round(dist_sl, 1),
                "age_min": int((time.time() - float(p.time or time.time())) / 60),
                "state": live_flags(pips, dist_tp, dist_sl, locked, "LIVE"),
            })
        if include_pending:
            for o in (mt5.orders_get() or []):
                if MAGIC and o.magic != MAGIC:
                    continue
                broker_name = str((CURRENT_BROKER or {}).get("name") or "MAIN")
                rec = jr_ticket_record(o.ticket, broker_name)
                src, cat, tag = agent_source_of(o.ticket)
                if rec:
                    src = str(rec.get("source") or src or "")
                    cat = str(rec.get("source_type") or cat or "").upper()
                    tag = str(rec.get("tag") or tag or "")
                pip = pip_size_of(o.symbol)
                px = float(o.price_open or 0)
                price = float(o.price_current or 0)
                away = abs(px - price) / pip if (px and price and pip) else None
                rows.append({
                    "kind": "PENDING", "ticket": int(o.ticket), "symbol": o.symbol,
                    "broker": broker_name, "source_type": cat,
                    "signal_ts": float((rec or {}).get("signal_ts") or 0.0),
                    "placed_ts": float((rec or {}).get("placed_ts") or
                                        getattr(o, "time_setup", 0.0) or 0.0),
                    "opened_ts": 0.0, "activated_ts": 0.0,
                    "direction": ("BUY" if int(o.type) in (
                        int(getattr(mt5, "ORDER_TYPE_BUY_LIMIT", 2)),
                        int(getattr(mt5, "ORDER_TYPE_BUY_STOP", 4))) else "SELL"),
                    "lot": float(o.volume_current or o.volume_initial or 0),
                    "channel": src, "channel_type": cat, "tag": tag,
                    "layer": ("layer 1 (quick)" if tag.lower().startswith("quick")
                              else (f"layer 2 ({tag})" if tag else "-")),
                    "entry": px, "price": price, "sl": float(o.sl or 0),
                    "tp": float(o.tp or 0), "pips": 0.0, "pl": 0.0, "locked": 0.0,
                    "dist_tp": None, "dist_sl": round(away, 1) if away is not None else None,
                    "age_min": int((time.time() - float(o.time_setup or time.time())) / 60),
                    "state": ["PENDING"],
                })
    except Exception as exc:
        log(f"live board: {exc}", "err")
        return rows
    rows.sort(key=lambda r: (0 if r["kind"] == "LIVE" else 1, -float(r["pips"] or 0)))
    return rows


def live_text() -> str:
    """--live : the board as text (in the console)."""
    rows = live_rows()
    L = [tg_title(EV_ICON["live"], "LIVE NOW",
                  f"at {datetime.now().strftime('%H:%M:%S')}")]
    if not rows:
        L.append("  nothing is open right now (no live position, no pending order)")
    else:
        live = [r for r in rows if r["kind"] == "LIVE"]
        L.append(f"  {len(live)} live position(s)   "
                 f"{len(rows) - len(live)} pending order(s)")
        L.append("")
        for r in rows:
            L.append(f"  {r['kind']:<8} {r['direction']:<5} {r['symbol']:<9} "
                     f"lot {r['lot']:<5} ticket {r['ticket']}")
            L.append(f"           channel {r['channel'] or '-'} ({r['channel_type'] or '-'})"
                     f"   {r['layer']}")
            if r["kind"] == "LIVE":
                L.append(f"           entry {r['entry']:g}  now {r['price']:g}  "
                         f"SL {r['sl']:g}  TP {r['tp']:g}   "
                         f"{r['pips']:+.0f} pips   {pl_usd(r['pl'])}   "
                         f"{r['age_min']} min old")
            else:
                L.append(f"           order {r['entry']:g} (price {r['price']:g})  "
                         f"SL {r['sl']:g}  TP {r['tp']:g}   {r['age_min']} min waiting")
            L.append(f"           -> {', '.join(r['state'])}")
    L += ["", BOT_TAGLINE]
    return "\n".join(L)


async def journal_watch() -> None:
    """Every TRADE_POLL_S seconds: MT5 <-> journal, then notify."""
    while True:
        await asyncio.sleep(max(2, int(TRADE_POLL_S)))
        try:
            if not (HAVE_MT5 and mt5_ready()):
                continue
            events = []
            for bname in broker_names():
                if len(broker_names()) > 1 and not select_broker(bname):
                    continue
                positions, orders = {}, {}
                for p in (mt5.positions_get() or []):
                    if MAGIC and p.magic != MAGIC:
                        continue
                    _position_row = {"open": float(p.price_open), "sl": float(p.sl),
                                     "tp": float(p.tp), "profit": float(p.profit),
                                     "time": float(getattr(p, "time", 0.0) or 0.0),
                                     "identifier": int(getattr(p, "identifier", 0) or p.ticket)}
                    positions[int(p.ticket)] = _position_row
                    if (_position_row["identifier"] > 0 and
                            _position_row["identifier"] not in positions):
                        positions[_position_row["identifier"]] = _position_row
                for o in (mt5.orders_get() or []):
                    if MAGIC and o.magic != MAGIC:
                        continue
                    orders[int(o.ticket)] = {"sl": float(o.sl), "tp": float(o.tp),
                                             "price": float(o.price_open)}
                events += jr_sync(positions, orders, mt5_close_info, broker=bname)
            for ev in events:
                jr_note_console(ev)
                jr_event_note(ev)
        except Exception as exc:                                # pragma: no cover
            log(f"journal watcher: {exc}", "err")


def preview_cli(text: str = "") -> int:
    """--preview : what would the bot do with this signal?  (nothing is sent)"""
    text = text or sys.stdin.read()
    if not text.strip():
        log("nothing to preview - pass the signal text:  --preview \"GOLD BUY 4100 "
            "SL 4095 TP 4115\"", "err")
        return 1
    rule("=")
    log("SIGNAL PREVIEW - nothing is sent to MT5", "info")
    rule("-")
    print(text.strip())
    rule("-")
    cat = "LIMIT" if re.search(r"(?i)\blimit\b", text) else "MARKET"
    for guess in (LIMIT_CHANNELS or []) + (MARKET_CHANNELS or []):
        if str(guess).lower() in text.lower():
            cat = "LIMIT" if guess in (LIMIT_CHANNELS or []) else "MARKET"
            break
    sig = parse_signal(text, default_order_type="LIMIT" if cat == "LIMIT" else "MARKET",
                       default_symbol=(DEFAULT_SYMBOL_WHEN_MISSING or None),
                       fix_direction=FIX_DIRECTION_MISMATCH)
    log(f"parsed: action={sig.action}  {sig.direction} {sig.symbol}   entries={sig.entries}"
        f"   SL={sig.sl}   TPs={sig.tps}   confidence={sig.confidence}", "ok")
    for issue in sig.issues:
        log(f"   note: {issue}", "info")
    if sig.action != "place":
        log(f"   -> this message is handled as: {sig.action} (no new orders)", "warn")
        rule("=")
        return 0
    symbol = sig.symbol or "XAUUSD"
    ask = bid = 0.0
    try:
        if HAVE_MT5 and mt5_ready():
            real = resolve_symbol(symbol)
            tick = mt5.symbol_info_tick(real) if real else None
            if tick:
                symbol = real
                ask, bid = float(tick.ask), float(tick.bid)
    except Exception:
        pass
    if not ask:
        ask, bid = (sig.entries[0] if sig.entries else 4100.0),                    (sig.entries[0] if sig.entries else 4100.0)
        log("   (MT5 is not connected -> the plan is shown with the signal's own "
            "prices)", "info")
    br = Broker(symbol=symbol)
    try:
        if HAVE_MT5 and mt5_ready():
            acc = mt5.account_info()
            br = broker_from_mt5(symbol) or br
            plan = build_plan(sig, cat, br, ask, bid, float(acc.balance) if acc else 0.0)
        else:
            plan = build_plan(sig, cat, br, ask, bid, 0.0)
    except Exception as exc:
        log(f"   could not build the plan: {exc}", "err")
        return 1
    if not plan:
        log("   -> no orders would be placed", "warn")
        rule("=")
        return 0
    log(f"WOULD PLACE {len(plan)} ORDER(S)   (channel type: {cat})", "ord")
    print()
    print(f"   {'#':<3}{'ORDER':<12}{'LOT':>7}{'ENTRY':>11}{'SL':>11}{'TP':>11}   TAG")
    for i, o in enumerate(plan, 1):
        print(f"   {i:<3}{o['type']:<12}{o['lot']:>7}{o['price']:>11.2f}"
              f"{(o['sl'] or 0):>11.2f}{(o['tp'] or 0):>11.2f}   {o['tag']}")
    print()
    d = sig.direction
    pip = pip_size_of(symbol)
    if plan[0]["tp"]:
        pips1 = abs(plan[0]["price"] - plan[0]["tp"]) / pip if pip else 0
        log(f"layer 1 TP = {pips1:.0f} pips (configured {LAYER1_TP_PIPS:g})", "info")
    if plan[1:]:
        pips2 = abs(plan[1]["price"] - plan[1]["tp"]) / pip if pip else 0
        log(f"layer 2 TP = channel TP ({plan[1]['tag']}, {pips2:.0f} pips)", "info")
    if sig.sl:
        log(f"SL = the signal's own SL {sig.sl:g} on every order (never shifted)", "info")
    rule("=")
    return 0


