def login_cli() -> int:
    """--login : phone -> code -> 2FA, all on ONE asyncio loop (v1.9.6)."""
    log(f"{BOT_NAME} - Telegram login (engine v{VERSION})", "info")
    log("the code arrives INSIDE Telegram (not by SMS) - keep the app open on your phone",
        "info")
    if acquire_singleton() is None:
        log("the bot IS RUNNING in another window right now.", "warn")
        log("Logging in here will make Telegram end the bot's old login - that is",
            "warn")
        log("safe (the bot keeps running and picks this new login up by itself within",
            "warn")
        log("20 s), but the clean way is: press STOP in the app, log in here, press START.",
            "warn")
        try:
            time.sleep(3)
        except Exception:
            pass
    try:
        phone = input("phone (+94771234567): ").strip()
    except Exception:
        phone = ""
    if not phone:
        log("no phone number -> nothing done", "warn")
        return 1

    async def _login_flow() -> dict:
        # A Telethon client is tied to the loop where it connects.  Keep SEND
        # CODE, USE CODE, and optional 2FA together in this single asyncio.run.
        try:
            res = await tg_login_send_code(phone)
            if not res.get("ok"):
                return res
            log("code sent - check Telegram", "ok")
            try:
                code = str(await asyncio.to_thread(input, "code: ")).strip()
            except Exception:
                code = ""
            res = await tg_login_enter_code(phone, code)
            if res.get("need_password"):
                try:
                    pw = str(await asyncio.to_thread(input, "two step password: "))
                except Exception:
                    pw = ""
                res = await tg_login_enter_password(pw)
            return res
        except Exception as exc:
            return {"ok": False, "error": explain_login_error(exc)}

    try:
        res = asyncio.run(_login_flow())
    except Exception as exc:
        log(explain_login_error(exc), "err")
        return 1
    if res.get("ok"):
        log("login saved - press START (app) or run EDGEQUANT-START.bat", "ok")
        return 0
    log(str(res.get("error") or "could not log in"), "err")
    return 1


def calendar_cli(month: str = "") -> int:
    """--calendar [YYYY-MM] : the profit calendar of one month, in the console."""
    jr_load()
    year = mon = None
    if month:
        try:
            year, mon = (int(x) for x in month.split("-"))
        except Exception:
            log("use it like this:  --calendar 2026-09", "err")
            return 1
    cal = jr_calendar(year, mon)
    rule("=")
    log(f"PROFIT CALENDAR   {cal['name']}", "info")
    rule("-")
    heads = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN", "WEEK")
    print("  " + "".join(h.rjust(12) for h in heads))
    for wk in range(6):
        cells = []
        for wd in range(7):
            dayno = wk * 7 + wd - cal["first_weekday"] + 1
            st = cal["days"].get(dayno) if 1 <= dayno <= cal["days_in_month"] else None
            cells.append("" if not st else f"{dayno:02d} {st['net']:+.1f}")
        if not any(cells):
            continue
        wkv = cal["weeks"].get(wk)
        print("  " + "".join(c.rjust(12) for c in cells) +
              ("" if wkv is None else f"{wkv:+.1f}".rjust(12)))
    print(f"  MONTH TOTAL  {cal['total']:+.2f} USD")
    if cal["days"]:
        log(f"  best day {cal['best'][0]:02d}  ({cal['best'][1]['net']:+.2f} USD)    "
            f"worst day {cal['worst'][0]:02d}  ({cal['worst'][1]['net']:+.2f} USD)    "
            f"trading days {len(cal['days'])}", "info")
    rule("-")
    for per in ("today", "week", "month", "all"):
        r = jr_range(per)
        win = "-" if r["win"] is None else f"{r['win']:.1f}%"
        log(f"  {r['label'][:26]:<28}orders {r['placed']:>4}   triggered {r['filled']:>4}"
            f"   missed {r['missed']:>3}   TP {r['tp']:>3}  SL {r['sl']:>3}  "
            f"BE {r['be']:>3}   win {win:>6}   net {r['net']:+.2f} USD", "info")
    rows = jr_rank(period="month")[:5]
    if rows:
        at = "PER CHANNEL - THIS MONTH   (#1 = highest realized net P&L)".ljust(60)
        log(at, "info")
        for r in rows:
            st = r["stats"]
            win = "-" if st["win"] is None else f"{st['win']:.1f}%"
            log(f"    {r.get('medal', ''):<4}{r['name'][:28]:<30}{st['n']:>4} orders"
                f"   win {win:>6}   {st['pl']:+.2f} USD", "info")
    rule("=")
    return 0


