# =========================================================================== #
#  PART 9 - TELEGRAM
# =========================================================================== #
def clean_title(title: str) -> str:
    """🟨TEST MARKET CHANNEL🟨  /  TEST SIGNAL CHANNEL®  ->  plain text for matching"""
    t = title or ""
    t = re.sub(r"[^\w\s\-&.,()/+]", " ", t)      # emoji & symbols out
    t = re.sub(r"\s+", " ", t)
    return t.strip()


def id_forms(value) -> set:
    """any way of writing a chat id -> all the forms it can appear as"""
    out = set()
    try:
        n = int(value)
    except (TypeError, ValueError):
        return out
    out.add(n)
    raw = -n if n < 0 else n
    if raw > 1_000_000_000_000:
        raw -= 1_000_000_000_000
    out.add(raw)
    out.add(-raw)
    out.add(1_000_000_000_000 + raw)
    out.add(-(1_000_000_000_000 + raw))
    return out


_STUDIO_ECHO_SKIP: dict = {}   # {(chat id form, exact caption): expiry epoch}


def studio_mark_echo(chat_id, text, ttl: float = 90.0) -> None:
    """Mark the next matching outgoing Studio post so it cannot auto-trade too."""
    body = str(text or "")
    expiry = time.time() + max(5.0, float(ttl))
    for form in id_forms(chat_id):
        _STUDIO_ECHO_SKIP[(form, body)] = expiry


def studio_consume_echo(chat_id, text) -> bool:
    """Consume a matching Studio post marker once; prune expired markers."""
    now = time.time()
    for key, expiry in list(_STUDIO_ECHO_SKIP.items()):
        if expiry < now:
            _STUDIO_ECHO_SKIP.pop(key, None)
    body = str(text or "")
    forms = id_forms(chat_id)
    matched = any((form, body) in _STUDIO_ECHO_SKIP for form in forms)
    if matched:
        # One Telegram chat can have several equivalent raw/marked ID forms;
        # consume all aliases so the same outgoing post is skipped only once.
        for form in forms:
            _STUDIO_ECHO_SKIP.pop((form, body), None)
    return matched


def id_set(value) -> set:
    """Tolerant id list:  910000001 | "910000001" | -100... | {..} | [..] | "a, b" """
    out: set = set()
    if value in (None, "", 0):
        return out
    if isinstance(value, (list, tuple, set, frozenset)):
        items = list(value)
    elif isinstance(value, str) and "," in value:
        items = value.split(",")
    else:
        items = [value]                      # a single int or a single string
    for item in items:
        out |= id_forms(item)
    return out


def name_list(value) -> list:
    """A channel list may be written as one string or a list of strings."""
    if not value:
        return []
    if isinstance(value, str):
        value = [value]
    return [str(x).strip() for x in value if str(x).strip()]


def category_of(chat_id, title: str):
    if id_set(IGNORE_CHAT_IDS) & id_forms(chat_id):
        log(f"chat {chat_id} is in IGNORE_CHAT_IDS -> left alone", "info")
        return None                       # user asked us to leave this chat alone

    # ---- channel id table (any id form / string keys all work) -----------
    for key, cat in (CHANNEL_IDS or {}).items():
        if id_forms(chat_id) & id_forms(key):
            cat = str(cat).strip().upper()
            return cat if cat in ("LIMIT", "MARKET") else None

    hay = clean_title(title).lower()
    if not hay:
        return None
    for name in name_list(LIMIT_CHANNELS):
        if name.lower() in hay:
            return "LIMIT"
    for name in name_list(MARKET_CHANNELS):
        if name.lower() in hay:
            return "MARKET"
    return None


# =========================================================================== #
#  v1.6.6  -  CHANNEL ON / OFF   (one switch per channel, saved on disk)
# =========================================================================== #
CHANNEL_OFF: dict = {}          # {"TEST LIMIT CHANNEL": True} -> that channel is OFF
CHANNEL_OFF_NAMES: dict = {}    # {"TEST LIMIT CHANNEL": "TEST LIMIT CHANNEL"} (how it is shown)
_CH_OFF_LOADED = False
_CH_OFF_TS = 0.0                # when the switch file was last read
_CH_OFF_EVERY_S = 5.0           # re-read it every 5s, so a switch flipped in the APP or
                                #   in another window reaches a running engine
_CH_OFF_TOLD: set = set()       # (channel, day) - the "skipped" note goes out once a day


def channel_key(name) -> str:
    return re.sub(r"\s+", " ", str(name or "").strip().lower())


def channel_switch_keys(name, chat_id=None) -> set:
    """Names and ID aliases that refer to the same configured source switch."""
    name = str(name or "").strip()
    name_key = channel_key(name)
    keys = {name_key} if name_key else set()
    query_forms = set()
    try:
        query_forms.update(id_forms(chat_id))
    except Exception:
        pass
    if not query_forms and re.fullmatch(r"-?\d+", name):
        try:
            query_forms.update(id_forms(int(name)))
        except Exception:
            pass
    names_by_id = CHANNEL_ID_NAMES if isinstance(CHANNEL_ID_NAMES, dict) else {}
    for cid in (CHANNEL_IDS or {}):
        try:
            cid_forms = id_forms(cid)
            same_id = bool(query_forms & cid_forms) if query_forms else False
        except Exception:
            cid_forms = set()
            same_id = False
        friendly = ""
        for map_id, map_name in names_by_id.items():
            try:
                mapped_same = bool(id_forms(cid) & id_forms(map_id))
            except Exception:
                mapped_same = str(cid) == str(map_id)
            if mapped_same:
                friendly = str(map_name or "").strip()
                break
        if same_id or channel_key(str(cid)) == name_key or \
                (friendly and channel_key(friendly) == name_key):
            keys.add(channel_key(str(cid)))
            if friendly:
                keys.add(channel_key(friendly))
    for map_id, map_name in names_by_id.items():
        friendly = str(map_name or "").strip()
        try:
            same_id = bool(query_forms & id_forms(map_id)) if query_forms else False
        except Exception:
            same_id = False
        if same_id or (friendly and channel_key(friendly) == name_key):
            keys.add(channel_key(str(map_id)))
            if friendly:
                keys.add(channel_key(friendly))
    return {key for key in keys if key}


def channels_off_load(force: bool = False) -> dict:
    """Read the ON/OFF switches from edgequant_state.json (once per run)."""
    global CHANNEL_OFF, CHANNEL_OFF_NAMES, _CH_OFF_LOADED, _CH_OFF_TS
    if _CH_OFF_LOADED and (time.time() - _CH_OFF_TS) < _CH_OFF_EVERY_S and not force:
        return CHANNEL_OFF
    try:
        data = state_get("channels_off", {}) or {}
        if isinstance(data, dict):
            CHANNEL_OFF = {channel_key(k): bool(v) for k, v in data.items()}
        names = state_get("channels_off_names", {}) or {}
        if isinstance(names, dict):
            CHANNEL_OFF_NAMES = {channel_key(k): str(v) for k, v in names.items()}
    except Exception:
        CHANNEL_OFF = {}
    _CH_OFF_LOADED = True
    _CH_OFF_TS = time.time()
    return CHANNEL_OFF


def channels_off_save() -> None:
    try:
        state_set("channels_off", {k: bool(v) for k, v in CHANNEL_OFF.items()})
        state_set("channels_off_names",
                  {k: str(v) for k, v in CHANNEL_OFF_NAMES.items() if k in CHANNEL_OFF})
    except Exception as exc:
        log(f"      the channel switch could not be saved: {exc}", "warn")


def channel_is_on(name, cat: str = "", chat_id=None) -> bool:
    """May this channel place new orders?  Name and Telegram-ID switches agree."""
    if not CHANNEL_SWITCH:
        return True
    off = channels_off_load()
    return not any(bool(off.get(key)) for key in channel_switch_keys(name, chat_id))


def set_channel_on(name, on: bool, cat: str = "", quiet: bool = False) -> bool:
    """Switch one channel ON/OFF, including any linked Telegram-ID aliases."""
    keys = channel_switch_keys(name)
    if not keys:
        return False
    off = channels_off_load()
    if on:
        for key in keys:
            off.pop(key, None)
            CHANNEL_OFF_NAMES.pop(key, None)
    else:
        label = str(name).strip()
        for key in keys:
            off[key] = True
            CHANNEL_OFF_NAMES[key] = label
    channels_off_save()
    if not quiet:
        log(f"      channel '{name}' is now {'ON - its signals are traded' if on else 'OFF - every signal from it is ignored'}",
            "ok" if on else "warn")
    return True


def channel_catalog() -> list:
    """Only configured, routable sources for the ON/OFF controls.

    Historical journal rows and stale switch keys are not active sources and
    must not reappear as apparently-ON channels.  A source added in the app is
    stored by both name and ID; use its friendly name once rather than showing
    the same Telegram chat twice.
    """
    rows, seen = [], set()

    def add(name, category):
        name = str(name or "").strip()
        category = str(category or "").strip().upper()
        key = channel_key(name)
        if name and key and category in ("LIMIT", "MARKET") and key not in seen:
            seen.add(key)
            rows.append({"name": name, "cat": category})

    for name in name_list(LIMIT_CHANNELS):
        add(name, "LIMIT")
    for name in name_list(MARKET_CHANNELS):
        add(name, "MARKET")

    names_by_id = CHANNEL_ID_NAMES if isinstance(CHANNEL_ID_NAMES, dict) else {}
    for cid, cat in (CHANNEL_IDS or {}).items():
        cat = str(cat or "").strip().upper()
        if cat not in ("LIMIT", "MARKET"):
            continue
        friendly = ""
        for map_id, map_name in names_by_id.items():
            try:
                same_id = bool(id_forms(cid) & id_forms(map_id))
            except Exception:
                same_id = str(cid) == str(map_id)
            candidate = str(map_name or "").strip()
            if same_id and candidate:
                friendly = candidate
                break
        # App-added name+ID pairs already have a name row.  Keep an ID-only
        # mapping visible by its numeric ID so it can still be managed.
        if friendly and channel_key(friendly) in seen:
            continue
        add(friendly or str(cid), cat)
    return rows


def channel_rows() -> list:
    """ON/OFF + today's numbers for every channel (the app draws this)."""
    channels_off_load()
    day = jr_today_key()
    per: dict = {}
    for t in TRADES:
        if jr_day_key(t.get("placed_ts")) != day:
            continue
        per.setdefault(channel_key(t.get("source")), []).append(t)
    out = []
    for c in channel_catalog():
        recs = per.get(channel_key(c["name"]), [])
        st = jr_stats([r for r in recs if r.get("closed_ts")]) if recs else {}
        out.append({"name": c["name"], "cat": c["cat"],
                    "on": channel_is_on(c["name"]),
                    "today": len(recs),
                    "live": sum(1 for r in recs if r.get("status") == "open"),
                    "net": float(st.get("net") or 0.0),
                    "closed": int(st.get("closed") or 0),
                    "tp": int(st.get("tp") or 0), "sl": int(st.get("sl") or 0)})
    return out


def channel_find(target):
    """Find a channel from a number (1, 2, 3...) or from its name."""
    rows = channel_rows()
    t = str(target or "").strip()
    if not t:
        return None
    if t.isdigit() and 1 <= int(t) <= len(rows):
        return rows[int(t) - 1]
    key = channel_key(t)
    for r in rows:
        if channel_key(r["name"]) == key:
            return r
    for r in rows:                                     # partial name is enough
        if key and (key in channel_key(r["name"]) or channel_key(r["name"]) in key):
            return r
    return None


def channels_text() -> str:
    """The /channels answer: every channel with ON / OFF + today."""
    channels_off_load()
    rows = channel_rows()
    L = [tg_title(EV_ICON["channels"], "CHANNELS  ON / OFF",
                  "an OFF channel is completely ignored - no new orders from it"),
         "  #   CHANNEL                  TYPE     TODAY   LIVE   NET USD   STATE",
         "-" * 66]
    for i, r in enumerate(rows, 1):
        L.append(f"  {i:<3} {str(r['name'])[:23]:<24}{r['cat']:<8}{r['today']:>4}   "
                 f"{r['live']:>4}   {r['net']:>+8.2f}   {'ON' if r['on'] else 'OFF'}")
    off = [r["name"] for r in rows if not r["on"]]
    L += ["-" * 66,
          f"ON {len(rows) - len(off)}   OFF {len(off)}"
          + (f"   ({', '.join(off)})" if off else "   (every channel is trading)"),
          "",
          "change it here:   /off 2        /off TEST LIMIT CHANNEL",
          "                  /on 2         /onall        /offall",
          "the app does the same with the ON/OFF buttons on the CHANNELS tab.",
          "",
          tg_foot()]
    return "\n".join(L)


def channels_set_command(args: str, on: bool) -> str:
    """The /on and /off commands.  'all' switches every channel."""
    t = (args or "").strip()
    if not t:
        return ("tell me which channel:\n   /off 2   or   /off TEST LIMIT CHANNEL\n"
                "   /onall      /offall\n\n" + channels_text())
    if t.lower() in ("all", "*", "every"):
        n = 0
        for r in channel_rows():
            if set_channel_on(r["name"], on, r["cat"], quiet=True):
                n += 1
        log(f"[command] every channel switched {'ON' if on else 'OFF'} ({n})",
            "ok" if on else "warn")
        return (f"every channel is now {'ON - signals are traded again' if on else 'OFF - nothing new will be placed'}."
                f"\n\n{channels_text()}")
    row = channel_find(t)
    if not row:
        return f"no channel called '{t}'.\n\n{channels_text()}"
    set_channel_on(row["name"], on, row["cat"])
    return (f"{row['name']} is now {'ON - its signals are traded' if on else 'OFF - its signals are ignored'}"
            f"\n\n{channels_text()}")


# =========================================================================== #
#  v1.6.6  -  MARKET HOURS / SESSIONS   (the dashboard + /market)
# =========================================================================== #
FX_OPEN_WEEKDAY_UTC = 6          # Sunday  (Monday = 0)
FX_OPEN_HOUR_UTC = 21            # 21:00 UTC = 00:00 your time (UTC+3) next day
FX_CLOSE_WEEKDAY_UTC = 4         # Friday
FX_CLOSE_HOUR_UTC = 21

SESSION_WINDOWS = (
    ("SYDNEY",   "\U0001F1E6\U0001F1FA", 21, 6,  "opens the week"),
    ("TOKYO",    "\U0001F1EF\U0001F1F5",  0, 9,  "quiet - ranges"),
    ("LONDON",   "\U0001F1EC\U0001F1E7",  7, 16, "the busiest morning"),
    ("NEW YORK", "\U0001F1FA\U0001F1F8", 12, 21, "the biggest moves"),
)


def utc_now(now=None) -> datetime:
    """Now in UTC (no timezone object) - the clock the FX week uses.

    * nothing given   -> the PC clock, converted to UTC  (UTC+3 -> minus 3 h)
    * an AWARE datetime (tzinfo) -> converted to UTC
    * a NAIVE datetime -> taken as UTC ALREADY  (v1.7.2: the engine passes UTC
      around internally; before this fix a UTC+3 PC shifted everything 3 hours)
    """
    if now is None:
        try:
            return datetime.now().astimezone(_timezone.utc).replace(tzinfo=None)
        except Exception:
            return datetime.now()
    try:
        if now.tzinfo is not None:                       # aware -> really convert
            return now.astimezone(_timezone.utc).replace(tzinfo=None)
        return now                                       # naive = already UTC
    except Exception:
        return now


def fx_open(u: datetime) -> tuple:
    """(open?, why not) - the FX / gold week: Sunday 21:00 UTC -> Friday 21:00 UTC."""
    wd, mins = u.weekday(), u.hour * 60 + u.minute
    if wd == FX_CLOSE_WEEKDAY_UTC and mins >= FX_CLOSE_HOUR_UTC * 60:
        return False, "the weekend - Friday close"
    if wd == 5:
        return False, "the weekend - Saturday"
    if wd == FX_OPEN_WEEKDAY_UTC and mins < FX_OPEN_HOUR_UTC * 60:
        return False, f"the weekend - opens Sunday {FX_OPEN_HOUR_UTC:02d}:00 UTC"
    return True, ""


def _next_weekday_hour(u: datetime, wd: int, hour: int) -> datetime:
    d = datetime(u.year, u.month, u.day, hour, 0) + timedelta(days=(wd - u.weekday()) % 7)
    if d <= u:
        d += timedelta(days=7)
    return d


def market_next_event(u: datetime) -> tuple:
    """('closes', when) while the market is open / ('opens', when) while it is closed."""
    ok, _why = fx_open(u)
    if ok:
        return "closes", _next_weekday_hour(u, FX_CLOSE_WEEKDAY_UTC, FX_CLOSE_HOUR_UTC)
    return "opens", _next_weekday_hour(u, FX_OPEN_WEEKDAY_UTC, FX_OPEN_HOUR_UTC)


def sessions_now(now=None) -> list:
    """Which trading sessions are open right now (UTC windows)."""
    u = utc_now(now)
    mins = u.hour * 60 + u.minute
    out = []
    for name, emoji, h1, h2, note in SESSION_WINDOWS:
        a, b = h1 * 60, h2 * 60
        opened = (a <= mins < b) if b > a else (mins >= a or mins < b)
        if opened:
            out.append({"name": name, "emoji": emoji, "note": note,
                        "closes": _session_close(u, h2)})
    return out


def _session_close(u: datetime, hour: int) -> datetime:
    d = datetime(u.year, u.month, u.day, hour, 0)
    if d <= u:
        d += timedelta(days=1)
    return d


def _next_session_open(u: datetime) -> tuple:
    """(name, emoji, when) of the next session that opens."""
    best = None
    for name, emoji, h1, _h2, _note in SESSION_WINDOWS:
        for add in (0, 1):
            d = datetime(u.year, u.month, u.day, h1, 0) + timedelta(days=add)
            if d > u and (best is None or d < best[2]):
                best = (name, emoji, d)
                break
    return best or ("SYDNEY", SESSION_WINDOWS[0][1], u)


def fmt_left(seconds: float) -> str:
    """'2h 05m' / '3d 4h' / '45m' - a countdown a human can read."""
    seconds = max(0, int(seconds))
    d, rem = divmod(seconds, 86400)
    h, rem = divmod(rem, 3600)
    m = rem // 60
    if d:
        return f"{d}d {h}h"
    if h:
        return f"{h}h {m:02d}m"
    return f"{m}m"


def market_situation(now=None) -> dict:
    """Everything the dashboard needs: open/closed, sessions, next event, times.

    `now` (when given) is UTC - the tests and the engine use it that way.  The
    'local' value is always YOUR PC clock (for the "local 21:56" part).
    """
    given = now is not None
    u = utc_now(now)              # None -> the real PC clock, converted to UTC
    if given:                     # show the real local clock again
        try:
            n = u.astimezone().replace(tzinfo=None)
        except Exception:
            n = datetime.now()
    else:
        n = datetime.now()
    open_now, why = fx_open(u)
    ses = sessions_now(u)
    what, when = market_next_event(u)
    nxt = _next_session_open(u)
    secs = max(0.0, (when - u).total_seconds())
    busy = ""
    if len(ses) >= 2:
        busy = "two sessions at once - the biggest moves"
    elif ses:
        busy = ses[0]["note"]
    return {"open": open_now, "why": why, "sessions": ses, "busy": busy,
            "next_what": what, "next_when": when, "next_in": secs,
            "next_left": fmt_left(secs),
            "next_session": nxt[0], "next_session_emoji": nxt[1],
            "next_session_in": max(0.0, (nxt[2] - u).total_seconds()),
            "next_session_left": fmt_left(max(0.0, (nxt[2] - u).total_seconds())),
            "utc": u, "local": n}


def mt5_market_note(symbol: str = "XAUUSD") -> str:
    """What MT5 itself says (tick freshness / symbol switched off).  Safe: no MT5 = ''."""
    if not HAVE_MT5:
        return ""
    try:
        tick = mt5.symbol_info_tick(symbol)
        if tick is None or not getattr(tick, "time", 0):
            return "MT5: no price yet for " + symbol
        age = time.time() - float(tick.time)
        if age > 300:
            return f"MT5: last {symbol} price is {age / 60:.0f} min old (market closed / no ticks)"
        return f"MT5: {symbol} ticking normally (last tick {age:.0f}s ago)"
    except Exception:
        return ""


def situation_line(now=None) -> str:
    """One line for the app + /status:  MARKET OPEN | LONDON + NEW YORK | ..."""
    s = market_situation(now)
    ses = (" + ".join(x["name"] for x in s["sessions"]) if s["open"] else "") \
        or ("weekend" if not s["open"] else "no session open")
    return (f"MARKET {'OPEN' if s['open'] else 'CLOSED'}   |   {ses}   |   "
            f"{s['next_what'].upper()} in {s['next_left']}   |   "
            f"UTC {s['utc'].strftime('%a %H:%M')}   local {s['local'].strftime('%a %H:%M')}")


def situation_text() -> str:
    """The /market answer - is the market open and which session are we in."""
    s = market_situation()
    ok, why = can_trade_now()
    L = [tg_title(EV_ICON["market"], "MARKET  SESSIONS",
                  f"the market is {'OPEN' if s['open'] else 'CLOSED'}"
                  + (f"   ({s['why']})" if s.get("why") else "")),
         f"  CLOCK      local {s['local'].strftime('%a %d %b %H:%M')}   "
         f"|   UTC {s['utc'].strftime('%a %d %b %H:%M')}",
         f"  NEXT       {s['next_what'].upper()} in {s['next_left']} "
         f"(that is {s['next_when'].strftime('%a %d %b %H:%M')} UTC)",
         "-" * 58,
         "  SESSION NOW"]
    if s["sessions"] and s["open"]:
        for x in s["sessions"]:
            L.append(f"     {x['emoji']} {x['name']:<9} OPEN   ({x['note']})   "
                     f"closes in {fmt_left((x['closes'] - s['utc']).total_seconds())}")
    elif not s["open"]:
        L.append(f"     the whole market is closed ({s['why']}) - no session is live")
    else:
        L.append("     no session is open right now (dead hours)")
    L += [f"  NEXT OPEN  {s['next_session_emoji']} {s['next_session']} in "
          f"{s['next_session_left']}",
          "-" * 58]
    if s["busy"]:
        L.append(f"  LIQUIDITY  {s['busy']}")
    L += [f"  YOUR BOT   {'taking signals now' if ok else 'not placing orders: ' + why}",
          f"  RULE       FX + gold trade Sunday 21:00 UTC -> Friday 21:00 UTC "
          f"(weekend orders are skipped)",
          ""]
    note = mt5_market_note(DEFAULT_SYMBOL_WHEN_MISSING or "XAUUSD")
    if note:
        L.append("  " + note)
    L += ["", tg_foot()]
    return "\n".join(L)


_LIVE_OK_ONCE = False            # v1.9.5: typed LIVE once in this run = enough


def confirm_live(acc) -> bool:
    """The typed LIVE word - asked ONCE per run.

    v1.9.5: the engine can restart itself after a new Telegram login.  Asking
    for the typed word again at 3 am would leave the bot waiting at a prompt
    nobody is looking at, so the first "yes" covers the whole run.
    """
    global _LIVE_OK_ONCE
    if _LIVE_OK_ONCE:
        return True
    ok = _confirm_live_inner(acc)
    if ok:
        _LIVE_OK_ONCE = True
    return ok


def _confirm_live_inner(acc) -> bool:
    """One typed word before real money is traded.  Ctrl+C cancels."""
    if DRY_RUN or not CONFIRM_LIVE_START or DEBUG:
        return True
    if os.environ.get("EDGEQUANT_AUTO") == "1":
        log("autostart mode (EDGEQUANT_AUTO=1) -> the typed LIVE step is skipped.  "
            "The watchdog starts this on every boot, so no typing is possible.",
            "warn")
        return True
    if os.environ.get("EDGEQUANT_APP") == "1":
        # started from the desktop app / .exe: the app asks for LIVE in its own
        # window, so there is nobody at the console to type here.  Asking anyway
        # used to kill the whole engine in a windowed .exe (no stdin at all).
        log("started from the EdgeQuant app -> the typed LIVE step was already done "
            "in the app window (this is normal, not an error)", "warn")
        return True
    if sys.stdin is None:
        log("there is no console here (.exe / windowed start), so the typed LIVE step "
            "cannot be asked.  Starting in LIVE because CONFIRM_LIVE_START = True and "
            "DRY_RUN = False - set DRY_RUN = True if you did not mean this.", "warn")
        return True
    print()
    rule("=", 76)
    log("LIVE MODE - real orders will be sent to this account", "live")
    log("   (this is NOT an error - the bot is waiting for your OK)", "info")
    log(f"   account {acc.login}   {acc.server}   balance {acc.balance} {acc.currency}", "warn")
    log(f"   lot {FIXED_LOT} per order x {FIXED_LAYERS_PER_ENTRY} layers  |  "
        f"L1 quick TP +{LAYER1_TP_PIPS:g} pips  |  shift {SHIFT_PIPS:g} pips", "warn")
    log("type  LIVE  and press Enter to start trading   (Ctrl + C to cancel)", "live")
    rule("=", 76)

    import threading
    stop = threading.Event()

    def _nag():
        n = 0
        while not stop.wait(30):
            n += 1
            print(f"   ... still waiting for YOU: type  LIVE  then Enter"
                  f"   ({n * 30}s)   -   Ctrl+C cancels", flush=True)

    threading.Thread(target=_nag, daemon=True).start()
    try:
        answer = input("   > ").strip().upper()
    except (EOFError, KeyboardInterrupt):
        answer = ""
    except Exception as exc:                     # no console at all -> never crash
        log(f"could not read the answer ({exc}) -> starting anyway "
            f"(set DRY_RUN = True if that was not what you wanted)", "warn")
        answer = "LIVE"
    finally:
        stop.set()
    if answer != "LIVE":
        log("cancelled - nothing was started.  (set CONFIRM_LIVE_START = False to skip "
            "this question)", "info")
        return False
    log("LIVE confirmed - watching the channels now", "ok")
    return True


# --------------------------------------------------------------------------- #
#  DAILY SUMMARY  (end of day message to the Telegram group)                  #
# --------------------------------------------------------------------------- #
def state_path() -> Path:
    return HERE / "edgequant_state.json"


_STATE_LOCK = threading.RLock()


def state_get(key: str, default=None):
    """Read shared UI/engine state safely while the engine and desktop run together."""
    try:
        with _STATE_LOCK:
            data = json.loads(state_path().read_text(encoding="utf-8"))
        return data.get(key, default) if isinstance(data, dict) else default
    except Exception:
        return default


def state_set(key: str, value) -> bool:
    """Atomic read-modify-write; return False instead of silently losing a safety flag."""
    path = state_path()
    try:
        with _STATE_LOCK:
            data = {}
            try:
                loaded = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    data = loaded
            except Exception:
                pass
            data[key] = value
            tmp = path.with_name(path.name + ".tmp")
            tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
            tmp.replace(path)
        return True
    except Exception as exc:
        log(f"      state file could not be written: {exc}", "warn")
        return False


# =========================================================================== #
#  v1.7.0  -  DEPOSITS / WITHDRAWALS  (the ADVANCED tab + /deposit /withdraw)
# =========================================================================== #
# ---- v1.7.0 : the data behind the DASHBOARD "BEST TRADES / KILL ZONES" board --
def trade_pips(t: dict) -> float:
    """How many pips a closed trade made (0 if it never opened)."""
    try:
        pip = float(t.get("pip") or 0) or pip_size_of(t.get("symbol") or "XAUUSD")
        op, cp = float(t.get("open_price") or 0), float(t.get("close_price") or 0)
        if not op or not cp or not pip:
            return 0.0
        d = (cp - op) if str(t.get("direction")).upper() == "BUY" else (op - cp)
        return d / pip
    except Exception:
        return 0.0


def best_trades(period: str = "today", channel: str = "", limit: int = 6) -> list:
    """The best CLOSED trades of a period (USD), channel-wise if you want.

    period: today / week / month / all
    """
    try:
        if TRADE_JOURNAL and not _JR_LOADED:
            jr_load()
    except Exception:
        pass
    if period == "all":
        recs = list(TRADES)
    else:
        start, end, _label = jr_period_bounds(period or "today")
        recs = [t for t in TRADES
                if jr_in(t.get("closed_ts") or t.get("placed_ts"), start, end)]
    want = str(channel or "").strip().lower()
    if want:
        recs = [t for t in recs if str(t.get("source") or "").strip().lower() == want]
    closed = [t for t in recs if t.get("closed_ts") and t.get("status") not in
              ("rejected", "cancelled")]
    closed.sort(key=lambda t: float(t.get("net") or 0.0), reverse=True)
    out = []
    for t in closed[:max(1, int(limit))]:
        out.append({"channel": t.get("source") or "-",
                    "cat": (t.get("source_type") or "?") or "?",
                    "symbol": t.get("symbol") or "-",
                    "direction": t.get("direction") or "",
                    "net": float(t.get("net") or 0.0),
                    "pips": trade_pips(t),
                    "result": t.get("result") or "",
                    "tag": t.get("tag") or "",
                    "ticket": t.get("ticket"),
                    "when": t.get("closed_ts") or t.get("placed_ts") or 0})
    return out


def kill_zones(period: str = "all") -> list:
    """The hours that actually make money for you (the 'kill zones').

    Uses YOUR journal: per hour -> trades / net / win %.  The first row is the
    best one.  Empty list = no closed trades in that period yet.
    """
    try:
        if TRADE_JOURNAL and not _JR_LOADED:
            jr_load()
    except Exception:
        pass
    start, end, _label = jr_period_bounds(period or "all")
    recs = [t for t in TRADES if t.get("closed_ts")
            and jr_in(t["closed_ts"], start, end)]
    buckets: dict = {}
    for t in recs:
        h = datetime.fromtimestamp(float(t["closed_ts"])).hour
        b = buckets.setdefault(h, {"hour": h, "n": 0, "tp": 0, "sl": 0, "net": 0.0})
        b["n"] += 1
        b["net"] += float(t.get("net") or 0.0)
        if t.get("result") == "tp":
            b["tp"] += 1
        elif t.get("result") == "sl":
            b["sl"] += 1
    rows = []
    for h in sorted(buckets):
        b = buckets[h]
        b["win"] = (b["tp"] / float(b["n"]) * 100.0) if b["n"] else None
        rows.append(b)
    rows.sort(key=lambda b: b["net"], reverse=True)
    return rows


SHOW_KILL_ZONE_ROWS = 5


def kill_zones_text() -> str:
    """A short text version (Telegram /status style)."""
    rows = kill_zones("all")
    if not rows:
        return "no closed trades yet - nothing to rank"
    L = ["  HOUR    TRADES   TP   SL     WIN%      NET USD"]
    for b in rows[:SHOW_KILL_ZONE_ROWS]:
        L.append(f"  {b['hour']:02d}:00    {b['n']:>5}   {b['tp']:>3}   {b['sl']:>3}   "
                 f"{'-' if b['win'] is None else f'{b[chr(119) + chr(105) + chr(110)]:>5.1f}':>5}   "
                 f"{b['net']:>+10.2f}")
    return "\n".join(L)


def cf_load() -> list:
    """The money in / money out ledger (edgequant_cashflows.json)."""
    try:
        data = json.loads((HERE / CF_FILE).read_text(encoding="utf-8"))
        if isinstance(data, dict):
            data = data.get("flows") or []
        return [d for d in (data or []) if isinstance(d, dict)]
    except Exception:
        return []


def cf_export() -> Path:
    """The deposit / withdrawal list as a CSV (Excel opens it directly)."""
    items = cf_load()
    out = HERE / "EDGEQUANT-CASHFLOWS.csv"
    lines = ["date,type,amount_usd,note"]
    for it in items:
        when = datetime.fromtimestamp(float(it.get("ts") or 0)).strftime("%Y-%m-%d %H:%M")
        note = str(it.get("note") or "").replace(",", " ")
        lines.append(f"{when},{it.get('kind') or ''},{float(it.get('amount') or 0):.2f},{note}")
    tot = cf_totals(items)
    lines.append("")
    lines.append(f"TOTAL DEPOSITED,,,,{tot['deposit']:.2f}")
    lines.append(f"TOTAL WITHDRAWN,,,,{tot['withdraw']:.2f}")
    lines.append(f"NET IN,,,,{tot['net']:.2f}")
    out.write_text("\r\n".join(lines), encoding="utf-8")
    return out


def cf_save(items: list) -> bool:
    try:
        (HERE / CF_FILE).write_text(json.dumps({"flows": items}, indent=2),
                                    encoding="utf-8")
        return True
    except Exception as exc:
        log(f"      the deposit ledger could not be written: {exc}", "err")
        return False


def cf_add(kind: str, amount: float, note: str = "", broker: str = "",
           when=None) -> dict:
    """Record a deposit or a withdrawal.  Returns the record."""
    kind = "withdraw" if str(kind).lower().startswith("w") else "deposit"
    try:
        amt = abs(float(amount))
    except Exception:
        amt = 0.0
    rec = {"ts": float(when or time.time()), "kind": kind, "amount": amt,
           "note": str(note or "").strip(), "broker": str(broker or "").strip().upper()}
    if amt <= 0:
        return {}
    items = cf_load()
    items.append(rec)
    cf_save(items)
    log(f"      {kind.upper()}  {amt:,.2f} USD recorded"
        + (f"  ({rec['note']})" if rec["note"] else ""), "ok")
    return rec


def cf_totals(items=None) -> dict:
    rows = cf_load() if items is None else list(items)
    dep = sum(float(r.get("amount") or 0) for r in rows
              if str(r.get("kind")) == "deposit")
    wit = sum(float(r.get("amount") or 0) for r in rows
              if str(r.get("kind")) == "withdraw")
    return {"deposit": dep, "withdraw": wit, "net": dep - wit, "count": len(rows),
            "last": (rows[-1] if rows else {})}


def cf_text() -> str:
    """The /cashflows answer."""
    rows = cf_load()
    t = cf_totals(rows)
    L = [tg_title("\U0001F4B0", "MONEY IN / MONEY OUT",
                  "your deposits and withdrawals (the ADVANCED tab)"),
         f"  DEPOSITED    {t['deposit']:>+12,.2f} USD",
         f"  WITHDRAWN    {t['withdraw']:>+12,.2f} USD",
         f"  NET IN       {t['net']:>+12,.2f} USD      {t['count']} entries",
         "-" * 52]
    for r in rows[-12:]:
        when = datetime.fromtimestamp(float(r.get("ts") or 0)).strftime("%d %b %H:%M")
        L.append(f"  {when}   {str(r.get('kind')).upper():<9}"
                 f"{float(r.get('amount') or 0):>10,.2f}   {str(r.get('note') or '')[:26]}")
    if not rows:
        L.append("  (nothing recorded yet)")
    L += ["", "  record one:   /deposit 500     /withdraw 200 profit", "",
          tg_foot()]
    return "\n".join(L)


def day_stats(day: str = "") -> dict:
    """Everything that happened on ONE day (default = today)."""
    day = day or jr_today_key()
    placed = [t for t in TRADES if jr_day_key(t.get("placed_ts")) == day]
    closed = [t for t in TRADES if t.get("closed_ts")
              and jr_day_key(t.get("closed_ts")) == day]
    st = jr_stats(closed)
    return {"day": day, "placed": len(placed),
            "filled": sum(1 for t in placed if t.get("opened_ts")),
            "waiting": sum(1 for t in placed if t.get("status") == "pending"),
            "missed": sum(1 for t in closed if t.get("status") == "cancelled"),
            "rejected": sum(1 for t in placed if t.get("status") == "rejected"),
            "tp": st["tp"], "sl": st["sl"], "be": st["be"], "manual": st["manual"],
            "net": st["pl"], "win": st["win"], "closed": len(closed)}


def summary_text(day: str = "") -> str:
    """The message that goes to the group at the end of the day."""
    ds = day_stats(day)
    d = ds["day"]
    win = "-" if ds["win"] is None else f"{ds['win']:.1f}%"
    L = [tg_title(EV_ICON["summary"], f"DAY SUMMARY   {d}")]
    if not ds["placed"] and not ds["closed"]:
        L.append("\U0001F4A4 no trades today - the channels were quiet.")
    else:
        L += ["-" * 56]
        L += portfolio_emoji_lines({"n": ds["placed"], "open": 0,
                                    "pending": ds["waiting"], "tp": ds["tp"],
                                    "sl": ds["sl"], "be": ds["be"],
                                    "manual": ds["manual"], "cancelled": ds["missed"],
                                    "rejected": ds["rejected"], "pl": ds["net"],
                                    "win": ds["win"]}, "TODAY")
        L.append(f"  \U0001F4CD triggered {ds['filled']}   \U0001F6A9 missed "
                 f"{ds['missed']}   \U0001F6AB refused {ds['rejected']}")
        rows = jr_rank(day=d, top=6)
        if rows:
            L += ["", "\U0001F4C8 BY CHANNEL   (#1 = highest realized net P&L)"]
            for r in rows:
                L += channel_block(r["name"], r["stats"], r.get("type", ""),
                                   r.get("medal", ""))
    ps = jr_pending_stats()
    if ps["n"]:
        rate = "" if ps.get("rate") is None else f"   ({ps['rate']:.0f}% triggered)"
        L += ["", f"  \u23F3 PENDING ORDERS (all time)   placed {ps['n']}   "
                  f"triggered {ps['trig']}{rate}   waiting {ps['pending']}   "
                  f"missed {ps['miss']}"]
    wk, mo, allt = jr_range("week"), jr_range("month"), jr_range("all")
    L += ["", "-" * 56,
          f"  \U0001F4C5 WEEK    {wk['net']:+,.2f} USD      "
          f"\U0001F5D3\uFE0F MONTH   {mo['net']:+,.2f} USD      "
          f"\U0001F3E6 ALL TIME {allt['net']:+,.2f} USD",
          "", tg_foot()]
    return "\n".join(L)


async def daily_summary_loop() -> None:
    """Send the day summary once a day (at DAILY_SUMMARY_AT)."""
    if not DAILY_SUMMARY:
        return
    while True:
        now = datetime.now()
        try:
            hh, mm = (int(x) for x in str(DAILY_SUMMARY_AT).replace(".", ":").split(":"))
            hh, mm = max(0, min(23, hh)), max(0, min(59, mm))
        except Exception:
            hh, mm = 23, 55
        when = now.replace(hour=hh, minute=mm, second=0, microsecond=0)
        if when <= now:
            when += timedelta(days=1)
        wait = max(30.0, (when - now).total_seconds())
        log(f"day summary: goes to Telegram every day at {hh:02d}:{mm:02d} "
            f"(next one in {wait / 3600:.1f} h)", "info")
        await asyncio.sleep(wait)
        try:
            ts = time.time() - (3600 if hh < 4 else 0)     # after midnight -> yesterday
            day = jr_day_key(ts)
            if state_get("last_summary") == day:
                continue
            if TRADE_JOURNAL:
                jr_load()
            _sum = summary_text(day)
            try:
                _sum += "\n\n" + dt_summary_block(day)
            except Exception:
                pass
            notify(_sum, photo=True)
            say("summary")                             # v1.8.0
            state_set("last_summary", day)
            if NEXT_DAY_PLAN:
                try:
                    notify(next_day_plan(), photo=True)      # v1.9.0
                except Exception as exc:
                    log(f"next day plan failed: {exc}", "warn")
            log(f"day summary for {day} queued to Telegram", "ok")
            try:
                d = datetime.fromtimestamp(float(ts))
                if WEEKLY_REPORT and d.weekday() == 6:            # Sunday
                    notify(period_report_text("week"), photo=True)
                    log("weekly report queued to Telegram", "ok")
                nxt = (d + timedelta(days=1))
                if MONTHLY_REPORT and nxt.month != d.month:        # last day
                    notify(period_report_text("month"), photo=True)
                    log("monthly report queued to Telegram", "ok")
            except Exception as exc:
                log(f"weekly/monthly report failed: {exc}", "warn")
        except Exception as exc:
            log(f"day summary failed: {exc}", "err")


def period_report_text(period: str) -> str:
    """WEEK / MONTH report for Telegram (the auto ones + /summary style)."""
    r = jr_range(period)
    m = jr_metrics([t for t in TRADES
                    if jr_in(t.get("closed_ts") or t.get("placed_ts"),
                             *jr_period_bounds(period)[:2])] if period != "all" else None)
    head = {"week": "WEEK REPORT", "month": "MONTH REPORT",
            "today": "DAY SUMMARY", "all": "ALL TIME REPORT"}.get(period, "REPORT")
    win = "-" if r["win"] is None else f"{r['win']:.1f}%"
    pf = "-" if m["profit_factor"] is None else (
        "inf" if m["profit_factor"] == float("inf") else f"{m['profit_factor']:.2f}")
    L = [tg_title(EV_ICON.get(period, EV_ICON["report"]),
                  f"{head}   {r['label']}"),
         "  " + "-" * 54,
         f"orders {r['placed']}   triggered {r['filled']}   missed {r['missed']}   "
         f"refused {r['rejected']}",
         f"TP {r['tp']}   |   SL {r['sl']}   |   BE {r['be']}   |   manual {r['manual']}",
         f"net P/L  {r['net']:+,.2f} USD      win rate {win}",
         f"profit factor {pf}   |   expectancy "
         f"{m['expectancy']:+,.2f} USD/trade",
         f"max drawdown {m['max_dd']:,.2f} USD   |   best {m['best']:+,.2f}   "
         f"worst {m['worst']:+,.2f}"]
    L += ["", "-" * 56]
    L += portfolio_emoji_lines(r, f"{period.upper()}   (all channels)")
    rows = jr_rank(period=period, top=8) if period != "all" else jr_rank(top=8)
    if rows:
        L += ["", "\U0001F4C8 BY CHANNEL   (#1 = highest realized net P&L)"]
        for i, rr in enumerate(rows):
            L += channel_block(rr["name"], rr["stats"], rr.get("type", ""),
                               rr.get("medal", ""))
            if i < len(rows) - 1:
                L.append("")
    hrs = jr_hours()
    if len(hrs) > 2:
        best = max(hrs, key=lambda b: b["net"])
        worst = min(hrs, key=lambda b: b["net"])
        L += ["", f"best hour {best['hour']:02d}:00 ({best['net']:+.2f})   |   "
                  f"worst hour {worst['hour']:02d}:00 ({worst['net']:+.2f})"]
    if period == "month":
        cmp_rows = jr_compare()
        if cmp_rows:
            L += ["", "vs LAST MONTH"]
            for (name, cat), d in sorted(cmp_rows.items(),
                                         key=lambda kv: -kv[1]["this"]["pl"])[:5]:
                arrow = "up" if d["delta"] > 0 else ("down" if d["delta"] < 0 else "flat")
                L.append(f"  {name[:24]:<26}{d['this']['pl']:+.2f}  ({arrow} "
                         f"{d['delta']:+.2f})")
    L += ["", tg_foot()]
    return "\n".join(L)


def _sym_guess() -> str:
    """The symbol the caps are counted on (the one signals use most)."""
    try:
        return str(DEFAULT_SYMBOL_WHEN_MISSING or "").strip()
    except Exception:
        return ""


def status_text(uptime_s: float = 0.0) -> str:
    """The /status answer."""
    acc, term = "", ""
    if HAVE_MT5:
        try:
            a = mt5.account_info()
            if a:
                acc = f"account {a.login}  {a.server}  balance {a.balance:g} {a.currency}"
            t = mt5.terminal_info()
            if t and not t.trade_allowed:
                term = "   [!] ALGO TRADING IS OFF in MT5 (Ctrl+E)"
        except Exception:
            pass
    live = pend = 0
    try:
        live, pend = len(my_positions()), len(my_pendings())
    except Exception:
        pass
    today = day_stats()
    ok, why = can_trade_now()
    try:
        _rows = channel_rows()
    except Exception:
        _rows = []
    on_n = sum(1 for r in _rows if r["on"])
    off_n = len(_rows) - on_n
    try:
        _ll = loss_limit_state()
    except Exception:
        _ll = {}
    try:
        _brows = broker_rows()
        _bk_on = sum(1 for r in _brows if r["on"])
        _bk_off = len(_brows) - _bk_on
    except Exception:
        _bk_on = _bk_off = 0
    try:
        _cf = cf_totals()
    except Exception:
        _cf = {"deposit": 0.0, "withdraw": 0.0, "net": 0.0, "count": 0}
    L = [tg_title(EV_ICON["status"], "STATUS"),
         f"mode: {'PAUSED' if PAUSED else ('DRY-RUN' if DRY_RUN else 'LIVE')}"
         f"{'  (' + why + ')' if not ok else ''}",
         acc + term,
         f"live {live}   pending {pend}   |   uptime "
         f"{uptime_s / 3600:.1f} h" if uptime_s else f"live {live}   pending {pend}",
         "", f"TODAY  orders {today['placed']}  triggered {today['filled']}  "
             f"TP {today['tp']}  SL {today['sl']}  BE {today['be']}  "
             f"net {today['net']:+,.2f} USD",
         f"week {jr_range('week')['net']:+,.2f} USD      "
         f"month {jr_range('month')['net']:+,.2f} USD",
         "",
         f"market: {situation_line()}",
         (f"loss limit: {_ll['limit']:.2f} USD   today {_ll['net']:+.2f} USD"
          + ("   [HIT - new orders are skipped, /resetloss]" if _ll["hit"] else
             ("   [unlocked for today]" if _ll["unlocked"] else
              (f"   (room left {_ll['left']:.2f})" if _ll["limit"] else "   (off)")))
          ) if _ll else "loss limit: -",
         (daily_target_text().strip() if DAILY_TARGET_ON else
          "daily target: OFF   (/target on)"),
         tg_status_text(),
         (lambda _sp: f"orders: {_sp['live']} LIVE  |  {_sp['pending']} PENDING   "
                      f"(caps: {_sp['live_cap'] or 'off'} live, "
                      f"{_sp['pending_cap'] or 'off'} pending per symbol)")(
             orders_split("XAUUSD" if _sym_guess() else "")),
         (last_skip_text(max_age_s=12 * 3600) or None),
         f"trades: 2 orders/signal (L1 +{LAYER1_TP_PIPS:g} pips / L2 signal TP - 10 pips inward)   |   " +
         (f"AUTO BE ON, trigger +{AUTO_BE_PIPS:g} pips" if AUTO_BE_ENABLED else
          "AUTO BE OFF") + "   (/layers  /ladder)",
         f"channels: {on_n} ON   {off_n} OFF   (/channels to change)",
         f"brokers: {_bk_on} ON   {_bk_off} OFF   (/brokers to change)",
         f"money: deposited {_cf['deposit']:,.2f}   withdrawn {_cf['withdraw']:,.2f}   "
         f"net in {_cf['net']:+,.2f} USD   (/cashflows)",
         "", "commands: /status /pause /resume /closeall /be /summary /calendar "
             "/metrics /hours /memory /channels /market /agent /live "
             "/layers /ladder /target /update /nextplan /voice /help"]
    return "\n".join([x for x in L if x is not None]) + "\n" + tg_foot()


