    globals()["IF_SL_IMPOSSIBLE"] = "skip"
    check("'no-sl' mode sends it without SL (opt-in)", [o["sl"] for o in plan], [0.0, 0.0])

    #  no SL in the signal -> automatic 50 pips SL (gold: 5.00)
    sig = parse_signal("XAUUSD SELL 4190\nTP 4145", default_order_type="LIMIT")
    plan = build_plan(sig, "LIMIT", br, 4180.0, 4179.8)      # placed at 4191
    check("no SL -> auto SL = shifted SELL entry + 50 pips (4196)", [o["sl"] for o in plan], [4196.0, 4196.0])
    sig = parse_signal("GOLD BUY 4100\nTP 4120", default_order_type="LIMIT")
    plan = build_plan(sig, "LIMIT", br, 4090.0, 4089.8)      # placed at 4099
