    #  a signal WITH an SL is never touched (even now)
    sig = parse_signal("XAUUSD SELL 4190\nSL 4198\nTP 4145", default_order_type="LIMIT")
    check("signal SL always wins over the auto SL",
          [o["sl"] for o in build_plan(sig, "LIMIT", br, 4180.0, 4179.8)], [4198.0, 4198.0])

