        def _incomplete_handler_probe():
            names = ("_CUR_CHANNEL", "channel_is_on", "signal_message_is_new",
                     "signal_review_add", "journal", "signal_audit", "can_trade_now",
                     "HAVE_MT5")
            saved = {name: globals().get(name) for name in names}
