        class _MoveBETestMT5:
            POSITION_TYPE_BUY = 0
            POSITION_TYPE_SELL = 1
            TRADE_ACTION_SLTP = 6
            TRADE_RETCODE_DONE = 10009
            def __init__(self, positions):
                self.positions = list(positions)
                self.requests = []
            def positions_get(self):
                return self.positions
            def order_send(self, req):
                self.requests.append(dict(req))
                return type("_Res", (), {"retcode": self.TRADE_RETCODE_DONE})()

        class _BEPos:
            def __init__(self, ticket, kind, now, sl):
                self.ticket, self.magic = ticket, MAGIC
                self.symbol, self.price_open, self.price_current = "XAUUSD", 4000.0, now
                self.sl, self.tp = sl, 4200.0 if kind == "buy" else 3800.0
                self.type = 0 if kind == "buy" else 1

