        def _dynamic_update_voice_probe(lang, has_voice, events="update"): 
            names = ("VOICE_LANG", "VOICE_MODE", "VOICE_ON", "VOICE_EVENTS",
                     "VOICE_SAY_PIPS", "voice_clip", "voice_play_file",
                     "voice_sapi", "voice_sapi_pick")
            saved = {k: globals()[k] for k in names}
            called, played = [], []
            try:
                globals().update({"VOICE_LANG": lang, "VOICE_MODE": "AI", "VOICE_ON": True,
                                  "VOICE_EVENTS": events, "VOICE_SAY_PIPS": False,
                                  "voice_clip": lambda *a, **k: Path("update.wav"),
                                  "voice_play_file": lambda p: played.append(p) or True,
                                  "voice_sapi": lambda text, lang=None:
                                      called.append((text, lang)) or True,
                                  "voice_sapi_pick": lambda *a, **k:
                                      "test voice" if has_voice else ""})
                say("update", _voice_update_si if lang == "SI" else _voice_update_en)
                return (len(called), called[0][1] if called else "", len(played))
            finally:
                globals().update(saved)
