        def _offline_dynamic_voice_probe():
            names = ("VOICE_LANG", "VOICE_MODE", "VOICE_ON", "VOICE_EVENTS",
                     "VOICE_SAY_PIPS", "voice_clip", "voice_play_file", "voice_sapi",
                     "voice_sapi_pick", "local_sinhala_voice_speak")
            saved = {k: globals()[k] for k in names}
            old_last = VOICE_LAST_DISPATCH[0]
            old_events, old_ids = dict(VOICE_DISPATCH_BY_EVENT), dict(VOICE_DISPATCH_BY_ID)
            calls, spoken, played = [], [], []
            def fake_local(text):
                calls.append(text)
                item = {"state": "queued", "route": "offline-local", "id": "test-offline-id",
                        "lang": "SI", "error": ""}
                VOICE_LAST_DISPATCH[0] = item
                VOICE_DISPATCH_BY_ID[item["id"]] = item
                return item["id"]
            try:
                globals().update({"VOICE_LANG": "SI", "VOICE_MODE": "AI", "VOICE_ON": True,
                                  "VOICE_EVENTS": "update", "VOICE_SAY_PIPS": False,
                                  "voice_clip": lambda *a, **k: Path("update.wav"),
                                  "voice_play_file": lambda p: played.append(p) or True,
                                  "voice_sapi": lambda text, lang=None:
                                      spoken.append((text, lang)) or True,
                                  "voice_sapi_pick": lambda *a, **k: "",
                                  "local_sinhala_voice_speak": fake_local})
                say("update", _voice_update_si)
                VOICE_LAST_DISPATCH[0]["state"] = "played"
                return (len(calls), len(spoken), len(played),
                        voice_last_dispatch("update").get("state"),
                        any("඀" <= ch <= "෿" for ch in calls[0][0]) if calls else False)
            finally:
                globals().update(saved)
                VOICE_LAST_DISPATCH[0] = old_last
                VOICE_DISPATCH_BY_EVENT.clear(); VOICE_DISPATCH_BY_EVENT.update(old_events)
                VOICE_DISPATCH_BY_ID.clear(); VOICE_DISPATCH_BY_ID.update(old_ids)
