    def _studio_poll_type(require_hash):
        if require_hash:
            def _init(self, id, question, answers, hash, closed=None,
                      public_voters=None, multiple_choice=None, quiz=None):
                _StudioTLType.__init__(self, id=id, question=question, answers=answers,
                                       hash=hash, closed=closed, public_voters=public_voters,
                                       multiple_choice=multiple_choice, quiz=quiz)
        else:
            def _init(self, id, question, answers, closed=None,
                      public_voters=None, multiple_choice=None, quiz=None):
                _StudioTLType.__init__(self, id=id, question=question, answers=answers,
                                       closed=closed, public_voters=public_voters,
                                       multiple_choice=multiple_choice, quiz=quiz)
        return type("Poll", (_StudioTLType,), {"__init__": _init})

    def _studio_poll_types(require_hash):
        module = _types.ModuleType("telethon.tl.types")
        module.__path__ = []
        for _type_name in ("InputMediaPoll", "PollAnswer", "TextWithEntities"):
            setattr(module, _type_name, type(_type_name, (_StudioTLType,), {}))
        module.Poll = _studio_poll_type(require_hash)
        return module

