    try:
        _same = (Path(__file__).read_text(encoding="utf-8")
                 == _SELFTEST_HEAD.get("src"))
    except Exception:
        _same = None
    _saved_ticket_rows = list(TRADES)
    try:
        TRADES[:] = [{"ticket": 8801, "position_id": 9901, "broker": "MAIN",
                      "source": "TEST LIMIT CHANNEL", "source_type": "LIMIT"}]
        _alias_row = jr_ticket_record(9901, "MAIN")
        _wrong_broker_row = jr_ticket_record(9901, "SECOND")
        check("a filled position identifier still resolves its original channel-scoped order",
              ((_alias_row or {}).get("ticket"), (_alias_row or {}).get("source"),
               _wrong_broker_row), (8801, "TEST LIMIT CHANNEL", None))
    finally:
        TRADES[:] = _saved_ticket_rows
    check("the self test does not rewrite your settings file",
          (_same is not False, len(_SELFTEST_BLOCKED) >= 1), (True, True))
    check("...and every blocked write was a real setting name",
          all(isinstance(n, str) and n for n, _ in _SELFTEST_BLOCKED), True)

    rule("=")
    print(f"  {ok} passed, {bad} failed")
    rule("=")
    return 0 if bad == 0 else 1


