def channel_groups():
    """LIMIT / MARKET lists taken straight from the SETTINGS in this file."""
    def split(blocks, wanted):
        names, ids = [], []
        for name in name_list(blocks):
            names.append(name)
        for key, cat in (CHANNEL_IDS or {}).items():
            if str(cat).strip().upper() == wanted:
                ids.append(key)
        return names, ids
    return split(LIMIT_CHANNELS, "LIMIT"), split(MARKET_CHANNELS, "MARKET")


def print_settings_channels() -> None:
    (limit_names, limit_ids), (market_names, market_ids) = channel_groups()
    limit_all = list(limit_names) + [str(i) for i in limit_ids]
    market_all = list(market_names) + [str(i) for i in market_ids]
    rule("=")
    log(f"CHANNEL MAP   ({BOT_NAME} v{VERSION})", "info")
    rule("=")
    log("LIMIT CHANNELS   - post a price  ->  PENDING orders are placed", "ok")
    for n in limit_names:
        log(f"   name  : {n}", "ok")
    for i in limit_ids:
        log(f"   id    : {i}", "ok")
    if not limit_names and not limit_ids:
        log("   (none)", "warn")
    rule("-")
    log("MARKET CHANNELS  - ENTER NOW / live price  ->  market orders", "ok")
    for n in market_names:
        log(f"   name  : {n}", "ok")
    for i in market_ids:
        log(f"   id    : {i}", "ok")
    if not market_names and not market_ids:
        log("   (none)", "warn")
    rule("-")
    log("SUMMARY  (one line each)", "info")
    log("   LIMIT  : " + (" | ".join(limit_all) if limit_all else "(none)"), "ok")
    log("   MARKET : " + (" | ".join(market_all) if market_all else "(none)"), "ok")
    rule("=")


def list_channels_sync() -> int:
    """Show which channels are LIMIT and which are MARKET (plus the ignored ones)."""
    print_settings_channels()

    if not HAVE_TELETHON:
        log("telethon is not installed - the list above comes from your SETTINGS", "warn")
        return 1

    if acquire_singleton() is None:
        log(f"{BOT_NAME} is running in another window, so Telegram cannot be read now.", "warn")
        log("The list above is exactly what the bot uses (from the SETTINGS in the file).", "info")
        log("Want to see every other chat too? close the bot window and run this again.", "info")
        return 0

    try:
        async def _list():
            client = TelegramClient(str(session_path()), int(API_ID), API_HASH)
            if not await safe_start(client):
                return
            limit, market, other = [], [], []
            async for d in client.iter_dialogs():
                cid = getattr(d.entity, "id", 0)
                cat = category_of(cid, d.name or "")
                if cat == "LIMIT":
                    limit.append((cid, d.name))
                elif cat == "MARKET":
                    market.append((cid, d.name))
                else:
                    other.append((cid, d.name))
            rule("=")
            log(f"STRAIGHT FROM TELEGRAM  ->  LIMIT {len(limit)}  |  MARKET {len(market)}  |  "
                f"ignored {len(other)}", "info")
            rule("-")
            log("WILL BE TRADED AS LIMIT  (pending orders):", "ok")
            for cid, name in limit:
                log(f"   {str(name)[:44]:<46} id={cid}", "ok")
            if not limit:
                log("   (none)", "warn")
            rule("-")
            log("WILL BE TRADED AS MARKET  (current price):", "ok")
            for cid, name in market:
                log(f"   {str(name)[:44]:<46} id={cid}", "ok")
            if not market:
                log("   (none)", "warn")
            rule("-")
            log(f"IGNORED CHATS: {len(other)}   (movies, friends, other groups - never traded)", "info")
            rule("=")
            await client.disconnect()

        try:
            asyncio.run(_list())
        except Exception as exc:                              # database locked, login, ...
            log(explain_login_error(exc), "err")
            log("The LIMIT / MARKET map above is still correct - it comes from your "
                "SETTINGS.", "info")
            try:
                import traceback
                with open(HERE / ERROR_LOG, "a", encoding="utf-8") as fh:
                    fh.write(f"\n===== {datetime.now().isoformat()} (--list) =====\n"
                             f"{traceback.format_exc()}")
            except Exception:
                pass
    finally:
        release_singleton()
    return 0


def apply_desktop_settings(values, types=None) -> None:
    """Apply persisted GUI preferences in a frozen client build without source edits."""
    values = values if isinstance(values, dict) else {}
    types = types if isinstance(types, dict) else {}
    namespace = globals()
    for name, value in values.items():
        if (not isinstance(name, str) or not name.isidentifier()
                or name.startswith("_") or name.upper() != name):
            continue
        kind = str(types.get(name) or "").lower()
        try:
            if kind == "bool":
                value = bool(value)
            elif kind == "int":
                value = int(value)
            elif kind == "float":
                value = float(value)
                if not math.isfinite(value):
                    continue
            elif kind == "str":
                value = str(value)
            elif kind == "set":
                value = set(value or [])
            elif kind == "tuple":
                value = tuple(value or [])
            elif kind in ("list", "dict", "map"):
                if kind in ("dict", "map") and not isinstance(value, dict):
                    continue
                if kind == "list" and not isinstance(value, list):
                    continue
            if name in ("CHANNEL_IDS", "CHANNEL_ID_NAMES") and isinstance(value, dict):
                normalized = {}
                for key, item in value.items():
                    try:
                        key = int(key)
                    except Exception:
                        pass
                    normalized[key] = item
                value = normalized
            namespace[name] = value
        except Exception:
            continue
    # Maintain the legacy aliases when clients edit the primary controls.
    if "LAYER1_TP_PIPS" in values and "QUICK_TP_PIPS" not in values:
        namespace["QUICK_TP_PIPS"] = namespace.get("LAYER1_TP_PIPS")
    if "FIXED_LAYERS_PER_ENTRY" in values and "LAYERS_PER_PRICE" not in values:
        namespace["LAYERS_PER_PRICE"] = namespace.get("FIXED_LAYERS_PER_ENTRY")
    # One-time compatibility migration from the old implicit 25/70-pip BE defaults.
    # Existing user-selected non-default values remain editable; BE is now opt-in.
    if "AUTO_BE_ENABLED" not in values and any(
            key in values for key in ("BE_LADDER_PIPS", "AUTO_BE_PIPS", "BE_AFTER_TP1")):
        namespace["AUTO_BE_ENABLED"] = False
        try:
            if float(namespace.get("BE_LADDER_PIPS", 50) or 0) == 25.0:
                namespace["BE_LADDER_PIPS"] = 50.0
            if float(namespace.get("AUTO_BE_PIPS", 50) or 0) == 70.0:
                namespace["AUTO_BE_PIPS"] = 50.0
        except (TypeError, ValueError):
            pass
        if "AUTO_BE_PIPS" not in values:
            namespace["AUTO_BE_PIPS"] = 50.0


def main(argv=None) -> int:
    global DEBUG
    ap = argparse.ArgumentParser(description=f"{BOT_NAME} v{VERSION} - Telegram -> MT5 execution engine")
    for _stream in (sys.stdout, sys.stderr):
        try:
            _stream.reconfigure(errors="replace")      # emoji can not crash it
        except Exception:
            pass
    ap.add_argument("--selftest", action="store_true", help="run offline tests (no Telegram, no MT5)")
    ap.add_argument("--debug", action="store_true", help="print every message, trade nothing")
    ap.add_argument("--list", action="store_true", help="list your chats with category + id")
    ap.add_argument("--simulate", metavar="TEXT", help="parse one signal and show the order plan")
    ap.add_argument("--journal", action="store_true",
                    help="show the trade journal report (channel win %%, TP/SL/BE)")
    ap.add_argument("--journal-pdf", action="store_true",
                    help="save the trade journal as a PDF (no window opened)")
    ap.add_argument("--brokers", action="store_true",
                    help="test every MT5 account in MT5_ACCOUNTS")
    ap.add_argument("--preview", nargs="?", const="", metavar="SIGNAL TEXT",
                    help="show the orders a signal would create (NOTHING is sent)")
    ap.add_argument("--metrics", action="store_true",
                    help="profit factor / expectancy / drawdown (text)")
    ap.add_argument("--hours", action="store_true",
                    help="which hour of the day makes money")
    ap.add_argument("--voice", nargs="?", const="", metavar="EVENT",
                    help="speak one event now (tp / sl / be / filled ...) - "
                         "tests the voice on this PC")
    ap.add_argument("--plan", nargs="*", metavar="N",
                    help="show the AI trading plan (capital months risk target)")
    ap.add_argument("--news", action="store_true",
                    help="the news guard: what is coming + is it blocking now")
    ap.add_argument("--slip", action="store_true",
                    help="fill / slippage report (asked price vs real fill)")
    ap.add_argument("--real", action="store_true",
                    help="read MT5 history: real commission + swap in the journal")
    ap.add_argument("--backup", action="store_true", help="write a backup zip now")
    ap.add_argument("--situation", action="store_true",
                    help="is the market open?  which session (London / New York)?")
    ap.add_argument("--channels", action="store_true",
                    help="list every channel with its ON / OFF switch")
    ap.add_argument("--agent", action="store_true",
                    help="AI AGENT: the rules + the last decisions it took")
    ap.add_argument("--live", action="store_true",
                    help="what is running RIGHT NOW (live + pending, with P/L)")
    ap.add_argument("--memory", action="store_true",
                    help="show what every channel did (today / week / month)")
    ap.add_argument("--login", action="store_true",
                    help="log in to Telegram here (phone -> code -> password)")
    ap.add_argument("--tgstatus", action="store_true",
                    help="is the Telegram connection up?  (reads the status file)")
    ap.add_argument("--notify-test", action="store_true",
                    help="send 5 example alerts to your Telegram group")
    ap.add_argument("--excel", action="store_true",
                    help="write the real .xlsx trade journal")
    ap.add_argument("--summary", nargs="?", const="", metavar="YYYY-MM-DD",
                    help="print the day report and send it to the Telegram group")
    ap.add_argument("--calendar", nargs="?", const="", metavar="YYYY-MM",
                    help="the profit calendar of one month (default: this month)")
    ap.add_argument("--notify-group", nargs="?", const="", metavar="NAME",
                    help="create the Telegram group for notifications (default name: "
                         "NOTIFY_GROUP_NAME)")
    ap.add_argument("--category", default="LIMIT", help="with --simulate: LIMIT or MARKET")
    ap.add_argument("--market", type=float, default=0.0, help="with --simulate: current price")
    args = ap.parse_args(argv)
    DEBUG = args.debug

    if args.selftest:
        return selftest()

    if args.tgstatus:
        return tg_status_cli()
    if args.login:
        return login_cli()

    if args.journal:
        return journal_cli()
    if args.journal_pdf:
        return journal_cli(pdf_only=True)
    if args.brokers:
        return brokers_cli()
    if args.calendar is not None:
        return calendar_cli(args.calendar)
    if args.summary is not None:
        return summary_cli(args.summary)
    if args.metrics:
        jr_load()
        rule("=")
        print(plain_text(metrics_text()))
        rule("=")
        return 0
    if args.hours:
        jr_load()
        rule("=")
        print(plain_text(hours_text()))
        rule("=")
        return 0
    if args.memory:
        jr_load()
        rule("=")
        print(plain_text(memory_text()))
        rule("=")
        return 0
    if args.situation:
        rule("=")
        print(plain_text(situation_text()))
        rule("=")
        return 0
    if args.voice is not None:
        ev = (args.voice or "tp").strip().lower()
        rule("=")
        if ev in ("list", "status", "files"):
            st = voice_status()
            print(f"VOICE {st['mode']}   {'ON' if st['on'] else 'OFF'}   "
                  f"clips {st['count']} in {st['dir']}")
            print("  " + (", ".join(st["files"]) or "(no clips)"))
            print("events: " + ", ".join(st["events"]))
            if st.get("lang") == "SI":
                local = st.get("local_sinhala") or {}
                print("offline female Sinhala voice: " + str(local.get("state") or "not installed"))
        else:
            print(plain_text(voice_test(ev)))
        rule("=")
        return 0
    if args.plan is not None:
        vals = []
        for x in (args.plan or []):
            try:
                vals.append(float(x))
            except Exception:
                pass
        rule("=")
        print(plain_text(plan_text()))
        rule("=")
        return 0
    if args.news:
        rule("=")
        print(plain_text(news_text()))
        rule("=")
        return 0
    if args.slip:
        jr_load()
        rule("=")
        print(plain_text(slippage_text()))
        rule("=")
        return 0
    if args.real:
        jr_load()
        got = real_pl_sync(30.0)
        rule("=")
        print(f"MT5 history: {got['checked']} trade(s) checked, "
              f"{got['fixed']} updated with the real commission + swap")
        print(plain_text(real_pl_text("month")))
        rule("=")
        return 0
    if args.backup:
        rule("=")
        got = auto_backup(force=True)
        print(f"backup: {got.name if got else 'already done today'}")
        rule("=")
        return 0
    if args.channels:
        jr_load()
        rule("=")
        print(plain_text(channels_text()))
        rule("=")
        return 0
    if args.agent:
        jr_load()
        rule("=")
        print(plain_text(agent_report_text()))
        rule("=")
        return 0
    if args.live:
        jr_load()
        rule("=")
        print(plain_text(live_text()))
        rule("=")
        return 0
    if args.notify_test:
        return notify_test_sync()
    if args.excel:
        jr_load()
        f = jr_excel()
        log(f"excel written: {f.name}  ({f.stat().st_size / 1024:.0f} KB, 6 sheets)", "ok")
        return 0
    if args.preview is not None:
        return preview_cli(args.preview)
    if args.notify_group is not None:
        return notify_group_sync(args.notify_group)

    if args.simulate:
        sig = parse_signal(args.simulate,
                           default_order_type="LIMIT" if args.category.upper() == "LIMIT" else "MARKET")
        print(json.dumps({"action": sig.action, "symbol": sig.symbol, "direction": sig.direction,
                          "entries": sig.entries, "sl": sig.sl, "tps": sig.tps,
                          "entry_marked": sig.entry_marked, "confidence": sig.confidence,
                          "issues": sig.issues}, indent=1))
        ref = args.market or (sig.entries[0] if sig.entries else 1000.0)
        br = Broker(symbol=sig.symbol or "XAUUSD")
        plan = build_plan(sig, args.category.upper(), br, ref, ref - 0.0002)
        rule("=")
        print(f"  PLAN - {len(plan)} order(s)   market={ref:g}")
        rule("=")
        for o in plan:
            print(f"   {o['kind']:<8}{o['type']:<12} price={o['price']:<10} sl={o['sl'] or '-':<10} "
                  f"tp={o['tp'] or '-':<10} lot={o['lot']}  [{o['tag']}]")
        return 0

    if args.list:
        try:
            return list_channels_sync()
        except Exception as exc:                             # last line of defence
            log(explain_login_error(exc), "err")
            return 1

    try:
        asyncio.run(run_bot(debug_only=args.debug))
    except KeyboardInterrupt:
        log("stopped by user", "info")
    except Exception as exc:                                 # no ugly traceback
        import traceback
        text = traceback.format_exc()
        try:
            with open(HERE / ERROR_LOG, "a", encoding="utf-8") as fh:
                fh.write(f"\n===== {datetime.now().isoformat()} =====\n{text}")
        except Exception:
            pass
        log(explain_login_error(exc), "err")
        log(f"(full detail saved to {ERROR_LOG})", "info")
    finally:
        if TRADE_JOURNAL and _JR_LOADED:
            jr_save()
            jr_write_files()
        release_singleton()
    return 0


if __name__ == "__main__":
    sys.exit(main())
